/* テキスト拡充・第4弾(担当:sci2) */
(function (L) {
  function add(id, o) { var x = L[id]; if (!x) return; ['pat', 'more'].forEach(function (k) { if (o[k]) x[k] = (x[k] || []).concat(o[k]); }); }

  add('p4_mech', {
    pat: [
      { name: '一直線上の衝突:運動量保存＋はね返り係数の連立', freq: 'とてもよく出る', when: '「衝突後の速度を求めよ」「はね返り係数 e」と書かれていて、未知数が2つ(2物体の衝突後の速度)ある問題です。', how: ['まず正の向きを1つ決め、左向きの速度にはマイナスをつけます(符号のつけ忘れが最大のミスです)。', '運動量保存の式 m₁v₁＋m₂v₂＝m₁v₁′＋m₂v₂′ を立てます。', 'はね返り係数の式 v₂′−v₁′＝e(v₁−v₂)(離れる速さ＝e×近づく速さ)を立てます。', '2式を連立して解き、最後に運動量の和が保存されているか代入して確かめます。'], ex: { q: '右向きに 3.0 m/s で進む質量 2.0 kg の物体Aが、静止している質量 1.0 kg の物体Bに衝突した。e＝0.50 のとき、衝突後のA、Bの速度を求めよ。', a: 'A:右向き 1.5 m/s、B:右向き 3.0 m/s', exp: '右向きを正とします。運動量保存:2.0×3.0＝2.0vA＋1.0vB。はね返り係数:vB−vA＝0.50×3.0＝1.5。vB＝vA＋1.5 を代入すると 6.0＝3.0vA＋1.5 より vA＝1.5 m/s、vB＝3.0 m/s。検算:2.0×1.5＋1.0×3.0＝6.0 で保存されています。' } },
      { name: '鉛直面内の円運動:最高点を通過できる条件', freq: 'とてもよく出る', when: '糸につけた小球や、円筒の内面をすべる小球が「1回転するための条件」「最高点で糸がたるまない条件」を問われたときです。', how: ['最高点での運動方程式 m v²/r＝T＋mg を立てます(張力 T と重力の両方が中心向き)。', '「糸がたるまない」は T≧0 なので、v²≧gr という条件になります。', '最下点と最高点を力学的エネルギー保存でつなぎます(高さの差は 2r)。', '2つを組み合わせて、最下点で必要な速さ v₀≧√(5gr) を出します。'], ex: { q: '長さ 0.40 m の軽い糸に小球をつけ、最下点で水平に速さ v₀ を与えた。小球が鉛直面内で1回転するための v₀ の最小値を求めよ。(g＝9.8 m/s²)', a: '約 4.4 m/s', exp: '最高点で張力 0 のとき mv²/L＝mg なので v²＝gL。エネルギー保存 ½mv₀²＝½mv²＋mg(2L) より v₀²＝gL＋4gL＝5gL。v₀＝√(5×9.8×0.40)＝√19.6≒4.4 m/s。最高点で v＝0 でよいと考えると √(4gL) になりまちがいです。' } },
      { name: 'ばね振り子の単振動:周期・最大速さ・最大加速度', freq: 'よく出る', when: '「ばね定数 k」「振幅 A」が与えられ、周期や速さの最大値を問う問題です。', how: ['角振動数 ω＝√(k/m) を最初に求めます。周期は T＝2π/ω です。', '速さの最大値は振動の中心で Aω、加速度の大きさの最大値は両端で Aω² です。', '鉛直ばねでも、つり合いの位置を中心にすれば同じ式が使えます。'], ex: { q: 'ばね定数 50 N/m のばねに質量 0.50 kg のおもりをつけ、なめらかな水平面上で振幅 0.10 m の単振動をさせた。周期と速さの最大値を求めよ。(π＝3.14)', a: '周期 約 0.63 s、最大の速さ 1.0 m/s', exp: 'ω＝√(k/m)＝√(50/0.50)＝10 rad/s。T＝2π/ω＝6.28/10≒0.63 s。最大の速さは振動の中心を通るときで Aω＝0.10×10＝1.0 m/s。エネルギー保存 ½kA²＝½mv² からも同じ値になります。' } },
      { name: '人工衛星・惑星の周期:ケプラーの第3法則の比で解く', freq: 'よく出る', when: '軌道半径が「○倍」になったときの周期や速さの変化を問う問題です。', how: ['万有引力が向心力になる式 GMm/r²＝mv²/r を立てます。', 'v²＝GM/r より、速さは √r に反比例します。', 'T＝2πr/v から T²∝r³(第3法則)が出ます。比で計算すると G や M がいりません。'], ex: { q: '地球のまわりを円軌道で回る衛星Aと、その4倍の軌道半径で回る衛星Bがある。Bの周期はAの何倍か。また、Bの速さはAの何倍か。', a: '周期は8倍、速さは 1/2 倍', exp: 'T²∝r³ なので T∝r^(3/2)。r が4倍なら T は 4^(3/2)＝8 倍です。v＝√(GM/r) なので速さは 1/√4＝1/2 倍。「遠い衛星ほどゆっくり回る」ので、周期は半径の4倍以上に長くなります。' } },
      { name: '動ける台の上の物体:水平方向の運動量保存＋エネルギー保存', freq: '難関大で出る', when: 'なめらかな床の上に置かれた台(曲面や斜面つき)があり、台も動けると書かれている問題です。', how: ['外から水平な力がはたらかないので、物体＋台の水平方向の運動量は保存します。', '最高点では物体が台に対して止まる(台と同じ速さになる)ことに注目します。', '摩擦がなければ力学的エネルギーも保存します。2式を連立します。'], ex: { q: 'なめらかな床に置いた質量 3.0 kg の台の曲面を、質量 1.0 kg の小物体が 4.0 m/s で上り始めた。小物体が達する最高点の高さを求めよ。(g＝9.8 m/s²、摩擦なし)', a: '約 0.61 m', exp: '最高点では両者が同じ速さ v になります。運動量保存 1.0×4.0＝4.0v より v＝1.0 m/s。エネルギー保存:½×1.0×4.0²＝½×4.0×1.0²＋1.0×9.8×h より 8.0−2.0＝9.8h、h≒0.61 m。台が動く分だけ、台が固定のとき(0.82 m)より低くなります。' } }
    ],
    more: [
      { lv: 1, q: '質量 0.20 kg のボールが速さ 15 m/s で飛んでいる。ボールの運動量の大きさを求めよ。', a: '3.0 kg·m/s', exp: '運動量は p＝mv です。0.20×15＝3.0 kg·m/s。運動量は向きをもつ量(ベクトル)なので、向きはボールの進む向きです。' },
      { lv: 1, q: '静止していた質量 0.50 kg の物体に、一定の力 4.0 N を 0.50 s 間加えた。物体が受けた力積と、そのあとの速さを求めよ。', a: '力積 2.0 N·s、速さ 4.0 m/s', exp: '力積＝FΔt＝4.0×0.50＝2.0 N·s。力積は運動量の変化に等しいので 0.50v−0＝2.0 より v＝4.0 m/s です。' },
      { lv: 1, q: 'ボールが床に 5.0 m/s で垂直に当たり、3.0 m/s ではね返った。床とボールのはね返り係数を求めよ。', a: '0.60', exp: 'はね返り係数は「はね返る速さ÷当たる速さ」です。3.0÷5.0＝0.60。e は 0 以上 1 以下の値になります。' },
      { lv: 1, q: '半径 0.50 m の円周上を、速さ 2.0 m/s で等速円運動している物体の加速度の大きさと向きを答えよ。', a: '8.0 m/s²、円の中心向き', exp: '等速円運動の加速度は a＝v²/r＝2.0²/0.50＝8.0 m/s² です。速さは一定でも速度の向きが変わり続けるので、中心向きの加速度があります。' },
      { lv: 1, q: '振幅 0.20 m、周期 2.0 s の単振動をする物体の速さの最大値を求めよ。(π＝3.14)', a: '約 0.63 m/s', exp: 'ω＝2π/T＝2×3.14/2.0＝3.14 rad/s。速さの最大値は Aω＝0.20×3.14≒0.63 m/s で、振動の中心を通るときです。' },
      { lv: 1, q: '惑星が楕円軌道を回るとき、速さがいちばん大きいのはどこか。', choices: ['太陽からいちばん遠い点', '太陽にいちばん近い点', '楕円の短い軸の端', 'どこでも同じ'], a: 'B(太陽にいちばん近い点)', exp: 'ケプラーの第2法則(面積速度一定)より、太陽からの距離 r が小さいところでは速さが大きくなります。近日点で最も速く、遠日点で最も遅くなります。' },
      { lv: 1, q: '長さ 0.90 m の単振り子の周期を求めよ。(g＝9.8 m/s²、π＝3.14、振れ幅は小さいとする)', a: '約 1.9 s', exp: 'T＝2π√(L/g)＝6.28×√(0.90/9.8)＝6.28×0.303≒1.9 s。単振り子の周期はおもりの質量や振れ幅(小さいとき)によらないことも大切です。' },
      { lv: 2, q: '右向きに 6.0 m/s で進む質量 2.0 kg の物体が、静止している質量 4.0 kg の物体に衝突して一体になった。衝突で失われた運動エネルギーを求めよ。', a: '24 J', exp: '運動量保存 2.0×6.0＝6.0v より v＝2.0 m/s。運動エネルギーは前が ½×2.0×6.0²＝36 J、後が ½×6.0×2.0²＝12 J。失われたのは 36−12＝24 J で、熱や音になります。' },
      { lv: 2, q: '高さ 1.6 m からボールを静かに落とした。床とのはね返り係数が 0.50 のとき、1回目にはね上がる高さを求めよ。', a: '0.40 m', exp: '高さは速さの2乗に比例します。はね返った直後の速さは当たる直前の e 倍なので、はね上がる高さは e² 倍:1.6×0.50²＝0.40 m。e 倍の 0.80 m としないよう注意します。' },
      { lv: 2, q: 'なめらかな水平面上で、質量 0.30 kg の小球を糸につなぎ、半径 0.60 m、周期 1.2 s で等速円運動させた。糸の張力を求めよ。(π＝3.14)', a: '約 4.9 N', exp: 'ω＝2π/T＝6.28/1.2≒5.23 rad/s。張力が向心力なので S＝mrω²＝0.30×0.60×5.23²≒4.9 N。周期が与えられたら、まず ω にするのが近道です。' },
      { lv: 2, q: 'ばねに質量 0.40 kg のおもりをつるすと、ばねは 0.098 m 伸びてつり合った。このおもりを上下に振動させたときの周期を求めよ。(g＝9.8 m/s²、π＝3.14)', a: '約 0.63 s', exp: 'つり合いの式 kx₀＝mg より k＝0.40×9.8/0.098＝40 N/m。T＝2π√(m/k)＝6.28×√(0.40/40)＝6.28×0.10≒0.63 s。鉛直でも周期の式は水平のときと同じです。' },
      { lv: 2, q: '地表での重力加速度を g、地球の半径を R とする。地表から高さ R の位置での重力加速度はいくらか。', choices: ['g/2', 'g/4', 'g/8', '2g'], a: 'B(g/4)', exp: '重力加速度は万有引力 GM/r² で決まり、地球の中心からの距離 r の2乗に反比例します。高さ R の点は中心から 2R なので g/2²＝g/4。高さと距離を取りちがえないことが大切です。' },
      { lv: 2, q: '静止していた質量 3.0 kg の物体が、内部の力で質量 1.0 kg と 2.0 kg の2つに分裂した。1.0 kg の方が 6.0 m/s で動き出したとき、2.0 kg の方の速さと、2つの運動エネルギーの比(1.0 kg:2.0 kg)を求めよ。', a: '3.0 m/s(逆向き)、2:1', exp: '分裂前の運動量は 0 なので 1.0×6.0＋2.0v＝0 より v＝−3.0 m/s。運動エネルギーは ½×1.0×36＝18 J と ½×2.0×9＝9 J で 2:1。分裂では軽い方が多くのエネルギーをもらいます。' },
      { lv: 2, q: 'なめらかな水平面上で、東向き 3.0 m/s の質量 1.0 kg の物体と、北向き 4.0 m/s の質量 1.0 kg の物体が衝突して一体になった。衝突後の速さを求めよ。', a: '2.5 m/s', exp: '運動量は向きごとに保存します。東向き成分 3.0、北向き成分 4.0 kg·m/s で、合計の大きさは √(3.0²＋4.0²)＝5.0 kg·m/s。質量 2.0 kg で割って 2.5 m/s。向きは東から北へ約 53° です。' },
      { lv: 2, q: '変位が x＝0.10 sin 4.0t(x は m、t は s)で表される単振動の、加速度の大きさの最大値を求めよ。', a: '1.6 m/s²', exp: '式から振幅 A＝0.10 m、角振動数 ω＝4.0 rad/s です。加速度は a＝−ω²x なので、最大値は Aω²＝0.10×16＝1.6 m/s²。振動の両端で最大になります。' },
      { lv: 3, q: 'なめらかな半球面(半径 r)の頂上から、小物体が静かにすべり出した。小物体が球面から離れる位置を、鉛直線と半径のなす角 θ の cosθ で答えよ。', a: 'cosθ＝2/3', exp: '角 θ の位置で、エネルギー保存より v²＝2gr(1−cosθ)。中心向きの運動方程式 mv²/r＝mg cosθ−N で、離れるのは N＝0 のとき。2gr(1−cosθ)＝gr cosθ より cosθ＝2/3 です。' },
      { lv: 3, q: 'なめらかな水平面上に、軽いばね(ばね定数 100 N/m)をつけた質量 1.0 kg の物体Bが静止している。質量 1.0 kg の物体Aが 2.0 m/s でばねに当たった。ばねの最大の縮みを求めよ。', a: '約 0.14 m', exp: 'ばねが最も縮むとき、AとBは同じ速さになります。運動量保存で v＝2.0/2＝1.0 m/s。運動エネルギーの減少 ½×1.0×4.0−½×2.0×1.0＝1.0 J がばねのエネルギー ½kx² になり、x²＝0.020、x≒0.14 m。' },
      { lv: 3, q: '惑星が楕円軌道を回っている。近日点での太陽からの距離は r、遠日点では 3r で、近日点での速さは v である。遠日点での速さを求めよ。', a: 'v/3', exp: '近日点・遠日点では速度が太陽への向きと垂直なので、面積速度は ½×距離×速さ です。第2法則より ½rv＝½×3r×v′、v′＝v/3。遠い点ほど遅いことと合っています。' },
      { lv: 3, q: '長さ 0.50 m の軽い糸につけた質量 0.20 kg の小球が、鉛直面内で円運動している。最下点での速さが 5.0 m/s のとき、最高点での糸の張力を求めよ。(g＝9.8 m/s²)', a: '約 0.20 N', exp: 'エネルギー保存:v²＝5.0²−2g×(2×0.50)＝25−19.6＝5.4。最高点では張力と重力の両方が中心向きなので T＝mv²/L−mg＝0.20×5.4/0.50−0.20×9.8＝2.16−1.96＝0.20 N。T＞0 なので1回転できます。' },
      { lv: 3, q: '地表から真上に物体を打ち上げ、地球の重力をふり切って無限の遠方まで行かせたい。必要な最小の速さを g と地球の半径 R で表し、数値で求めよ。(g＝9.8 m/s²、R＝6.4×10⁶ m、空気抵抗と地球の自転は無視)', a: '√(2gR)≒1.1×10⁴ m/s', exp: '万有引力による位置エネルギーは −GMm/r です。無限遠で速さ 0 になる条件は ½mv²−GMm/R＝0。GM＝gR² を使うと v＝√(2gR)＝√(2×9.8×6.4×10⁶)＝1.12×10⁴ m/s(第2宇宙速度)。' }
    ]
  });

  add('p4_heat', {
    pat: [
      { name: '状態方程式 pV＝nRT で1つの量を求める', freq: 'とてもよく出る', when: '圧力・体積・温度のうち3つがわかっていて、残り(物質量など)を問われたときです。', how: ['単位をそろえます:圧力は Pa、体積は m³、温度は K(セ氏温度＋273)。', 'pV＝nRT に代入し、求めたい量について解きます。', '1 L＝1.0×10⁻³ m³ の換算をまちがえないよう、最後にけた数を見直します。'], ex: { q: '体積 8.3×10⁻³ m³ の容器に、圧力 3.0×10⁵ Pa、温度 300 K の理想気体が入っている。物質量を求めよ。(R＝8.3 J/(mol·K))', a: '1.0 mol', exp: 'n＝pV/(RT)＝(3.0×10⁵×8.3×10⁻³)/(8.3×300)＝(2.49×10³)/(2.49×10³)＝1.0 mol。体積を L のまま 8.3 として代入すると 1000 倍の答えになるので、単位に気をつけます。' } },
      { name: '熱力学第一法則 Q＝ΔU＋W で熱の出入りを決める', freq: 'とてもよく出る', when: '「気体が吸収した熱量」「内部エネルギーの変化」「気体がした仕事」のどれかを問われたときです。', how: ['内部エネルギーの変化は温度だけで決まります:単原子分子なら ΔU＝(3/2)nRΔT。', '気体がした仕事 W は、定圧なら pΔV(＝nRΔT)、定積なら 0 です。', 'Q＝ΔU＋W で熱量を出します。符号(吸収か放出か)を最後に言葉で確かめます。'], ex: { q: '単原子分子の理想気体 1.0 mol を、圧力一定のまま温度を 100 K 上げた。気体が吸収した熱量を求めよ。(R＝8.3 J/(mol·K))', a: '約 2.1×10³ J', exp: 'ΔU＝(3/2)×1.0×8.3×100＝1245 J。定圧なので W＝pΔV＝nRΔT＝830 J。Q＝ΔU＋W＝2075≒2.1×10³ J。定圧モル比熱 (5/2)R を使って (5/2)×8.3×100 と計算しても同じです。' } },
      { name: 'ピストンのつり合いから気体の圧力を求める', freq: 'よく出る', when: 'なめらかに動くピストンが静止していて、ピストンの質量や大気圧が与えられている問題です。', how: ['ピストンにはたらく力をすべて書き出します(気体が押す力 pS、大気が押す力 p₀S、重力 Mg など)。', '力のつり合いの式を立て、気体の圧力 p を求めます。', 'ピストンがゆっくり動く間も圧力は同じなので、その変化は定圧変化として扱えます。'], ex: { q: '鉛直に立てたシリンダーに、断面積 2.0×10⁻³ m²、質量 4.0 kg のなめらかなピストンで気体を閉じこめた。大気圧が 1.0×10⁵ Pa のとき、気体の圧力を求めよ。(g＝9.8 m/s²)', a: '約 1.2×10⁵ Pa', exp: 'つり合いの式 pS＝p₀S＋Mg より p＝p₀＋Mg/S＝1.0×10⁵＋(4.0×9.8)/(2.0×10⁻³)＝1.0×10⁵＋1.96×10⁴≒1.2×10⁵ Pa。ピストンの重さの分だけ、大気圧より高くなります。' } },
      { name: 'p-V グラフのサイクルの熱効率', freq: 'よく出る', when: 'p-V 図に囲まれた図形(長方形・三角形など)があり、「熱効率を求めよ」と問われたときです。', how: ['1サイクルで気体がした正味の仕事は、グラフが囲む面積です。', '各過程で Q＞0(吸収)か Q＜0(放出)かを判定し、吸収した熱だけを合計します。', '熱効率 e＝W/Q吸収 を計算します。放出した熱を分母に入れないよう注意します。'], ex: { q: 'ある熱機関の気体は、1サイクルの間に高温の物体から 500 J の熱を吸収し、低温の物体へ 300 J の熱を放出した。熱効率を求めよ。', a: '0.40', exp: '1サイクルでは内部エネルギーがもとにもどるので ΔU＝0。正味の仕事は W＝500−300＝200 J。熱効率は e＝W/Q吸収＝200/500＝0.40 です。分母を 500＋300 にしないことがポイントです。' } },
      { name: '断熱変化:熱の出入りなしで温度がどう変わるか', freq: 'よく出る', when: '「断熱」「急激に圧縮(膨張)」「熱を通さない容器」と書かれている問題です。', how: ['断熱なので Q＝0。第一法則より ΔU＝−W(気体がした仕事の分だけ内部エネルギーが減る)です。', '圧縮されると(W＜0)内部エネルギーが増えて温度が上がり、膨張すると温度が下がります。', '量の計算が必要なら pV^γ＝一定(単原子分子で γ＝5/3)を使います。'], ex: { q: '断熱容器内の気体を、外から 300 J の仕事をして圧縮した。気体の内部エネルギーの変化と、温度はどうなるかを答えよ。', a: '内部エネルギーは 300 J 増え、温度は上がる', exp: '断熱なので Q＝0。気体がした仕事は W＝−300 J なので、ΔU＝Q−W＝0−(−300)＝＋300 J。内部エネルギーは温度で決まるので、温度は上がります。自転車の空気入れが熱くなるのも同じしくみです。' } }
    ],
    more: [
      { lv: 1, q: '体積を一定に保ったまま、0 ℃の気体を 273 ℃にした。圧力ははじめの何倍になるか。', choices: ['1倍', '2倍', '273倍', '274倍'], a: 'B(2倍)', exp: '体積一定なら圧力は絶対温度に比例します。0 ℃＝273 K、273 ℃＝546 K で、546/273＝2倍。セ氏温度のまま比べると大きなまちがいになります。' },
      { lv: 1, q: '圧力 2.0×10⁵ Pa、体積 3.0 L の気体を、温度を一定に保って体積 6.0 L にした。圧力を求めよ。', a: '1.0×10⁵ Pa', exp: '温度一定ならボイルの法則 pV＝一定が成り立ちます。2.0×10⁵×3.0＝p×6.0 より p＝1.0×10⁵ Pa。体積が2倍で圧力は半分です。' },
      { lv: 1, q: '単原子分子の理想気体 2.0 mol が温度 300 K のとき、内部エネルギーを求めよ。(R＝8.3 J/(mol·K))', a: '約 7.5×10³ J', exp: '単原子分子の内部エネルギーは U＝(3/2)nRT です。(3/2)×2.0×8.3×300＝7470≒7.5×10³ J。分子の並進運動のエネルギーの合計です。' },
      { lv: 1, q: '体積を一定にした容器内の気体に 200 J の熱を加えた。気体がした仕事と、内部エネルギーの変化を答えよ。', a: '仕事 0 J、内部エネルギーは 200 J 増加', exp: '体積が変わらないとピストンを押さないので W＝0。第一法則 Q＝ΔU＋W より ΔU＝200 J。加えた熱がすべて内部エネルギーになり、温度が上がります。' },
      { lv: 1, q: '1000 J の熱を吸収して、250 J の仕事をする熱機関の熱効率を求めよ。', a: '0.25(25 %)', exp: '熱効率は「した仕事÷吸収した熱」で e＝250/1000＝0.25。残りの 750 J は低温の物体へ捨てられます。熱効率は必ず 1 より小さくなります。' },
      { lv: 1, q: '理想気体の等温変化について正しいものはどれか。', choices: ['内部エネルギーが増える', '吸収した熱と気体がした仕事が等しい', '気体は仕事をしない', '圧力は変わらない'], a: 'B(吸収した熱と気体がした仕事が等しい)', exp: '温度が一定なので ΔU＝0。第一法則より Q＝W となり、吸収した熱はすべて外への仕事になります。体積が変わるので圧力は変わります。' },
      { lv: 1, q: '圧力 1.0×10⁵ Pa を保ったまま、気体の体積が 2.0×10⁻³ m³ 増えた。気体が外にした仕事を求めよ。', a: '2.0×10² J', exp: '定圧変化で気体がする仕事は W＝pΔV＝1.0×10⁵×2.0×10⁻³＝200 J。p-V グラフでは、横軸との間の長方形の面積にあたります。' },
      { lv: 2, q: '単原子分子の理想気体 0.50 mol を、圧力一定で 40 K 温度上昇させるのに必要な熱量を求めよ。(R＝8.3 J/(mol·K))', a: '約 4.2×10² J', exp: '単原子分子の定圧モル比熱は Cp＝(5/2)R です。Q＝nCpΔT＝0.50×2.5×8.3×40＝415≒4.2×10² J。定積モル比熱 (3/2)R を使うと 249 J となりまちがいです。' },
      { lv: 2, q: '理想気体の絶対温度を4倍にすると、分子の二乗平均速度(速さの目安)は何倍になるか。', choices: ['2倍', '4倍', '8倍', '16倍'], a: 'A(2倍)', exp: '分子1個の平均運動エネルギー ½m⟨v²⟩＝(3/2)kT は温度に比例します。速さの2乗が4倍なので、速さは √4＝2倍です。' },
      { lv: 2, q: '大気圧 1.0×10⁵ Pa のもと、断面積 1.0×10⁻² m²、質量 10 kg のなめらかなピストンで気体を閉じこめた鉛直シリンダーがある。気体をゆっくり加熱してピストンが 0.050 m 上がったとき、気体がした仕事を求めよ。(g＝9.8 m/s²)', a: '約 55 J', exp: 'つり合いより p＝1.0×10⁵＋98/(1.0×10⁻²)＝1.098×10⁵ Pa で一定。ΔV＝1.0×10⁻²×0.050＝5.0×10⁻⁴ m³ なので W＝pΔV≒54.9≒55 J。大気を押しのける仕事とピストンを持ち上げる仕事の合計です。' },
      { lv: 2, q: '圧力 1.0×10⁵ Pa、温度 27 ℃、体積 6.0 L の気体を、圧力 2.0×10⁵ Pa、温度 127 ℃にした。体積を求めよ。', a: '4.0 L', exp: 'ボイル・シャルルの法則 pV/T＝一定を使います。V＝6.0×(1.0/2.0)×(400/300)＝4.0 L。温度は 300 K、400 K に直して使います。' },
      { lv: 2, q: 'p-V 図で、圧力 1.0×10⁵ Pa と 2.0×10⁵ Pa、体積 1.0×10⁻³ m³ と 3.0×10⁻³ m³ を頂点とする長方形のサイクルを時計回りに1周した。気体が1サイクルでした正味の仕事を求めよ。', a: '2.0×10² J', exp: '正味の仕事は囲まれた長方形の面積です。(2.0−1.0)×10⁵×(3.0−1.0)×10⁻³＝200 J。時計回りなら正(外に仕事をする)、反時計回りなら負になります。' },
      { lv: 2, q: '温度を一定に保ちながら、気体を圧縮するのに外から 150 J の仕事をした。気体が吸収した熱量を答えよ。', a: '−150 J(150 J を放出した)', exp: '等温なので ΔU＝0。気体がした仕事は W＝−150 J。Q＝ΔU＋W＝−150 J で、外にされた仕事の分の熱を外へ逃がすことで温度が一定に保たれます。' },
      { lv: 2, q: '断熱容器の中を仕切り板で2つに分け、片方に理想気体を、もう片方を真空にした。仕切りを外して気体が全体に広がったとき、気体の温度はどうなるか。', choices: ['上がる', '下がる', '変わらない', '気体の種類による'], a: 'C(変わらない)', exp: '真空へ広がるときは押しのける相手がいないので W＝0、断熱なので Q＝0。ΔU＝0 となり、理想気体の温度は変わりません(断熱自由膨張)。断熱膨張だから下がる、と早合点しないようにします。' },
      { lv: 2, q: '二原子分子の理想気体 1.0 mol を、体積一定で 10 K 温度上昇させた。吸収した熱量を求めよ。(定積モル比熱は (5/2)R、R＝8.3 J/(mol·K))', a: '約 2.1×10² J', exp: '定積なので Q＝ΔU＝nCvΔT＝1.0×2.5×8.3×10＝207.5≒2.1×10² J。二原子分子は回転の分もエネルギーをもつので、単原子分子の (3/2)R より大きくなります。' },
      { lv: 3, q: '単原子分子の理想気体を、断熱的に体積を 1/8 に圧縮した。圧力と絶対温度はそれぞれ何倍になるか。(比熱比 γ＝5/3)', a: '圧力 32 倍、温度 4 倍', exp: 'pV^γ＝一定より p は 8^(5/3)＝(8^(1/3))⁵＝2⁵＝32 倍。TV^(γ−1)＝一定より T は 8^(2/3)＝4 倍。検算:pV/T は 32×(1/8)/4＝1 で一定です。' },
      { lv: 3, q: '単原子分子の理想気体で、状態 A(p₀, V₀)→B(2p₀, V₀)→C(2p₀, 2V₀)→D(p₀, 2V₀)→A と変化させる。このサイクルの熱効率を求めよ。', a: '2/13(約 0.15)', exp: '熱を吸収するのは A→B(定積)と B→C(定圧)です。A→B:Q＝(3/2)(2p₀V₀−p₀V₀)＝1.5p₀V₀。B→C:Q＝(5/2)×2p₀×V₀＝5p₀V₀。合計 6.5p₀V₀。正味の仕事は面積 p₀V₀ なので e＝1/6.5＝2/13≒0.15。' },
      { lv: 3, q: '温度 300 K のヘリウム(モル質量 4.0×10⁻³ kg/mol)分子の二乗平均速度 √⟨v²⟩ を求めよ。(R＝8.31 J/(mol·K))', a: '約 1.4×10³ m/s', exp: '½m⟨v²⟩＝(3/2)kT を1 mol 分に直すと ⟨v²⟩＝3RT/M。√(3×8.31×300/4.0×10⁻³)＝√(1.87×10⁶)≒1.4×10³ m/s。モル質量を g/mol のまま 4.0 で入れないよう注意します。' },
      { lv: 3, q: '単原子分子の理想気体に、圧力一定で 500 J の熱を与えた。気体がした仕事と内部エネルギーの増加を求めよ。', a: '仕事 200 J、内部エネルギーの増加 300 J', exp: '定圧変化では W＝nRΔT、ΔU＝(3/2)nRΔT、Q＝(5/2)nRΔT なので W:ΔU:Q＝2:3:5。Q＝500 J なら W＝200 J、ΔU＝300 J。比で覚えておくと計算が速くなります。' },
      { lv: 3, q: '断熱容器の中で、300 K の単原子分子の理想気体 1.0 mol と、600 K の同じ気体 2.0 mol を、仕切りを外して混ぜた。全体の体積は変わらない。十分時間がたった後の温度を求めよ。', a: '500 K', exp: '外との熱・仕事のやりとりがないので内部エネルギーの合計が保存します。(3/2)R(1.0×300＋2.0×600)＝(3/2)R×3.0×T より T＝1500/3.0＝500 K。物質量で重みをつけた平均になります。' }
    ]
  });

  add('p4_wave', {
    pat: [
      { name: '波の式 y＝A sin 2π(t/T−x/λ) から波の量を読み取る', freq: 'よく出る', when: '式が与えられ、振幅・周期・波長・速さ・進む向きを問われたときです。', how: ['与えられた式を y＝A sin 2π(t/T−x/λ) の形に合わせ、A・T・λ を読み取ります。', '速さは v＝λ/T で求めます。', 't と x の符号が逆(−)なら ＋x 向き、同じ(＋)なら −x 向きに進む波です。'], ex: { q: '波の式が y＝0.20 sin 2π(t/0.50−x/4.0)(単位は m、s)で表される。振幅・周期・波長・速さと進む向きを答えよ。', a: '振幅 0.20 m、周期 0.50 s、波長 4.0 m、速さ 8.0 m/s、＋x 向き', exp: '式を見比べると A＝0.20 m、T＝0.50 s、λ＝4.0 m。v＝λ/T＝4.0/0.50＝8.0 m/s。t の項と x の項の符号が逆なので、時間がたつと同じ位相が x の大きい方へ移る、つまり ＋x 向きの波です。' } },
      { name: 'ドップラー効果:f′＝(V−u観測者)/(V−v音源)×f', freq: 'とてもよく出る', when: '音源や観測者が動いていて、「聞こえる音の振動数」を問われたときです。', how: ['「音源から観測者へ向かう向き」を正と決めます。', '音源の速度 v、観測者の速度 u をその向きの符号つきで表します。', 'f′＝(V−u)/(V−v)×f に代入します。近づくと高く、遠ざかると低くなるか最後に確かめます。'], ex: { q: '振動数 680 Hz の音を出す音源が、静止した観測者に 20 m/s で近づいている。観測者が聞く振動数を求めよ。(音速 340 m/s)', a: '約 723 Hz', exp: '音源から観測者の向きを正とすると v＝＋20、u＝0。f′＝340/(340−20)×680＝340/320×680＝722.5≒723 Hz。近づくので高くなり、結果と合っています。' } },
      { name: 'ヤングの実験:明線の間隔 Δx＝Lλ/d', freq: 'とてもよく出る', when: '2つのスリットとスクリーンがあり、「明線の間隔」や「波長」を問われたときです。', how: ['2つのスリットからの経路差は dx/L(L≫d のとき)と近似できます。', '明線の条件は 経路差＝mλ、暗線は (m＋½)λ です。', '隣り合う明線の間隔は Δx＝Lλ/d。d・L・λ のどれを変えると間隔がどうなるかもこの式で判断します。'], ex: { q: 'スリット間隔 0.50 mm の二重スリットに波長 6.0×10⁻⁷ m の光を当て、1.0 m 離れたスクリーンに干渉じまをつくった。明線の間隔を求めよ。', a: '1.2×10⁻³ m(1.2 mm)', exp: 'Δx＝Lλ/d＝(1.0×6.0×10⁻⁷)/(0.50×10⁻³)＝1.2×10⁻³ m。スリット間隔を mm から m に直すのを忘れると、1000 倍ずれた答えになります。' } },
      { name: '薄膜の干渉:反射での位相のずれを数えてから条件を立てる', freq: 'よく出る', when: 'シャボン膜・油膜・レンズのコーティングなど、薄い膜での反射光の強め合い・弱め合いを問われたときです。', how: ['膜の中の光路差は 2nd(垂直入射のとき)です。', '屈折率の小さい側から大きい側への反射では位相が π ずれます。2つの反射光のずれの回数を数えます。', 'ずれが1回なら強め合いは 2nd＝(m＋½)λ、0回か2回なら 2nd＝mλ です。'], ex: { q: '空気中にある屈折率 1.5 の薄い膜に、波長 600 nm の光を垂直に当てた。反射光が強め合う膜の厚さの最小値を求めよ。', a: '100 nm', exp: '上の面(空気→膜)の反射だけ位相が π ずれ、下の面(膜→空気)ではずれません。ずれは1回なので強め合いは 2nd＝(m＋½)λ。m＝0 で d＝λ/(4n)＝600/(4×1.5)＝100 nm です。' } },
      { name: '回折格子:d sinθ＝mλ', freq: 'よく出る', when: '「1 mm あたり ○ 本の格子」と書かれ、回折角や波長を問われたときです。', how: ['格子定数 d は「1本あたりの間隔」です。1 mm に N 本なら d＝1/N mm。', '明線の条件 d sinθ＝mλ に代入します。', '見える最大の次数は sinθ＜1 から m＜d/λ で決まります。'], ex: { q: '1 mm あたり 500 本の線を引いた回折格子に、波長 5.0×10⁻⁷ m の光を垂直に当てた。1次の明線の回折角 θ について sinθ を求めよ。', a: 'sinθ＝0.25', exp: 'd＝1/500 mm＝2.0×10⁻⁶ m。d sinθ＝1×λ より sinθ＝5.0×10⁻⁷/2.0×10⁻⁶＝0.25。ヤングの実験とちがい、角度が大きくなるので sinθ を近似せずに使います。' } }
    ],
    more: [
      { lv: 1, q: '振動数 500 Hz、波長 0.68 m の音の速さを求めよ。', a: '340 m/s', exp: '波の基本式 v＝fλ を使います。500×0.68＝340 m/s。1秒間に 500 個の波が出て、1個の長さが 0.68 m なので、1秒で 340 m 進みます。' },
      { lv: 1, q: '周期 0.25 s の波の振動数を求めよ。', a: '4.0 Hz', exp: '振動数は周期の逆数です。f＝1/T＝1/0.25＝4.0 Hz。1秒間に4回振動するということです。' },
      { lv: 1, q: '弦を伝わる波が固定端で反射するとき、反射波についての説明として正しいものはどれか。', choices: ['山は山のまま反射する', '山は谷になって反射する', '波は反射しない', '波長が半分になる'], a: 'B(山は谷になって反射する)', exp: '固定端では媒質が動けないので、入射波と反射波が打ち消し合う形になり、位相が π(半波長分)ずれます。自由端では山は山のまま反射します。' },
      { lv: 1, q: '真空中の光の速さを 3.0×10⁸ m/s とする。屈折率 1.5 のガラスの中での光の速さを求めよ。', a: '2.0×10⁸ m/s', exp: '屈折率 n の物質中では光の速さは 1/n 倍になります。3.0×10⁸/1.5＝2.0×10⁸ m/s。振動数は変わらず、波長も 1/n 倍になります。' },
      { lv: 1, q: '静止した音源に観測者が近づくとき、聞こえる音はどうなるか。', choices: ['高くなる', '低くなる', '変わらない', '大きくなるが高さは変わらない'], a: 'A(高くなる)', exp: '観測者が近づくと、1秒間に出会う波の数が増えます。そのため振動数が大きくなり、高く聞こえます。f′＝(V＋u)/V×f です。' },
      { lv: 1, q: '屈折率 1.33 の水の中を光が 3.0 cm 進んだ。光路長を求めよ。', a: '約 4.0 cm', exp: '光路長は「屈折率×実際の距離」です。1.33×3.0＝3.99≒4.0 cm。真空中なら 4.0 cm 進むのと同じ数の波が入っている、という意味です。' },
      { lv: 1, q: '両端を固定した長さ 0.60 m の弦が基本振動している。この定常波の波長を求めよ。', a: '1.2 m', exp: '基本振動では両端が節で、間に腹が1つだけです。弦の長さが半波長にあたるので λ＝2×0.60＝1.2 m。' },
      { lv: 2, q: '静止した音源が振動数 500 Hz の音を出している。観測者が音源から 17 m/s で遠ざかるとき、聞こえる振動数を求めよ。(音速 340 m/s)', a: '475 Hz', exp: '音源から観測者の向きを正とすると u＝＋17。f′＝(340−17)/340×500＝323/340×500＝475 Hz。遠ざかるので低くなります。' },
      { lv: 2, q: 'ヤングの実験で、ほかの条件はそのままにスリット間隔 d を2倍にした。明線の間隔はどうなるか。', choices: ['2倍', '1/2倍', '4倍', '変わらない'], a: 'B(1/2倍)', exp: 'Δx＝Lλ/d なので、d が2倍なら Δx は 1/2 倍です。スリットが離れるほど、少しの位置のずれで経路差が大きく変わるため、しまがつまります。' },
      { lv: 2, q: 'ヤングの実験の装置全体を、屈折率 1.33 の水の中に入れた。明線の間隔ははじめの何倍になるか。', a: '1/1.33 倍(約 0.75 倍)', exp: '水中では光の波長が λ/n になります。Δx＝Lλ/d の λ が 1/1.33 倍になるので、間隔も 1/1.33≒0.75 倍にせまくなります。' },
      { lv: 2, q: '1 mm あたり 1000 本の回折格子に単色光を垂直に当てると、1次の明線が回折角 30° の方向にできた。光の波長を求めよ。', a: '5.0×10⁻⁷ m', exp: 'd＝1/1000 mm＝1.0×10⁻⁶ m。d sinθ＝λ より λ＝1.0×10⁻⁶×sin30°＝1.0×10⁻⁶×0.50＝5.0×10⁻⁷ m(緑色の光)。' },
      { lv: 2, q: '2枚の平らなガラス板の一端に厚さ 0.030 mm の紙をはさみ、くさび形の空気層をつくった。紙とガラスの接点の距離は 0.10 m である。波長 600 nm の光を上から当てたとき、反射光のしまの間隔を求めよ。', a: '1.0×10⁻³ m(1.0 mm)', exp: '空気層の厚さが λ/2 増えるごとに次のしまができます。傾き D/L より Δx＝λL/(2D)＝(6.0×10⁻⁷×0.10)/(2×3.0×10⁻⁵)＝1.0×10⁻³ m。往復で 2 倍になることを忘れないようにします。' },
      { lv: 2, q: '一端が閉じた長さ 0.17 m の管(閉管)の基本振動数を求めよ。(音速 340 m/s、開口端補正は無視)', a: '500 Hz', exp: '閉管の基本振動は、閉じた端が節、開いた端が腹で、管の長さが 1/4 波長です。λ＝4×0.17＝0.68 m、f＝340/0.68＝500 Hz。開管なら λ＝2L になります。' },
      { lv: 2, q: '波の式 y＝0.10 sin 2π(2.0t−0.50x)(単位は m、s)で表される波の振動数・波長・速さを求めよ。', a: '振動数 2.0 Hz、波長 2.0 m、速さ 4.0 m/s', exp: 't/T＝2.0t より T＝0.50 s、f＝2.0 Hz。x/λ＝0.50x より λ＝2.0 m。v＝fλ＝4.0 m/s。係数そのものが波長ではなく、その逆数であることに注意します。' },
      { lv: 2, q: '440 Hz と 443 Hz のおんさを同時に鳴らした。1秒間に聞こえるうなりの回数を求めよ。', a: '3 回', exp: 'うなりの回数は振動数の差です。443−440＝3 回/s。楽器の調律では、うなりがなくなるように音の高さを合わせます。' },
      { lv: 3, q: '振動数 680 Hz の音源が、静止した壁に向かって 10 m/s で動いている。音源の真後ろにいる静止した観測者には、音源から直接届く音と壁からの反射音が聞こえる。1秒間のうなりの回数を求めよ。(音速 340 m/s)', a: '約 40 回', exp: '直接音は遠ざかる音源の音:340/350×680≒660.6 Hz。壁は近づく音源の音を受けて同じ振動数で反射するので、反射音は 340/330×680≒700.6 Hz。差は約 40 回/s です。' },
      { lv: 3, q: 'ヤングの実験で、一方のスリットを屈折率 1.5、厚さ 6.0 μm の透明な薄膜でおおった。波長 600 nm の光を使うとき、中央の明線(0次)は明線何本分ずれるか。', a: '5 本分(膜をおおった側へずれる)', exp: '膜によって光路長が (n−1)t＝0.5×6.0×10⁻⁶＝3.0×10⁻⁶ m 増えます。これを λ で割ると 3.0×10⁻⁶/6.0×10⁻⁷＝5。経路差 0 の点が、膜側の道のりが短くなる方へ 5 本分ずれます。' },
      { lv: 3, q: '水(屈折率 1.33)の上に広がった屈折率 1.4、厚さ 300 nm の油膜に、白色光を真上から当てた。可視光(400〜700 nm)のうち、反射光で強め合う波長を求めよ。', a: '560 nm', exp: '空気→油(1→1.4)の反射で位相が π ずれ、油→水(1.4→1.33)ではずれません。ずれ1回なので 2nd＝(m＋½)λ。2×1.4×300＝840 nm より λ＝840/(m＋0.5):m＝0 で 1680、m＝1 で 560、m＝2 で 336 nm。可視光は 560 nm だけです。' },
      { lv: 3, q: '1 mm あたり 500 本の回折格子に、波長 6.0×10⁻⁷ m の光を垂直に当てた。スクリーンに見える明線は、0次をふくめて全部で何本か(格子の正面側の半空間すべてで考える)。', a: '7 本', exp: 'd＝2.0×10⁻⁶ m。sinθ＝mλ/d＜1 より m＜2.0×10⁻⁶/6.0×10⁻⁷≒3.3。m＝0、±1、±2、±3 の 7 本です。片側だけ数えて 3 本や 4 本としないようにします。' },
      { lv: 3, q: '音源も観測者も静止していて、音源から観測者の向きに風速 10 m/s の風が吹いている。観測者が聞く音の振動数はどうなるか。', choices: ['高くなる', '低くなる', '変わらない', '風速によって高くも低くもなる'], a: 'C(変わらない)', exp: '風があると音の速さは 340＋10 m/s になりますが、波長も同じ割合で長くなります。音源と観測者が空気に対して同じ速さで動いているのと同じなので、f′＝(V＋w−w)/(V＋w−w)×f＝f で変わりません。' }
    ]
  });

  add('p4_elec', {
    pat: [
      { name: 'コンデンサーの直列・並列:電荷と電圧の分かれ方', freq: 'とてもよく出る', when: '複数のコンデンサーが電池につながれ、それぞれの電荷や電圧を問われたときです。', how: ['直列は「電荷が等しい」、並列は「電圧が等しい」をまず確認します。', '合成容量:直列は 1/C＝1/C₁＋1/C₂、並列は C＝C₁＋C₂。', '全体の電荷 Q＝CV を出してから、それぞれの電圧(V＝Q/C)や電荷に分けます。'], ex: { q: '2.0 μF と 3.0 μF のコンデンサーを直列にして、10 V の電池につないだ。合成容量、たくわえられる電荷、それぞれの電圧を求めよ。', a: '1.2 μF、12 μC、2.0 μF 側 6.0 V・3.0 μF 側 4.0 V', exp: '1/C＝1/2.0＋1/3.0＝5/6 より C＝1.2 μF。Q＝CV＝12 μC で、直列なのでどちらも 12 μC。電圧は 12/2.0＝6.0 V、12/3.0＝4.0 V で、合計 10 V になります。容量の小さい方に大きな電圧がかかります。' } },
      { name: '極板の間隔・誘電体を変える:電池につないだままか、切り離したか', freq: 'とてもよく出る', when: '「極板の間隔を2倍にする」「誘電体を入れる」と書かれた問題で、まず電池との接続の有無を確かめます。', how: ['C＝εS/d で容量の変化を出します。', '電池につないだままなら V が一定、切り離したなら Q が一定です。', '残りの量を Q＝CV、エネルギー U＝½CV²＝Q²/(2C) で出します。'], ex: { q: '電池で充電した平行板コンデンサーを電池から切り離し、極板の間隔を2倍にした。容量・電荷・電圧・静電エネルギーはそれぞれ何倍になるか。', a: '容量 1/2、電荷 1(変わらない)、電圧 2倍、エネルギー 2倍', exp: 'C＝εS/d より C は 1/2 倍。切り離したので Q は一定。V＝Q/C で 2倍、U＝Q²/(2C) で 2倍。エネルギーが増えたのは、引き合う極板を引き離す外力が仕事をしたからです。' } },
      { name: 'キルヒホッフの法則:電池が2つある回路', freq: 'よく出る', when: '電池が2つ以上あり、抵抗の直列・並列だけでは解けない回路です。', how: ['各枝の電流を向きを仮定して I₁、I₂、I₃ とおきます。', '分岐点で「入る電流＝出る電流」の式(第1法則)を立てます。', '閉回路を1周して「起電力の和＝電圧降下の和」の式(第2法則)を2つ立てて解きます。答えが負なら、仮定と逆向きです。'], ex: { q: '起電力 6.0 V の電池と 2.0 Ω の抵抗の枝、起電力 3.0 V の電池と 1.0 Ω の抵抗の枝、2.0 Ω の抵抗だけの枝の3本が、同じ2点 P、Q の間に並列につながっている(電池はどちらも P 側が正極)。2.0 Ω だけの枝を流れる電流を求めよ。(電池の内部抵抗は無視)', a: '1.5 A', exp: 'Q の電位を 0、P の電位を V とします。電池の枝の電流は (6.0−V)/2.0 と (3.0−V)/1.0、抵抗の枝は V/2.0。第1法則より (6.0−V)/2.0＋(3.0−V)＝V/2.0、6.0＝2V で V＝3.0 V。電流は 3.0/2.0＝1.5 A。3.0 V の電池には電流が流れません。' } },
      { name: '電池の内部抵抗:端子電圧 V＝E−rI', freq: 'よく出る', when: '「内部抵抗 r」「端子電圧」と書かれていたり、外の抵抗を変えたときの電流のデータが2組与えられている問題です。', how: ['回路全体で I＝E/(R＋r) を立てます。', '端子電圧は V＝E−rI(電池の中で rI だけ電圧が下がる)。', 'データが2組あれば E と r を未知数として連立します。'], ex: { q: '起電力 1.5 V、内部抵抗 0.50 Ω の電池に 2.5 Ω の抵抗をつないだ。流れる電流と端子電圧を求めよ。', a: '電流 0.50 A、端子電圧 1.25 V', exp: 'I＝E/(R＋r)＝1.5/(2.5＋0.50)＝0.50 A。端子電圧 V＝E−rI＝1.5−0.50×0.50＝1.25 V。外の抵抗の電圧 RI＝2.5×0.50＝1.25 V と一致します。' } },
      { name: 'コンデンサーをふくむ直流回路:十分時間がたった後', freq: 'よく出る', when: '抵抗とコンデンサーが混ざった回路で「スイッチを入れて十分時間がたった後」の電荷を問われたときです。', how: ['十分時間がたつと、コンデンサーには電流が流れません(その枝は切れているのと同じ)。', '残りの抵抗の回路で電流を求めます。', 'コンデンサーと並列な部分の電圧を出し、Q＝CV で電荷を求めます。'], ex: { q: '起電力 12 V の電池(内部抵抗なし)に 4.0 Ω と 2.0 Ω の抵抗を直列につなぎ、2.0 Ω の抵抗と並列に 5.0 μF のコンデンサーをつないだ。十分時間がたった後のコンデンサーの電荷を求めよ。', a: '20 μC', exp: 'コンデンサーには電流が流れないので、電流は I＝12/(4.0＋2.0)＝2.0 A。2.0 Ω の抵抗の電圧は 4.0 V で、並列のコンデンサーも 4.0 V。Q＝CV＝5.0×4.0＝20 μC です。' } }
    ],
    more: [
      { lv: 1, q: '2.0×10⁻⁶ C の点電荷2つが 0.30 m 離れて置かれている。2つの間にはたらく静電気力の大きさを求めよ。(k＝9.0×10⁹ N·m²/C²)', a: '0.40 N', exp: 'クーロンの法則 F＝kq₁q₂/r²＝9.0×10⁹×(2.0×10⁻⁶)²/0.30²＝9.0×10⁹×4.0×10⁻¹²/0.090＝0.40 N。同符号なので反発力です。' },
      { lv: 1, q: '強さ 200 V/m の一様な電場の中で、電場の向きに 0.050 m 離れた2点の電位差を求めよ。', a: '10 V', exp: '一様な電場では V＝Ed です。200×0.050＝10 V。電場の向きに進むほど電位は下がります。' },
      { lv: 1, q: '平行板コンデンサーの極板の間隔を半分にすると、電気容量はどうなるか。', choices: ['1/2倍', '2倍', '4倍', '変わらない'], a: 'B(2倍)', exp: 'C＝εS/d なので、間隔 d が半分なら容量は2倍です。極板が近いほど、同じ電圧で多くの電荷をためられます。' },
      { lv: 1, q: '電気容量 4.0 μF のコンデンサーを 50 V で充電した。たくわえられた電荷を求めよ。', a: '2.0×10⁻⁴ C', exp: 'Q＝CV＝4.0×10⁻⁶×50＝2.0×10⁻⁴ C です。μ(マイクロ)は 10⁻⁶ を表します。' },
      { lv: 1, q: '電気容量 2.0 μF のコンデンサーを 100 V で充電した。たくわえられた静電エネルギーを求めよ。', a: '1.0×10⁻² J', exp: 'U＝½CV²＝½×2.0×10⁻⁶×100²＝1.0×10⁻² J。電圧が2倍になるとエネルギーは4倍になる点が大切です。' },
      { lv: 1, q: '電気量 1.6×10⁻¹⁹ C の粒子が、電位差 100 V で加速された。粒子が得た運動エネルギーを求めよ。', a: '1.6×10⁻¹⁷ J', exp: '電場がした仕事 W＝qV＝1.6×10⁻¹⁹×100＝1.6×10⁻¹⁷ J が運動エネルギーになります。これは 100 eV にあたります。' },
      { lv: 1, q: '3.0 μF と 6.0 μF のコンデンサーの、並列接続と直列接続での合成容量をそれぞれ求めよ。', a: '並列 9.0 μF、直列 2.0 μF', exp: '並列は和で 3.0＋6.0＝9.0 μF。直列は 1/C＝1/3.0＋1/6.0＝1/2.0 より 2.0 μF。直列の合成容量はどちらよりも小さくなります(抵抗とは逆)。' },
      { lv: 2, q: '電気量 4.0×10⁻⁹ C の点電荷から 0.20 m の点での電場の強さと電位を求めよ。(k＝9.0×10⁹ N·m²/C²、無限遠を電位の基準とする)', a: '電場 9.0×10² N/C、電位 1.8×10² V', exp: 'E＝kQ/r²＝9.0×10⁹×4.0×10⁻⁹/0.040＝900 N/C。V＝kQ/r＝36/0.20＝180 V。電場は r² に、電位は r に反比例するのが違いです。' },
      { lv: 2, q: '電池につないだままの平行板コンデンサーの極板間を、比誘電率 3 の誘電体ですき間なく満たした。正しいものはどれか。', choices: ['容量3倍、電圧3倍', '容量3倍、電荷3倍', '容量1/3倍、電荷1/3倍', '容量3倍、電荷は変わらない'], a: 'B(容量3倍、電荷3倍)', exp: '誘電体で容量は ε_r 倍の3倍。電池につないだままなので電圧は一定、Q＝CV より電荷も3倍です。切り離した後なら電荷一定で電圧が 1/3 になります。' },
      { lv: 2, q: '電気量 2.0×10⁻⁶ C の点電荷を、電位 300 V の点から電位 100 V の点まで動かした。この間に静電気力がした仕事を求めよ。', a: '4.0×10⁻⁴ J', exp: '静電気力がする仕事は W＝q(V始−V終)＝2.0×10⁻⁶×(300−100)＝4.0×10⁻⁴ J。正の電荷が電位の低い方へ動くとき、静電気力は正の仕事をします。道すじにはよりません。' },
      { lv: 2, q: 'ある電池に 4.0 Ω の抵抗をつなぐと 1.2 A、2.0 Ω の抵抗をつなぐと 2.0 A の電流が流れた。電池の起電力と内部抵抗を求めよ。', a: '起電力 6.0 V、内部抵抗 1.0 Ω', exp: 'E＝I(R＋r) より E＝1.2(4.0＋r)、E＝2.0(2.0＋r)。4.8＋1.2r＝4.0＋2.0r から r＝1.0 Ω、E＝6.0 V。2組のデータを連立するのが内部抵抗の問題の型です。' },
      { lv: 2, q: 'ホイートストンブリッジで、P＝10 Ω、Q＝20 Ω、R＝15 Ω としたとき検流計の電流が 0 になった。P/Q＝R/X の関係から未知の抵抗 X を求めよ。', a: '30 Ω', exp: '検流計に電流が流れないのは、両側の分岐点の電位が等しいときで、P/Q＝R/X が成り立ちます。X＝QR/P＝20×15/10＝30 Ω。' },
      { lv: 2, q: '3.0 μF のコンデンサーを 10 V で充電してから電池を外し、充電されていない 2.0 μF のコンデンサーと並列につないだ。つないだ後の電圧と、失われた静電エネルギーを求めよ。', a: '電圧 6.0 V、失われたエネルギー 60 μJ', exp: '電荷 Q＝30 μC が保存し、合成容量 5.0 μF に分かれるので V＝30/5.0＝6.0 V。エネルギーは前 ½×3.0×10²＝150 μJ、後 ½×5.0×6.0²＝90 μJ で、60 μJ が導線のジュール熱などになります。' },
      { lv: 2, q: '静止していた電子を電位差 2.0×10³ V で加速した。電子の速さを求めよ。(電子の質量 9.1×10⁻³¹ kg、電気素量 1.6×10⁻¹⁹ C)', a: '約 2.7×10⁷ m/s', exp: '½mv²＝eV より v＝√(2eV/m)＝√(2×1.6×10⁻¹⁹×2.0×10³/9.1×10⁻³¹)＝√(7.0×10¹⁴)≒2.7×10⁷ m/s。光の速さの約 1/10 です。' },
      { lv: 2, q: '100 V で 40 W を消費する電球を、50 V の電源につないだ。消費電力を求めよ。(抵抗は一定とする)', a: '10 W', exp: '抵抗は R＝V²/P＝100²/40＝250 Ω。50 V では P＝V²/R＝2500/250＝10 W。電圧が 1/2 なので電力は 1/4 になります。' },
      { lv: 3, q: '極板の間隔 d の平行板コンデンサー(容量 C₀)の中央に、極板と平行に厚さ d/2 の金属板を入れた。容量はいくらになるか。', a: '2C₀', exp: '金属板の中は電場が 0 なので、電場がある部分の厚さは d−d/2＝d/2 になります。間隔 d/2 のコンデンサーと同じなので C＝εS/(d/2)＝2C₀。金属板の位置(中央かどうか)によりません。' },
      { lv: 3, q: '2点 P、Q の間に3本の枝が並列につながっている。枝1は起電力 10 V の電池と 2.0 Ω、枝2は起電力 4.0 V の電池と 4.0 Ω、枝3は 4.0 Ω の抵抗だけである。2つの電池はどちらも P 側が正極で、内部抵抗は無視する。枝2の電池を流れる電流の大きさと向きを答えよ。', a: '0.50 A、電池の正極から負極の向き(電池が充電される向き)', exp: 'Q を 0 V、P を V とすると (10−V)/2.0＋(4.0−V)/4.0＝V/4.0 より 24＝4V、V＝6.0 V。枝2の電流は (4.0−6.0)/4.0＝−0.50 A で、電池から押し出す向きとは逆に流れます。' },
      { lv: 3, q: 'x 軸上の原点に ＋4q、x＝3a の点に ＋q の点電荷がある。2つの電荷の間で電場が 0 になる点の x 座標を求めよ。', a: 'x＝2a', exp: '間の点 x では2つの電場が逆向きなので、大きさが等しい点を探します。k×4q/x²＝kq/(3a−x)² より 2/x＝1/(3a−x)、6a−2x＝x、x＝2a。電荷の小さい方に近い点になります。' },
      { lv: 3, q: '起電力 12 V の電池(内部抵抗なし)に 2.0 Ω と 4.0 Ω の抵抗を直列につなぎ、4.0 Ω の抵抗と並列に 2.0 μF のコンデンサーをつないだ。十分時間がたってから電池を回路から外すと、コンデンサーは 4.0 Ω の抵抗だけを通して放電した。この放電で 4.0 Ω の抵抗に発生するジュール熱を求めよ。', a: '6.4×10⁻⁵ J', exp: 'はじめ電流は 12/6.0＝2.0 A、4.0 Ω の電圧は 8.0 V なので、コンデンサーも 8.0 V。たくわえたエネルギー ½×2.0×10⁻⁶×8.0²＝6.4×10⁻⁵ J が、放電ですべて 4.0 Ω の抵抗の熱になります。' },
      { lv: 3, q: '＋1.0×10⁻⁶ C と −1.0×10⁻⁶ C の点電荷が 0.10 m 離れている。これを 0.30 m までゆっくり引き離すのに、外力がする仕事を求めよ。(k＝9.0×10⁹ N·m²/C²)', a: '6.0×10⁻² J', exp: '2つの電荷の静電エネルギーは U＝kq₁q₂/r。0.10 m では −9.0×10⁹×1.0×10⁻¹²/0.10＝−0.090 J、0.30 m では −0.030 J。外力の仕事は U の増加分で −0.030−(−0.090)＝0.060 J。引き合う電荷を離すので正の仕事が必要です。' }
    ]
  });

  add('p4_mag', {
    pat: [
      { name: '電流がつくる磁場:直線・円形・ソレノイドの使い分け', freq: 'よく出る', when: '「導線から r の点の磁場」「コイルの中心の磁場」など、電流から磁場の強さを求める問題です。', how: ['電流の形を見て式を選びます:直線 H＝I/(2πr)、円形の中心 H＝I/(2r)、ソレノイド H＝nI(n は 1 m あたりの巻数)。', '向きは右ねじの法則で決めます(電流の向きにねじを進めると、回す向きが磁場の向き)。', '磁束密度が必要なら B＝μ₀H に直します。'], ex: { q: '十分に長い直線導線に 5.0 A の電流が流れている。導線から 0.10 m の点の磁場の強さを求めよ。(π＝3.14)', a: '約 8.0 A/m', exp: 'H＝I/(2πr)＝5.0/(2×3.14×0.10)＝5.0/0.628≒8.0 A/m。円形電流の中心の式 I/(2r) とまちがえると 25 A/m になるので、電流の形をまず確認します。' } },
      { name: '電流が磁場から受ける力 F＝IBL とフレミングの左手', freq: 'よく出る', when: '磁場の中に置かれた導線(導体棒)に電流が流れていて、力の大きさや向きを問われたときです。', how: ['電流と磁場が垂直かを確かめます(斜めなら B の垂直成分を使います)。', '大きさは F＝IBL。', '向きはフレミングの左手の法則(中指が電流、人差し指が磁場、親指が力)で決めます。'], ex: { q: '磁束密度 0.50 T の一様な磁場に垂直に、長さ 0.30 m の導線を置き、2.0 A の電流を流した。導線が受ける力の大きさを求めよ。', a: '0.30 N', exp: 'F＝IBL＝2.0×0.50×0.30＝0.30 N。力の向きは電流と磁場の両方に垂直です。電流と磁場が平行なら力は 0 になります。' } },
      { name: '磁場中の荷電粒子の円運動:r＝mv/(qB)', freq: 'とてもよく出る', when: '荷電粒子が磁場に垂直に入射し、「半径」「周期」を問われたときです。', how: ['ローレンツ力 qvB が向心力になる式 mv²/r＝qvB を立てます。', 'r＝mv/(qB)。速いほど、重いほど大きな円になります。', '周期 T＝2πr/v＝2πm/(qB) は速さによりません。'], ex: { q: '質量 1.67×10⁻²⁷ kg、電気量 1.6×10⁻¹⁹ C の陽子が、速さ 1.0×10⁶ m/s で磁束密度 0.10 T の磁場に垂直に入った。円運動の半径を求めよ。', a: '約 0.10 m', exp: 'r＝mv/(qB)＝(1.67×10⁻²⁷×1.0×10⁶)/(1.6×10⁻¹⁹×0.10)＝1.67×10⁻²¹/1.6×10⁻²⁰≒0.10 m。ローレンツ力は速度と垂直なので仕事をせず、速さは変わりません。' } },
      { name: 'レール上の導体棒:誘導起電力 vBL と終端速度', freq: 'とてもよく出る', when: '平行なレールの上を導体棒が動き、抵抗につながれている問題です。', how: ['棒に生じる誘導起電力 V＝vBL、電流 I＝vBL/R を出します。', '棒は磁場から運動をさまたげる向きに F＝IBL＝B²L²v/R の力を受けます。', '一定の力で引くと、速さが増えるほど逆向きの力が増え、つり合ったところで等速(終端速度)になります。'], ex: { q: '間隔 0.40 m の水平なレールが抵抗 2.0 Ω につながれ、鉛直に磁束密度 0.50 T の磁場がある。レール上の導体棒を一定の力 0.20 N で引くとき、棒の最終的な速さを求めよ。(摩擦と棒・レールの抵抗は無視)', a: '10 m/s', exp: '終端速度では引く力と電磁力がつり合います:F＝B²L²v/R。v＝FR/(B²L²)＝0.20×2.0/(0.50²×0.40²)＝0.40/0.040＝10 m/s。このとき引く力の仕事率 Fv＝2.0 W が、抵抗の消費電力 V²/R＝2.0²/2.0＝2.0 W と一致します。' } },
      { name: 'ファラデーの電磁誘導の法則 V＝NΔΦ/Δt', freq: 'よく出る', when: 'コイルを貫く磁束が変化する(磁石を動かす、磁場が変わる、コイルが回る)問題です。', how: ['磁束 Φ＝BS を、変化の前後で求めます。', 'V＝N×(ΔΦ/Δt) で誘導起電力の大きさを出します。', '向きはレンツの法則(磁束の変化をさまたげる向き)で決めます。'], ex: { q: '巻数 100 のコイルを貫く磁束が、0.10 s の間に 0 から 2.0×10⁻³ Wb に一定の割合で増えた。誘導起電力の大きさを求めよ。', a: '2.0 V', exp: 'V＝NΔΦ/Δt＝100×2.0×10⁻³/0.10＝2.0 V。巻数をかけ忘れると 0.020 V になるので注意します。' } },
      { name: '交流:実効値とリアクタンス', freq: 'よく出る', when: '「実効値」「最大値」や、コイル・コンデンサーに交流を流したときの電流を問われたときです。', how: ['実効値＝最大値÷√2。家庭の 100 V は実効値です。', 'コイルのリアクタンス X_L＝ωL、コンデンサーは X_C＝1/(ωC)(ω＝2πf)。', '電流の実効値は I＝V/X。コイルとコンデンサーは平均の消費電力が 0 です。'], ex: { q: '実効値 100 V、周波数 50 Hz の交流電源に、自己インダクタンス 0.20 H のコイルをつないだ。電圧の最大値とコイルのリアクタンスを求めよ。(√2＝1.41、π＝3.14)', a: '最大値 141 V、リアクタンス 約 63 Ω', exp: '最大値＝実効値×√2＝141 V。X_L＝2πfL＝2×3.14×50×0.20＝62.8≒63 Ω。電流の実効値は 100/62.8≒1.6 A になります。' } }
    ],
    more: [
      { lv: 1, q: '紙面の表から裏へ向かう直線電流のまわりにできる磁場の向きはどれか(紙面を見ている向きで答える)。', choices: ['時計回り', '反時計回り', '電流と同じ向き', '電流から遠ざかる向き'], a: 'A(時計回り)', exp: '右ねじを紙面の裏へ進めるときに回す向きは、手前から見て時計回りです。右ねじの法則で、ねじの進む向き＝電流、回す向き＝磁場です。' },
      { lv: 1, q: '1 m あたりの巻数が 1000 回のソレノイドに 2.0 A の電流を流した。内部の磁場の強さを求めよ。', a: '2.0×10³ A/m', exp: 'ソレノイド内部の磁場は H＝nI＝1000×2.0＝2000 A/m で、内部ではほぼ一様です。全体の巻数ではなく 1 m あたりの巻数を使います。' },
      { lv: 1, q: '真空中で磁場の強さが 2.0×10³ A/m のとき、磁束密度を求めよ。(μ₀＝4π×10⁻⁷ N/A²、π＝3.14)', a: '約 2.5×10⁻³ T', exp: 'B＝μ₀H＝4×3.14×10⁻⁷×2.0×10³≒2.5×10⁻³ T。磁束密度の単位 T(テスラ)は Wb/m² と同じです。' },
      { lv: 1, q: '磁束密度 0.20 T の一様な磁場に垂直に、長さ 0.50 m の導線を置いて 3.0 A の電流を流した。導線が受ける力の大きさを求めよ。', a: '0.30 N', exp: 'F＝IBL＝3.0×0.20×0.50＝0.30 N。電流と磁場が垂直なとき力は最大になります。' },
      { lv: 1, q: '最大値が 141 V の交流電圧の実効値を求めよ。(√2＝1.41)', a: '100 V', exp: '実効値＝最大値÷√2＝141÷1.41＝100 V。実効値は、同じ電力を出す直流の電圧にあたります。' },
      { lv: 1, q: 'コイルに棒磁石の N 極を近づけた。コイルに流れる誘導電流がつくる磁場について正しいものはどれか。', choices: ['磁石側に N 極ができて反発する', '磁石側に S 極ができて引き合う', '磁場はできない', '磁石を止めても電流が流れ続ける'], a: 'A(磁石側に N 極ができて反発する)', exp: 'レンツの法則より、誘導電流は磁束の変化をさまたげる向きに流れます。N 極が近づいて磁束が増えるのをさまたげるため、磁石側に N 極ができて押し返します。' },
      { lv: 1, q: '磁束密度 0.40 T の一様な磁場に垂直に、面積 0.050 m² の平面がある。この面を貫く磁束を求めよ。', a: '2.0×10⁻² Wb', exp: 'Φ＝BS＝0.40×0.050＝0.020 Wb。磁束は「面を貫く磁力線の本数」のイメージです。面が磁場と平行なら 0 になります。' },
      { lv: 2, q: '磁束密度 0.50 T の鉛直な磁場の中で、間隔 0.20 m の水平なレール上の導体棒を 2.0 m/s で動かした。レールには 0.40 Ω の抵抗がつながっている。流れる電流と、棒が磁場から受ける力の大きさを求めよ。', a: '電流 0.50 A、力 0.050 N', exp: '誘導起電力 V＝vBL＝2.0×0.50×0.20＝0.20 V。I＝V/R＝0.50 A。力 F＝IBL＝0.50×0.50×0.20＝0.050 N で、運動をさまたげる向きです。' },
      { lv: 2, q: '平行な2本の導線に、同じ向きの電流を流した。導線どうしにはたらく力はどれか。', choices: ['引き合う', '反発し合う', '力ははたらかない', '片方だけが力を受ける'], a: 'A(引き合う)', exp: '一方の電流がつくる磁場から、もう一方の電流が力を受けます。フレミングの左手の法則で向きを調べると、同じ向きの電流は引き合い、逆向きなら反発します。' },
      { lv: 2, q: '電子(質量 9.1×10⁻³¹ kg、電気量 1.6×10⁻¹⁹ C)が、磁束密度 1.0×10⁻³ T の一様な磁場の中で等速円運動している。周期を求めよ。(π＝3.14)', a: '約 3.6×10⁻⁸ s', exp: 'T＝2πm/(eB)＝2×3.14×9.1×10⁻³¹/(1.6×10⁻¹⁹×1.0×10⁻³)≒3.6×10⁻⁸ s。周期は速さによらないので、速さが与えられていなくても求められます。' },
      { lv: 2, q: '自己インダクタンス 0.50 H のコイルを流れる電流が、0.10 s の間に一定の割合で 2.0 A 変化した。コイルに生じる誘導起電力の大きさを求めよ。', a: '10 V', exp: '自己誘導の起電力は V＝LΔI/Δt＝0.50×2.0/0.10＝10 V。向きは電流の変化をさまたげる向きです。' },
      { lv: 2, q: '相互インダクタンス 0.20 H の2つのコイルがある。1次コイルの電流が 0.050 s の間に一定の割合で 3.0 A 変化したとき、2次コイルに生じる誘導起電力の大きさを求めよ。', a: '12 V', exp: '相互誘導の起電力は V₂＝MΔI₁/Δt＝0.20×3.0/0.050＝12 V。変圧器はこのしくみで電圧を変えています。' },
      { lv: 2, q: '自己インダクタンス 0.40 H のコイルに 3.0 A の電流が流れている。コイルにたくわえられているエネルギーを求めよ。', a: '1.8 J', exp: 'U＝½LI²＝½×0.40×3.0²＝1.8 J。コンデンサーの ½CV² と同じ形で、L が質量、I が速さにあたると考えると覚えやすいです。' },
      { lv: 2, q: '1次コイル 1000 回、2次コイル 100 回の理想的な変圧器の1次側に 100 V の交流をかけた。2次側の電圧と、1次電流:2次電流の比を求めよ。', a: '10 V、1:10', exp: '電圧は巻数に比例するので V₂＝100×100/1000＝10 V。理想変圧器では電力が保存する(V₁I₁＝V₂I₂)ので、電流は巻数に反比例し 1:10 です。' },
      { lv: 2, q: '電気容量 10 μF のコンデンサーの、周波数 50 Hz の交流に対するリアクタンスを求めよ。(π＝3.14)', a: '約 3.2×10² Ω', exp: 'X_C＝1/(2πfC)＝1/(2×3.14×50×10×10⁻⁶)≒318≒3.2×10² Ω。周波数が高いほど小さくなり、交流を通しやすくなります(コイルとは逆)。' },
      { lv: 3, q: '電場 E＝2.0×10⁴ V/m と磁束密度 B＝0.10 T の磁場が互いに垂直にかかった領域に、両方に垂直な向きで荷電粒子を入射させた。まっすぐ進む粒子の速さを求めよ。', a: '2.0×10⁵ m/s', exp: '静電気力 qE とローレンツ力 qvB が逆向きでつり合うとき直進します。qE＝qvB より v＝E/B＝2.0×10⁴/0.10＝2.0×10⁵ m/s。電気量や質量によらず速さだけで選ばれます(速度選択器)。' },
      { lv: 3, q: '自己インダクタンス 2.0 mH のコイルと電気容量 8.0 μF のコンデンサーでつくった電気振動回路の固有振動数を求めよ。(π＝3.14)', a: '約 1.3×10³ Hz', exp: 'f＝1/(2π√(LC))。LC＝2.0×10⁻³×8.0×10⁻⁶＝1.6×10⁻⁸、√(LC)≒1.26×10⁻⁴ s。f＝1/(6.28×1.26×10⁻⁴)≒1.3×10³ Hz。単位を mH、μF から直すのが要注意点です。' },
      { lv: 3, q: '鉛直に立てた間隔 0.20 m の2本のレールの上端を 0.50 Ω の抵抗でつなぎ、レール面に垂直に磁束密度 0.50 T の磁場をかけた。質量 0.020 kg の導体棒をレールにそって静かに落とすと、やがて一定の速さになった。その速さを求めよ。(g＝9.8 m/s²、摩擦・空気抵抗・棒とレールの抵抗は無視)', a: '9.8 m/s', exp: '一定の速さでは重力と電磁力がつり合います:mg＝B²L²v/R。v＝mgR/(B²L²)＝0.020×9.8×0.50/(0.25×0.040)＝0.098/0.010＝9.8 m/s。重力の仕事率 mgv がすべて抵抗のジュール熱になります。' },
      { lv: 3, q: '質量 m、電気量 q(＞0)の粒子が、一様な磁場(磁束密度 B)に対して 60° の角をなす向きに速さ v で入射した。粒子はらせん運動をする。らせんの半径と、1周する間に磁場の向きに進む距離(ピッチ)を求めよ。', a: '半径 √3mv/(2qB)、ピッチ πmv/(qB)', exp: '速度を磁場に垂直な成分 v sin60°＝(√3/2)v と平行な成分 v cos60°＝v/2 に分けます。垂直成分で円運動:r＝m(√3/2)v/(qB)。周期 2πm/(qB) の間に平行成分で進むので、ピッチは (v/2)×2πm/(qB)＝πmv/(qB)。' },
      { lv: 3, q: '1辺 0.10 m、抵抗 0.20 Ω の正方形コイルが、磁束密度 0.40 T の一様な磁場の領域に、一定の速さ 0.50 m/s で入っていく(コイル面は磁場に垂直)。コイルの一部だけが磁場に入っている間の、誘導電流の大きさと、速さを一定に保つための外力の仕事率を求めよ。', a: '電流 0.10 A、仕事率 2.0×10⁻³ W', exp: '磁場に入った辺だけが起電力を生み V＝vBL＝0.50×0.40×0.10＝0.020 V、I＝0.020/0.20＝0.10 A。電磁力 F＝IBL＝4.0×10⁻³ N とつり合う外力の仕事率は Fv＝2.0×10⁻³ W で、I²R＝2.0×10⁻³ W と一致します。' }
    ]
  });

  add('p4_atom', {
    pat: [
      { name: '光電効果:最大運動エネルギー K＝hν−W', freq: 'とてもよく出る', when: '光の波長(振動数)と金属の仕事関数が与えられ、飛び出す電子のエネルギーを問われたときです。', how: ['光子1個のエネルギー E＝hν＝hc/λ を求めます。', 'eV 単位にそろえると計算が楽です(1 eV＝1.6×10⁻¹⁹ J)。', 'K＝E−W。E＜W なら電子は飛び出しません(光の強さによらない)。'], ex: { q: '仕事関数 2.0 eV の金属に、波長 4.0×10⁻⁷ m の光を当てた。飛び出す電子の運動エネルギーの最大値を eV で求めよ。(h＝6.6×10⁻³⁴ J·s、c＝3.0×10⁸ m/s、1 eV＝1.6×10⁻¹⁹ J)', a: '約 1.1 eV', exp: 'E＝hc/λ＝6.6×10⁻³⁴×3.0×10⁸/4.0×10⁻⁷＝4.95×10⁻¹⁹ J。eV に直すと 4.95×10⁻¹⁹/1.6×10⁻¹⁹≒3.1 eV。K＝3.1−2.0≒1.1 eV です。' } },
      { name: '光電効果のグラフ:K-ν 直線の傾きと切片', freq: 'よく出る', when: '横軸が振動数、縦軸が電子の運動エネルギー(または阻止電圧)のグラフが与えられたときです。', how: ['K＝hν−W は傾き h の直線です(金属によらず傾きは同じ)。', '横軸との交点が限界振動数 ν₀、縦軸の切片が −W です。', '阻止電圧 V のグラフなら eV＝hν−W なので、傾きは h/e になります。'], ex: { q: 'ある金属の限界振動数は 5.0×10¹⁴ Hz である。この金属の仕事関数を eV で求めよ。(h＝6.6×10⁻³⁴ J·s、1 eV＝1.6×10⁻¹⁹ J)', a: '約 2.1 eV', exp: '限界振動数では K＝0 なので W＝hν₀＝6.6×10⁻³⁴×5.0×10¹⁴＝3.3×10⁻¹⁹ J。eV に直して 3.3/1.6≒2.1 eV。グラフでは横軸との交点がこの ν₀ です。' } },
      { name: '電子のド・ブロイ波長:λ＝h/(mv)＝h/√(2meV)', freq: 'よく出る', when: '「電圧 V で加速した電子の波長」「電子線の回折」を問われたときです。', how: ['運動エネルギー ½mv²＝eV から運動量 p＝mv＝√(2meV) を求めます。', 'λ＝h/p に代入します。', '電圧が4倍なら波長は 1/2 倍、のように比で考えることもできます。'], ex: { q: '静止していた電子を 150 V で加速した。電子のド・ブロイ波長を求めよ。(h＝6.63×10⁻³⁴ J·s、電子の質量 9.1×10⁻³¹ kg、e＝1.6×10⁻¹⁹ C)', a: '約 1.0×10⁻¹⁰ m', exp: 'p＝√(2meV)＝√(2×9.1×10⁻³¹×1.6×10⁻¹⁹×150)≒6.6×10⁻²⁴ kg·m/s。λ＝h/p＝6.63×10⁻³⁴/6.6×10⁻²⁴≒1.0×10⁻¹⁰ m。原子の間隔くらいなので、結晶で回折します。' } },
      { name: '水素原子のエネルギー準位と放出される光', freq: 'とてもよく出る', when: '「n＝3 から n＝2 に移るときに出る光」など、準位の間の移り変わりを問われたときです。', how: ['エネルギー準位 E_n＝−13.6/n² eV を使います。', '放出される光子のエネルギーは準位の差 E上−E下 です。', '波長は λ＝hc/E。λ(nm)≒1240/E(eV) を使うと速く計算できます。'], ex: { q: '水素原子の電子が n＝3 から n＝2 の準位に移るとき放出される光のエネルギー(eV)と波長を求めよ。(E_n＝−13.6/n² eV、hc＝1240 eV·nm とする)', a: '約 1.89 eV、約 656 nm', exp: 'E＝13.6×(1/2²−1/3²)＝13.6×5/36≒1.89 eV。λ＝1240/1.89≒656 nm で、赤い光(バルマー系列の最初の線)です。' } },
      { name: '半減期:(1/2)^(t/T) で残りの量を求める', freq: 'よく出る', when: '「半減期」が与えられ、ある時間後に残る量や、経過時間を問われたときです。', how: ['経過時間 t が半減期 T の何倍かを求めます。', '残る割合は (1/2)^(t/T)。', '逆に残りの割合から時間を求めるときは、1/2 を何回かけたかを数えます。'], ex: { q: '半減期 8 日の放射性物質がある。24 日後には、はじめの量のどれだけが残っているか。', a: '1/8', exp: '24÷8＝3 なので、半減期3回分です。(1/2)³＝1/8。「3回で 3/8 減る」と足し算で考えるのはまちがいです。' } },
      { name: '崩壊の回数:α・β 崩壊で質量数と原子番号を合わせる', freq: 'よく出る', when: '「²³⁸U が ²⁰⁶Pb になるまでに α 崩壊と β 崩壊を何回ずつ起こすか」という問題です。', how: ['質量数は α 崩壊でだけ 4 減るので、まず α の回数を決めます。', 'α 崩壊で原子番号は 2 ずつ減ります。そのときの原子番号を計算します。', '目標の原子番号との差を、β 崩壊(1回で ＋1)の回数で合わせます。'], ex: { q: '²³⁸₉₂U が α 崩壊と β 崩壊をくり返して ²⁰⁶₈₂Pb になった。α 崩壊と β 崩壊はそれぞれ何回か。', a: 'α 崩壊 8 回、β 崩壊 6 回', exp: '質量数の差 238−206＝32 は α 崩壊だけで減るので 32/4＝8 回。原子番号は 92−2×8＝76 になりますが、実際は 82 なので、β 崩壊で 6 増えたことになります。' } }
    ],
    more: [
      { lv: 1, q: '振動数 6.0×10¹⁴ Hz の光子1個のエネルギーを求めよ。(h＝6.63×10⁻³⁴ J·s)', a: '約 4.0×10⁻¹⁹ J', exp: 'E＝hν＝6.63×10⁻³⁴×6.0×10¹⁴≒3.98×10⁻¹⁹≒4.0×10⁻¹⁹ J。約 2.5 eV で、緑〜青の光です。' },
      { lv: 1, q: 'α 線の正体はどれか。', choices: ['電子', 'ヘリウムの原子核', '電磁波', '中性子'], a: 'B(ヘリウムの原子核)', exp: 'α 線は陽子2個と中性子2個からなる ⁴He の原子核です。β 線は電子、γ 線は波長の短い電磁波です。α 線は紙1枚で止まります。' },
      { lv: 1, q: '5.0 eV は何 J か。(1 eV＝1.6×10⁻¹⁹ J)', a: '8.0×10⁻¹⁹ J', exp: '5.0×1.6×10⁻¹⁹＝8.0×10⁻¹⁹ J。1 eV は、電子1個を 1 V で加速したときに得るエネルギーです。' },
      { lv: 1, q: '¹⁴C の半減期を 5730 年とする。11460 年後には、はじめの ¹⁴C のどれだけが残っているか。', a: '1/4', exp: '11460 年は半減期の2倍なので (1/2)²＝1/4 です。この性質を使って、遺跡の木や骨の年代を調べます。' },
      { lv: 1, q: 'β 崩壊(β⁻崩壊)で、原子核の質量数と原子番号はどうなるか。', choices: ['質量数 −4、原子番号 −2', '質量数は変わらず、原子番号 ＋1', '質量数 ＋1、原子番号は変わらず', 'どちらも変わらない'], a: 'B(質量数は変わらず、原子番号 ＋1)', exp: 'β 崩壊では中性子が陽子に変わり、電子が飛び出します。核子の数(質量数)は同じで、陽子が1個増えるので原子番号が ＋1 になります。' },
      { lv: 1, q: '光電効果で、当てる光の振動数を変えずに光を強くした。どうなるか。', choices: ['電子の最大運動エネルギーが大きくなる', '飛び出す電子の数が増える', '電子が飛び出さなくなる', '限界振動数が小さくなる'], a: 'B(飛び出す電子の数が増える)', exp: '光を強くすると光子の数が増えるので、飛び出す電子の数が増えます。光子1個のエネルギー hν は変わらないので、最大運動エネルギーは変わりません。' },
      { lv: 1, q: '²³⁵₉₂U の原子核に含まれる中性子の数を求めよ。', a: '143 個', exp: '質量数＝陽子の数＋中性子の数 です。原子番号 92 が陽子の数なので、中性子は 235−92＝143 個です。' },
      { lv: 2, q: '波長 5.0×10⁻⁷ m の光子の運動量を求めよ。(h＝6.63×10⁻³⁴ J·s)', a: '約 1.3×10⁻²⁷ kg·m/s', exp: '光子の運動量は p＝h/λ＝6.63×10⁻³⁴/5.0×10⁻⁷≒1.3×10⁻²⁷ kg·m/s。質量のない光も運動量をもつので、物に当たると押す力(光圧)を生じます。' },
      { lv: 2, q: '光電効果で、飛び出す電子の運動エネルギーの最大値が 1.5 eV であった。阻止電圧はいくらか。', a: '1.5 V', exp: '最も速い電子も止める電圧が阻止電圧で、eV₀＝K_max です。K_max＝1.5 eV なので V₀＝1.5 V。eV 単位なら数値がそのまま電圧になります。' },
      { lv: 2, q: 'X 線管に 3.0×10⁴ V の電圧をかけた。発生する X 線の最短波長を求めよ。(h＝6.63×10⁻³⁴ J·s、c＝3.0×10⁸ m/s、e＝1.6×10⁻¹⁹ C)', a: '約 4.1×10⁻¹¹ m', exp: '電子の運動エネルギー eV がすべて1個の光子になるとき波長が最も短くなります。λmin＝hc/(eV)＝1.99×10⁻²⁵/4.8×10⁻¹⁵≒4.1×10⁻¹¹ m。電圧を上げるほど短くなります。' },
      { lv: 2, q: '水素原子で、n＝2 の状態にある電子を電離させる(原子の外へ出す)のに必要な最小のエネルギーを求めよ。(E_n＝−13.6/n² eV)', a: '3.4 eV', exp: 'n＝2 のエネルギーは −13.6/4＝−3.4 eV。電離は E＝0 まで上げることなので 3.4 eV が必要です。基底状態(n＝1)からなら 13.6 eV です。' },
      { lv: 2, q: 'ある原子核の質量欠損が 0.030 u であった。結合エネルギーを MeV で求めよ。(1 u は 931 MeV に相当する)', a: '約 28 MeV', exp: '結合エネルギーは質量欠損をエネルギーに直したもの(E＝mc²)です。0.030×931≒27.9≒28 MeV。核子をばらばらにするにはこれだけのエネルギーが必要です。' },
      { lv: 2, q: 'ある放射性物質の量が、40 日で 1/16 に減った。半減期を求めよ。', a: '10 日', exp: '1/16＝(1/2)⁴ なので、40 日は半減期4回分です。半減期は 40÷4＝10 日。' },
      { lv: 2, q: '²³²₉₀Th が α 崩壊と β 崩壊をくり返して ²⁰⁸₈₂Pb になった。α 崩壊と β 崩壊はそれぞれ何回か。', a: 'α 崩壊 6 回、β 崩壊 4 回', exp: '質量数の差 232−208＝24 は α 崩壊だけで減るので 24/4＝6 回。原子番号は 90−12＝78 になり、82 との差 4 を β 崩壊4回で合わせます。' },
      { lv: 2, q: '速さ 1.0×10⁶ m/s の電子のド・ブロイ波長を求めよ。(h＝6.63×10⁻³⁴ J·s、電子の質量 9.1×10⁻³¹ kg)', a: '約 7.3×10⁻¹⁰ m', exp: 'λ＝h/(mv)＝6.63×10⁻³⁴/(9.1×10⁻³¹×1.0×10⁶)≒7.3×10⁻¹⁰ m。速さが大きいほど、また質量が大きいほど波長は短くなります。' },
      { lv: 3, q: '水素原子のライマン系列(n≧2 から n＝1 への移り変わり)で放出される光のうち、最も長い波長と最も短い波長を求めよ。(E_n＝−13.6/n² eV、hc＝1240 eV·nm)', a: '最長 約 122 nm、最短 約 91 nm', exp: '最長は差が最小の n＝2→1:13.6×(1−1/4)＝10.2 eV、1240/10.2≒122 nm。最短は n＝∞→1 の 13.6 eV で 1240/13.6≒91 nm。どちらも紫外線です。' },
      { lv: 3, q: '陽子の質量を 1.0073 u、中性子を 1.0087 u、重水素 ²H の原子核を 2.0136 u とする。²H の原子核の結合エネルギーを MeV で求めよ。(1 u は 931 MeV に相当)', a: '約 2.2 MeV', exp: '質量欠損は (1.0073＋1.0087)−2.0136＝0.0024 u。結合エネルギーは 0.0024×931≒2.2 MeV。核子1個あたりでは約 1.1 MeV で、ほかの原子核よりかなり小さい値です。' },
      { lv: 3, q: 'ある金属に振動数 8.0×10¹⁴ Hz の光を当てると阻止電圧は 1.30 V、6.0×10¹⁴ Hz の光では 0.475 V であった。プランク定数と、この金属の仕事関数(eV)を求めよ。(e＝1.6×10⁻¹⁹ C)', a: 'h＝6.6×10⁻³⁴ J·s、仕事関数 2.0 eV', exp: 'eV₀＝hν−W の2式を引くと e(1.30−0.475)＝h(2.0×10¹⁴)。h＝1.6×10⁻¹⁹×0.825/2.0×10¹⁴＝6.6×10⁻³⁴ J·s。W＝hν−eV₀＝5.28×10⁻¹⁹−2.08×10⁻¹⁹＝3.2×10⁻¹⁹ J＝2.0 eV。' },
      { lv: 3, q: '半減期 T の放射性物質が、はじめの 1/10 になるまでの時間は T の約何倍か。(log₁₀2＝0.30)', a: '約 3.3 倍', exp: '(1/2)^(t/T)＝1/10 の両辺の常用対数をとると −(t/T)×0.30＝−1。t/T＝1/0.30≒3.3。半減期3回で 1/8、4回で 1/16 なので、その間の値になり合っています。' },
      { lv: 3, q: 'X 線を物質に当てると、散乱された X 線の中に、もとより波長の長いものがふくまれる(コンプトン効果)。その理由として正しいものはどれか。', choices: ['X 線が物質中で減速するから', 'X 線光子が電子と衝突してエネルギーと運動量の一部を電子に与えるから', 'X 線が原子核に吸収されるから', 'X 線の振動数が物質によって増えるから'], a: 'B(X 線光子が電子と衝突してエネルギーと運動量の一部を電子に与えるから)', exp: '光子を粒子と考え、電子との衝突でエネルギーと運動量が保存するとすると、光子のエネルギー hc/λ が減る、つまり波長が長くなることが説明できます。光の粒子性の証拠です。' }
    ]
  });

  add('c4_state', {
    pat: [
      { name: '液体が残るかどうかの判定:「全部気体」と仮定して蒸気圧と比べる', freq: 'とてもよく出る', when: '水やエタノールなど蒸発しやすい物質を容器に入れ、「圧力を求めよ」と問われたときで、蒸気圧の値が与えられている問題です。', how: ['まず全部が気体になったと仮定して、pV＝nRT で圧力 p仮 を計算します。', 'p仮 が蒸気圧より小さければ、本当に全部気体で、圧力は p仮 です。', 'p仮 が蒸気圧より大きければ液体が残り、圧力は蒸気圧そのものになります。気体の物質量は蒸気圧から逆算します。'], ex: { q: '容積 10 L の真空容器に水 0.10 mol を入れ、27 ℃に保った。容器内の圧力を求めよ。(27 ℃の水の蒸気圧 3.6×10³ Pa、R＝8.3×10³ Pa·L/(K·mol))', a: '3.6×10³ Pa(液体の水が残る)', exp: '全部気体と仮定すると p＝0.10×8.3×10³×300/10＝2.49×10⁴ Pa。これは蒸気圧 3.6×10³ Pa より大きく、ありえません。よって液体が残り、圧力は蒸気圧の 3.6×10³ Pa です。' } },
      { name: '混合気体:分圧＝全圧×モル分率', freq: 'よく出る', when: '2種類以上の気体が混ざっていて、それぞれの分圧や平均分子量を問われたときです。', how: ['各気体の物質量を求め、モル分率(その気体の mol÷全体の mol)を出します。', '分圧＝全圧×モル分率。分圧の和は全圧になります。', '平均分子量は「分子量×モル分率」の和です。'], ex: { q: '窒素 0.30 mol と酸素 0.10 mol の混合気体の全圧が 2.0×10⁵ Pa であった。それぞれの分圧を求めよ。', a: '窒素 1.5×10⁵ Pa、酸素 5.0×10⁴ Pa', exp: '全体は 0.40 mol なので、モル分率は窒素 0.75、酸素 0.25。分圧は 2.0×10⁵×0.75＝1.5×10⁵ Pa、2.0×10⁵×0.25＝5.0×10⁴ Pa。合計すると全圧にもどります。' } },
      { name: '凝固点降下・沸点上昇:Δt＝K×m(電解質は粒子の数で)', freq: 'とてもよく出る', when: '「凝固点(沸点)は何 ℃か」「分子量を求めよ」と問われ、モル凝固点降下(沸点上昇)が与えられている問題です。', how: ['質量モル濃度 m(溶媒 1 kg あたりの溶質の mol)を求めます。', '電解質なら、電離してできる粒子の数をかけます(NaCl は2倍、CaCl₂ は3倍)。', 'Δt＝K×m を計算します。分子量を求めるときは、Δt から m を出して逆算します。'], ex: { q: '水 1.0 kg に塩化ナトリウム 0.10 mol を溶かした水溶液の凝固点を求めよ。(水のモル凝固点降下 1.85 K·kg/mol、NaCl は完全に電離する)', a: '約 −0.37 ℃', exp: 'NaCl→Na⁺＋Cl⁻ で粒子は2倍になるので、粒子の質量モル濃度は 0.20 mol/kg。Δt＝1.85×0.20＝0.37 K で、凝固点は 0−0.37＝−0.37 ℃です。電離を忘れると −0.185 ℃になります。' } },
      { name: '浸透圧 Π＝cRT(ファントホッフの法則)', freq: 'よく出る', when: '半透膜をはさんだ溶液や、高分子の分子量を問う問題です。', how: ['モル濃度 c(mol/L)を求めます(電解質は粒子の数をかけます)。', 'Π＝cRT に代入します。R の単位が Pa·L/(K·mol) なら c は mol/L のまま使えます。', '分子量を求めるときは c＝Π/(RT) から物質量を出し、質量を割ります。'], ex: { q: '0.010 mol/L のグルコース水溶液の 27 ℃での浸透圧を求めよ。(R＝8.3×10³ Pa·L/(K·mol))', a: '約 2.5×10⁴ Pa', exp: 'Π＝cRT＝0.010×8.3×10³×300＝2.49×10⁴≒2.5×10⁴ Pa。わずか 0.010 mol/L でも、水柱にすると約 2.5 m 分の圧力になります。' } },
      { name: '溶解度と析出量:飽和溶液を冷やしたときに出る結晶', freq: 'よく出る', when: '溶解度の表や曲線が与えられ、「冷却すると何 g の結晶が析出するか」を問われたときです。', how: ['溶解度は「水 100 g に溶ける溶質の g」です。高温の飽和溶液の質量は 100＋S高 です。', '冷やすと、水 100 g あたり S高−S低 g が析出します。', '与えられた溶液の質量に合わせて比で計算します(溶液 (100＋S高) g あたり (S高−S低) g)。'], ex: { q: '硝酸カリウムの溶解度は 60 ℃で 109、20 ℃で 32 である。60 ℃の飽和水溶液 209 g を 20 ℃まで冷やすと、何 g の結晶が析出するか。', a: '77 g', exp: '60 ℃の飽和溶液 209 g は、水 100 g に 109 g が溶けたものです。20 ℃では 32 g しか溶けないので、109−32＝77 g が析出します。溶液の質量が 209 g でないときは比を使います。' } },
      { name: 'ヘンリーの法則:溶ける気体の量は分圧に比例する', freq: 'よく出る', when: '酸素・窒素・二酸化炭素などが水に溶ける量を、圧力を変えて問う問題です。', how: ['溶ける気体の物質量(または質量)は、その気体の分圧に比例します。', '水の量にも比例するので、「分圧の比×水の量の比」をかけます。', '溶けた気体の体積を「その圧力のもとで」測ると、圧力によらず一定になる点にも注意します。'], ex: { q: '酸素は分圧 1.0×10⁵ Pa のとき、ある温度で水 1.0 L に 1.4×10⁻³ mol 溶ける。同じ温度で、分圧 5.0×10⁵ Pa の酸素に水 2.0 L を接触させると、何 mol 溶けるか。', a: '1.4×10⁻² mol', exp: '分圧が5倍、水の量が2倍なので 1.4×10⁻³×5×2＝1.4×10⁻² mol。分圧が全圧ではなく、その気体だけの圧力であることに気をつけます。' } }
    ],
    more: [
      { lv: 1, q: 'ドライアイスが、液体にならずに直接気体になる変化を何というか。', choices: ['融解', '蒸発', '昇華', '凝縮'], a: 'C(昇華)', exp: '固体から直接気体になる変化(または気体から直接固体になる変化)を昇華といいます。ドライアイス(固体の CO₂)やヨウ素で見られます。' },
      { lv: 1, q: '高い山の上で水を加熱すると、100 ℃より低い温度で沸騰する。その理由として正しいものはどれか。', choices: ['空気中の酸素が少ないから', '外圧(大気圧)が低いので、蒸気圧が外圧に達する温度が低いから', '水の分子が軽くなるから', '気温が低いから'], a: 'B(外圧(大気圧)が低いので、蒸気圧が外圧に達する温度が低いから)', exp: '沸騰は、液体の蒸気圧が外圧と等しくなったときに起こります。山の上は大気圧が低いので、低い温度で蒸気圧が外圧に達し、沸点が下がります。' },
      { lv: 1, q: '圧力 1.0×10⁵ Pa、体積 4.0 L の気体を、温度一定で体積 2.0 L に圧縮した。圧力を求めよ。', a: '2.0×10⁵ Pa', exp: 'ボイルの法則 pV＝一定より、1.0×10⁵×4.0＝p×2.0 で p＝2.0×10⁵ Pa。体積が半分なら圧力は2倍です。' },
      { lv: 1, q: '27 ℃で 3.0 L の気体を、圧力一定で 127 ℃にした。体積を求めよ。', a: '4.0 L', exp: 'シャルルの法則より、体積は絶対温度に比例します。3.0×(400/300)＝4.0 L。27 と 127 のセ氏温度で比を取らないよう注意します。' },
      { lv: 1, q: '0.50 mol の気体を 27 ℃で 5.0 L の容器に入れた。圧力を求めよ。(R＝8.3×10³ Pa·L/(K·mol))', a: '約 2.5×10⁵ Pa', exp: 'p＝nRT/V＝0.50×8.3×10³×300/5.0＝2.49×10⁵≒2.5×10⁵ Pa。R の単位に L が入っているので、体積は L のまま代入できます。' },
      { lv: 1, q: 'コロイド溶液に横から強い光を当てると、光の通り道が明るく見える。この現象を何というか。', choices: ['ブラウン運動', 'チンダル現象', '電気泳動', '透析'], a: 'B(チンダル現象)', exp: 'コロイド粒子は光を散乱するほど大きいので、光の通り道が見えます。これをチンダル現象といいます。ふつうの溶液(真の溶液)では見られません。' },
      { lv: 1, q: '尿素 0.20 mol を水 500 g に溶かした。質量モル濃度を求めよ。', a: '0.40 mol/kg', exp: '質量モル濃度は「溶媒 1 kg あたりの溶質の mol」です。0.20÷0.500＝0.40 mol/kg。溶液ではなく溶媒の質量で割ります。' },
      { lv: 2, q: 'ある気体 1.6 g を 1.0 L の容器に入れると、27 ℃で圧力が 1.0×10⁵ Pa になった。この気体の分子量を求めよ。(R＝8.3×10³ Pa·L/(K·mol))', a: '約 40', exp: 'pV＝(w/M)RT より M＝wRT/(pV)＝1.6×8.3×10³×300/(1.0×10⁵×1.0)≒39.8≒40。アルゴンの原子量に近い値です。' },
      { lv: 2, q: '窒素と酸素が物質量の比 4:1 で混ざった空気の平均分子量を求めよ。(N₂＝28、O₂＝32)', a: '28.8', exp: '平均分子量は「分子量×モル分率」の和です。28×0.80＋32×0.20＝22.4＋6.4＝28.8。空気より分子量が大きい気体(CO₂ など)は空気より重いと判断できます。' },
      { lv: 2, q: 'ある非電解質 3.0 g を水 100 g に溶かすと、凝固点が 0.37 K 下がった。この物質の分子量を求めよ。(水のモル凝固点降下 1.85 K·kg/mol)', a: '150', exp: 'Δt＝Km より m＝0.37/1.85＝0.20 mol/kg。水 0.100 kg なので溶質は 0.020 mol。分子量は 3.0÷0.020＝150 です。' },
      { lv: 2, q: '次の水溶液(いずれも 0.10 mol/kg)のうち、沸点が最も高いものはどれか。(電解質は完全に電離するとする)', choices: ['グルコース', '尿素', '塩化ナトリウム', '塩化カルシウム'], a: 'D(塩化カルシウム)', exp: '沸点上昇は溶けている粒子の数に比例します。CaCl₂→Ca²⁺＋2Cl⁻ で粒子が3倍(0.30 mol/kg)になり、最も大きくなります。NaCl は2倍、グルコース・尿素は1倍です。' },
      { lv: 2, q: 'あるタンパク質 1.0 g を水に溶かして 100 mL にすると、27 ℃での浸透圧が 2.49×10² Pa であった。このタンパク質の分子量を求めよ。(R＝8.3×10³ Pa·L/(K·mol))', a: '1.0×10⁵', exp: 'c＝Π/(RT)＝249/(8.3×10³×300)＝1.0×10⁻⁴ mol/L。0.100 L 中の物質量は 1.0×10⁻⁵ mol。分子量＝1.0÷1.0×10⁻⁵＝1.0×10⁵。高分子では凝固点降下より浸透圧の方が測りやすいです。' },
      { lv: 2, q: '気体を 27 ℃で水上置換で集めたところ、容器内の全圧が 1.0×10⁵ Pa であった。集めた気体の分圧を求めよ。(27 ℃の水の蒸気圧 3.6×10³ Pa)', a: '9.64×10⁴ Pa', exp: '水上置換で集めた気体には、飽和した水蒸気が混ざっています。気体の分圧＝全圧−水蒸気圧＝1.0×10⁵−3.6×10³＝9.64×10⁴ Pa。' },
      { lv: 2, q: '正に帯電した水酸化鉄(Ⅲ)のコロイドを、少量で最も効率よく沈殿(凝析)させるイオンはどれか。', choices: ['Cl⁻', 'NO₃⁻', 'SO₄²⁻', 'PO₄³⁻'], a: 'D(PO₄³⁻)', exp: '凝析には、コロイドと反対の符号で、価数の大きいイオンほど有効です。正のコロイドには陰イオンが効き、3価の PO₄³⁻ が最も効果が大きくなります。' },
      { lv: 2, q: '塩化カリウムの溶解度は 80 ℃で 51、20 ℃で 34 である。80 ℃の飽和水溶液 302 g を 20 ℃まで冷やすと、何 g の結晶が析出するか。', a: '34 g', exp: '80 ℃の飽和溶液 151 g(水 100 g＋KCl 51 g)を冷やすと 51−34＝17 g 析出します。302 g はその2倍なので 17×2＝34 g です。' },
      { lv: 3, q: '容積 5.0 L の真空容器に水 0.020 mol を入れ、27 ℃に保った。容器内の圧力と、液体として残る水の物質量を求めよ。(27 ℃の水の蒸気圧 3.6×10³ Pa、R＝8.3×10³ Pa·L/(K·mol))', a: '圧力 3.6×10³ Pa、液体の水 約 0.013 mol', exp: '全部気体なら 0.020×8.3×10³×300/5.0≒9.96×10³ Pa で、蒸気圧より大きいので液体が残ります。気体の水は n＝pV/(RT)＝3.6×10³×5.0/(8.3×10³×300)≒0.0072 mol。液体は 0.020−0.0072≒0.013 mol です。' },
      { lv: 3, q: '硫酸銅(Ⅱ)(無水物)の溶解度は 60 ℃で 40、20 ℃で 20 である。60 ℃の飽和水溶液 140 g を 20 ℃まで冷やすと、硫酸銅(Ⅱ)五水和物 CuSO₄·5H₂O が何 g 析出するか。(CuSO₄＝160、CuSO₄·5H₂O＝250)', a: '約 35 g', exp: '析出量を x g とすると、その中の CuSO₄ は 0.64x g。残った溶液は 20 ℃の飽和溶液なので (40−0.64x)/(140−x)＝20/120。6(40−0.64x)＝140−x より 100＝2.84x、x≒35 g。水和水も一緒に出ていくのがポイントです。' },
      { lv: 3, q: '容積 10 L の容器に水素 0.20 mol と酸素 0.20 mol を入れ、点火して完全に反応させたあと 27 ℃にもどした。容器内の全圧を求めよ。(27 ℃の水の蒸気圧 3.6×10³ Pa、R＝8.3×10³ Pa·L/(K·mol))', a: '約 2.9×10⁴ Pa', exp: '2H₂＋O₂→2H₂O より、水 0.20 mol ができ酸素が 0.10 mol 残ります。酸素の分圧は 0.10×8.3×10³×300/10≒2.49×10⁴ Pa。水は全部気体なら 4.98×10³ Pa で蒸気圧を超えるので液体が残り、分圧は 3.6×10³ Pa。合計 2.85×10⁴≒2.9×10⁴ Pa です。' },
      { lv: 3, q: '0.15 mol/L の塩化ナトリウム水溶液(生理食塩水に近い)の 37 ℃での浸透圧を求めよ。(NaCl は完全に電離する、R＝8.3×10³ Pa·L/(K·mol))', a: '約 7.7×10⁵ Pa', exp: '電離で粒子は 0.30 mol/L。Π＝cRT＝0.30×8.3×10³×310≒7.7×10⁵ Pa。血液の浸透圧とほぼ同じなので、赤血球を入れても形が変わりにくいです。温度を 310 K にするのを忘れないようにします。' },
      { lv: 3, q: '二酸化炭素の三重点の圧力は約 5.1×10⁵ Pa である。このことから言えることとして正しいものはどれか。', choices: ['1.0×10⁵ Pa のもとでは、CO₂ の固体を温めると液体を経ずに気体になる', '1.0×10⁵ Pa のもとでは、CO₂ は液体として存在できる', '圧力を上げても CO₂ は液体にならない', 'CO₂ は水と同じく、圧力を上げると融点が下がる'], a: 'A(1.0×10⁵ Pa のもとでは、CO₂ の固体を温めると液体を経ずに気体になる)', exp: '三重点より低い圧力では液体の領域がないので、固体はそのまま気体になります(昇華)。大気圧は三重点より低いので、ドライアイスは液体になりません。5.1×10⁵ Pa 以上なら液体にできます。' }
    ]
  });

  add('c4_thermo', {
    pat: [
      { name: 'ヘスの法則:熱化学の式を足し引きして目的の式をつくる', freq: 'とてもよく出る', when: '直接測れない反応(例:C から CO ができる反応)の ΔH を、ほかの反応の ΔH から求める問題です。', how: ['求めたい式に出てくる物質に注目し、与えられた式のどれに含まれるかを探します。', '左右の位置と係数を合わせるように、式を何倍かしたり、逆向き(ΔH の符号を反対)にしたりします。', '式を足し合わせ、いらない物質が消えることを確かめてから ΔH を足し算します。'], ex: { q: 'C(黒鉛)＋O₂→CO₂ ΔH＝−394 kJ、CO＋½O₂→CO₂ ΔH＝−283 kJ のとき、C(黒鉛)＋½O₂→CO の ΔH を求めよ。', a: '−111 kJ', exp: '1つ目の式から2つ目の式を引きます(2つ目を逆向きにして足す)。C＋O₂−CO−½O₂→CO₂−CO₂ より C＋½O₂→CO。ΔH＝−394−(−283)＝−111 kJ です。' } },
      { name: '生成エンタルピーから反応エンタルピーを求める', freq: 'とてもよく出る', when: '各物質の生成エンタルピー(ΔfH)の表があり、燃焼などの ΔH を問われたときです。', how: ['反応式を書き、係数をそろえます。', 'ΔH＝(生成物の ΔfH×係数の和)−(反応物の ΔfH×係数の和)。', '単体(O₂、H₂、C(黒鉛)など)の生成エンタルピーは 0 です。'], ex: { q: 'メタン CH₄ の燃焼エンタルピーを求めよ。生成エンタルピーは CH₄ −75 kJ/mol、CO₂ −394 kJ/mol、H₂O(液) −286 kJ/mol とする。', a: '−891 kJ/mol', exp: 'CH₄＋2O₂→CO₂＋2H₂O(液)。ΔH＝{−394＋2×(−286)}−{−75＋0}＝−966＋75＝−891 kJ。H₂O の係数 2 をかけ忘れないことが大切です。' } },
      { name: '結合エネルギーから反応エンタルピーを求める', freq: 'よく出る', when: '結合エネルギーの表があり、気体どうしの反応の ΔH を問われたときです。', how: ['反応物の結合をすべて切るのに必要なエネルギー(吸収)を合計します。', '生成物の結合ができるときに放出するエネルギーを合計します。', 'ΔH＝(切る結合のエネルギーの和)−(できる結合のエネルギーの和)。生成エンタルピーの式とは引く順番が逆です。'], ex: { q: '結合エネルギーが H−H 436、Cl−Cl 243、H−Cl 432(いずれも kJ/mol)のとき、H₂＋Cl₂→2HCl の ΔH を求めよ。', a: '−185 kJ', exp: '切る結合:436＋243＝679 kJ。できる結合:2×432＝864 kJ。ΔH＝679−864＝−185 kJ で発熱反応です。結合エネルギーは気体の分子についての値なので、液体がある場合は蒸発の分を考えます。' } },
      { name: '熱量測定:q＝mcΔt から1 mol あたりの ΔH へ', freq: 'よく出る', when: '水に物質を溶かしたり中和させたりして、温度が何 K 上がったかのデータがある問題です。', how: ['発生した熱量 q＝(溶液の質量)×(比熱)×(温度変化)を計算します。', '反応した物質の物質量で割り、1 mol あたりにします。', '温度が上がった(発熱)なら ΔH は負にします。単位を J から kJ に直します。'], ex: { q: '水 100 g に水酸化ナトリウム 2.0 g を溶かすと、温度が 5.0 K 上がった。NaOH の溶解エンタルピーを求めよ。(溶液の比熱 4.2 J/(g·K)、溶液の質量は 100 g とみなす、NaOH＝40)', a: '−42 kJ/mol', exp: 'q＝100×4.2×5.0＝2100 J＝2.1 kJ。NaOH は 2.0/40＝0.050 mol なので、1 mol あたり 2.1/0.050＝42 kJ。発熱なので ΔH＝−42 kJ/mol です。' } },
      { name: '燃焼で出た熱から混合気体の組成を決める', freq: 'よく出る', when: '2種類の燃料の混合物を燃やした熱量と、全体の物質量が与えられている問題です。', how: ['2つの成分の物質量を x、y とおきます。', '物質量の和の式と、熱量の和の式(燃焼エンタルピー×物質量)を立てます。', '連立して解き、答えを代入して熱量が合うか確かめます。'], ex: { q: '水素とメタンの混合気体 0.50 mol を完全燃焼させると 264 kJ の熱が出た。それぞれの物質量を求めよ。(燃焼エンタルピー:水素 −286 kJ/mol、メタン −891 kJ/mol、水は液体)', a: '水素 0.30 mol、メタン 0.20 mol', exp: '水素 x mol、メタン y mol とすると x＋y＝0.50、286x＋891y＝264。x＝0.50−y を代入して 143＋605y＝264、y＝0.20、x＝0.30。検算:85.8＋178.2＝264 kJ。' } }
    ],
    more: [
      { lv: 1, q: '反応エンタルピー ΔH が負の値になる反応はどれか。', choices: ['発熱反応', '吸熱反応', '状態変化しない反応', '反応速度が大きい反応'], a: 'A(発熱反応)', exp: '発熱反応では物質のもつエンタルピーが減り、そのぶんが熱として外に出るので ΔH＜0 です。吸熱反応では ΔH＞0 になります。' },
      { lv: 1, q: '燃焼エンタルピーの説明として正しいものはどれか。', choices: ['物質 1 g が燃えるときの熱', '物質 1 mol が完全燃焼するときの ΔH', '酸素 1 mol が反応するときの ΔH', '1 mol の物質が単体からできるときの ΔH'], a: 'B(物質 1 mol が完全燃焼するときの ΔH)', exp: '燃焼エンタルピーは「物質 1 mol が完全燃焼するときの反応エンタルピー」です。D は生成エンタルピーの説明です。どの物質の 1 mol かを必ず確認します。' },
      { lv: 1, q: '黒鉛(炭素)の燃焼エンタルピーは −394 kJ/mol である。黒鉛 6.0 g を完全燃焼させたときに発生する熱量を求めよ。(C＝12)', a: '197 kJ', exp: '6.0 g は 6.0/12＝0.50 mol です。発生する熱は 394×0.50＝197 kJ。ΔH で表すと −197 kJ です。' },
      { lv: 1, q: '中和エンタルピーを −56 kJ/mol とする。0.10 mol の塩酸と 0.10 mol の水酸化ナトリウムが中和したときに発生する熱量を求めよ。', a: '5.6 kJ', exp: '中和エンタルピーは、水 1 mol ができるときの値です。水は 0.10 mol できるので 56×0.10＝5.6 kJ の熱が出ます。' },
      { lv: 1, q: '水 200 g の温度を 10 K 上げるのに必要な熱量を求めよ。(水の比熱 4.2 J/(g·K))', a: '8.4 kJ', exp: 'q＝mcΔt＝200×4.2×10＝8400 J＝8.4 kJ。J と kJ の換算(1000 倍)に注意します。' },
      { lv: 1, q: '液体の水が蒸発して水蒸気になる変化について正しいものはどれか。', choices: ['発熱で ΔH＜0', '吸熱で ΔH＞0', '熱の出入りはない', '圧力によって発熱にも吸熱にもなる'], a: 'B(吸熱で ΔH＞0)', exp: '蒸発では分子どうしの引力をふり切るためにエネルギーが必要なので、吸熱です(H₂O(液)→H₂O(気) ΔH＝＋44 kJ)。汗が蒸発すると体が冷えるのはこのためです。' },
      { lv: 1, q: '生成エンタルピーが 0 であるものはどれか。', choices: ['H₂O(液)', 'CO₂(気)', 'O₂(気)', 'CH₄(気)'], a: 'C(O₂(気))', exp: '生成エンタルピーは単体からその物質 1 mol ができるときの ΔH です。O₂ はもともと最も安定な単体なので 0 です。' },
      { lv: 2, q: '2H₂＋O₂→2H₂O(液) ΔH＝−572 kJ、H₂O(液)→H₂O(気) ΔH＝＋44 kJ のとき、H₂＋½O₂→H₂O(気) の ΔH を求めよ。', a: '−242 kJ', exp: '1つ目の式を ½ 倍すると ΔH＝−286 kJ。これに2つ目の式を足すと H₂O(気) ができる式になり、ΔH＝−286＋44＝−242 kJ。水蒸気になる分だけ発熱が小さくなります。' },
      { lv: 2, q: 'エチレン C₂H₄ の燃焼エンタルピーを求めよ。生成エンタルピーは C₂H₄ ＋52 kJ/mol、CO₂ −394 kJ/mol、H₂O(液) −286 kJ/mol とする。', a: '−1412 kJ/mol', exp: 'C₂H₄＋3O₂→2CO₂＋2H₂O(液)。ΔH＝{2×(−394)＋2×(−286)}−{52}＝−1360−52＝−1412 kJ。C₂H₄ の生成エンタルピーが正なので、引くと発熱がさらに大きくなります。' },
      { lv: 2, q: '結合エネルギーを N≡N 945、H−H 436、N−H 391(いずれも kJ/mol)として、アンモニアの生成エンタルピーを求めよ。', a: '約 −47 kJ/mol', exp: '½N₂＋3/2H₂→NH₃。切る結合:½×945＋3/2×436＝472.5＋654＝1126.5 kJ。できる結合:N−H 3本で 3×391＝1173 kJ。ΔH＝1126.5−1173＝−46.5≒−47 kJ/mol です。' },
      { lv: 2, q: 'プロパン C₃H₈ の燃焼エンタルピーは −2219 kJ/mol である。プロパン 22 g を完全燃焼させたときに発生する熱量を求めよ。(C₃H₈＝44)', a: '約 1.1×10³ kJ', exp: '22 g は 22/44＝0.50 mol。発生する熱は 2219×0.50≒1110≒1.1×10³ kJ。家庭用のプロパンガスはこの大きな燃焼熱を利用しています。' },
      { lv: 2, q: 'NaOH(固)の溶解エンタルピーを −44.5 kJ/mol、中和エンタルピーを −56 kJ/mol とする。固体の NaOH 1 mol を十分な量の塩酸に加えたときの ΔH を求めよ。', a: '−100.5 kJ', exp: '固体を塩酸に入れると、「溶ける」と「中和する」の2つが同時に起こります。ヘスの法則より ΔH＝−44.5＋(−56)＝−100.5 kJ。溶解熱を忘れやすい問題です。' },
      { lv: 2, q: 'ある反応の正反応の活性化エネルギーが 180 kJ、反応エンタルピーが −90 kJ である。逆反応の活性化エネルギーを求めよ。', a: '270 kJ', exp: 'エネルギー図で、生成物は反応物より 90 kJ 低い位置にあります。山の頂上は反応物より 180 kJ 高いので、生成物からは 180＋90＝270 kJ 登ることになります。' },
      { lv: 2, q: 'メタンとプロパンの混合気体 1.0 mol を完全燃焼させると、1555 kJ の熱が出た。それぞれの物質量を求めよ。(燃焼エンタルピー:メタン −891、プロパン −2219 kJ/mol)', a: 'メタン 0.50 mol、プロパン 0.50 mol', exp: 'メタン x mol とすると 891x＋2219(1.0−x)＝1555。2219−1328x＝1555 より x＝0.50。プロパンも 0.50 mol です。検算:445.5＋1109.5＝1555 kJ。' },
      { lv: 2, q: '熱量測定で、温度の最高値を、グラフの直線部分を反応開始の時刻まで延ばして(外挿して)読み取ることがある。その理由として正しいものはどれか。', choices: ['温度計の目盛りが粗いから', '反応している間にも熱が周囲へ逃げるので、それを補正するため', '反応が終わるまで時間がかかるので、計算を楽にするため', '水の比熱が温度で変わるから'], a: 'B(反応している間にも熱が周囲へ逃げるので、それを補正するため)', exp: '実際の容器では、温度が上がる間にも熱が逃げるので、測った最高温度は本来より低くなります。一瞬で反応が終わったと考えたときの温度を、外挿して求めます。' },
      { lv: 3, q: 'C(黒鉛)→C(気) ΔH＝＋717 kJ、H−H の結合エネルギー 436 kJ/mol、CH₄ の生成エンタルピー −75 kJ/mol から、C−H の結合エネルギーを求めよ。', a: '416 kJ/mol', exp: 'C(黒鉛)＋2H₂→CH₄ を、原子にばらばらにする道で考えます。C(気)と 4H(気)にするのに 717＋2×436＝1589 kJ 必要。そこから C−H 4本ができて −75 kJ になるので 4E＝1589＋75＝1664、E＝416 kJ/mol です。' },
      { lv: 3, q: '0.50 mol/L の塩酸 100 mL と 0.50 mol/L の水酸化ナトリウム水溶液 100 mL を混ぜると、温度が 3.4 K 上がった。中和エンタルピーを求めよ。(溶液の密度 1.0 g/mL、比熱 4.2 J/(g·K))', a: '約 −57 kJ/mol', exp: '溶液は 200 g なので q＝200×4.2×3.4＝2856 J。生じた水は 0.50×0.100＝0.050 mol。1 mol あたり 2856/0.050≒5.7×10⁴ J。発熱なので ΔH≒−57 kJ/mol。溶液の質量を 100 g としないよう注意します。' },
      { lv: 3, q: '黒鉛 1.0 mol を酸素不足の状態で燃やすと、CO と CO₂ が物質量の比 1:3 でできた。発生した熱量を求めよ。(C＋½O₂→CO ΔH＝−111 kJ、C＋O₂→CO₂ ΔH＝−394 kJ)', a: '約 323 kJ', exp: 'CO が 0.25 mol、CO₂ が 0.75 mol できたので、熱量は 0.25×111＋0.75×394＝27.75＋295.5≒323 kJ。完全燃焼の 394 kJ より少なく、不完全燃焼ではエネルギーをむだにすることがわかります。' },
      { lv: 3, q: 'CaCO₃→CaO＋CO₂ は ΔH＝＋178 kJ、エントロピー変化 ΔS＝＋0.160 kJ/K の反応である。ΔG＝ΔH−TΔS が負になり、反応が自然に進むようになる温度を求めよ。(ΔH、ΔS は温度によらないとする)', a: '約 1.1×10³ K 以上', exp: 'ΔG＜0 となるのは T＞ΔH/ΔS＝178/0.160≒1.1×10³ K のときです。吸熱反応でも、気体ができて乱雑さが増す反応は、高温にすると進みます。石灰石を強く熱して生石灰をつくるのはこのためです。' },
      { lv: 3, q: 'エタノール C₂H₅OH(液)の燃焼エンタルピーは −1368 kJ/mol である。CO₂ と H₂O(液)の生成エンタルピーを −394、−286 kJ/mol として、エタノール(液)の生成エンタルピーを求めよ。', a: '−278 kJ/mol', exp: 'C₂H₅OH＋3O₂→2CO₂＋3H₂O(液)。−1368＝{2×(−394)＋3×(−286)}−x より −1368＝−1646−x、x＝−278 kJ/mol。公式を逆に使って、未知の生成エンタルピーを求める型です。' }
    ]
  });

  add('c4_rate', {
    pat: [
      { name: '平衡の量計算:「反応前・変化量・平衡時」の表', freq: 'とてもよく出る', when: '平衡定数 K と最初の物質量が与えられ、平衡時の量を問われたときです。', how: ['反応式の下に「反応前」「変化量」「平衡時」の3行の表をつくります。', '変化量を x とおき、係数の比で各物質の変化量を書きます。', '平衡時の濃度を K の式に代入して x を解きます。x が反応前の量をこえないか確かめます。'], ex: { q: 'H₂＋I₂⇄2HI の平衡定数は、ある温度で 64 である。H₂ と I₂ を 1.0 mol ずつ容器に入れてこの温度に保つと、平衡時に HI は何 mol できるか。', a: '1.6 mol', exp: 'H₂ と I₂ が x mol 反応すると、平衡時は H₂、I₂ が 1.0−x、HI が 2x。体積は約分されるので (2x)²/(1.0−x)²＝64、2x/(1.0−x)＝8 より x＝0.80。HI は 1.6 mol です。' } },
      { name: 'ルシャトリエの原理:条件を変えたら平衡はどちらへ動くか', freq: 'とてもよく出る', when: '「圧力を上げる」「温度を上げる」「物質を加える」と、平衡の移動の向きを問われたときです。', how: ['濃度:加えた物質を減らす向きへ動きます。', '圧力:圧力を上げると気体の分子の数が減る向きへ動きます(両辺の気体の係数の和を比べます)。', '温度:温度を上げると吸熱の向きへ動きます(ΔH の符号を確認します)。触媒では平衡は動きません。'], ex: { q: 'N₂＋3H₂⇄2NH₃ ΔH＝−92 kJ の平衡で、(1) 圧力を上げる (2) 温度を上げる と、平衡はそれぞれどちらへ移動するか。', a: '(1) 右(NH₃ が増える) (2) 左(NH₃ が減る)', exp: '(1) 左辺の気体は 4 分子、右辺は 2 分子なので、圧力を上げると分子の数が減る右へ動きます。(2) 正反応は発熱なので、温度を上げると吸熱の左へ動きます。' } },
      { name: '弱酸の pH:[H⁺]＝√(cKa)', freq: 'とてもよく出る', when: '酢酸などの弱酸の濃度と電離定数 Ka が与えられ、pH や電離度を問われたときです。', how: ['電離度 α が 1 よりずっと小さいとき、Ka＝cα² と近似できます。', 'α＝√(Ka/c)、[H⁺]＝cα＝√(cKa)。', 'pH＝−log[H⁺] を計算します。α が 0.05 程度より大きければ近似が使えないことに注意します。'], ex: { q: '0.10 mol/L の弱酸 HA の水溶液がある(Ka＝1.0×10⁻⁵ mol/L)。pH と電離度を求めよ。', a: 'pH 3.0、電離度 1.0×10⁻²', exp: '[H⁺]＝√(cKa)＝√(0.10×1.0×10⁻⁵)＝√(1.0×10⁻⁶)＝1.0×10⁻³ mol/L で pH＝3.0。α＝[H⁺]/c＝1.0×10⁻³/0.10＝0.010 で、1 よりずっと小さいので近似は正しいです。' } },
      { name: '緩衝液の pH:[H⁺]＝Ka×(酸の量/塩の量)', freq: 'よく出る', when: '弱酸とその塩(例:酢酸と酢酸ナトリウム)が混ざった溶液の pH を問われたときです。', how: ['塩は完全に電離し、弱酸はほとんど電離しないとみなします。', '[H⁺]＝Ka×[HA]/[A⁻] に代入します(同じ溶液なので物質量の比でもよい)。', '強酸・強塩基を少し加えた場合は、先に中和で酸と塩の量を変えてから代入します。'], ex: { q: '酢酸 0.20 mol と酢酸ナトリウム 0.10 mol を水に溶かして 1.0 L にした。pH を求めよ。(Ka＝2.0×10⁻⁵ mol/L、log₁₀2＝0.30)', a: '約 4.4', exp: '[H⁺]＝Ka×(0.20/0.10)＝2.0×10⁻⁵×2＝4.0×10⁻⁵ mol/L。pH＝5−log4＝5−0.60＝4.4。酸と塩が同じ量なら pH＝−logKa になることも覚えておきます。' } },
      { name: '溶解度積:イオン濃度の積と Ksp を比べて沈殿を判定する', freq: 'よく出る', when: '2つの溶液を混ぜたとき「沈殿が生じるか」、または「何 mol/L まで溶けるか」を問われたときです。', how: ['混ぜたあとの体積で、各イオンの濃度を計算し直します(等体積なら半分)。', 'イオン濃度の積 [Mⁿ⁺][Xⁿ⁻] を求めます。', 'Ksp より大きければ沈殿が生じ、小さければ生じません。'], ex: { q: '2.0×10⁻⁵ mol/L の硝酸銀水溶液と 2.0×10⁻⁵ mol/L の塩化ナトリウム水溶液を等体積ずつ混ぜた。AgCl の沈殿は生じるか。(AgCl の Ksp＝1.8×10⁻¹⁰ mol²/L²)', a: '生じない', exp: '等体積で混ぜると濃度は半分の 1.0×10⁻⁵ mol/L ずつ。積は 1.0×10⁻¹⁰ で、Ksp の 1.8×10⁻¹⁰ より小さいので沈殿しません。混合で薄まるのを忘れると 4.0×10⁻¹⁰ になり、判定をまちがえます。' } },
      { name: '反応速度式の次数を実験データから決める', freq: 'よく出る', when: '初濃度を変えたいくつかの実験の「初速度」の表があり、v＝k[A]ᵃ[B]ᵇ の a、b を問われたときです。', how: ['B の濃度が同じで A の濃度だけがちがう2つの実験を選びます。', 'A を2倍にして v が2倍なら a＝1、4倍なら a＝2、変わらなければ a＝0。', 'B についても同じように調べ、最後に1つの実験の値から k を求めます。'], ex: { q: 'A→生成物 の反応で、A の濃度を2倍にすると初速度が4倍になった。この反応の速度式を答えよ。また、A の濃度を3倍にすると初速度は何倍になるか。', a: 'v＝k[A]²、9倍', exp: '2倍で4倍(＝2²倍)なので2次反応で v＝k[A]²。3倍にすると 3²＝9 倍です。速度式の次数は反応式の係数からは決まらず、実験で決めることに注意します。' } }
    ],
    more: [
      { lv: 1, q: '温度を上げると反応速度が大きくなる主な理由はどれか。', choices: ['活性化エネルギーが小さくなるから', '活性化エネルギー以上のエネルギーをもつ分子の割合が増えるから', '反応エンタルピーが大きくなるから', '分子の数が増えるから'], a: 'B(活性化エネルギー以上のエネルギーをもつ分子の割合が増えるから)', exp: '温度を上げても活性化エネルギーは変わりませんが、エネルギーの大きい分子の割合が急に増えるので、山をこえられる衝突が増えます。活性化エネルギーを下げるのは触媒です。' },
      { lv: 1, q: '触媒についての説明で正しいものはどれか。', choices: ['反応エンタルピーを小さくする', '活性化エネルギーを小さくし、平衡は移動させない', '平衡を生成物の側へ移動させる', '反応の前後で別の物質に変わる'], a: 'B(活性化エネルギーを小さくし、平衡は移動させない)', exp: '触媒は活性化エネルギーの低い別の道すじをつくります。正反応も逆反応も同じように速くなるので、平衡に達するまでの時間は短くなりますが、平衡の位置や ΔH は変わりません。' },
      { lv: 1, q: 'N₂O₄⇄2NO₂ の平衡定数 K を、濃度を使った式で表せ。', a: 'K＝[NO₂]²/[N₂O₄]', exp: '平衡定数は「右辺の物質の濃度の積÷左辺の物質の濃度の積」で、係数を指数にします。NO₂ の係数 2 が2乗になります。' },
      { lv: 1, q: '0.010 mol/L の塩酸の pH を求めよ。(HCl は完全に電離する)', a: '2', exp: '[H⁺]＝0.010＝1.0×10⁻² mol/L なので pH＝2。強酸は完全に電離するので、濃度がそのまま [H⁺] になります。' },
      { lv: 1, q: '25 ℃で [OH⁻]＝1.0×10⁻³ mol/L の水溶液の pH を求めよ。(Kw＝1.0×10⁻¹⁴ mol²/L²)', a: '11', exp: '[H⁺]＝Kw/[OH⁻]＝1.0×10⁻¹⁴/1.0×10⁻³＝1.0×10⁻¹¹ mol/L で pH＝11。pOH＝3 から pH＝14−3 と求めてもよいです。' },
      { lv: 1, q: '2NO₂(赤褐色)⇄N₂O₄(無色) ΔH＜0 の平衡にある気体を冷やすと、色はどうなるか。', choices: ['濃くなる', 'うすくなる', '変わらない', '無色から赤褐色になる'], a: 'B(うすくなる)', exp: '冷やすと発熱の向き(右)へ平衡が移動し、赤褐色の NO₂ が減って無色の N₂O₄ が増えます。そのため色がうすくなります。' },
      { lv: 1, q: 'ある反応で、反応物の濃度が 60 秒間に 0.80 mol/L から 0.50 mol/L に減った。この間の平均の反応速度を求めよ。', a: '5.0×10⁻³ mol/(L·s)', exp: '反応速度は単位時間あたりの濃度の変化です。(0.80−0.50)/60＝0.30/60＝5.0×10⁻³ mol/(L·s)。' },
      { lv: 2, q: 'A＋B⇄C の反応が平衡に達したとき、[A]＝0.20、[B]＝0.40、[C]＝0.40 mol/L であった。平衡定数を求めよ。', a: '5.0 L/mol', exp: 'K＝[C]/([A][B])＝0.40/(0.20×0.40)＝5.0 L/mol。単位は濃度の次数から決まります。' },
      { lv: 2, q: '0.10 mol/L の弱酸の水溶液がある(Ka＝4.0×10⁻⁵ mol/L)。電離度と pH を求めよ。(log₁₀2＝0.30)', a: '電離度 2.0×10⁻²、pH 約 2.7', exp: 'α＝√(Ka/c)＝√(4.0×10⁻⁴)＝0.020。[H⁺]＝cα＝2.0×10⁻³ mol/L。pH＝3−log2＝3−0.30＝2.7。' },
      { lv: 2, q: '0.10 mol/L の弱塩基 B の水溶液がある(Kb＝1.0×10⁻⁵ mol/L)。25 ℃での pH を求めよ。(Kw＝1.0×10⁻¹⁴ mol²/L²)', a: '11', exp: '弱酸と同じように [OH⁻]＝√(cKb)＝√(1.0×10⁻⁶)＝1.0×10⁻³ mol/L。pOH＝3 なので pH＝14−3＝11 です。' },
      { lv: 2, q: '次の塩の水溶液のうち、酸性を示すものはどれか。', choices: ['CH₃COONa', 'NH₄Cl', 'NaCl', 'Na₂CO₃'], a: 'B(NH₄Cl)', exp: '強酸(HCl)と弱塩基(NH₃)からできた塩 NH₄Cl では、NH₄⁺ が水と反応して H⁺(H₃O⁺)を出すので酸性です。CH₃COONa と Na₂CO₃ は塩基性、NaCl は中性です。' },
      { lv: 2, q: 'N₂O₄⇄2NO₂ の平衡で、全圧が 1.0×10⁵ Pa、NO₂ のモル分率が 0.20 であった。圧平衡定数 Kp を求めよ。', a: '5.0×10³ Pa', exp: '分圧は NO₂ が 2.0×10⁴ Pa、N₂O₄ が 8.0×10⁴ Pa。Kp＝(2.0×10⁴)²/(8.0×10⁴)＝4.0×10⁸/8.0×10⁴＝5.0×10³ Pa です。' },
      { lv: 2, q: '難溶性の塩 MX の溶解度積が Ksp＝1.6×10⁻⁹ mol²/L² である。MX は純水 1 L に何 mol 溶けるか。', a: '4.0×10⁻⁵ mol', exp: '溶ける量を s mol/L とすると [M⁺]＝[X⁻]＝s で、s²＝1.6×10⁻⁹。s＝4.0×10⁻⁵ mol/L です。' },
      { lv: 2, q: '0.10 mol/L の塩化ナトリウム水溶液に AgCl を溶かすとき、溶ける Ag⁺ の濃度の最大値を求めよ。(AgCl の Ksp＝1.8×10⁻¹⁰ mol²/L²)', a: '1.8×10⁻⁹ mol/L', exp: '[Cl⁻] はほぼ 0.10 mol/L なので [Ag⁺]＝Ksp/[Cl⁻]＝1.8×10⁻¹⁰/0.10＝1.8×10⁻⁹ mol/L。純水(約 1.3×10⁻⁵ mol/L)よりずっと溶けにくくなります(共通イオン効果)。' },
      { lv: 2, q: 'A＋B→C の反応で、[B] を一定にして [A] を2倍にすると初速度は2倍、[A] を一定にして [B] を2倍にすると初速度は4倍になった。[A] と [B] を両方2倍にすると初速度は何倍になるか。', a: '8倍', exp: 'A について1次、B について2次なので v＝k[A][B]²。両方2倍なら 2×2²＝8 倍です。' },
      { lv: 3, q: 'H₂＋I₂⇄2HI(平衡定数 64)の容器に、H₂ 2.0 mol と I₂ 1.0 mol を入れて平衡にした。生成する HI の物質量を求めよ。', a: '約 1.9 mol', exp: 'x mol 反応すると (2x)²/{(2.0−x)(1.0−x)}＝64。整理して 15x²−48x＋32＝0、x＝{48−√384}/30≒0.95(もう一方の解は 1.0 をこえるので不適)。HI は 2x≒1.9 mol です。' },
      { lv: 3, q: '酢酸と酢酸ナトリウムを 0.10 mol ずつ含む水溶液 1.0 L に、塩化水素 0.010 mol を加えた。pH はいくらからいくらに変わるか。(Ka＝2.0×10⁻⁵ mol/L、log₁₀2＝0.30、log₁₀2.44＝0.39、体積変化なし)', a: '約 4.7 から約 4.6', exp: 'はじめは [H⁺]＝Ka で pH＝5−0.30＝4.7。加えた H⁺ は CH₃COO⁻ と反応し、酢酸 0.11 mol、酢酸イオン 0.09 mol になります。[H⁺]＝2.0×10⁻⁵×0.11/0.09≒2.44×10⁻⁵ で pH≒4.6。少しの酸ではほとんど変わりません。' },
      { lv: 3, q: '一次反応で、速度定数 k＝0.0231 /min である。半減期と、90 分後に残る反応物の割合を求めよ。(ln2＝0.693)', a: '半減期 30 分、残り 1/8', exp: '一次反応の半減期は t½＝ln2/k＝0.693/0.0231＝30 分で、濃度によりません。90 分は半減期3回分なので (1/2)³＝1/8 が残ります。' },
      { lv: 3, q: '0.10 mol/L の酢酸 10 mL を 0.10 mol/L の水酸化ナトリウム水溶液 10 mL でちょうど中和した。中和点の pH を求めよ。(Ka＝2.0×10⁻⁵ mol/L、Kw＝1.0×10⁻¹⁴ mol²/L²、log₁₀5＝0.70)', a: '約 8.7', exp: '酢酸ナトリウムが 0.050 mol/L になります。CH₃COO⁻ の Kb＝Kw/Ka＝5.0×10⁻¹⁰。[OH⁻]＝√(0.050×5.0×10⁻¹⁰)＝5.0×10⁻⁶。pOH＝6−0.70＝5.3、pH＝8.7。中和点が塩基性なので、指示薬はフェノールフタレインを使います。' },
      { lv: 3, q: 'N₂O₄⇄2NO₂ で、全圧 1.0×10⁵ Pa のとき N₂O₄ の解離度は 0.20 であった。同じ温度で全圧を 4.0×10⁵ Pa にすると、解離度はおよそいくらになるか。', a: '約 0.10', exp: '解離度 α のとき Kp＝4α²P/(1−α²)。はじめの値から Kp＝4×0.04×1.0×10⁵/0.96≒1.67×10⁴ Pa。P＝4.0×10⁵ では 16×10⁵α²＝1.67×10⁴(1−α²) より α²≒0.0103、α≒0.10。圧力を上げると分子が減る向きへ動くことと合っています。' }
    ]
  });

  add('c4_redox', {
    pat: [
      { name: 'ファラデーの法則:電気量→電子の物質量→生成物の量', freq: 'とてもよく出る', when: '「○ A の電流を △ 秒流した」と書かれ、析出・発生する物質の量を問われたときです。', how: ['電気量 Q＝It(C)を計算します。', '電子の物質量＝Q/(9.65×10⁴)。', '電極の反応式の係数から、電子 1 mol あたりの生成物の mol を読み取り、質量や体積にします。'], ex: { q: '硫酸銅(Ⅱ)水溶液を白金電極で電気分解し、2.0 A の電流を 965 秒流した。陰極に析出する銅の質量を求めよ。(Cu＝63.5、F＝9.65×10⁴ C/mol)', a: '約 0.64 g', exp: 'Q＝2.0×965＝1930 C、電子は 1930/9.65×10⁴＝0.020 mol。Cu²⁺＋2e⁻→Cu より銅は 0.010 mol で、0.010×63.5≒0.64 g。電子 2 mol で銅 1 mol になる点が大切です。' } },
      { name: '電気分解の電極反応を決める', freq: 'とてもよく出る', when: '水溶液と電極の種類が与えられ、「陽極・陰極で起こる反応」を問われたときです。', how: ['陰極:イオン化傾向の小さい金属イオン(Cu²⁺、Ag⁺ など)があれば金属が析出し、なければ水(H⁺)が還元されて H₂ が出ます。', '陽極:電極が Cu や Ag なら電極自身が溶けます。白金・炭素なら、Cl⁻ があれば Cl₂、なければ水が酸化されて O₂ が出ます。', '電子の数をそろえて、両極の生成物の量の関係を出します。'], ex: { q: '硫酸銅(Ⅱ)水溶液を白金電極で電気分解した。陽極と陰極で起こる反応を、電子を含む式で書け。', a: '陽極:2H₂O→O₂＋4H⁺＋4e⁻、陰極:Cu²⁺＋2e⁻→Cu', exp: '陰極では Cu²⁺ が H₂O より還元されやすいので銅が析出します。陽極は白金で溶けず、SO₄²⁻ は酸化されにくいので水が酸化され O₂ が出ます。溶液には H⁺ が増えて酸性になります。' } },
      { name: '鉛蓄電池:放電で両極の質量がどう変わるか', freq: 'よく出る', when: '鉛蓄電池で「電子が ○ mol 流れたとき、正極・負極の質量の変化」や「硫酸の濃度の変化」を問われたときです。', how: ['負極:Pb＋SO₄²⁻→PbSO₄＋2e⁻(SO₄ の分だけ重くなる)。', '正極:PbO₂＋4H⁺＋SO₄²⁻＋2e⁻→PbSO₄＋2H₂O(SO₂ の分だけ重くなる)。', '電子 2 mol あたり、負極は 96 g、正極は 64 g 増えます。電子の物質量から比で求めます。'], ex: { q: '鉛蓄電池を放電させ、電子が 0.20 mol 流れた。負極と正極の質量はそれぞれ何 g 増えるか。(O＝16、S＝32)', a: '負極 9.6 g、正極 6.4 g 増える', exp: '電子 0.20 mol で、両極とも PbSO₄ が 0.10 mol できます。負極は Pb→PbSO₄ で SO₄(96)の分、96×0.10＝9.6 g 増加。正極は PbO₂→PbSO₄ で SO₂(64)の分、64×0.10＝6.4 g 増加します。' } },
      { name: '燃料電池:使った水素と取り出せる電気量', freq: 'よく出る', when: '燃料電池で、水素の量・電流・時間のどれかから残りを求める問題です。', how: ['負極 H₂→2H⁺＋2e⁻、正極 O₂＋4H⁺＋4e⁻→2H₂O を書きます。', '水素 1 mol から電子 2 mol、酸素 1 mol で電子 4 mol です。', '電子の物質量×9.65×10⁴ で電気量にし、時間や電流に直します。'], ex: { q: '水素を燃料とする燃料電池で、水素 0.50 mol を消費した。流れた電気量を求めよ。(F＝9.65×10⁴ C/mol)', a: '9.65×10⁴ C', exp: 'H₂→2H⁺＋2e⁻ より、水素 0.50 mol から電子 1.0 mol が流れます。電気量は 1.0×9.65×10⁴＝9.65×10⁴ C。このとき酸素は 0.25 mol 使われます。' } },
      { name: '直列につないだ電解槽:どの槽も同じ電気量', freq: 'よく出る', when: '2つ以上の電解槽が直列につながれ、片方の槽の結果からもう片方の生成量を問われたときです。', how: ['直列なので、すべての電解槽に同じ電子の物質量が流れます。', 'わかっている槽の生成物から電子の物質量を求めます。', 'その電子の量を使って、もう一方の槽の生成物の量を計算します。'], ex: { q: '硝酸銀水溶液と硫酸銅(Ⅱ)水溶液の電解槽を直列につなぎ、白金電極で電気分解した。銀が 1.08 g 析出したとき、銅は何 g 析出するか。(Ag＝108、Cu＝64)', a: '0.32 g', exp: 'Ag⁺＋e⁻→Ag より、銀 0.010 mol で電子 0.010 mol。同じ電子が銅の槽にも流れ、Cu²⁺＋2e⁻→Cu なので銅は 0.0050 mol、0.0050×64＝0.32 g です。' } }
    ],
    more: [
      { lv: 1, q: '電池の負極で起こる反応はどれか。', choices: ['酸化反応(電子を失う)', '還元反応(電子を受け取る)', '中和反応', '反応は起こらない'], a: 'A(酸化反応(電子を失う))', exp: '負極では電極の物質が電子を失い(酸化)、その電子が導線を通って正極へ流れます。正極では電子を受け取る還元反応が起こります。' },
      { lv: 1, q: 'ダニエル電池を放電させたとき、質量が増える電極はどれか。', choices: ['亜鉛板', '銅板', '両方', 'どちらも変わらない'], a: 'B(銅板)', exp: '正極の銅板では Cu²⁺＋2e⁻→Cu で銅が析出し、質量が増えます。負極の亜鉛板は Zn→Zn²⁺＋2e⁻ で溶けて軽くなります。' },
      { lv: 1, q: '亜鉛板と銅板を電解質溶液に入れて電池をつくった。負極になるのはどちらか。', a: '亜鉛板', exp: 'イオン化傾向の大きい金属ほど電子を出しやすく、負極になります。亜鉛は銅よりイオン化傾向が大きいので負極です。' },
      { lv: 1, q: '電子 0.50 mol がもつ電気量の大きさを求めよ。(F＝9.65×10⁴ C/mol)', a: '約 4.8×10⁴ C', exp: '電子 1 mol の電気量がファラデー定数 9.65×10⁴ C です。0.50×9.65×10⁴≒4.8×10⁴ C。' },
      { lv: 1, q: '3.0 A の電流を 10 分間流した。流れた電気量を求めよ。', a: '1.8×10³ C', exp: 'Q＝It＝3.0×(10×60)＝1800 C。時間は秒に直してから計算します。' },
      { lv: 1, q: '塩化ナトリウム水溶液を炭素電極で電気分解したとき、陽極と陰極で発生する気体の組み合わせはどれか。', choices: ['陽極 O₂、陰極 H₂', '陽極 Cl₂、陰極 H₂', '陽極 Cl₂、陰極 Na', '陽極 H₂、陰極 Cl₂'], a: 'B(陽極 Cl₂、陰極 H₂)', exp: '陽極では Cl⁻ が酸化されて Cl₂、陰極ではイオン化傾向の大きい Na⁺ は還元されず、水が還元されて H₂ が出ます。陰極付近には OH⁻ がたまります。' },
      { lv: 1, q: '鉛蓄電池を放電させると、電解液の希硫酸の濃度はどうなるか。', choices: ['大きくなる', '小さくなる', '変わらない', 'はじめ大きくなり、あとで小さくなる'], a: 'B(小さくなる)', exp: '放電では両極で硫酸イオンが PbSO₄ になり、水ができます。硫酸が減って水が増えるので濃度は小さくなります。充電すると元にもどります。' },
      { lv: 2, q: '水酸化ナトリウム水溶液を白金電極で電気分解し、電子が 0.40 mol 流れた。陰極と陽極で発生する気体の物質量を求めよ。', a: '陰極 H₂ 0.20 mol、陽極 O₂ 0.10 mol', exp: '陰極 2H₂O＋2e⁻→H₂＋2OH⁻ で H₂ は 0.20 mol。陽極 4OH⁻→O₂＋2H₂O＋4e⁻ で O₂ は 0.10 mol。体積比 H₂:O₂＝2:1 になり、水の電気分解と同じです。' },
      { lv: 2, q: '硝酸銀水溶液を白金電極で電気分解し、5.0 A の電流を 193 秒流した。陰極に析出する銀の質量を求めよ。(Ag＝108、F＝9.65×10⁴ C/mol)', a: '1.08 g', exp: 'Q＝5.0×193＝965 C で、電子は 0.010 mol。Ag⁺＋e⁻→Ag より銀も 0.010 mol で 1.08 g。銀は電子 1 mol で 1 mol 析出します。' },
      { lv: 2, q: '銅の電解精錬について正しいものはどれか。', choices: ['純銅を陽極、粗銅を陰極にする', '粗銅を陽極にすると、金や銀は陽極の下に陽極泥としてたまる', '亜鉛や鉄も陰極に析出する', '電解液には塩化ナトリウム水溶液を使う'], a: 'B(粗銅を陽極にすると、金や銀は陽極の下に陽極泥としてたまる)', exp: '粗銅を陽極、純銅を陰極にして硫酸銅(Ⅱ)水溶液中で電気分解します。銅よりイオン化傾向の小さい金・銀はイオンにならず陽極泥に、大きい亜鉛・鉄はイオンのまま溶液に残ります。' },
      { lv: 2, q: '硫酸銅(Ⅱ)水溶液の電気分解で、陰極に銅 0.32 g を析出させたい。1.0 A の電流を何秒流せばよいか。(Cu＝64、F＝9.65×10⁴ C/mol)', a: '965 秒', exp: '銅 0.32/64＝0.0050 mol には電子 0.010 mol が必要です。電気量は 0.010×9.65×10⁴＝965 C で、1.0 A なら 965 秒です。' },
      { lv: 2, q: '水素燃料電池から 1.0 A の電流を 1 時間取り出した。消費された水素の物質量を求めよ。(F＝9.65×10⁴ C/mol)', a: '約 1.9×10⁻² mol', exp: 'Q＝1.0×3600＝3600 C で、電子は 3600/9.65×10⁴≒0.0373 mol。水素 1 mol で電子 2 mol なので、水素は 0.0373/2≒1.9×10⁻² mol です。' },
      { lv: 2, q: '鉛蓄電池から 9.65×10³ C の電気量を取り出した。消費された硫酸と、生じた水の質量を求めよ。(H₂SO₄＝98、H₂O＝18、F＝9.65×10⁴ C/mol)', a: '硫酸 9.8 g 消費、水 1.8 g 生成', exp: '電子は 0.10 mol。全体の反応 Pb＋PbO₂＋2H₂SO₄→2PbSO₄＋2H₂O は電子 2 mol の反応なので、電子 1 mol あたり硫酸 1 mol を使い水 1 mol ができます。硫酸 0.10 mol＝9.8 g、水 0.10 mol＝1.8 g です。' },
      { lv: 2, q: '陽イオン交換膜を使った塩化ナトリウム水溶液の電気分解で、電子が 0.20 mol 流れた。陰極側で得られる水酸化ナトリウムの質量を求めよ。(NaOH＝40)', a: '8.0 g', exp: '陰極で 2H₂O＋2e⁻→H₂＋2OH⁻ により OH⁻ が 0.20 mol でき、膜を通ってきた Na⁺ と合わせて NaOH 0.20 mol になります。0.20×40＝8.0 g です。' },
      { lv: 2, q: 'アルミニウム 27 g を、酸化アルミニウムの溶融塩電解でつくるのに必要な電気量を求めよ。また、水溶液ではなく融解した塩を使う理由を答えよ。(Al＝27、F＝9.65×10⁴ C/mol)', a: '約 2.9×10⁵ C。Al はイオン化傾向が大きく、水溶液では水が先に還元されて H₂ が出てしまうから。', exp: 'Al³⁺＋3e⁻→Al なので、1 mol の Al に電子 3 mol、3×9.65×10⁴≒2.9×10⁵ C 必要です。アルミの製錬に大量の電力が要るのはこのためです。' },
      { lv: 3, q: '硫酸銅(Ⅱ)水溶液に 2.0 A の電流を 9650 秒流したところ、陰極に銅が 5.72 g 析出した。電流のうち銅の析出に使われた割合(電流効率)を求めよ。(Cu＝63.5、F＝9.65×10⁴ C/mol)', a: '約 90 %', exp: '流れた電子は 2.0×9650/9.65×10⁴＝0.20 mol。銅 5.72/63.5≒0.090 mol に使われた電子は 0.18 mol。0.18/0.20＝0.90 で約 90 %。残りは水素の発生などに使われたと考えられます。' },
      { lv: 3, q: 'ダニエル電池を放電させると、亜鉛板の質量が 0.65 g 減った。銅板の質量の増加と、流れた電気量を求めよ。(Zn＝65、Cu＝64、F＝9.65×10⁴ C/mol)', a: '銅板 0.64 g 増加、電気量 1.93×10³ C', exp: '亜鉛 0.65/65＝0.010 mol が溶け、電子 0.020 mol が流れます。銅は 0.010 mol 析出して 0.64 g 増加。電気量は 0.020×9.65×10⁴＝1930 C です。' },
      { lv: 3, q: '1.0 L の硫酸銅(Ⅱ)水溶液を白金電極で電気分解し、電子 0.20 mol 分の電気量を流した。陰極では銅だけが析出したとする。電気分解後の水溶液中で、新たに生じた H⁺ による pH を求めよ。(H⁺ は完全に電離しているとみなす、log₁₀2＝0.30、体積変化なし)', a: '約 0.70', exp: '陽極 2H₂O→O₂＋4H⁺＋4e⁻ より、電子 1 mol で H⁺ 1 mol ができます。H⁺ は 0.20 mol/L で、pH＝−log(2.0×10⁻¹)＝1−0.30＝0.70。電気分解で溶液がだんだん酸性になります。' },
      { lv: 3, q: '質量パーセント濃度 35 % の希硫酸 1000 g を電解液とする鉛蓄電池から、電子 0.50 mol 分を放電させた。放電後の硫酸の質量パーセント濃度を求めよ。(H₂SO₄＝98、H₂O＝18)', a: '約 31 %', exp: 'はじめ H₂SO₄ は 350 g。電子 0.50 mol で硫酸 0.50 mol(49 g)が減り、水 0.50 mol(9.0 g)が増えます。溶液は 1000−49＋9.0＝960 g、硫酸は 301 g なので 301/960≒0.31 で約 31 %。' },
      { lv: 3, q: '1.0 L の塩化ナトリウム水溶液を陽イオン交換膜を使って電気分解し、電子 0.10 mol を流した。陽極で発生する塩素の体積(標準状態)と、陰極側の溶液の pH を求めよ。(標準状態の気体 1 mol は 22.4 L、陰極側は 1.0 L、体積変化なし)', a: '塩素 1.12 L、pH 13', exp: '陽極 2Cl⁻→Cl₂＋2e⁻ で Cl₂ は 0.050 mol、22.4×0.050＝1.12 L。陰極では OH⁻ が 0.10 mol でき、[OH⁻]＝0.10 mol/L、pOH＝1 なので pH＝13 です。' }
    ]
  });

  add('c4_inorg', {
    pat: [
      { name: '気体の製法・捕集法・乾燥剤のセット', freq: 'とてもよく出る', when: '「この気体を発生させる薬品・装置・捕集法・乾燥剤を選べ」という組み合わせの問題です。', how: ['製法:反応の型(弱酸の遊離・弱塩基の遊離・揮発性の酸の遊離・酸化還元)から薬品を決めます。', '捕集法:水に溶けにくければ水上置換。溶けやすければ、空気(平均分子量 29)より重いか軽いかで下方置換・上方置換を選びます。', '乾燥剤:酸性の気体に塩基性の乾燥剤(ソーダ石灰)は使えず、塩基性の気体(NH₃)に酸性の乾燥剤(濃硫酸・十酸化四リン)や塩化カルシウムは使えません。'], ex: { q: 'アンモニアを実験室でつくるときの薬品、捕集法、乾燥剤を答えよ。', a: '塩化アンモニウムと水酸化カルシウムを加熱、上方置換、ソーダ石灰', exp: '弱塩基の遊離:2NH₄Cl＋Ca(OH)₂→CaCl₂＋2H₂O＋2NH₃。NH₃ は水によく溶け空気より軽い(分子量 17)ので上方置換。塩基性なので塩基性の乾燥剤ソーダ石灰を使います。CaCl₂ は NH₃ と結合するので使えません。' } },
      { name: '金属イオンの系統分離:加える試薬の順番', freq: 'とてもよく出る', when: '数種類の金属イオンを含む溶液に、試薬を順に加えて沈殿を分けていく問題です。', how: ['HCl で Cl⁻ と沈殿する Ag⁺(AgCl)、Pb²⁺(PbCl₂)を先に取り出します。', '酸性で H₂S を通すと、イオン化傾向の小さい Cu²⁺ などが硫化物(CuS)で沈殿します。', '煮沸して H₂S を追い出し、NH₃ 水を加えると Fe³⁺、Al³⁺ が水酸化物で沈殿します。続いて塩基性で H₂S(ZnS)、(NH₄)₂CO₃(CaCO₃ など)の順です。'], ex: { q: 'Ag⁺、Cu²⁺、Fe³⁺ を含む水溶液に、(1) 希塩酸 (2) 酸性のまま H₂S (3) 煮沸後に硝酸を加え、さらに過剰の NH₃ 水 の順で試薬を加えた。各段階で沈殿する物質を答えよ。', a: '(1) AgCl (2) CuS (3) Fe(OH)₃', exp: '(1) Ag⁺ だけが白色の AgCl になります。(2) 酸性でも沈殿するのはイオン化傾向の小さい Cu²⁺ で、黒色の CuS。(3) H₂S で還元された鉄を硝酸で Fe³⁺ にもどし、NH₃ 水で赤褐色の Fe(OH)₃ にします。' } },
      { name: '両性金属と錯イオン:過剰の NaOH・NH₃ で溶けるかどうか', freq: 'よく出る', when: '水酸化物の沈殿に「過剰に加えると溶けた」と書かれていて、イオンを特定する問題です。', how: ['過剰の NaOH 水溶液で溶ける水酸化物:Al、Zn、Sn、Pb(両性)。', '過剰の NH₃ 水で溶ける水酸化物(酸化物):Cu、Zn、Ag(アンモニア錯イオンになる)。', '両方の条件を組み合わせると、Zn²⁺(どちらでも溶ける)と Al³⁺(NaOH だけで溶ける)が区別できます。'], ex: { q: 'ある金属イオンを含む水溶液に NaOH 水溶液を加えると白色沈殿ができ、過剰に加えると溶けた。同じ溶液に NH₃ 水を過剰に加えると白色沈殿は溶けなかった。この金属イオンは何か。Al³⁺、Zn²⁺、Cu²⁺ から選べ。', a: 'Al³⁺', exp: '過剰の NaOH で溶けるので両性の Al³⁺ か Zn²⁺。過剰の NH₃ 水で溶けないので、錯イオン [Zn(NH₃)₄]²⁺ をつくる Zn²⁺ ではありません。よって Al³⁺ です。Cu²⁺ の沈殿は青白色です。' } },
      { name: '工業的製法の量計算:全体の反応式で原料と製品をつなぐ', freq: 'よく出る', when: 'オストワルト法・接触法・ハーバー・ボッシュ法・アンモニアソーダ法などで、原料からできる製品の量を問われたときです。', how: ['途中の反応式を足し合わせて、全体の反応式(または原料と製品の物質量の比)をつくります。', 'たとえばオストワルト法は全体で NH₃＋2O₂→HNO₃＋H₂O、NH₃ 1 mol から HNO₃ 1 mol です。', 'kg のまま計算すると、物質量は kmol になるだけで比は同じです。'], ex: { q: 'オストワルト法で、アンモニア 17 kg がすべて硝酸になったとすると、硝酸は何 kg できるか。(NH₃＝17、HNO₃＝63)', a: '63 kg', exp: '全体の反応 NH₃＋2O₂→HNO₃＋H₂O より、NH₃ 1 kmol(17 kg)から HNO₃ 1 kmol(63 kg)ができます。途中の NO や NO₂ の量を一つずつ追わなくても、全体の式で一気に計算できます。' } },
      { name: '酸化物の分類:酸性・塩基性・両性', freq: 'よく出る', when: '酸化物が「水や酸・塩基とどう反応するか」を問われたときです。', how: ['非金属の酸化物(CO₂、SO₃、P₄O₁₀ など)はふつう酸性酸化物で、塩基と反応します。', '金属の酸化物(Na₂O、CaO など)は塩基性酸化物で、酸と反応します。', 'Al₂O₃、ZnO などは両性酸化物で、酸とも強塩基とも反応します。'], ex: { q: 'SO₃、Na₂O、Al₂O₃ を、酸性酸化物・塩基性酸化物・両性酸化物に分類せよ。', a: 'SO₃:酸性、Na₂O:塩基性、Al₂O₃:両性', exp: 'SO₃ は水と反応して硫酸になる酸性酸化物。Na₂O は水と反応して NaOH になる塩基性酸化物。Al₂O₃ は塩酸にも NaOH 水溶液にも溶ける両性酸化物です。' } }
    ],
    more: [
      { lv: 1, q: 'ハロゲンの単体のうち、酸化力が最も強いものはどれか。', choices: ['F₂', 'Cl₂', 'Br₂', 'I₂'], a: 'A(F₂)', exp: 'ハロゲンは原子番号が小さいほど電子を受け取りやすく、酸化力が強くなります。F₂＞Cl₂＞Br₂＞I₂ の順です。' },
      { lv: 1, q: '実験室で塩素をつくる方法として正しいものはどれか。', choices: ['酸化マンガン(Ⅳ)に濃塩酸を加えて加熱する', '亜鉛に希塩酸を加える', '塩化ナトリウムを水に溶かす', '石灰石に塩酸を加える'], a: 'A(酸化マンガン(Ⅳ)に濃塩酸を加えて加熱する)', exp: 'MnO₂＋4HCl→MnCl₂＋2H₂O＋Cl₂ で、MnO₂ が HCl を酸化して塩素ができます。B は水素、D は二酸化炭素の発生方法です。' },
      { lv: 1, q: '濃硫酸をスクロース(砂糖)にかけると黒くなる。この性質を何というか。', choices: ['酸化作用', '脱水作用', '吸湿性', '揮発性'], a: 'B(脱水作用)', exp: '濃硫酸は、有機物から H と O を水の形で奪う脱水作用をもちます。スクロースから水が奪われ、炭素が残るので黒くなります。' },
      { lv: 1, q: '炎色反応で黄色を示す元素はどれか。', choices: ['Na', 'K', 'Cu', 'Ca'], a: 'A(Na)', exp: 'Na は黄色、K は赤紫色、Cu は青緑色、Ca は橙赤色です。トンネルのオレンジ色の照明(ナトリウムランプ)も Na の光です。' },
      { lv: 1, q: '二酸化窒素 NO₂ の色を答えよ。', a: '赤褐色', exp: 'NO₂ は赤褐色で刺激臭のある有毒な気体です。一酸化窒素 NO は無色で、空気にふれるとすぐ NO₂ になって赤褐色に変わります。' },
      { lv: 1, q: '硝酸銀水溶液に塩化ナトリウム水溶液を加えるとできる沈殿の色を答えよ。', a: '白色(AgCl)', exp: 'Ag⁺＋Cl⁻→AgCl で白色沈殿ができます。AgCl は光が当たると分解して黒っぽくなり、NH₃ 水には [Ag(NH₃)₂]⁺ となって溶けます。' },
      { lv: 1, q: 'Fe³⁺ を含む水溶液にチオシアン酸カリウム KSCN 水溶液を加えたときの変化を答えよ。', a: '血赤色の溶液になる', exp: 'Fe³⁺ は SCN⁻ と結びついて血赤色になります。Fe³⁺ のわずかな量でも見分けられる、鋭い検出反応です。Fe²⁺ では色が出ません。' },
      { lv: 2, q: 'フッ化水素酸をポリエチレンの容器に保存する理由として正しいものはどれか。', choices: ['光で分解するから', 'ガラスの主成分 SiO₂ と反応して溶かすから', '揮発しやすいから', '強い酸化剤だから'], a: 'B(ガラスの主成分 SiO₂ と反応して溶かすから)', exp: 'SiO₂＋6HF→H₂SiF₆＋2H₂O の反応でガラスを溶かします。この性質を利用して、ガラスに目盛りや模様をつけることができます。' },
      { lv: 2, q: '接触法で、硫黄 32 kg をすべて硫酸にすると、硫酸は何 kg できるか。(S＝32、H₂SO₄＝98)', a: '98 kg', exp: 'S→SO₂→SO₃→H₂SO₄ と、硫黄原子は1個ずつ受けつがれます。S 1 kmol(32 kg)から H₂SO₄ 1 kmol(98 kg)ができます。' },
      { lv: 2, q: '銅 0.30 mol を希硝酸と完全に反応させた。発生する一酸化窒素の物質量を求めよ。', a: '0.20 mol', exp: '3Cu＋8HNO₃→3Cu(NO₃)₂＋2NO＋4H₂O より、Cu 3 mol から NO 2 mol。0.30×2/3＝0.20 mol です。濃硝酸なら NO₂ が出て、Cu 1 mol から 2 mol になります。' },
      { lv: 2, q: 'Zn²⁺ と Al³⁺ を含む水溶液から、2つを分けるのに使える試薬はどれか。', choices: ['過剰の NaOH 水溶液', '過剰の NH₃ 水', '希塩酸', '硝酸'], a: 'B(過剰の NH₃ 水)', exp: '過剰の NH₃ 水では、Zn は [Zn(NH₃)₄]²⁺ となって溶け、Al(OH)₃ は沈殿のまま残ります。NaOH 水溶液ではどちらも溶けてしまうので分けられません。' },
      { lv: 2, q: 'アンモニアの乾燥に使える乾燥剤はどれか。', choices: ['濃硫酸', '十酸化四リン', '塩化カルシウム', 'ソーダ石灰'], a: 'D(ソーダ石灰)', exp: 'NH₃ は塩基性なので、酸性の濃硫酸・十酸化四リンとは中和してしまいます。塩化カルシウムは NH₃ と化合物をつくるので使えません。塩基性のソーダ石灰が適しています。' },
      { lv: 2, q: 'ハーバー・ボッシュ法で、窒素 14 kg がすべてアンモニアになったとすると、アンモニアは何 kg できるか。(N₂＝28、NH₃＝17)', a: '17 kg', exp: 'N₂＋3H₂→2NH₃ より、N₂ 0.50 kmol から NH₃ 1.0 kmol ができます。1.0 kmol×17＝17 kg です。窒素原子の数で考えて、N 1 kmol から NH₃ 1 kmol としても同じです。' },
      { lv: 2, q: 'Pb²⁺ を含む水溶液に希塩酸を加えてできた白色沈殿が、ほかの白色沈殿 AgCl と異なる性質はどれか。', choices: ['熱湯に溶ける', 'NH₃ 水に溶ける', '光で黒くなる', '水に全く溶けない'], a: 'A(熱湯に溶ける)', exp: 'PbCl₂ は冷水には溶けにくいですが、熱湯には溶けます。AgCl は熱湯には溶けず、NH₃ 水に溶けます。この違いで2つを分けられます。' },
      { lv: 2, q: 'アンモニアソーダ法(ソルベー法)で、塩化ナトリウム 117 g がすべて反応したとすると、炭酸ナトリウムは何 g できるか。(NaCl＝58.5、Na₂CO₃＝106)', a: '106 g', exp: '全体の反応は 2NaCl＋CaCO₃→Na₂CO₃＋CaCl₂ で、NaCl 2 mol から Na₂CO₃ 1 mol。117 g は 2.0 mol なので、Na₂CO₃ 1.0 mol＝106 g です。' },
      { lv: 3, q: '次の錯イオンのうち、形が正方形であるものはどれか。', choices: ['[Ag(NH₃)₂]⁺', '[Zn(NH₃)₄]²⁺', '[Cu(NH₃)₄]²⁺', '[Fe(CN)₆]³⁻'], a: 'C([Cu(NH₃)₄]²⁺)', exp: '[Ag(NH₃)₂]⁺ は直線形、[Zn(NH₃)₄]²⁺ は正四面体形、[Cu(NH₃)₄]²⁺ は正方形、[Fe(CN)₆]³⁻ は正八面体形です。配位数が同じ 4 でも、Zn と Cu で形がちがう点がよく問われます。' },
      { lv: 3, q: 'Ag⁺、Cu²⁺、Zn²⁺、Ca²⁺、Na⁺ を含む水溶液に、(1) 希塩酸 (2) 酸性で H₂S (3) 煮沸してから NH₃ 水で塩基性にして H₂S (4) (NH₄)₂CO₃ 水溶液 を順に加えた。各段階の沈殿と、最後に残るイオンの確かめ方を答えよ。', a: '(1) AgCl (2) CuS (3) ZnS (4) CaCO₃。残る Na⁺ は炎色反応(黄色)で確かめる。', exp: 'Cl⁻ で Ag⁺、酸性の H₂S でイオン化傾向の小さい Cu²⁺、塩基性の H₂S で Zn²⁺、CO₃²⁻ で Ca²⁺ が沈殿します。Na⁺ はどの試薬でも沈殿しないので、炎色反応で確認します。' },
      { lv: 3, q: '酸化マンガン(Ⅳ) 8.7 g に十分な量の濃塩酸を加えて加熱した。発生する塩素の体積(標準状態)と、反応した HCl のうち酸化された HCl の物質量を求めよ。(MnO₂＝87、標準状態の気体 1 mol は 22.4 L)', a: '塩素 2.24 L、酸化された HCl 0.20 mol', exp: 'MnO₂＋4HCl→MnCl₂＋2H₂O＋Cl₂。MnO₂ 0.10 mol から Cl₂ 0.10 mol(2.24 L)。HCl は 0.40 mol 反応しますが、Cl₂ になったのは Cl 原子 0.20 mol 分で、残りは MnCl₂ に入っています。' },
      { lv: 3, q: 'オストワルト法で、質量パーセント濃度 63 % の硝酸 1.0 kg をつくるのに必要なアンモニアの質量と、酸素の物質量を求めよ。(NH₃＝17、HNO₃＝63)', a: 'アンモニア 170 g、酸素 20 mol', exp: '硝酸は 630 g＝10 mol。全体の反応 NH₃＋2O₂→HNO₃＋H₂O より、NH₃ 10 mol(170 g)と O₂ 20 mol が必要です。全体の式を使うと、途中の NO の再利用も含めて考えたことになります。' },
      { lv: 3, q: '塩化ナトリウムに濃硫酸を加えて加熱すると、塩化水素が発生する。この反応が進む理由と、塩化水素の捕集法を答えよ。', a: '不揮発性の硫酸が、揮発性の塩化水素を追い出すため。下方置換で集める。', exp: 'NaCl＋H₂SO₄→NaHSO₄＋HCl。硫酸は沸点が高く揮発しにくいので、生じた HCl が気体として出ていき、反応が右へ進みます。HCl は水によく溶け、空気より重い(分子量 36.5)ので下方置換です。' }
    ]
  });

  add('c4_org', {
    pat: [
      { name: '元素分析:CO₂ と H₂O の質量から組成式を出す', freq: 'とてもよく出る', when: '「試料 ○ mg を完全燃焼させると CO₂ が △ mg、H₂O が □ mg 生じた」という問題です。', how: ['C の質量＝CO₂ の質量×12/44、H の質量＝H₂O の質量×2/18。', 'O の質量＝試料の質量−C−H。', '各元素の質量を原子量で割り、いちばん小さい数でわって整数の比(組成式)にします。分子量が与えられれば分子式にします。'], ex: { q: 'C、H、O からなる化合物 3.0 mg を完全燃焼させると、CO₂ が 6.6 mg、H₂O が 3.6 mg 生じた。組成式を求めよ。(H＝1.0、C＝12、O＝16)', a: 'C₃H₈O', exp: 'C＝6.6×12/44＝1.8 mg、H＝3.6×2/18＝0.40 mg、O＝3.0−1.8−0.40＝0.80 mg。物質量の比は C:H:O＝1.8/12:0.40/1.0:0.80/16＝0.15:0.40:0.050＝3:8:1 で C₃H₈O です。' } },
      { name: '不飽和度から構造の候補をしぼる', freq: 'よく出る', when: '分子式が与えられ、「考えられる構造(異性体)をすべて書け」と問われたときです。', how: ['不飽和度＝(2×C の数＋2−H の数)/2 を計算します(O は無視)。', '不飽和度 1 なら二重結合1つか環1つ、4 以上ならベンゼン環を疑います。', '炭素の骨組み(直鎖・枝分かれ)を順に書き、二重結合や官能基の位置を変えて重複なく数えます。'], ex: { q: '分子式 C₄H₈ で表される化合物の異性体の数を、シス・トランス異性体も区別して答えよ。', a: '6 種類', exp: '不飽和度は (8＋2−8)/2＝1。アルケンが 1-ブテン、シス-2-ブテン、トランス-2-ブテン、2-メチルプロペンの4種、環式がシクロブタン、メチルシクロプロパンの2種で、合計6種類です。' } },
      { name: '検出反応で官能基を特定する(ヨードホルム・銀鏡・塩化鉄(Ⅲ))', freq: 'とてもよく出る', when: '「ヨードホルム反応を示した」「銀鏡反応を示した」など、反応の結果から構造を決める問題です。', how: ['ヨードホルム反応(黄色沈殿):CH₃CO− か CH₃CH(OH)− の部分をもつ。', '銀鏡反応・フェーリング液の還元:アルデヒド基 −CHO(ギ酸もふくむ)をもつ。', '塩化鉄(Ⅲ)で紫色:フェノール類(ベンゼン環に直接 −OH)。'], ex: { q: 'エタノール、1-プロパノール、アセトン、2-プロパノールのうち、ヨードホルム反応を示さないものはどれか。', a: '1-プロパノール', exp: 'エタノール CH₃CH₂OH と 2-プロパノール CH₃CH(OH)CH₃ は CH₃CH(OH)− を、アセトン CH₃COCH₃ は CH₃CO− をもちます。1-プロパノール CH₃CH₂CH₂OH の OH は端の炭素にあり、どちらの形ももちません。' } },
      { name: '芳香族化合物の分離:酸の強さの順で水層へ移す', freq: 'とてもよく出る', when: 'エーテルに溶けた数種類の芳香族化合物に、NaHCO₃ 水・NaOH 水・塩酸を順に加えて分ける問題です。', how: ['酸の強さはカルボン酸＞炭酸＞フェノールの順です。', 'NaHCO₃ 水では、炭酸より強いカルボン酸だけが塩になって水層へ移ります。', 'NaOH 水でフェノール類、塩酸でアニリンなどの塩基が水層へ移り、中性の物質(トルエンなど)はエーテル層に残ります。'], ex: { q: '安息香酸・フェノール・アニリン・トルエンを含むエーテル溶液に、(1) NaHCO₃ 水 (2) NaOH 水 (3) 塩酸 を順に加えてふり混ぜ、そのつど水層を分けた。各段階で水層に移る物質と、最後にエーテル層に残る物質を答えよ。', a: '(1) 安息香酸 (2) フェノール (3) アニリン。残るのはトルエン。', exp: '(1) 安息香酸は炭酸より強い酸なので、安息香酸ナトリウムになって水層へ。(2) フェノールはナトリウムフェノキシドに。(3) アニリンはアニリン塩酸塩になります。トルエンは酸とも塩基とも反応しません。' } },
      { name: 'エステルのけん化:必要な塩基の量', freq: 'よく出る', when: 'エステルや油脂を NaOH・KOH で加水分解(けん化)し、必要な塩基の量や分子量を問われたときです。', how: ['エステル結合 1 つに NaOH(KOH)1 mol が反応します。', '油脂はエステル結合を3つもつので、油脂 1 mol に塩基 3 mol です。', '塩基の量から逆に、エステルの物質量や分子量を求めることもできます。'], ex: { q: '酢酸エチル CH₃COOC₂H₅ 8.8 g を完全にけん化するのに必要な水酸化ナトリウムの質量を求めよ。(CH₃COOC₂H₅＝88、NaOH＝40)', a: '4.0 g', exp: '酢酸エチルは 8.8/88＝0.10 mol。CH₃COOC₂H₅＋NaOH→CH₃COONa＋C₂H₅OH で 1:1 に反応するので、NaOH も 0.10 mol＝4.0 g です。' } }
    ],
    more: [
      { lv: 1, q: '−COOH の名前を答えよ。', a: 'カルボキシ基', exp: '−COOH はカルボキシ基で、これをもつ化合物をカルボン酸といいます。水溶液は弱い酸性を示します。' },
      { lv: 1, q: '一般式 CₙH₂ₙ₊₂ で表され、すべて単結合でできている鎖式炭化水素を何というか。', choices: ['アルカン', 'アルケン', 'アルキン', 'シクロアルカン'], a: 'A(アルカン)', exp: 'メタン CH₄、エタン C₂H₆ などのアルカンです。アルケンは CₙH₂ₙ(二重結合1つ)、アルキンは CₙH₂ₙ₋₂(三重結合1つ)です。' },
      { lv: 1, q: 'エチレンを臭素水に通すと、臭素水の赤褐色が消える。この反応の種類はどれか。', choices: ['置換反応', '付加反応', '縮合反応', '脱離反応'], a: 'B(付加反応)', exp: 'C＝C の二重結合に Br₂ が付け加わり、1,2-ジブロモエタン CH₂BrCH₂Br ができます(付加反応)。二重結合・三重結合があるかを調べる方法として使われます。' },
      { lv: 1, q: '第一級アルコールを酸化すると、順に何ができるか。', choices: ['ケトン→カルボン酸', 'アルデヒド→カルボン酸', 'エーテル→エステル', 'ケトン→アルデヒド'], a: 'B(アルデヒド→カルボン酸)', exp: '第一級アルコール(例:エタノール)はアルデヒド(アセトアルデヒド)を経てカルボン酸(酢酸)になります。第二級はケトンになり、第三級は酸化されにくいです。' },
      { lv: 1, q: 'ベンゼンに濃硝酸と濃硫酸の混合物を加えて加熱すると、何ができるか。', a: 'ニトロベンゼン', exp: 'ベンゼンの H が −NO₂ に置き換わるニトロ化(置換反応)です。ベンゼン環は安定なので、付加より置換が起こりやすいのが特徴です。' },
      { lv: 1, q: 'エタノール C₂H₅OH の分子量を求めよ。(H＝1.0、C＝12、O＝16)', a: '46', exp: '12×2＋1.0×6＋16＝46。分子式は C₂H₆O で、同じ分子式のジメチルエーテル CH₃OCH₃ とは異性体の関係です。' },
      { lv: 1, q: 'フェノールの水溶液に塩化鉄(Ⅲ)水溶液を加えると、何色になるか。', a: '紫色', exp: 'ベンゼン環に直接 −OH がついたフェノール類は、塩化鉄(Ⅲ)で紫色(青紫〜赤紫)になります。ベンジルアルコールのように −OH が環に直接ついていないものは呈色しません。' },
      { lv: 2, q: '組成式が CH₂O で、分子量が 60 の化合物の分子式を求めよ。(H＝1.0、C＝12、O＝16)', a: 'C₂H₄O₂', exp: 'CH₂O の式量は 30。60÷30＝2 なので分子式は (CH₂O)₂＝C₂H₄O₂ です。酢酸やギ酸メチルがこの分子式をもちます。' },
      { lv: 2, q: '分子式 C₅H₁₂ の構造異性体はいくつあるか。', a: '3 つ', exp: 'ペンタン(直鎖)、2-メチルブタン、2,2-ジメチルプロパンの3つです。炭素の骨組みだけを考え、同じものを向きを変えて二重に数えないようにします。' },
      { lv: 2, q: 'アセチレンに、触媒を使って水を付加させると何ができるか。', choices: ['エタノール', 'アセトアルデヒド', '酢酸', 'エチレン'], a: 'B(アセトアルデヒド)', exp: 'アセチレンに水が付加すると、まずビニルアルコール CH₂＝CHOH ができますが、不安定なのですぐにアセトアルデヒド CH₃CHO に変わります。' },
      { lv: 2, q: 'シス-トランス異性体(幾何異性体)が存在するものはどれか。', choices: ['エチレン', 'プロペン', '2-ブテン', '2-メチルプロペン'], a: 'C(2-ブテン)', exp: 'C＝C の両方の炭素に、それぞれ異なる2つの原子(団)がついているとシス-トランス異性体ができます。2-ブテン CH₃CH＝CHCH₃ は両方の C に H と CH₃ がつくので当てはまります。' },
      { lv: 2, q: '銀鏡反応を示すものはどれか。', choices: ['アセトン', 'ホルムアルデヒド', 'エタノール', '酢酸'], a: 'B(ホルムアルデヒド)', exp: '銀鏡反応はアルデヒド基 −CHO の還元性による反応です。ホルムアルデヒド HCHO はアルデヒド基をもちます。ギ酸 HCOOH も −CHO の形をふくむので示しますが、酢酸は示しません。' },
      { lv: 2, q: 'ベンゼン C₆H₆ の不飽和度を求めよ。', a: '4', exp: '(2×6＋2−6)/2＝4。ベンゼン環は、環1つと二重結合3つ分に相当します。分子式で不飽和度が 4 以上なら、まずベンゼン環を考えます。' },
      { lv: 2, q: 'ニトロベンゼンからアニリンをつくる方法として正しいものはどれか。', choices: ['スズと濃塩酸で還元し、そのあと NaOH 水溶液を加える', '濃硫酸で加熱する', '水酸化ナトリウムと高温で融解する', '過マンガン酸カリウムで酸化する'], a: 'A(スズと濃塩酸で還元し、そのあと NaOH 水溶液を加える)', exp: 'スズと塩酸で −NO₂ を −NH₂ に還元すると、塩酸の中ではアニリン塩酸塩になります。NaOH 水溶液を加えると弱塩基のアニリンが遊離します。' },
      { lv: 2, q: '分子量 884 の油脂 1.0 g を完全にけん化するのに必要な水酸化カリウムは何 mg か。(KOH＝56)', a: '約 190 mg', exp: '油脂 1 mol に KOH 3 mol が反応します。油脂 1.0/884 mol に対して KOH は 3×1.0/884 mol、質量は 3×56/884≒0.190 g＝190 mg。この値を「けん化価」といい、分子量が小さい油脂ほど大きくなります。' },
      { lv: 3, q: '分子式 C₄H₁₀O のアルコールのうち、ナトリウムとは反応するが、二クロム酸カリウムの硫酸酸性溶液で酸化されにくいものの名前を答えよ。', a: '2-メチル-2-プロパノール', exp: 'C₄H₁₀O のアルコールは 1-ブタノール、2-ブタノール、2-メチル-1-プロパノール、2-メチル-2-プロパノールの4つ。OH のついた C に H がない第三級アルコール (CH₃)₃COH だけが酸化されにくいです。' },
      { lv: 3, q: 'ある鎖式のアルケン CₙH₂ₙ 2.8 g に、臭素 8.0 g がちょうど付加した。このアルケンの分子式を求めよ。(H＝1.0、C＝12、Br₂＝160)', a: 'C₄H₈', exp: 'アルケン 1 mol に Br₂ 1 mol が付加します。Br₂ は 8.0/160＝0.050 mol なので、アルケンも 0.050 mol。分子量は 2.8/0.050＝56。14n＝56 より n＝4 で C₄H₈ です。' },
      { lv: 3, q: '分子式 C₈H₁₀ で、ベンゼン環をもつ化合物の異性体はいくつあるか。', a: '4 つ', exp: '不飽和度は 4 でベンゼン環1つ。残りの C 2つの付き方で、エチルベンゼン(1つ)と、メチル基2つのキシレン(o-、m-、p- の3つ)があり、合計4つです。' },
      { lv: 3, q: 'サリチル酸 13.8 g に無水酢酸を反応させてアセチルサリチル酸をつくったところ、収率は 80 % であった。得られたアセチルサリチル酸の質量を求めよ。(サリチル酸＝138、アセチルサリチル酸＝180)', a: '14.4 g', exp: 'サリチル酸 0.10 mol から、理論上アセチルサリチル酸 0.10 mol＝18.0 g ができます。収率 80 % なので 18.0×0.80＝14.4 g。サリチル酸の −OH がアセチル化されています。' },
      { lv: 3, q: '安息香酸とフェノールを含むエーテル溶液から安息香酸だけを水層へ移したい。NaOH 水溶液ではなく NaHCO₃ 水溶液を使う理由を説明せよ。', a: '酸の強さはカルボン酸＞炭酸＞フェノールなので、NaHCO₃ とは炭酸より強い安息香酸だけが反応し、フェノールは反応せずエーテル層に残るから。', exp: 'NaOH は強塩基なので、安息香酸とフェノールの両方を塩にして水層へ移してしまいます。NaHCO₃ は「炭酸より強い酸」とだけ反応して CO₂ を出すので、2つを分けられます。' }
    ]
  });

  add('c4_poly', {
    pat: [
      { name: '重合度:分子量÷くり返し単位の式量', freq: 'とてもよく出る', when: '高分子の平均分子量が与えられ、「重合度」「結合の数」を問われたときです。', how: ['単量体の構造から、くり返し単位の式量を求めます(付加重合なら単量体と同じ式量)。', '重合度 n＝分子量÷くり返し単位の式量。', '縮合重合では、くり返し単位の中に結合がいくつあるか(ナイロン66 なら2つ)を確認して、結合の数を出します。'], ex: { q: '平均分子量 2.8×10⁴ のポリエチレンの重合度を求めよ。(H＝1.0、C＝12)', a: '1.0×10³', exp: 'くり返し単位 −CH₂−CH₂− の式量は 28。n＝2.8×10⁴/28＝1.0×10³ です。高分子の分子量は平均値なので、重合度も平均の値です。' } },
      { name: '糖の還元性:ヘミアセタール構造が残っているか', freq: 'とてもよく出る', when: '「フェーリング液を還元する糖はどれか」「銀鏡反応を示す糖はどれか」を問われたときです。', how: ['単糖(グルコース、フルクトース、ガラクトース)はすべて還元性があります。', '二糖は、結合に使われずに残っている −OH(ヘミアセタール構造)があれば還元性をもちます。マルトース・ラクトース・セロビオースはあり、スクロースはありません。', 'デンプン・セルロースなどの多糖は、ほとんど還元性を示しません。'], ex: { q: 'グルコース、マルトース、スクロース、ラクトースのうち、フェーリング液を還元しないものはどれか。', a: 'スクロース', exp: 'スクロースは、グルコースとフルクトースが、どちらも還元性を示す部分どうしで結合しているので、開いた鎖状構造になれません。ほかの3つは還元性を示します。スクロースを加水分解すると還元性が出ます。' } },
      { name: '縮合重合の量計算:ナイロン66 の重合度とアミド結合の数', freq: 'よく出る', when: 'ナイロン66・PET などの分子量から、重合度や結合の数、原料の量を問われたときです。', how: ['くり返し単位を書きます(ナイロン66 は −CO(CH₂)₄CO−NH(CH₂)₆NH−、式量 226)。', '重合度 n＝分子量÷226。', 'くり返し単位1つにアミド結合は2つあるので、結合の数は約 2n です。'], ex: { q: '平均分子量 2.26×10⁴ のナイロン66 1分子に含まれるアミド結合の数はおよそいくつか。(くり返し単位 C₁₂H₂₂N₂O₂ の式量 226)', a: '約 200', exp: 'n＝2.26×10⁴/226＝100。くり返し単位1つにアミド結合が2つあるので 2×100＝200 です。末端の分の 1 つのちがいは、分子が大きいので無視できます。' } },
      { name: 'タンパク質・アミノ酸の検出反応', freq: 'よく出る', when: '「ビウレット反応」「キサントプロテイン反応」などの結果から、含まれる構造を答える問題です。', how: ['ビウレット反応(赤紫色):ペプチド結合を2つ以上もつ(トリペプチド以上)。', 'キサントプロテイン反応(黄色→塩基性で橙黄色):ベンゼン環をもつアミノ酸を含む。', '硫黄の検出(NaOH で加熱し酢酸鉛(Ⅱ)で黒色):S を含むアミノ酸(システインなど)を含む。ニンヒドリン反応(赤紫〜青紫)はアミノ基があれば起こる。'], ex: { q: 'あるペプチドの水溶液は、ニンヒドリン反応とキサントプロテイン反応を示したが、ビウレット反応は示さなかった。このペプチドについて言えることを答えよ。', a: 'ベンゼン環をもつアミノ酸を含むジペプチドである', exp: 'ビウレット反応を示さないので、ペプチド結合は1つだけ、つまりジペプチドです。キサントプロテイン反応からベンゼン環(チロシンやフェニルアラニンなど)を含むことがわかります。' } },
      { name: '多糖の加水分解:(C₆H₁₀O₅)ₙ→n C₆H₁₂O₆ の質量の増え方', freq: 'よく出る', when: 'デンプンやセルロースを加水分解して、何 g のグルコースができるかを問われたときです。', how: ['くり返し単位 C₆H₁₀O₅(式量 162)1つから、グルコース C₆H₁₂O₆(180)1分子ができます。', '多糖の質量÷162 で、できるグルコースの物質量がわかります。', 'グルコースの質量は多糖の 180/162 倍です(水が加わる分だけ増えます)。'], ex: { q: 'デンプン 81 g を完全に加水分解すると、グルコースは何 g できるか。(C₆H₁₀O₅＝162、C₆H₁₂O₆＝180)', a: '90 g', exp: 'くり返し単位は 81/162＝0.50 mol。それぞれが水 1 分子を受け取ってグルコースになるので、グルコースも 0.50 mol で 90 g です。重さが増えるのは水が加わったからです。' } }
    ],
    more: [
      { lv: 1, q: 'グルコースの分子式を答えよ。', a: 'C₆H₁₂O₆', exp: 'グルコース(ブドウ糖)は代表的な単糖で、分子式は C₆H₁₂O₆ です。同じ分子式のフルクトース(果糖)とは異性体の関係です。' },
      { lv: 1, q: 'デンプンの水溶液にヨウ素ヨウ化カリウム水溶液を加えると何色になるか。', choices: ['赤色', '青紫色', '黄色', '無色'], a: 'B(青紫色)', exp: 'デンプンのらせん構造の中にヨウ素がとりこまれて青紫色になります(ヨウ素デンプン反応)。加熱するとらせんがほどけて色が消えます。' },
      { lv: 1, q: '付加重合でできる高分子はどれか。', choices: ['ポリエチレン', 'ナイロン66', 'ポリエチレンテレフタラート', 'タンパク質'], a: 'A(ポリエチレン)', exp: 'ポリエチレンは、エチレンの二重結合が開いてつながる付加重合でできます。ナイロン66、PET、タンパク質は、水がとれてつながる縮合重合でできます。' },
      { lv: 1, q: 'アミノ酸どうしがつながるときにできる結合 −CO−NH− を何というか。', a: 'ペプチド結合', exp: '一方のアミノ酸の −COOH と、もう一方の −NH₂ から水がとれてできる結合です。形はアミド結合と同じで、アミノ酸どうしのときに特にペプチド結合とよびます。' },
      { lv: 1, q: 'DNA に含まれ、RNA には含まれない塩基はどれか。', choices: ['アデニン', 'グアニン', 'シトシン', 'チミン'], a: 'D(チミン)', exp: 'DNA の塩基は A、G、C、T、RNA の塩基は A、G、C、U です。DNA のチミン(T)が、RNA ではウラシル(U)に代わります。' },
      { lv: 1, q: '天然ゴムの単量体を答えよ。', a: 'イソプレン', exp: '天然ゴムはイソプレン CH₂＝C(CH₃)−CH＝CH₂ が付加重合したポリイソプレンで、二重結合がシス形になっています。硫黄を加えると弾性が増します(加硫)。' },
      { lv: 1, q: 'セルロースをつくっている単糖を答えよ。', a: 'β-グルコース', exp: 'セルロースは β-グルコースが直線状につながった多糖です。デンプンは α-グルコースからできています。同じグルコースでも、つながり方で性質が大きく変わります。' },
      { lv: 2, q: '平均分子量 6.25×10⁴ のポリ塩化ビニルの重合度を求めよ。(H＝1.0、C＝12、Cl＝35.5)', a: '1.0×10³', exp: 'くり返し単位 −CH₂−CHCl− の式量は 12×2＋1.0×3＋35.5＝62.5。n＝6.25×10⁴/62.5＝1.0×10³ です。' },
      { lv: 2, q: 'スクロースを加水分解して得られる混合物(転化糖)について正しいものはどれか。', choices: ['グルコースだけからなり、還元性はない', 'グルコースとフルクトースからなり、還元性がある', 'ガラクトースを含む', 'デンプンにもどる'], a: 'B(グルコースとフルクトースからなり、還元性がある)', exp: 'スクロースは酵素インベルターゼや酸で加水分解され、グルコースとフルクトースの等量混合物(転化糖)になります。どちらも還元性をもつので、フェーリング液を還元します。' },
      { lv: 2, q: 'グリシン1分子とアラニン1分子からできるジペプチドは何種類あるか(鏡像異性体は考えない)。', a: '2 種類', exp: 'どちらのアミノ酸の −COOH を使うかで、Gly−Ala と Ala−Gly の2種類ができます。順番がちがうと別の物質になるのがペプチドの特徴です。' },
      { lv: 2, q: 'ポリエチレンテレフタラート(PET)の原料の組み合わせはどれか。', choices: ['エチレンとテレフタル酸', 'エチレングリコールとテレフタル酸', 'エチレングリコールとアジピン酸', 'ヘキサメチレンジアミンとテレフタル酸'], a: 'B(エチレングリコールとテレフタル酸)', exp: '2価アルコールのエチレングリコールと2価カルボン酸のテレフタル酸が、エステル結合でつながる縮合重合でできます。ペットボトルや衣類の繊維に使われます。' },
      { lv: 2, q: 'グルコース 90 g をアルコール発酵させると、エタノールは何 g できるか。(C₆H₁₂O₆＝180、C₂H₅OH＝46)', a: '46 g', exp: 'C₆H₁₂O₆→2C₂H₅OH＋2CO₂。グルコース 0.50 mol からエタノール 1.0 mol＝46 g ができます。係数の 2 を忘れると半分の答えになります。' },
      { lv: 2, q: '加熱しても軟らかくならない熱硬化性樹脂はどれか。', choices: ['ポリエチレン', 'ポリスチレン', 'フェノール樹脂', 'ポリ塩化ビニル'], a: 'C(フェノール樹脂)', exp: 'フェノール樹脂は、分子が立体的な網目状につながっているので、加熱しても軟らかくならず、熱硬化性です。ほかの3つは鎖状の高分子で、熱可塑性です。' },
      { lv: 2, q: 'ナイロン6 のつくり方として正しいものはどれか。', choices: ['カプロラクタムの開環重合', 'アジピン酸とヘキサメチレンジアミンの縮合重合', 'エチレンの付加重合', 'アクリロニトリルの付加重合'], a: 'A(カプロラクタムの開環重合)', exp: 'ナイロン6 は、環状のアミドであるカプロラクタムの環が開いてつながる開環重合でできます。B はナイロン66 のつくり方です。' },
      { lv: 2, q: 'タンパク質の窒素の含有率を 16 % とする。ある食品から窒素が 0.80 g 検出されたとき、タンパク質はおよそ何 g 含まれていたか。', a: '5.0 g', exp: 'タンパク質の 16 % が窒素なので、タンパク質＝0.80÷0.16＝5.0 g。食品のタンパク質量を窒素の量から見積もる方法(ケルダール法)の考え方です。' },
      { lv: 3, q: '平均分子量 4.52×10⁴ のナイロン66 1分子に含まれるアミド結合の数を求めよ。(くり返し単位の式量 226)', a: '約 400', exp: '重合度 n＝4.52×10⁴/226＝200。くり返し単位 −CO(CH₂)₄CO−NH(CH₂)₆NH− にはアミド結合が2つあるので 2×200＝400。重合度とアミド結合の数を取りちがえないよう注意します。' },
      { lv: 3, q: 'グルコースを含む水溶液にアンモニア性硝酸銀水溶液を加えて温めると、銀が 2.16 g 析出した。水溶液中のグルコースの質量を求めよ。(グルコース 1 mol から Ag 2 mol が析出するとする、Ag＝108、C₆H₁₂O₆＝180)', a: '1.80 g', exp: '銀は 2.16/108＝0.020 mol。グルコースはその半分の 0.010 mol で、0.010×180＝1.80 g です。アルデヒド基 1 つが Ag⁺ 2 つを還元するためです。' },
      { lv: 3, q: 'ポリ酢酸ビニル 86 g を完全にけん化すると、ポリビニルアルコールは何 g できるか。(くり返し単位の式量:ポリ酢酸ビニル 86、ポリビニルアルコール 44)', a: '44 g', exp: 'ポリ酢酸ビニルのくり返し単位は 86/86＝1.0 mol。けん化でそれぞれの −OCOCH₃ が −OH になるので、ポリビニルアルコールのくり返し単位も 1.0 mol＝44 g です。ビニルアルコールは不安定なので、この方法でつくります。' },
      { lv: 3, q: 'グリシン(等電点 6.0)、グルタミン酸(等電点 3.2)、リシン(等電点 9.7)を含む水溶液を、pH 6.0 の緩衝液中で電気泳動した。それぞれどちらの極へ移動するか。', a: 'グリシン:ほとんど移動しない、グルタミン酸:陽極、リシン:陰極', exp: 'pH が等電点より高いと、アミノ酸は全体として負の電荷をもち陽極へ、低いと正の電荷で陰極へ動きます。グリシンは等電点と同じ pH なので動きません。' },
      { lv: 3, q: 'ある2本鎖 DNA の塩基のうち、アデニンが 30 % を占めていた。グアニンは何 % か。', a: '20 %', exp: '2本鎖 DNA では A と T、G と C が対になるので A＝T＝30 %。残りの 40 % を G と C が等しく分けるので、G＝20 % です。' }
    ]
  });

  add('b4_cell', {
    pat: [
      { name: '酵素反応のグラフ:基質濃度と反応速度', freq: 'とてもよく出る', when: '横軸が基質濃度、縦軸が反応速度のグラフがあり、「やがて一定になる理由」や「酵素量を変えたときのグラフ」を問われたときです。', how: ['基質が少ないうちは、基質が多いほど酵素と出会う回数が増えて速度が上がります。', '基質が十分多いと、すべての酵素が基質と結合した状態(飽和)になり、速度は最大値で一定になります。', '酵素の量を2倍にすると最大速度が2倍になります。温度・pH は酵素のはたらきやすさそのものを変えます。'], ex: { q: '基質濃度を上げていくと、酵素反応の速度がやがて一定になる。その理由を説明せよ。', a: 'すべての酵素の活性部位が基質と結合した状態になり、それ以上基質をふやしても、同時に反応できる数が増えないから。', exp: '酵素は1つの活性部位で1つずつ基質を処理します。全部の酵素がふさがると、基質がいくらあっても「順番待ち」になるだけで、速度は酵素の量で決まる最大値になります。' } },
      { name: '競争的阻害と非競争的阻害の見分け方', freq: 'よく出る', when: '阻害物質を加えたときのグラフが、加えないときのグラフと比べて示されている問題です。', how: ['基質濃度が高いところで、阻害物質ありとなしのグラフが近づくかを見ます。', '近づく(最大速度はほぼ同じ)なら、基質と活性部位をうばい合う競争的阻害です。', '基質濃度を上げても最大速度が下がったままなら、活性部位以外に結合する非競争的阻害です。'], ex: { q: 'ある阻害物質を加えると、基質濃度が低いときは反応速度が大きく下がったが、基質濃度を十分高くすると阻害物質がないときとほぼ同じ速度になった。この阻害のしかたを何というか。', a: '競争的阻害', exp: '阻害物質が基質と似た形で活性部位をうばい合っていると、基質がたくさんあれば基質の方が活性部位に入りやすくなり、阻害の効果がうすれます。これが競争的阻害の特徴です。' } },
      { name: '膜輸送の種類を見分ける:受動輸送か能動輸送か', freq: 'よく出る', when: '物質が膜を通るしくみを問われ、「濃度の高い方へ」「ATP を使う」などの手がかりがある問題です。', how: ['濃度の高い方から低い方へ(濃度勾配にしたがって)動くなら受動輸送です。', 'その中で、チャネルや輸送体を通るものを促進拡散といいます(水はアクアポリンを通ります)。', '濃度の低い方から高い方へ、ATP のエネルギーを使って運ぶなら能動輸送です(ナトリウムポンプなど)。'], ex: { q: 'ナトリウムポンプは、細胞内の Na⁺ を外へ、細胞外の K⁺ を内へ運ぶ。これは受動輸送か能動輸送か。理由も答えよ。', a: '能動輸送。濃度勾配に逆らって、ATP を分解したエネルギーで運んでいるから。', exp: '細胞内は Na⁺ が少なく K⁺ が多いので、Na⁺ を外へ、K⁺ を内へ運ぶのはどちらも濃度の低い方から高い方への輸送です。ATP 1分子あたり Na⁺ 3個を出し、K⁺ 2個を入れます。' } },
      { name: '細胞小器官の識別:原核細胞・動物細胞・植物細胞', freq: 'よく出る', when: '「〇〇細胞にあって△△細胞にないもの」を選ぶ問題です。', how: ['原核細胞には核膜がなく、膜でできた細胞小器官(ミトコンドリア・葉緑体など)もありません。リボソーム・細胞膜・DNA はあります。', '植物細胞には葉緑体・細胞壁・発達した液胞があります。', '中心体は動物細胞(と一部の植物)にあります。'], ex: { q: '大腸菌(原核生物)の細胞にあるものはどれか。核膜、ミトコンドリア、リボソーム、葉緑体 から選べ。', a: 'リボソーム', exp: 'リボソームは膜をもたない粒で、タンパク質合成のために、すべての生物の細胞にあります。原核細胞には核膜や、膜でできたミトコンドリア・葉緑体はありません。' } },
      { name: '酵素の性質の実験:失活と最適条件', freq: 'よく出る', when: 'カタラーゼと過酸化水素などの実験で、「煮た肝臓」「酸化マンガン(Ⅳ)」などと比べる問題です。', how: ['酵素の本体はタンパク質なので、高温で立体構造がこわれる(変性)と、冷やしても元にもどりません(失活)。', '無機触媒(MnO₂ など)は高温でもはたらき、温度を上げると反応はむしろ速くなります。', '低温では酵素ははたらきにくくなるだけで、温度をもどすと活性がもどります。'], ex: { q: '生の肝臓片、煮た肝臓片、酸化マンガン(Ⅳ)をそれぞれ過酸化水素水に入れた。気体が発生しないものはどれか。理由も答えよ。', a: '煮た肝臓片。肝臓の酵素カタラーゼは熱で変性して失活しているから。', exp: '生の肝臓はカタラーゼをふくむので酸素が発生します。酸化マンガン(Ⅳ)は無機触媒なので、熱の影響を受けずにはたらきます。煮た肝臓では酵素の立体構造がこわれています。' } }
    ],
    more: [
      { lv: 1, q: '呼吸によって ATP をつくる主な場所となる細胞小器官はどれか。', choices: ['ミトコンドリア', 'ゴルジ体', 'リボソーム', 'リソソーム'], a: 'A(ミトコンドリア)', exp: 'ミトコンドリアでは、有機物を酸素を使って分解し、多くの ATP をつくります。内膜とひだ(クリステ)、内部のマトリックスをもちます。' },
      { lv: 1, q: 'リボソームのはたらきを答えよ。', a: 'タンパク質の合成(mRNA の情報をもとにアミノ酸をつなぐ)', exp: 'リボソームは rRNA とタンパク質からできた粒で、翻訳の場です。細胞質基質に浮かぶものと、小胞体の表面につくもの(粗面小胞体)があります。' },
      { lv: 1, q: '細胞膜の基本構造として正しいものはどれか。', choices: ['タンパク質の二重層', 'リン脂質の二重層にタンパク質がうかんでいる', 'セルロースの網目', '糖の一重層'], a: 'B(リン脂質の二重層にタンパク質がうかんでいる)', exp: 'リン脂質は水になじむ頭部を外側、なじまない尾部を内側に向けて二重層をつくります。そこに膜タンパク質がモザイク状にうかび、動き回っています(流動モザイクモデル)。' },
      { lv: 1, q: '酵素の主成分は何か。', a: 'タンパク質', exp: '酵素はタンパク質でできた生体触媒です。特定の基質だけに作用する性質(基質特異性)は、活性部位の立体構造によって生まれます。' },
      { lv: 1, q: 'ヒトの体内ではたらく多くの酵素の最適温度に近いものはどれか。', choices: ['約 5 ℃', '約 37 ℃', '約 70 ℃', '約 100 ℃'], a: 'B(約 37 ℃)', exp: 'ヒトの酵素の多くは体温に近い 35〜40 ℃でよくはたらきます。これより高いと変性しはじめ、急に活性が下がります。' },
      { lv: 1, q: '水を通すチャネルとしてはたらく膜タンパク質を何というか。', a: 'アクアポリン', exp: 'アクアポリンは水分子だけを通す通路です。腎臓の集合管などに多く、水の再吸収にはたらいています。' },
      { lv: 1, q: '原核生物はどれか。', choices: ['酵母', 'ゾウリムシ', '大腸菌', 'アメーバ'], a: 'C(大腸菌)', exp: '大腸菌は核膜をもたない原核生物(細菌)です。酵母・ゾウリムシ・アメーバは核膜をもつ真核生物です。' },
      { lv: 2, q: '胃ではたらくペプシンと、小腸ではたらくトリプシンの最適 pH の組み合わせとして正しいものはどれか。', choices: ['ペプシン 約2、トリプシン 約8', 'ペプシン 約8、トリプシン 約2', 'どちらも約7', 'どちらも約2'], a: 'A(ペプシン 約2、トリプシン 約8)', exp: '酵素の最適 pH は、はたらく場所の環境に合っています。胃液は強い酸性なのでペプシンは pH 2 付近、すい液は弱い塩基性なのでトリプシンは pH 8 付近でよくはたらきます。' },
      { lv: 2, q: '補酵素の性質として正しいものはどれか。', choices: ['分子が大きく、透析で膜を通らない', '分子が小さく熱に比較的強く、透析で酵素から分けられる', 'タンパク質なので熱に弱い', '基質と同じものである'], a: 'B(分子が小さく熱に比較的強く、透析で酵素から分けられる)', exp: '補酵素は低分子の有機物(NAD⁺ など)で、セロハン膜を通るので透析で酵素本体と分けられます。分けると両方とも単独でははたらかず、混ぜると活性がもどります。' },
      { lv: 2, q: '一連の反応の最終産物が、最初の段階の酵素のはたらきをおさえるしくみを何というか。また、その利点を答えよ。', a: 'フィードバック調節。最終産物が十分あるときは合成を止め、むだな物質やエネルギーを使わずにすむ。', exp: '最終産物が多くなると最初の酵素(アロステリック酵素が多い)に結合して活性を下げ、少なくなると阻害が外れて合成が再開します。量を自動的に一定に保つしくみです。' },
      { lv: 2, q: '1辺 1 cm の立方体と 1辺 2 cm の立方体で、「表面積÷体積」の値をそれぞれ求めよ。', a: '1 cm:6 /cm、2 cm:3 /cm', exp: '1 cm の立方体は表面積 6 cm²、体積 1 cm³ で 6。2 cm では表面積 24 cm²、体積 8 cm³ で 3。大きくなるほど体積あたりの表面積が小さくなり、物質の出入りが追いつかなくなります。' },
      { lv: 2, q: 'タンパク質の二次構造(αヘリックスや βシート)を保っている主な結合はどれか。', choices: ['ペプチド結合', 'ジスルフィド結合', '水素結合', 'イオン結合'], a: 'C(水素結合)', exp: '二次構造は、ペプチド結合の C＝O と N−H の間の水素結合で保たれます。ペプチド結合はアミノ酸の並び(一次構造)をつくり、ジスルフィド結合は三次構造を安定させます。' },
      { lv: 2, q: 'ナトリウムポンプが ATP 1分子を使って運ぶイオンの数と向きを答えよ。', a: 'Na⁺ 3個を細胞外へ、K⁺ 2個を細胞内へ', exp: '外へ出す正の電荷の方が多いので、細胞の内側が負になる静止電位づくりにも関わります。神経細胞では、エネルギーの大きな割合をこのポンプが使います。' },
      { lv: 2, q: '細胞分裂のときの紡錘体や、べん毛・繊毛の中心となる細胞骨格はどれか。', choices: ['アクチンフィラメント', '微小管', '中間径フィラメント', 'セルロース'], a: 'B(微小管)', exp: '微小管はチューブリンからなる中空の管で、紡錘体やべん毛・繊毛のじくをつくります。モータータンパク質(ダイニン・キネシン)が微小管の上を動いて物を運びます。' },
      { lv: 2, q: '細胞膜の一部がくびれこんで、外の物質を小胞に包んで取りこむはたらきを何というか。', a: 'エンドサイトーシス', exp: '白血球が細菌を取りこむ食作用もエンドサイトーシスの一つです。逆に、小胞の膜が細胞膜と融合して中身を外へ出すのはエキソサイトーシスです。' },
      { lv: 3, q: '酵素反応の実験で、反応速度が 2.0 μmol/分 の条件で反応を始めた。基質ははじめ 15 μmol しかないとすると、10 分後の生成物の量はいくらか。酵素の量は十分あり、速度は基質がなくなる直前まで一定とする。', a: '15 μmol', exp: '速度だけで計算すると 2.0×10＝20 μmol ですが、基質は 15 μmol しかないので 7.5 分で使い切り、そこで反応が止まります。酵素は触媒なので、生成物の量の上限は基質の量で決まります。' },
      { lv: 3, q: 'ある酵素液を 80 ℃で 10 分加熱してから 37 ℃にもどした場合と、0 ℃で 10 分冷やしてから 37 ℃にもどした場合で、活性はそれぞれどうなるか。理由とともに答えよ。', a: '80 ℃:活性はもどらない(変性による失活)。0 ℃:活性はもどる(低温では動きがにぶくなるだけで構造はこわれない)。', exp: '高温では水素結合などが切れて立体構造がこわれ、元の形にもどれません。低温では分子の運動がにぶくなって反応が遅くなるだけなので、温度をもどすとはたらきも回復します。' },
      { lv: 3, q: '過酸化水素水に、(a) 生の肝臓片、(b) すりつぶした生の肝臓、(c) 酸化マンガン(Ⅳ) を加えて 4 ℃と 37 ℃で比べた。気体の発生が 37 ℃で 4 ℃よりはっきり多くなるのは (a)〜(c) のどれか。最も適切なものを選び、理由を答えよ。', a: '(a) と (b)。酵素は 37 ℃付近でよくはたらき、低温では活性が低いから。', exp: '酵素の反応は最適温度まで温度とともに大きく速くなります。無機触媒の (c) も温度で速くなりますが、酵素ほどの差はありません。すりつぶすと細胞内の酵素が出やすくなり (b) は (a) より速くなります。' },
      { lv: 3, q: 'ヒトの細胞とマウスの細胞の膜タンパク質を別々の色の蛍光で標識してから2つの細胞を融合させると、しばらくして2色が細胞膜全体に混ざった。この結果からわかることを答えよ。', a: '膜タンパク質はリン脂質の二重層の中を横方向に自由に動ける(細胞膜は流動性をもつ)。', exp: 'もし膜タンパク質が固定されていれば、2色は融合した細胞の半分ずつに分かれたままのはずです。混ざったことから、膜が液体のような流動性をもつ「流動モザイクモデル」が支持されました。' }
    ]
  });

  add('b4_meta', {
    pat: [
      { name: '呼吸商(RQ)で呼吸基質を見分ける', freq: 'とてもよく出る', when: '発芽種子などが吸収した O₂ と放出した CO₂ の体積が与えられ、「主な呼吸基質は何か」を問われたときです。', how: ['呼吸商 RQ＝放出した CO₂ の体積÷吸収した O₂ の体積 を計算します。', '炭水化物は 1.0、タンパク質は約 0.8、脂肪は約 0.7 です。', '測定では、KOH で CO₂ を吸収させた装置(O₂ の量がわかる)と、水を入れた装置(O₂−CO₂ がわかる)を比べて求めます。'], ex: { q: 'ある発芽種子が、一定時間に酸素を 100 mL 吸収し、二酸化炭素を 70 mL 放出した。呼吸商と、主な呼吸基質を答えよ。', a: '呼吸商 0.70、脂肪', exp: 'RQ＝70/100＝0.70 で、脂肪の値に近いです。脂肪は炭水化物にくらべて O の割合が少ないので、燃やすのに多くの酸素が必要で、RQ が小さくなります。ゴマやヒマなど脂肪の多い種子で見られます。' } },
      { name: '呼吸・発酵の量計算:反応式の係数で mol をつなぐ', freq: 'よく出る', when: 'グルコースの質量から、消費する O₂ や放出する CO₂ の量を問われたときです。', how: ['呼吸:C₆H₁₂O₆＋6O₂＋6H₂O→6CO₂＋12H₂O。グルコース 1 mol で O₂ 6 mol、CO₂ 6 mol。', 'アルコール発酵:C₆H₁₂O₆→2C₂H₅OH＋2CO₂。グルコース 1 mol で CO₂ 2 mol。', 'グルコース 180 g/mol、CO₂ 44 g/mol、O₂ 32 g/mol を使って質量に直します。'], ex: { q: 'グルコース 9.0 g が呼吸で完全に分解されたとき、放出される CO₂ の質量を求めよ。(C₆H₁₂O₆＝180、CO₂＝44)', a: '13.2 g', exp: 'グルコースは 9.0/180＝0.050 mol。CO₂ はその6倍の 0.30 mol で、0.30×44＝13.2 g。グルコースより重くなるのは、酸素が結びつくからです。' } },
      { name: '光合成速度のグラフ:見かけの光合成速度＋呼吸速度', freq: 'とてもよく出る', when: '光の強さと CO₂ 吸収速度のグラフがあり、「光合成速度」「光補償点」「光飽和点」を問われたときです。', how: ['光の強さ 0 のときの CO₂ 放出速度が呼吸速度です。', 'グラフの値(CO₂ 吸収速度)は見かけの光合成速度で、光合成速度＝見かけの光合成速度＋呼吸速度です。', '吸収速度が 0 になる光の強さが光補償点、それ以上強くしても増えなくなる点が光飽和点です。'], ex: { q: 'ある植物は、暗所で CO₂ を 2 mg/(100 cm²·時) 放出し、ある光の強さでは CO₂ を 8 mg/(100 cm²·時) 吸収した。この光の強さでの光合成速度を求めよ。', a: '10 mg/(100 cm²·時)', exp: '光を当てている間も呼吸は続いているので、実際の光合成で使った CO₂ は、外から吸収した 8 と、呼吸で出した分 2 の合計で 10 です(呼吸速度が明暗で同じと仮定)。' } },
      { name: '陽生植物と陰生植物のグラフの比べ方', freq: 'よく出る', when: '2種類の植物の光-光合成曲線が重ねて描かれ、どちらが陰生植物かを問われたときです。', how: ['陰生植物は呼吸速度が小さく、光補償点が低いので、弱い光でも成長できます。', '陽生植物は光飽和点が高く、強い光のもとでの最大の光合成速度が大きくなります。', '「弱い光の場所でどちらが有利か」は、その光の強さでの見かけの光合成速度を比べて判断します。'], ex: { q: '植物 X は光補償点が低く光飽和点も低い。植物 Y は光補償点も光飽和点も高い。林の下のうす暗い場所で育ちやすいのはどちらか。', a: '植物 X(陰生植物)', exp: '光補償点が低いと、弱い光でも見かけの光合成速度が正になり、有機物をたくわえて成長できます。Y は弱い光では呼吸の方が上回り、有機物が減ってしまいます。' } },
      { name: '呼吸と発酵が同時に起こるとき:O₂ と CO₂ の量から分ける', freq: '難関大で出る', when: '酵母などで、吸収した O₂ と放出した CO₂ の量が与えられ、呼吸と発酵で使ったグルコースの比を問われたときです。', how: ['O₂ は呼吸でしか使わないので、O₂ の量から呼吸のグルコース量(O₂÷6)を出します。', '呼吸で出た CO₂(O₂ と同じ量)を全体の CO₂ から引くと、発酵で出た CO₂ がわかります。', '発酵のグルコース量は、発酵の CO₂÷2 です。'], ex: { q: '酵母が一定時間に O₂ を 6.0 mmol 吸収し、CO₂ を 10 mmol 放出した。呼吸とアルコール発酵で使われたグルコースの物質量の比を求めよ。', a: '呼吸:発酵＝1:2', exp: '呼吸のグルコースは 6.0/6＝1.0 mmol で、CO₂ を 6.0 mmol 出します。残りの CO₂ 4.0 mmol は発酵によるので、発酵のグルコースは 4.0/2＝2.0 mmol。比は 1:2 です。' } }
    ],
    more: [
      { lv: 1, q: '解糖系の反応が行われる場所はどこか。', choices: ['細胞質基質', 'ミトコンドリアのマトリックス', 'ミトコンドリアの内膜', '葉緑体のストロマ'], a: 'A(細胞質基質)', exp: '解糖系はグルコースをピルビン酸に分解する反応で、細胞質基質で行われます。酸素を使わないので、呼吸にも発酵にも共通の段階です。' },
      { lv: 1, q: 'クエン酸回路が行われる場所はどこか。', a: 'ミトコンドリアのマトリックス', exp: 'ピルビン酸はミトコンドリアに入り、マトリックスでクエン酸回路によって CO₂ にまで分解されます。このとき NADH や FADH₂ ができます。' },
      { lv: 1, q: '電子伝達系で、電子を最後に受け取る物質は何か。', a: '酸素(O₂)', exp: 'NADH などの電子は、ミトコンドリア内膜のタンパク質を順に渡され、最後に O₂ が受け取って H⁺ と結びつき水ができます。酸素がないと電子伝達系は止まります。' },
      { lv: 1, q: '光合成で光エネルギーを吸収する光化学系がある場所はどこか。', choices: ['ストロマ', 'チラコイド膜', '外膜', '細胞壁'], a: 'B(チラコイド膜)', exp: '葉緑体の中の平たい袋(チラコイド)の膜にクロロフィルをふくむ光化学系があり、ここで光エネルギーをとらえて ATP と NADPH をつくります。' },
      { lv: 1, q: 'カルビン回路で CO₂ を固定する反応が行われる場所はどこか。', a: '葉緑体のストロマ', exp: 'ストロマでは、チラコイドでつくられた ATP と NADPH を使って CO₂ から有機物がつくられます(カルビン回路)。' },
      { lv: 1, q: '乳酸発酵で、グルコース1分子あたりにできる ATP は何分子か。', a: '2 分子', exp: '発酵では解糖系だけで ATP をつくるので、グルコース1分子あたり ATP は2分子です。酸素を使う呼吸よりずっと少なくなります。' },
      { lv: 1, q: '光合成で発生する酸素 O₂ は、何に由来するか。', choices: ['CO₂', 'H₂O', 'グルコース', 'クロロフィル'], a: 'B(H₂O)', exp: '光化学系Ⅱで水が分解され(2H₂O→4H⁺＋4e⁻＋O₂)、そのときに O₂ が出ます。CO₂ の O は有機物や水の方に入ります。' },
      { lv: 2, q: 'グルコース 18 g を呼吸で完全に分解するのに必要な酸素の質量を求めよ。(C₆H₁₂O₆＝180、O₂＝32)', a: '19.2 g', exp: 'グルコースは 18/180＝0.10 mol。必要な O₂ は6倍の 0.60 mol で、0.60×32＝19.2 g です。' },
      { lv: 2, q: 'ある種子が O₂ を 50 mL 吸収し、CO₂ を 40 mL 放出した。呼吸商と、主な呼吸基質として考えられるものを答えよ。', a: '呼吸商 0.80、タンパク質', exp: 'RQ＝40/50＝0.80 で、タンパク質の値(約 0.8)に近いです。ただし、炭水化物と脂肪が混ざって使われても 0.8 前後になることがあり、RQ だけで決められない場合もあります。' },
      { lv: 2, q: 'ある植物は、暗所で CO₂ を 3 mg/時 放出し、ある光の強さで CO₂ を 12 mg/時 吸収した。この光の強さでの光合成速度(CO₂ の量)を求めよ。', a: '15 mg/時', exp: '光合成速度＝見かけの光合成速度＋呼吸速度＝12＋3＝15 mg/時。呼吸速度は明るいときも暗いときも同じと考えています。' },
      { lv: 2, q: 'ミトコンドリアで ATP 合成酵素がはたらくしくみとして正しいものはどれか。', choices: ['グルコースを直接分解して ATP をつくる', '内膜の内外の H⁺ の濃度差を使い、H⁺ が流れこむ力で ATP をつくる', '光のエネルギーで ATP をつくる', '酸素を直接 ATP に変える'], a: 'B(内膜の内外の H⁺ の濃度差を使い、H⁺ が流れこむ力で ATP をつくる)', exp: '電子伝達系で H⁺ がマトリックスから膜間腔へくみ出され、濃度差ができます。H⁺ が ATP 合成酵素を通ってもどるときに ATP がつくられます(化学浸透)。' },
      { lv: 2, q: '酵母のアルコール発酵で CO₂ が 88 mg 発生した。使われたグルコースの質量を求めよ。(C₆H₁₂O₆＝180、CO₂＝44)', a: '180 mg', exp: 'CO₂ は 88/44＝2.0 mmol。C₆H₁₂O₆→2C₂H₅OH＋2CO₂ より、グルコースは半分の 1.0 mmol＝180 mg。エタノールも 2.0 mmol できます。' },
      { lv: 2, q: 'CO₂ 濃度が低い条件では、光を強くしても光合成速度がある値以上に上がらなかった。このときの光合成の限定要因は何か。', a: 'CO₂ 濃度', exp: '光合成速度は、いちばん不足している条件(限定要因)で決まります。光が十分でも、CO₂ が足りなければカルビン回路が進まないので速度は上がりません。' },
      { lv: 2, q: 'C₄植物の例として正しいものはどれか。', choices: ['イネ', 'トウモロコシ', 'コムギ', 'ダイズ'], a: 'B(トウモロコシ)', exp: 'トウモロコシやサトウキビは C₄植物で、CO₂ をいったん C₄化合物として固定してから、維管束鞘細胞でカルビン回路に渡します。高温・強光の環境で光合成の効率が高くなります。' },
      { lv: 2, q: '脂肪が呼吸基質になるとき、脂肪酸はどのように分解されてクエン酸回路に入るか。', choices: ['解糖系でピルビン酸になる', 'β酸化でアセチル CoA になる', 'アミノ基がとれて有機酸になる', 'そのままミトコンドリアで燃える'], a: 'B(β酸化でアセチル CoA になる)', exp: '脂肪はグリセリンと脂肪酸に分解され、脂肪酸はミトコンドリアで炭素2個ずつ切り出される β酸化を受けてアセチル CoA になり、クエン酸回路に入ります。' },
      { lv: 3, q: '酵母が一定時間に O₂ を 24 mL 吸収し、CO₂ を 36 mL 放出した。呼吸とアルコール発酵で使われたグルコースの量の比を求めよ。(気体の体積は同じ条件で測った)', a: '呼吸:発酵＝2:3', exp: '呼吸ではグルコース1分子あたり O₂ 6、CO₂ 6。呼吸の分は 24/6＝4(単位量)で、CO₂ 24 mL。残りの CO₂ 12 mL は発酵によるので、発酵のグルコースは 12/2＝6。比は 4:6＝2:3 です。' },
      { lv: 3, q: 'ある植物の葉 100 cm² は、光を当てると CO₂ を 12 mg/時 吸収し、暗所では 4 mg/時 放出する。1日のうち 10 時間光を当て、14 時間暗所に置くと、1日で葉 100 cm² にたくわえられるグルコースは何 mg か。(CO₂ 6 分子からグルコース 1 分子、C₆H₁₂O₆＝180、CO₂＝44)', a: '約 44 mg', exp: '1日の CO₂ の正味の吸収量は 12×10−4×14＝120−56＝64 mg。グルコースに直すと 64×180/(6×44)≒43.6≒44 mg。光の時間だけでなく、暗い間の呼吸による消費も引くのがポイントです。' },
      { lv: 3, q: '呼吸ではグルコース1分子あたり最大で約 38 分子の ATP ができ、発酵では 2 分子である。同じ量の ATP を得るのに、発酵は呼吸の約何倍のグルコースが必要か。', a: '約 19 倍', exp: '38÷2＝19 倍です。酸素のない環境で発酵にたよる生物が、大量の糖を消費する理由です。なお、現在の測定では呼吸の ATP は 30 分子前後ともいわれます。' },
      { lv: 3, q: '酸素の同位体 ¹⁸O を含む水 H₂¹⁸O を与えて光合成させると、発生する O₂ に ¹⁸O が含まれた。C¹⁸O₂ を与えた場合は O₂ に ¹⁸O が含まれなかった。この実験からわかることを答えよ。', a: '光合成で発生する O₂ は、CO₂ ではなく水 H₂O の分解に由来する。', exp: '目印をつけた原子がどこへ行くかを追う実験です(ルーベンらの実験)。発生した O₂ に目印が出たのは水を標識したときだけなので、O₂ は水からできていると結論できます。' },
      { lv: 3, q: 'ある種子の呼吸商は 0.85 であった。呼吸基質が炭水化物(RQ 1.0)と脂肪(RQ 0.70)だけだとすると、吸収した酸素のうち、炭水化物の分解に使われた割合を求めよ。', a: '50 %', exp: '吸収した O₂ を 1 とし、そのうち炭水化物に使われた割合を x とすると、放出した CO₂ は 1.0x＋0.70(1−x)。これが 0.85 なので 0.30x＝0.15、x＝0.50 です。' }
    ]
  });

  add('b4_gene', {
    pat: [
      { name: '鋳型鎖から mRNA を書く:向き(5′→3′)と U に注意', freq: 'とてもよく出る', when: 'DNA の塩基配列が与えられ、「転写される mRNA の配列」を問われたときです。', how: ['mRNA は鋳型鎖と相補的に、5′→3′ の向きにつくられます。', '鋳型鎖の 3′ 側から読み、A→U、T→A、G→C、C→G と置きかえます(T ではなく U)。', 'もう一方の鎖(非鋳型鎖)と比べると、T が U に変わっただけの配列になるので検算に使えます。'], ex: { q: 'DNA の鋳型鎖の配列が 3′−TACGGA−5′ のとき、転写される mRNA の配列を 5′→3′ の向きで書け。', a: '5′−AUGCCU−3′', exp: '鋳型鎖の 3′ 側から相補的な塩基を並べると、T→A、A→U、C→G、G→C、G→C、A→U で AUGCCU。mRNA は鋳型鎖と逆向きなので、左が 5′ 側になります。最初の AUG は開始コドンです。' } },
      { name: 'コドン表で翻訳する:開始コドンから3つずつ', freq: 'とてもよく出る', when: 'mRNA の配列とコドン表が与えられ、「できるアミノ酸の並び」を問われたときです。', how: ['5′ 側から AUG(開始コドン、メチオニン)を探し、そこから3塩基ずつ区切ります(読み枠)。', 'コドン表で1つずつアミノ酸に直します。', '終止コドン(UAA、UAG、UGA)が出たらそこで終わります。終止コドンはアミノ酸を指定しません。'], ex: { q: 'mRNA 5′−GCAUGGCUAAAUAAGC−3′ を翻訳すると、どのようなアミノ酸の並びになるか。(AUG:メチオニン、GCU:アラニン、AAA:リシン、UAA:終止)', a: 'メチオニン−アラニン−リシン', exp: '5′ 側から AUG を探すと 3 番目から始まります。AUG|GCU|AAA|UAA と区切ると、メチオニン・アラニン・リシンのあと終止コドン UAA で止まります。先頭の GC は翻訳されません。' } },
      { name: '突然変異の影響:置換・欠失・挿入', freq: 'よく出る', when: '「1塩基が置換(欠失)すると、タンパク質はどうなるか」を問われたときです。', how: ['置換:1つのコドンだけが変わります。同じアミノ酸のまま(同義置換)、別のアミノ酸、終止コドンになる場合があります。', '1塩基の欠失・挿入:そこから後ろの読み枠がすべてずれ(フレームシフト)、アミノ酸が大きく変わります。', '3塩基の欠失・挿入なら、アミノ酸1つが減る(増える)だけで、読み枠はずれません。'], ex: { q: '遺伝子の翻訳領域の中ほどで、1塩基が欠失した。できるタンパク質への影響として考えられることを答えよ。', a: '欠失した位置から後ろの読み枠がずれ、アミノ酸配列が大きく変わる。途中で終止コドンが現れて短くなることも多い。', exp: '3塩基ずつ読むので、1つ抜けると後ろの区切りがすべて1つずれます(フレームシフト)。置換よりも影響が大きく、はたらきを失ったタンパク質になりやすいです。' } },
      { name: '制限酵素で切った断片の数:直鎖か環状か', freq: 'よく出る', when: 'DNA を制限酵素で切ったときの「断片の数」や、電気泳動の結果から切断部位を決める問題です。', how: ['直鎖状 DNA は、切断部位が k か所なら断片は k＋1 本です。', '環状 DNA(プラスミド)は、k か所で切ると断片は k 本です。', '2種類の酵素で別々に切った結果と、同時に切った結果を組み合わせて位置を決めます。'], ex: { q: '制限酵素 X の切断部位が2か所ある DNA を X で切った。DNA が直鎖状の場合と環状の場合、断片はそれぞれ何本になるか。', a: '直鎖状 3本、環状 2本', exp: '直鎖のひもは2か所切ると3本になります。輪ゴムのような環状は、1か所目で切ると1本のひもになるだけなので、2か所切ると2本です。プラスミドの問題でよく使います。' } },
      { name: 'PCR の増え方:1回で2倍', freq: 'よく出る', when: 'PCR の回数(サイクル数)と DNA の量の関係を問われたときです。', how: ['PCR は「熱で2本鎖をほどく→プライマーを結合させる→DNA ポリメラーゼで伸ばす」を1サイクルとします。', '1サイクルで DNA は2倍になるので、n サイクル後は 2ⁿ 倍です。', '2¹⁰≒1000(10³)を使うと、けたを速く見積もれます。'], ex: { q: '1分子の DNA を PCR で 30 サイクル増幅すると、理論上およそ何分子になるか。', a: '約 1.1×10⁹ 分子(約 10 億分子)', exp: '30 サイクルで 2³⁰ 倍です。2¹⁰≒10³ なので 2³⁰≒10⁹。正確には 1,073,741,824 です。ごく少量の DNA からでも、調べられる量まで短時間で増やせます。' } },
      { name: 'オペロンの調節:リプレッサーがはたらくかどうか', freq: 'よく出る', when: '大腸菌のラクトースオペロンなどで、「ラクトースがあるとき・ないとき」に遺伝子が転写されるかを問われたときです。', how: ['調節遺伝子からつくられるリプレッサーは、オペレーターに結合して転写を止めます。', 'ラクトース(の代謝物)がリプレッサーに結合すると、リプレッサーはオペレーターから外れ、転写が始まります。', '調節遺伝子やオペレーターに変異があると、ラクトースの有無にかかわらず転写される(または転写されない)ことになります。'], ex: { q: '大腸菌の培地にグルコースがなく、ラクトースがあるとき、ラクトースを分解する酵素の遺伝子は転写されるか。理由も答えよ。', a: '転写される。ラクトースの代謝物がリプレッサーに結合してオペレーターから外し、RNA ポリメラーゼが転写できるようになるから。', exp: '必要なときだけ酵素をつくるしくみです。ラクトースがないときはリプレッサーがオペレーターをふさぎ、むだな酵素をつくりません。' } }
    ],
    more: [
      { lv: 1, q: 'DNA の複製で、新しくできた2本鎖 DNA のそれぞれが、もとの鎖を1本ずつ受けつぐ方式を何というか。', a: '半保存的複製', exp: 'もとの2本鎖がほどけ、それぞれを鋳型として新しい鎖がつくられます。メセルソンとスタールの実験で確かめられました。' },
      { lv: 1, q: 'DNA ポリメラーゼが新しい鎖を伸ばす向きはどれか。', choices: ['5′→3′ の向きだけ', '3′→5′ の向きだけ', 'どちらの向きにも', '向きは決まっていない'], a: 'A(5′→3′ の向きだけ)', exp: 'DNA ポリメラーゼは、伸びている鎖の 3′ 末端にヌクレオチドをつなぐので、5′→3′ の向きにしか合成できません。このためラギング鎖は短い断片で合成されます。' },
      { lv: 1, q: 'DNA の情報を RNA に写しとる反応(転写)を行う酵素は何か。', a: 'RNA ポリメラーゼ', exp: 'RNA ポリメラーゼは、プロモーターに結合して DNA の2本鎖をほどき、鋳型鎖に相補的な RNA を 5′→3′ の向きに合成します。' },
      { lv: 1, q: '真核生物で、転写された RNA からイントロンを取り除き、エキソンをつなぐ過程を何というか。', a: 'スプライシング', exp: 'スプライシングは核の中で行われ、できた mRNA が核の外へ出て翻訳されます。原核生物にはふつうイントロンがありません。' },
      { lv: 1, q: 'tRNA がもつ、mRNA のコドンと相補的な3つの塩基を何というか。', a: 'アンチコドン', exp: 'tRNA はアンチコドンでコドンと対になり、反対側の端に運んできたアミノ酸を、リボソームでつないでいきます。' },
      { lv: 1, q: '翻訳の開始コドンを答えよ。', a: 'AUG', exp: 'AUG はメチオニンを指定し、翻訳の始まりの合図になります。終止コドンは UAA、UAG、UGA の3つです。' },
      { lv: 1, q: 'DNA の一方の鎖の配列が ATGC のとき、相補的な鎖の配列(対になる順に)を答えよ。', a: 'TACG', exp: 'DNA では A と T、G と C が対になります。A→T、T→A、G→C、C→G で TACG です。RNA なら T のかわりに U になります。' },
      { lv: 2, q: '重い窒素 ¹⁵N だけをふくむ DNA をもつ大腸菌を、¹⁴N の培地で2回分裂させた。DNA を密度で分けると、中間の重さ:軽い DNA の比はどうなるか。', a: '中間:軽い＝1:1', exp: '1回目の分裂後はすべて ¹⁵N と ¹⁴N の鎖を1本ずつもつ中間。2回目ではそれぞれが中間1と軽い1に分かれるので 1:1 です。全保存的なら重いものが残るはずで、半保存的複製の証拠になります。' },
      { lv: 2, q: 'ある mRNA の翻訳される部分は、開始コドンから終止コドンまでで 303 塩基である。できるポリペプチドのアミノ酸の数を求めよ。', a: '100 個', exp: '303÷3＝101 コドンですが、最後の終止コドンはアミノ酸を指定しないので 101−1＝100 個です。終止コドンを数えるかどうかに注意します。' },
      { lv: 2, q: '3つの塩基で1つのアミノ酸を指定するとき、コドンは全部で何通りあるか。', a: '64 通り', exp: '4種類の塩基を3つ並べるので 4³＝64 通りです。アミノ酸は約20種類なので、1つのアミノ酸を複数のコドンが指定することが多くあります。' },
      { lv: 2, q: '翻訳領域で1塩基の置換が起こっても、アミノ酸が変わらないことがある。その理由を答えよ。', a: '1つのアミノ酸を指定するコドンが複数あり、置換後のコドンも同じアミノ酸を指定する場合があるから。', exp: '特にコドンの3番目の塩基は、変わっても同じアミノ酸になることが多いです(同義置換)。このような変異はタンパク質に影響しません。' },
      { lv: 2, q: '6塩基の配列を認識する制限酵素の切断部位は、塩基がでたらめに並んでいるとすると、平均して何塩基に1回現れるか。', a: '約 4096 塩基に1回', exp: '各位置で特定の塩基になる確率は 1/4 なので、6塩基がそろう確率は (1/4)⁶＝1/4096 です。4塩基認識なら 256 塩基に1回と、もっと頻繁に切れます。' },
      { lv: 2, q: '遺伝子組換えで、目的の遺伝子と抗生物質耐性遺伝子をもつプラスミドを大腸菌に入れたあと、抗生物質を含む培地で培養する理由を答えよ。', a: 'プラスミドを取りこんだ大腸菌だけが生き残るので、それらを選び出せるから。', exp: 'プラスミドを取りこむ大腸菌はごく一部です。抗生物質の中では耐性遺伝子をもつ菌だけが増えるので、組換えに成功した菌を効率よく選べます。' },
      { lv: 2, q: 'DNA の電気泳動で、DNA 断片はどちらの極へ動くか。また、どのような断片ほど速く動くか。', a: '陽極へ動く。短い(小さい)断片ほど速く動く。', exp: 'DNA はリン酸の部分が負の電荷をもつので陽極へ移動します。ゲルの網目の中では、短い断片ほどすり抜けやすく、遠くまで進みます。' },
      { lv: 2, q: 'DNA の複製で、ラギング鎖側でつくられる短い DNA 断片を何というか。', a: '岡崎フラグメント', exp: 'DNA ポリメラーゼは 5′→3′ にしか伸ばせないので、ほどける向きと逆の鎖では短い断片を少しずつつくり、あとで DNA リガーゼがつなぎます。発見した岡崎令治にちなんだ名前です。' },
      { lv: 3, q: '長さ 10 kb の直鎖状 DNA を制限酵素 A で切ると 3 kb と 7 kb、制限酵素 B で切ると 4 kb と 6 kb の断片ができた。A と B で同時に切ると 3 kb、1 kb、6 kb の断片ができた。左端から測って、A と B の切断部位はそれぞれ何 kb の位置か(A は左端から 3 kb の位置とする)。', a: 'A:3 kb、B:4 kb', exp: 'B は左端から 4 kb か 6 kb のどちらかです。B が 4 kb なら同時切断で 3、1、6 kb になり、6 kb なら 3、3、4 kb になります。結果は 3、1、6 kb なので B は 4 kb の位置です。' },
      { lv: 3, q: 'mRNA 5′−AUGUUUGGCAAAUGGUAG−3′ が翻訳されてできるアミノ酸の並びを答えよ。また、UGG の G が A に置換されて UGA になると、どうなるか。(AUG:Met、UUU:Phe、GGC:Gly、AAA:Lys、UGG:Trp、UAG・UGA:終止)', a: 'Met−Phe−Gly−Lys−Trp。置換後は Met−Phe−Gly−Lys で止まり、短くなる。', exp: '3つずつ AUG|UUU|GGC|AAA|UGG|UAG と区切ります。UGG(Trp)が終止コドン UGA に変わると、そこで翻訳が終わってしまいます(ナンセンス変異)。' },
      { lv: 3, q: 'ある遺伝子はエキソン 1〜4 からなり、エキソン 1 と 4 は必ず使われ、エキソン 2 と 3 はそれぞれ使われる場合と使われない場合がある(順番は入れかわらない)。選択的スプライシングで何種類の mRNA ができうるか。', a: '4 種類', exp: 'エキソン 2 を使う・使わないの2通り、エキソン 3 も2通りで、2×2＝4 種類(1-2-3-4、1-2-4、1-3-4、1-4)です。1つの遺伝子から複数のタンパク質ができるしくみです。' },
      { lv: 3, q: 'ラクトースオペロンの調節遺伝子に変異が起こり、はたらくリプレッサーがつくれなくなった大腸菌がある。この菌では、ラクトース分解酵素の遺伝子の転写はどうなるか。', a: 'ラクトースがなくても、常に転写される。', exp: 'リプレッサーがないと、オペレーターをふさぐものがないので、RNA ポリメラーゼはいつでも転写できます。調節のしくみが壊れ、必要のないときにも酵素がつくられ続けます。' }
    ]
  });

  add('b4_dev', {
    pat: [
      { name: '配偶子の比から交配の分離比を組み立てる', freq: 'とてもよく出る', when: '2組の遺伝子について、交配して生まれる子の表現型の比を問われたときです。', how: ['まず親がつくる配偶子の種類と比を書き出します(独立なら AaBb は AB:Ab:aB:ab＝1:1:1:1)。', '配偶子どうしの組み合わせを表にするか、遺伝子ごとに分けて比をかけ合わせます。', '独立した遺伝子なら、Aa×Aa の 3:1 と Bb×Bb の 3:1 をかけて 9:3:3:1 のように計算できます。'], ex: { q: '2組の遺伝子が独立している AaBb と aabb を交配した。子の表現型 [AB]:[Ab]:[aB]:[ab] の比を求めよ。', a: '1:1:1:1', exp: 'aabb の配偶子は ab だけなので、子の表現型は AaBb がつくる配偶子の比そのままになります。AaBb の配偶子は AB:Ab:aB:ab＝1:1:1:1 なので、子も 1:1:1:1 です(検定交雑)。' } },
      { name: '組換え価:検定交雑の結果から求める', freq: 'とてもよく出る', when: '連鎖している2つの遺伝子について、検定交雑の子の数が与えられているときです。', how: ['数が少ない2つの表現型が、組換えでできたものです。', '組換え価(%)＝組換えでできた個体の数÷全体の数×100。', '組換え価が r % なら、親型の配偶子はそれぞれ (100−r)/2 %、組換え型はそれぞれ r/2 % です。'], ex: { q: 'AaBb の個体を aabb と検定交雑すると、[AB] 45、[Ab] 5、[aB] 5、[ab] 45 の子が生じた。組換え価を求めよ。', a: '10 %', exp: '数が少ない [Ab] と [aB] が組換え型です。(5＋5)/(45＋5＋5＋45)×100＝10 %。多い方が [AB] と [ab] なので、A と B が同じ染色体に乗った相引の連鎖とわかります。' } },
      { name: '三点交雑:距離の足し算で遺伝子の並び順を決める', freq: 'よく出る', when: '3つの遺伝子どうしの組換え価が与えられ、染色体上の並び順を問われたときです。', how: ['3つの組換え価のうち、最大のものが両端の2遺伝子の間の値です。', '残りの2つの値の和が最大値に(ほぼ)等しくなることを確かめます。', '最大値をつくらない残りの遺伝子が真ん中にきます。'], ex: { q: '遺伝子 A と B の組換え価は 8 %、B と C は 3 %、A と C は 11 % であった。3つの遺伝子の並び順を答えよ。', a: 'A−B−C(または C−B−A)', exp: '最大の 11 % が A と C の間なので、A と C が両端です。8＋3＝11 で、B が真ん中にあれば距離の足し算が合います。' } },
      { name: '誘導の実験:どこを移植するとどうなるか', freq: 'よく出る', when: 'イモリなどの胚で、一部を別の胚に移植した結果から、誘導のしくみを考える問題です。', how: ['移植した部分が「自分の予定どおりの組織になったか」と「まわりの組織を別のものに変えたか」を分けて考えます。', '原口背唇部(形成体)は、移植先で脊索などになり、まわりの外胚葉を神経管に誘導して二次胚をつくります。', '時期によって予定運命が決まっているか(決定)を、移植片が移植先に合わせて変わるかで判断します。'], ex: { q: 'イモリの初期原腸胚の原口背唇部を、別の初期原腸胚の腹側に移植した。どのような結果になるか。', a: '移植先の腹側に、神経管などをもつ二次胚ができる。', exp: '原口背唇部は形成体としてはたらき、接した外胚葉を神経に誘導します。移植片自身は主に脊索になり、二次胚の神経管などの多くは移植先(宿主)の細胞からできます(シュペーマンの実験)。' } },
      { name: '減数分裂でできる配偶子の種類:2ⁿ 通り', freq: 'よく出る', when: '染色体数 2n が与えられ、「乗換えを考えないとき配偶子の染色体の組み合わせは何通りか」を問われたときです。', how: ['相同染色体の対が n 組あります。', '減数分裂で、各対のどちらが配偶子に入るかは独立に2通りです。', '組み合わせは 2ⁿ 通り。受精で生じる組み合わせは 2ⁿ×2ⁿ 通りになります。'], ex: { q: '体細胞の染色体数が 2n＝8 の生物で、乗換えを考えないとき、1個体がつくる配偶子の染色体の組み合わせは何通りか。', a: '16 通り', exp: '相同染色体は 4 組なので 2⁴＝16 通り。ヒト(2n＝46)では 2²³≒840 万通りになり、さらに乗換えが加わるので、同じ親からも多様な子が生まれます。' } }
    ],
    more: [
      { lv: 1, q: '減数分裂で、相同染色体が対合して二価染色体ができるのはいつか。', choices: ['第一分裂前期', '第一分裂後期', '第二分裂前期', '第二分裂後期'], a: 'A(第一分裂前期)', exp: '第一分裂前期に相同染色体どうしが並んで対合し、二価染色体になります。このとき乗換えが起こることがあります。' },
      { lv: 1, q: '卵割の特徴として正しいものはどれか。', choices: ['細胞が成長しながら分裂する', '分裂ごとに細胞(割球)が小さくなる', '分裂の速度が体細胞分裂より遅い', '分裂のたびに染色体数が半分になる'], a: 'B(分裂ごとに細胞(割球)が小さくなる)', exp: '卵割では、間期に細胞が大きくならないまま分裂をくり返すので、割球はどんどん小さくなります。そのぶん分裂の速さは速いです。' },
      { lv: 1, q: '外胚葉から分化するものはどれか。', choices: ['神経管・表皮', '筋肉・骨', '消化管の内側の上皮', '心臓'], a: 'A(神経管・表皮)', exp: '外胚葉からは表皮や神経系(脳・脊髄)、目の水晶体などができます。筋肉・骨・心臓は中胚葉、消化管の上皮は内胚葉からできます。' },
      { lv: 1, q: '中胚葉から分化するものを1つ答えよ。', a: '筋肉(ほかに骨、血管、心臓、腎臓など)', exp: '中胚葉は脊索・体節・腎節・側板に分かれ、体節から骨格筋や脊椎骨、側板から心臓や血管などができます。' },
      { lv: 1, q: '内胚葉から分化するものはどれか。', choices: ['脊髄', '肝臓', '骨格筋', '皮膚の表皮'], a: 'B(肝臓)', exp: '内胚葉からは消化管の内側の上皮、肝臓、すい臓、肺などができます。' },
      { lv: 1, q: '被子植物の胚乳の核相を答えよ。', a: '3n', exp: '重複受精で、精細胞の1つが中央細胞の2つの極核(n＋n)と合体するので、胚乳は 3n になります。もう1つの精細胞は卵細胞と合体して胚(2n)になります。' },
      { lv: 1, q: 'からだの前後軸にそって各部分の形をつくる指令を出し、変異すると体の一部が別の部分に置きかわる遺伝子を何というか。', choices: ['ホメオティック遺伝子', '母性効果遺伝子', '調節遺伝子', 'がん遺伝子'], a: 'A(ホメオティック遺伝子)', exp: 'ショウジョウバエのホメオティック遺伝子に変異が起こると、触角の位置に脚が生えるなど、体の部分が別の部分に置きかわります。' },
      { lv: 2, q: 'A と B が完全に連鎖(組換えなし)し、相引(AB/ab)の個体を aabb と検定交雑した。子の表現型の比を求めよ。', a: '[AB]:[ab]＝1:1', exp: '組換えがないと、AB/ab の配偶子は AB と ab の2種類だけです。検定交雑では配偶子の比がそのまま子の表現型の比になり、[AB]:[ab]＝1:1 です。' },
      { lv: 2, q: 'A と B が相引で連鎖し、組換え価は 15 % である。AaBb を aabb と検定交雑したとき、子の表現型 [AB]:[Ab]:[aB]:[ab] の比を求めよ。', a: '17:3:3:17', exp: '組換え型の配偶子 Ab と aB はそれぞれ 7.5 %、親型の AB と ab はそれぞれ 42.5 %。比は 42.5:7.5:7.5:42.5＝17:3:3:17 です。' },
      { lv: 2, q: '独立した2組の遺伝子について AaBb どうしを交配し、子が 1600 個体生まれた。[AB]、[Ab]、[aB]、[ab] の個体数の期待値を求めよ。', a: '[AB] 900、[Ab] 300、[aB] 300、[ab] 100', exp: '比は 9:3:3:1 で、合計 16 にあたります。1600÷16＝100 なので、900:300:300:100 です。' },
      { lv: 2, q: '2n＝6 の生物で、乗換えを考えないとき、配偶子の染色体の組み合わせは何通りか。', a: '8 通り', exp: '相同染色体が 3 組あり、それぞれ2通りなので 2³＝8 通りです。' },
      { lv: 2, q: 'カエルの胞胚で、動物極側の部分(アニマルキャップ)だけを培養すると表皮になるが、植物極側の部分と接して培養すると中胚葉の組織ができる。このような誘導を何というか。', a: '中胚葉誘導', exp: '植物極側(予定内胚葉)の細胞が、接した動物極側の細胞に中胚葉をつくらせます。発見者の名から、ニューコープの実験として知られています。' },
      { lv: 2, q: 'ショウジョウバエの卵で、前方にかたよって分布し、頭部のでき方を決める母性効果遺伝子の mRNA はどれか。', choices: ['ビコイド', 'ナノス', 'ギャップ', 'ペアルール'], a: 'A(ビコイド)', exp: 'ビコイド mRNA は卵の前端に局在し、翻訳されたタンパク質が前ほど濃い濃度勾配をつくって頭部側を決めます。ナノスは後端に局在します。' },
      { lv: 2, q: 'カエルの受精卵で、精子が進入した側と反対側にできる灰色三日月環は、将来どちら側になるか。', a: '背側', exp: '精子の進入で表層が回転し、その反対側に灰色三日月環ができます。この付近から原口背唇部ができ、背側(脊索や神経管ができる側)になります。' },
      { lv: 2, q: '体細胞の G₁ 期の DNA 量を 2 とすると、減数分裂でできた精子の DNA 量はいくらか。', a: '1', exp: 'DNA は S 期に複製されて 4 になり、第一分裂で 2、第二分裂で 1 になります。受精すると 1＋1 で 2 にもどります。' },
      { lv: 3, q: 'A と B が相引で連鎖し、組換え価は 20 % である(雌雄とも同じ)。AaBb どうしを交配したとき、子の表現型 [AB]:[Ab]:[aB]:[ab] の比を求めよ。', a: '66:9:9:16', exp: '配偶子は AB 0.4、Ab 0.1、aB 0.1、ab 0.4。[ab] は ab×ab で 0.16。[aB] は aa かつ B をもつもので、aa の確率 0.5×0.5＝0.25 から aabb の 0.16 を引いて 0.09。[Ab] も 0.09、[AB] は残りの 0.66 です。' },
      { lv: 3, q: '遺伝子 A と B の組換え価は 12 %、B と C は 5 %、A と C は 7 % であった。3つの遺伝子の並び順を答えよ。', a: 'A−C−B(または B−C−A)', exp: '最大の 12 % が A と B の間なので A と B が両端です。7＋5＝12 で、C が真ん中にあると足し算が合います。' },
      { lv: 3, q: 'ハツカネズミの黄色の毛の遺伝子 Y は、黒色の y に対して優性だが、YY の個体は胎児のうちに死ぬ。黄色どうし(Yy×Yy)を交配すると、生まれる子の黄色:黒色の比はどうなるか。', a: '黄色:黒色＝2:1', exp: '組み合わせは YY:Yy:yy＝1:2:1 ですが、YY は生まれません。生まれるのは Yy(黄色)2 と yy(黒色)1 なので 2:1 です。3:1 にならないことから致死遺伝子の存在がわかります。' },
      { lv: 3, q: 'ヒトの赤緑色覚異常の遺伝子は X 染色体上にあり、正常に対して劣性である。保因者の母親と色覚が正常な父親の間に生まれる子で、息子と娘それぞれが色覚異常になる確率を求めよ。', a: '息子 1/2、娘 0', exp: '母は XᴬXᵃ、父は XᴬY。息子は母から X をもらうので、Xᵃ をもらう確率 1/2 で色覚異常。娘は父から必ず Xᴬ をもらうので色覚異常にはなりません(1/2 の確率で保因者)。' },
      { lv: 3, q: '遺伝子型 AA の植物のめしべに、aa の植物の花粉を受粉させた。できた種子の胚と胚乳の遺伝子型を答えよ。', a: '胚 Aa、胚乳 AAa', exp: '卵細胞は A、極核2つも A と A、精細胞は 2 つとも a です。胚は A＋a で Aa、胚乳は A＋A＋a で AAa(3n)になります。胚乳では母親の遺伝子が2倍入ります。' }
    ]
  });

  add('b4_resp', {
    pat: [
      { name: '伝導速度:2か所を刺激して時間の差から求める', freq: 'とてもよく出る', when: '神経筋標本で、筋肉から異なる距離の2点を刺激し、収縮までの時間が与えられている問題です。', how: ['2点の距離の差と、収縮までの時間の差を求めます。', 'シナプスの伝達や筋肉の収縮にかかる時間は両方に共通なので、差をとると消えます。', '伝導速度＝距離の差÷時間の差。単位を m/s にそろえます。'], ex: { q: '神経筋標本で、筋肉から 5.0 cm の点を刺激すると 6.0 ミリ秒後、2.0 cm の点を刺激すると 4.5 ミリ秒後に筋肉が収縮しはじめた。伝導速度と、神経の末端に興奮が届いてから筋肉が収縮するまでの時間を求めよ。', a: '伝導速度 20 m/s、3.5 ミリ秒', exp: '距離の差 3.0 cm を時間の差 1.5 ミリ秒で進むので 0.030/0.0015＝20 m/s。2.0 cm 伝わるのに 1.0 ミリ秒かかるので、残りの 4.5−1.0＝3.5 ミリ秒が伝達と筋肉の収縮の準備にかかる時間です。' } },
      { name: '活動電位の形とイオンの動き', freq: 'とてもよく出る', when: '膜電位の時間変化のグラフがあり、各部分で何が起きているかを問われたときです。', how: ['静止状態では、K⁺ が漏れ出て膜の内側が負(約 −70 mV)になっています。', '刺激で電位依存性 Na⁺ チャネルが開き、Na⁺ が流れこんで内側が正に逆転します(脱分極)。', 'すぐに Na⁺ チャネルが閉じて K⁺ チャネルが開き、K⁺ が流れ出て元にもどります(再分極)。'], ex: { q: '活動電位が発生して膜電位が負から正へ急に変わるとき、主に起こっているイオンの動きを答えよ。', a: 'Na⁺ が細胞の外から内へ流れこむ', exp: '細胞の外は Na⁺ が多いので、Na⁺ チャネルが開くと濃度差と電気的な引力で一気に流れこみます。正の電荷が入るので、内側が正に変わります。' } },
      { name: '全か無かの法則と、刺激の強さの伝わり方', freq: 'よく出る', when: '刺激の強さを変えたときの、1本の神経繊維と神経(繊維の束)の反応のちがいを問われたときです。', how: ['1本の神経繊維は、閾値以上の刺激では同じ大きさの活動電位を出し、閾値未満では出しません(全か無かの法則)。', '神経(束)では、閾値の異なる繊維が混ざっているので、刺激を強くすると興奮する繊維の数が増え、全体の反応が大きくなります。', '刺激の強さは、1本の繊維では活動電位の「頻度」として伝えられます。'], ex: { q: '1本の神経繊維に、閾値の2倍の強さの刺激を与えた。閾値ちょうどの刺激のときと比べて、活動電位の大きさはどうなるか。', a: '変わらない', exp: '1本の神経繊維では、閾値をこえれば活動電位の大きさは一定です(全か無かの法則)。強い刺激は、活動電位がくり返し発生する頻度が上がることで伝えられます。' } },
      { name: '筋収縮の滑り説:どの部分の長さが変わるか', freq: 'よく出る', when: 'サルコメア(筋節)の図があり、収縮したとき各部分の長さがどうなるかを問われたときです。', how: ['暗帯(A帯)はミオシンフィラメントの長さで、収縮しても変わりません。', 'アクチンフィラメントがミオシンの間にすべりこむので、明帯(I帯)と H帯が短くなります。', 'サルコメアの長さ＝暗帯＋明帯。数値が与えられたら、フィラメントの長さを使って計算します。'], ex: { q: '骨格筋が収縮したとき、長さが変わらないのはどれか。暗帯、明帯、H帯、サルコメア から選べ。', a: '暗帯', exp: 'フィラメントそのものは縮まず、アクチンフィラメントがミオシンフィラメントの間にすべりこみます。ミオシンのある暗帯の長さは同じで、明帯・H帯・サルコメアが短くなります。' } },
      { name: 'シナプスでの伝達は一方向:理由を説明する', freq: 'よく出る', when: '「軸索の途中を刺激すると興奮は両方向に伝わるが、シナプスでは一方向にしか伝わらない」理由を問われたときです。', how: ['伝導(1本の神経細胞の中)は、刺激した点から両方向に伝わります。', '伝達(シナプス)では、神経伝達物質を放出するのはシナプス前細胞の末端だけです。', '受容体はシナプス後細胞の膜にだけあるので、逆向きには伝わりません。'], ex: { q: 'シナプスで興奮が一方向にしか伝わらない理由を説明せよ。', a: '神経伝達物質はシナプス前細胞の軸索の末端からだけ放出され、それを受け取る受容体はシナプス後細胞にだけあるから。', exp: '電気の信号が化学物質の信号に変わるところに方向性があります。このため、神経回路の中で情報は決まった向きに流れます。' } }
    ],
    more: [
      { lv: 1, q: 'ヒトの網膜で、色の区別にはたらき、明るいところでよくはたらく視細胞はどれか。', choices: ['桿体細胞', '錐体細胞', '視神経細胞', '色素細胞'], a: 'B(錐体細胞)', exp: '錐体細胞は黄斑に多く、赤・緑・青の光によく反応する3種類があって色を区別します。桿体細胞はうす暗いところで明暗を感じます。' },
      { lv: 1, q: '網膜で視神経が束になって出ていく部分には視細胞がなく、光を感じない。この部分を何というか。', a: '盲斑', exp: '盲斑には視細胞がないので、ここに像が結ばれても見えません。ふだんは両目で補い合い、脳が補完するので気づきません。' },
      { lv: 1, q: '静止状態のニューロンの膜電位について正しいものはどれか。', choices: ['内側が外側に対して正(約 ＋70 mV)', '内側が外側に対して負(約 −70 mV)', '内外の電位差は 0', '内側と外側が交互に入れかわる'], a: 'B(内側が外側に対して負(約 −70 mV))', exp: '静止電位は、開いている K⁺ チャネルから K⁺ が外へ漏れ出ることで、内側が負になってできます。値はおよそ −60〜−70 mV です。' },
      { lv: 1, q: '有髄神経繊維で、興奮がランビエ絞輪からランビエ絞輪へとびとびに伝わることを何というか。', a: '跳躍伝導', exp: '髄鞘は電気を通しにくいので、活動電位は髄鞘のすき間(ランビエ絞輪)でだけ発生します。そのため興奮がとびとびに伝わり、伝導速度が大きくなります。' },
      { lv: 1, q: '運動神経の末端から放出され、筋肉に興奮を伝える神経伝達物質は何か。', a: 'アセチルコリン', exp: '運動神経と骨格筋のシナプスではアセチルコリンが放出され、筋細胞の受容体に結合して筋細胞を興奮させます。' },
      { lv: 1, q: '骨格筋の収縮で、筋小胞体から放出されて収縮の引き金となるイオンはどれか。', choices: ['Na⁺', 'K⁺', 'Ca²⁺', 'Cl⁻'], a: 'C(Ca²⁺)', exp: '興奮が伝わると筋小胞体から Ca²⁺ が放出され、トロポニンに結合します。これによりアクチンとミオシンが結合できるようになり、収縮が始まります。' },
      { lv: 1, q: 'ヒトの耳で、からだの回転を感じる器官はどれか。', choices: ['うずまき管', '半規管', '前庭', '鼓膜'], a: 'B(半規管)', exp: '半規管は3本の半円形の管で、回転するとリンパ液が動いて感覚毛を曲げ、回転を感じます。前庭は傾き、うずまき管は音を感じます。' },
      { lv: 2, q: 'ある神経で、6.0 cm 離れた2点を刺激したとき、筋肉が収縮するまでの時間の差は 2.0 ミリ秒であった。伝導速度を求めよ。', a: '30 m/s', exp: '0.060 m を 0.0020 s で伝わるので 0.060÷0.0020＝30 m/s。cm と ms をそのまま割ると 3.0 となり、単位の換算をまちがえやすいので注意します。' },
      { lv: 2, q: '同じ太さで比べると、有髄神経繊維の方が無髄神経繊維より伝導速度が大きい。その理由を答えよ。', a: '髄鞘が絶縁体としてはたらき、興奮がランビエ絞輪だけでとびとびに伝わる(跳躍伝導)から。', exp: '活動電位を発生させる場所が少ないほど、伝わるのに時間がかかりません。無髄神経では膜の全体で次々に発生させる必要があるので遅くなります。' },
      { lv: 2, q: '神経(多数の神経繊維の束)を刺激するとき、閾値以上で刺激を強くしていくと、記録される活動電位の大きさはある範囲で大きくなる。その理由を答えよ。', a: '神経繊維ごとに閾値がちがい、刺激を強くするほど興奮する繊維の数が増えるから。', exp: '1本1本は全か無かの法則にしたがいますが、束全体の電位は興奮した繊維の合計です。すべての繊維が興奮すると、それ以上は大きくなりません。' },
      { lv: 2, q: '骨格筋が収縮したとき、短くなる部分の組み合わせとして正しいものはどれか。', choices: ['暗帯と明帯', '明帯と H帯', '暗帯と H帯', '暗帯だけ'], a: 'B(明帯と H帯)', exp: 'アクチンフィラメントがミオシンフィラメントの間にすべりこむので、アクチンだけの明帯と、ミオシンだけの H帯が短くなります。暗帯の長さは変わりません。' },
      { lv: 2, q: '筋収縮で ATP はどのようにはたらくか。正しいものを選べ。', choices: ['アクチンが ATP を分解して伸びる', 'ミオシンの頭部が ATP を分解し、そのエネルギーでアクチンをたぐりよせる', 'ATP が Ca²⁺ のかわりにトロポニンに結合する', 'ATP は筋収縮には使われない'], a: 'B(ミオシンの頭部が ATP を分解し、そのエネルギーでアクチンをたぐりよせる)', exp: 'ミオシン頭部は ATP 分解酵素としてはたらき、そのエネルギーで首振り運動をしてアクチンフィラメントを引き寄せます。ATP は、ミオシンがアクチンから離れるのにも必要です。' },
      { lv: 2, q: 'ヒトが近くのものを見るとき、毛様筋・チン小帯・水晶体はそれぞれどうなるか。', a: '毛様筋が収縮し、チン小帯がゆるみ、水晶体が自身の弾性で厚くなる。', exp: '水晶体が厚くなると焦点距離が短くなり、近くのものの像が網膜上に結ばれます。遠くを見るときは逆に、毛様筋がゆるんでチン小帯が引かれ、水晶体はうすくなります。' },
      { lv: 2, q: '抑制性シナプスで神経伝達物質を受け取ると、シナプス後細胞の膜電位はどうなるか。', a: 'Cl⁻ が流れこむなどして、内側がさらに負になる(過分極する)。', exp: '膜電位が静止電位よりさらに負になると、閾値に達しにくくなり、興奮が起こりにくくなります。GABA などがはたらく抑制のしくみです。' },
      { lv: 2, q: 'イヌにベルの音を聞かせてからえさを与えることをくり返すと、ベルの音だけでだ液を出すようになった。この学習を何というか。', a: '古典的条件づけ', exp: 'もともと関係のない刺激(ベルの音)が、えさという刺激と結びついて反応を引き起こすようになる学習です。パブロフが研究しました。' },
      { lv: 3, q: '神経筋標本で、筋肉から 3.0 cm の点を刺激すると 3.0 ミリ秒後、9.0 cm の点を刺激すると 5.0 ミリ秒後に収縮が始まった。伝導速度と、神経の末端に興奮が届いてから収縮が始まるまでの時間を求めよ。', a: '伝導速度 30 m/s、2.0 ミリ秒', exp: '距離の差 6.0 cm を 2.0 ミリ秒で伝わるので 0.060/0.0020＝30 m/s。3.0 cm を伝わるのに 1.0 ミリ秒かかるので、残り 3.0−1.0＝2.0 ミリ秒が伝達と収縮の準備の時間です。' },
      { lv: 3, q: 'フグ毒のテトロドトキシンは、電位依存性 Na⁺ チャネルをふさぐ。これを作用させた神経繊維に閾値以上の刺激を与えると、どうなるか。理由とともに答えよ。', a: '活動電位が発生しない(興奮が伝わらない)。Na⁺ が流れこめず、脱分極が起こらないから。', exp: '活動電位の立ち上がりは Na⁺ の流入によるので、それをふさぐと興奮が起こりません。そのため、運動神経や呼吸の筋肉への命令が止まり、まひが起こります。' },
      { lv: 3, q: '1つのニューロンの軸索の途中を刺激すると、興奮は細胞体側と軸索の末端側の両方へ伝わった。しかし、軸索の末端の先にある次のニューロンを刺激しても、前のニューロンには興奮が伝わらなかった。この2つの結果からわかることを答えよ。', a: '1つのニューロンの中では興奮は両方向に伝導するが、シナプスでは前のニューロンから後のニューロンへの一方向にしか伝達されない。', exp: '伝導と伝達のちがいを示す実験です。シナプスでは、伝達物質の放出と受容体の位置に方向性があるためです。' },
      { lv: 3, q: 'あるサルコメアでは、ミオシンフィラメントの長さが 1.6 μm、Z膜から伸びるアクチンフィラメントの長さが片側 0.80 μm である。サルコメアの長さが 1.8 μm のとき、暗帯・明帯(1つのサルコメア内の合計)・H帯の長さを求めよ。', a: '暗帯 1.6 μm、明帯 0.20 μm、H帯 0.20 μm', exp: '暗帯はミオシンの長さで 1.6 μm。明帯はサルコメアから暗帯を引いて 1.8−1.6＝0.20 μm。H帯はアクチンが届かない部分で 1.8−2×0.80＝0.20 μm です。' },
      { lv: 3, q: 'ミツバチの尻ふりダンスで、巣板の上で真上に向かって尻をふりながら進むと、えさ場は太陽の方向にあることを示す。真上から右へ 60° の向きに進んだとき、えさ場はどちらにあるか。', a: '太陽の方向から右(時計回り)へ 60° の方向', exp: '鉛直上向きが太陽の方向に対応し、ダンスの向きと鉛直のなす角が、太陽の方向とえさ場の方向のなす角を表します。ダンスの速さ(回数)は距離を表します。' }
    ]
  });

  add('b4_plant', {
    pat: [
      { name: '光屈性の実験:オーキシンの移動を雲母片・寒天片で調べる', freq: 'とてもよく出る', when: '幼葉鞘の先端に雲母片を差しこむ、先端を切って寒天片にのせる、などの実験の結果を予想する問題です。', how: ['オーキシンは先端でつくられ、光の当たらない側へ移動してから下へ運ばれます。', '雲母片は物質を通さず、寒天片は通します。どこをさえぎったかを図に書きこみます。', '陰側のオーキシンが多い側がよく伸び、光の方へ曲がります。陰側への移動や下への移動が止められると曲がりません。'], ex: { q: 'マカラスムギの幼葉鞘の先端に、光の方向と垂直に(光側と陰側を分けるように)雲母片を差しこみ、片側から光を当てた。幼葉鞘はどうなるか。', a: 'ほとんど曲がらない', exp: '雲母片で先端が光側と陰側に仕切られるので、オーキシンが陰側へ移動できません。左右のオーキシン量に差ができないため、成長の差も生じず、ほぼまっすぐ伸びます。' } },
      { name: '花芽形成:限界暗期と光中断', freq: 'とてもよく出る', when: '明期と暗期の長さを変えた条件で、短日植物・長日植物が花芽をつけるかを問われたときです。', how: ['花芽形成を決めるのは、連続した暗期の長さです。', '短日植物は連続暗期が限界暗期より長いと花芽をつけ、長日植物は短いと花芽をつけます。', '暗期の途中で短時間光を当てる(光中断)と、暗期は2つに分かれたことになります。'], ex: { q: '限界暗期が 10 時間の短日植物を、明期 12 時間・暗期 12 時間で育てたが、暗期の真ん中で数分間光を当てた。花芽をつけるか。', a: '花芽をつけない', exp: '光中断で暗期は 6 時間ずつに分かれます。連続暗期 6 時間は限界暗期 10 時間より短いので、短日植物は花芽をつけません。暗期の合計ではなく「連続した長さ」で判断します。' } },
      { name: '光発芽種子:最後に当てた光で決まる', freq: 'よく出る', when: 'レタスなどの種子に、赤色光と遠赤色光を交互に当てた実験の結果を問われたときです。', how: ['フィトクロムは赤色光を吸収すると Pfr 型(はたらく型)、遠赤色光を吸収すると Pr 型になります。', 'Pfr 型が多いと発芽が促進されます。', 'したがって、最後に当てた光が赤色光なら発芽し、遠赤色光なら発芽しません。'], ex: { q: 'レタスの種子に、赤色光→遠赤色光→赤色光 の順に光を当ててから暗所に置いた。発芽するか。', a: '発芽する', exp: '最後に当てたのが赤色光なので、フィトクロムは Pfr 型になっています。途中で遠赤色光を当てても、そのあとの赤色光で再び Pfr 型にもどるので発芽します。' } },
      { name: '植物ホルモンのはたらきを見分ける', freq: 'よく出る', when: '「種子の休眠」「果実の成熟」「気孔の閉鎖」などのはたらきから、植物ホルモンの名前を答える問題です。', how: ['オーキシン:成長促進・屈性・頂芽優勢。ジベレリン:茎の伸長・発芽促進・単為結実。', 'サイトカイニン:細胞分裂の促進・老化の抑制・側芽の成長。', 'アブシシン酸:気孔の閉鎖・休眠の維持。エチレン:果実の成熟・落葉(離層の形成)。'], ex: { q: '乾燥すると葉で合成され、孔辺細胞にはたらいて気孔を閉じさせる植物ホルモンは何か。', a: 'アブシシン酸', exp: 'アブシシン酸は、乾燥などのストレスにこたえて気孔を閉じ、水分が失われるのを防ぎます。種子の休眠を保つはたらきもあり、ジベレリンと反対の作用を示すことが多いです。' } },
      { name: 'オーキシン濃度と器官の感受性:根と茎で逆になる', freq: 'よく出る', when: '横にした植物で、根が下へ、茎が上へ曲がる理由を問われたときです。', how: ['重力によって、オーキシンは横にした茎や根の下側に多く集まります。', '茎は高い濃度のオーキシンで成長が促進されるので、下側がよく伸びて上へ曲がります。', '根はずっと低い濃度で最もよく伸び、高い濃度では成長がおさえられるので、下側が伸びにくくなり下へ曲がります。'], ex: { q: '芽ばえを横にしておくと、根は下へ、茎は上へ曲がる。根が下へ曲がる理由を、オーキシンの濃度と感受性から説明せよ。', a: '根の下側にオーキシンが多く集まるが、根は茎より低い濃度で成長が最大になり、高い濃度では成長がおさえられる。そのため下側の成長が上側より遅くなり、下へ曲がる。', exp: '同じオーキシンでも、器官によって最適な濃度がちがいます。根の最適濃度は茎よりずっと低いので、茎では促進になる濃度が、根では抑制になります。' } }
    ],
    more: [
      { lv: 1, q: '種なしブドウをつくるのに使われる植物ホルモンはどれか。', choices: ['ジベレリン', 'アブシシン酸', 'エチレン', 'サイトカイニン'], a: 'A(ジベレリン)', exp: 'ジベレリンで処理すると、受精しなくても子房が成長して果実になります(単為結実)。ジベレリンには茎の伸長や種子の発芽を促すはたらきもあります。' },
      { lv: 1, q: '果実の成熟を促進する気体の植物ホルモンは何か。', a: 'エチレン', exp: 'エチレンは気体なので、熟したリンゴと未熟なキウイを同じ袋に入れると、キウイの成熟が早まります。落葉や落果を促すはたらきもあります。' },
      { lv: 1, q: '細胞分裂を促進し、葉の老化をおさえる植物ホルモンはどれか。', choices: ['オーキシン', 'サイトカイニン', 'アブシシン酸', 'エチレン'], a: 'B(サイトカイニン)', exp: 'サイトカイニンは細胞分裂を促し、切り取った葉を緑のまま保つ(老化をおさえる)はたらきがあります。側芽の成長を促すこともあります。' },
      { lv: 1, q: '植物の茎が光の来る方向へ曲がる性質を何というか。', a: '正の光屈性', exp: '刺激の方向へ曲がるのが正、反対へ曲がるのが負です。茎は光の方へ曲がるので正の光屈性を示します。' },
      { lv: 1, q: '葉でつくられ、師管を通って茎頂へ運ばれて花芽の形成を引き起こす物質を何というか。', a: 'フロリゲン(花成ホルモン)', exp: 'フロリゲンの正体は FT などのタンパク質であることがわかっています。日長を感じるのは葉で、花芽ができるのは茎頂なので、情報を運ぶ物質が必要です。' },
      { lv: 1, q: '気孔が開くとき、孔辺細胞ではどのような変化が起こるか。', choices: ['水が出ていき、しぼむ', '水を吸収してふくらむ', '細胞が分裂する', '細胞壁がなくなる'], a: 'B(水を吸収してふくらむ)', exp: '孔辺細胞に K⁺ が流れこむと浸透圧が上がり、水を吸ってふくらみます。孔辺細胞は気孔側の細胞壁が厚いので、ふくらむと外側へ曲がり、すき間(気孔)が開きます。' },
      { lv: 1, q: '頂芽があると側芽の成長がおさえられる現象を何というか。', a: '頂芽優勢', exp: '頂芽でつくられたオーキシンが下へ運ばれ、側芽の成長をおさえます。頂芽を切りとると側芽が伸び出します(摘心)。' },
      { lv: 2, q: '短日植物の例として正しいものはどれか。', choices: ['アブラナ', 'ホウレンソウ', 'キク', 'コムギ'], a: 'C(キク)', exp: 'キク・アサガオ・オナモミなどは短日植物で、夏から秋に連続暗期が長くなると花芽をつけます。アブラナ・ホウレンソウ・コムギは長日植物です。' },
      { lv: 2, q: '光が当たると発芽が促進される光発芽種子をもつ植物はどれか。', choices: ['レタス', 'カボチャ', 'トマト', 'ケイトウ'], a: 'A(レタス)', exp: 'レタスやタバコの種子は光発芽種子です。小さな種子が多く、土の浅いところ(光が届くところ)で発芽することで、芽ばえが確実に光を受けられます。' },
      { lv: 2, q: '光屈性や気孔の開口にはたらく、青色光を吸収する光受容体は何か。', a: 'フォトトロピン', exp: 'フォトトロピンは青色光を受けてオーキシンの移動や気孔の開口を引き起こします。赤色光・遠赤色光を受けるフィトクロムとは別の受容体です。' },
      { lv: 2, q: '秋にできた種子がすぐには発芽せず、冬をこしてから発芽する。この休眠を保つはたらきをもつ植物ホルモンは何か。', a: 'アブシシン酸', exp: 'アブシシン酸は種子の休眠を維持し、ジベレリンは休眠を破って発芽を促します。2つのホルモンのバランスで発芽の時期が決まります。' },
      { lv: 2, q: 'フィトクロムについて正しいものはどれか。', choices: ['赤色光を吸収すると Pr 型になる', '遠赤色光を吸収すると Pfr 型になる', '赤色光を吸収すると Pfr 型になり、遠赤色光で Pr 型にもどる', '青色光だけを吸収する'], a: 'C(赤色光を吸収すると Pfr 型になり、遠赤色光で Pr 型にもどる)', exp: 'フィトクロムは赤色光(R)と遠赤色光(FR)で2つの型を行き来します。Pfr 型が発芽の促進や花芽形成の調節にはたらきます。' },
      { lv: 2, q: '芽ばえを横にしておいたとき、茎と根が示す重力屈性の組み合わせとして正しいものはどれか。', choices: ['茎:正、根:正', '茎:負、根:正', '茎:正、根:負', '茎:負、根:負'], a: 'B(茎:負、根:正)', exp: '茎は重力と反対の上へ曲がるので負の重力屈性、根は重力の方向の下へ曲がるので正の重力屈性です。' },
      { lv: 2, q: '秋に葉の付け根に離層ができて落葉する。このとき、離層の形成を促す植物ホルモンと、おさえる植物ホルモンの組み合わせを答えよ。', a: '促す:エチレン、おさえる:オーキシン', exp: '葉が老化して葉からのオーキシンの供給が減ると、エチレンのはたらきが強まって離層ができ、葉が落ちます。' },
      { lv: 2, q: 'コムギなどで、種子や芽ばえが一定期間の低温にさらされることで、花芽をつけられるようになる現象を何というか。', a: '春化', exp: '秋まきコムギは冬の寒さを経験しないと花芽をつけません。冬をこす前に花をつけて寒さで枯れることを防ぐしくみと考えられます。' },
      { lv: 3, q: '限界暗期 9 時間の短日植物を、次の条件で育てた。(1) 明期 16 時間・暗期 8 時間 (2) 明期 8 時間・暗期 16 時間 (3) 明期 8 時間・暗期 16 時間で、暗期の真ん中に短時間の光を当てる。それぞれ花芽をつけるか。', a: '(1) つけない (2) つける (3) つけない', exp: '短日植物は連続暗期が限界暗期 9 時間より長いと花芽をつけます。(1) 8 時間は短い。(2) 16 時間は長い。(3) 光中断で 8 時間ずつに分かれるので短く、つけません。' },
      { lv: 3, q: 'レタスの種子に、赤色光→遠赤色光→赤色光→遠赤色光 の順に短時間ずつ光を当て、暗所に置いた。発芽するか。理由も答えよ。', a: '発芽しない。最後に当てた遠赤色光でフィトクロムが Pr 型になっているから。', exp: '何回切りかえても、最後の光で決まります。最後が遠赤色光なので Pfr 型が少なく、発芽が促進されません。' },
      { lv: 3, q: 'オナモミ(短日植物)の葉を1枚だけ残し、その葉だけを短日条件にし、ほかの部分は長日条件にした。すると植物全体に花芽ができた。この実験からわかることを2つ答えよ。', a: '日長を感じとるのは葉であること。葉でつくられた花芽形成を促す物質が、ほかの部分へ運ばれること。', exp: '茎頂は長日条件なのに花芽ができたので、葉が受けた情報が物質として移動したと考えられます。この物質がフロリゲンです。' },
      { lv: 3, q: 'マカラスムギの幼葉鞘から切り出した切片の上(先端側)にオーキシンを含む寒天片、下に何も含まない寒天片を置くと、下の寒天片にオーキシンが移動した。切片の上下を逆さまにして同じことをすると、移動しなかった。この結果からわかることを答えよ。', a: 'オーキシンは、重力の向きに関係なく、茎の先端側から基部側へ一方向にだけ運ばれる(極性移動)。', exp: '逆さにすると、寒天片から下向きは「基部側から先端側」になります。それでは運ばれなかったので、移動の向きは重力ではなく、細胞の向き(先端→基部)で決まっていることがわかります。' },
      { lv: 3, q: '葉が昆虫に食べられた植物では、食べられていない葉でも、タンパク質分解酵素のはたらきをおさえる物質がつくられるようになる。このとき合成されて防御の信号としてはたらく植物ホルモンはどれか。', choices: ['ジャスモン酸', 'ジベレリン', 'サイトカイニン', 'フロリゲン'], a: 'A(ジャスモン酸)', exp: '食害を受けるとジャスモン酸が合成され、阻害物質の遺伝子の発現を引き起こします。阻害物質を食べた昆虫は消化がうまくできなくなります。' }
    ]
  });

  add('b4_eco', {
    pat: [
      { name: '標識再捕法:N＝(はじめに標識した数×2回目に捕まえた数)÷(その中の標識の数)', freq: 'とてもよく出る', when: '動き回る動物の個体数を、捕まえて印をつけて放し、もう一度捕まえる方法で推定する問題です。', how: ['「全体の中の標識個体の割合＝2回目に捕まえた中の標識個体の割合」と考えます。', 'N:M＝n:m(N 全体、M 標識して放した数、n 2回目の数、m その中の標識数)。', 'N＝M×n/m を計算します。標識が外れない・よく混ざる・移出入がない、などの条件が必要です。'], ex: { q: 'ある池でコイを 50 匹捕まえて印をつけて放した。数日後に 60 匹捕まえると、そのうち 10 匹に印があった。池のコイの数を推定せよ。', a: '約 300 匹', exp: '2回目の 60 匹中 10 匹、つまり 1/6 に印があったので、池全体でも印のある 50 匹が全体の 1/6 と考えます。N＝50×60/10＝300 匹です。' } },
      { name: '物質生産の収支:総生産量・純生産量・成長量', freq: 'とてもよく出る', when: '生産者や消費者の「総生産量」「呼吸量」「被食量」「枯死量」などが与えられ、成長量を求める問題です。', how: ['生産者:純生産量＝総生産量−呼吸量、成長量＝純生産量−(被食量＋枯死量)。', '消費者:同化量＝摂食量−不消化排出量、生産量＝同化量−呼吸量、成長量＝生産量−(被食量＋死亡量)。', '式を書いてから数字を入れると、引き忘れを防げます。'], ex: { q: 'ある森林の生産者の1年間の総生産量が 100、呼吸量が 60、被食量が 5、枯死量が 15(単位はすべて同じ)であった。純生産量と成長量を求めよ。', a: '純生産量 40、成長量 20', exp: '純生産量＝100−60＝40。成長量＝40−(5＋15)＝20。成長量は、その年に生産者の体として新しくたくわえられた量です。' } },
      { name: 'エネルギー効率:上の段階の同化量÷下の段階の同化量', freq: 'よく出る', when: '各栄養段階のエネルギー量の表があり、「エネルギー効率」を問われたときです。', how: ['生産者のエネルギー効率＝総生産量÷太陽から受けたエネルギー×100。', '消費者のエネルギー効率＝その段階の同化量÷1つ前の段階の同化量(生産者なら総生産量)×100。', '一般に、上の栄養段階ほどエネルギー効率は 10〜20 % 程度と小さくなりやすいです。'], ex: { q: '生産者の総生産量が 10000、一次消費者の同化量が 1000 であった(単位は同じ)。一次消費者のエネルギー効率を求めよ。', a: '10 %', exp: 'エネルギー効率＝1000÷10000×100＝10 %。生産者がつくったエネルギーの多くは、生産者自身の呼吸や枯死などで使われ、一次消費者には一部しか渡りません。' } },
      { name: '個体群の成長曲線と環境収容力', freq: 'よく出る', when: '個体数が S 字に増える成長曲線のグラフがあり、増え方が変わる理由を問われたときです。', how: ['はじめは食物や空間に余裕があり、個体数は急に増えます。', '密度が高くなると、食物不足や排出物の増加などで増え方がにぶります(密度効果)。', 'やがて環境収容力に近い一定の個体数になります。増加の速さが最大になるのは、およそ環境収容力の半分のときです。'], ex: { q: 'ゾウリムシを一定量の培養液で育てると、個体数は S 字型に増えてやがて一定になった。一定になる理由を答えよ。', a: '密度が高くなると食物の不足や老廃物の増加などで出生率が下がり死亡率が上がるため、増加が止まる(環境収容力に達する)から。', exp: 'このような密度による個体群への影響を密度効果といいます。一定になった個体数が、その環境で維持できる最大の数(環境収容力)です。' } },
      { name: '種間関係の識別', freq: 'よく出る', when: '2種の生物の関係を説明した文から、「競争」「捕食」「相利共生」「寄生」などを答える問題です。', how: ['両方が不利になる(資源をうばい合う)なら種間競争です。', '一方が得をして他方が損をするなら、捕食(食べる)か寄生(相手の体から栄養をとる)です。', '両方が得をするなら相利共生、一方が得をして他方は損も得もしないなら片利共生です。'], ex: { q: 'アリはアブラムシの出す甘い液をもらい、アブラムシはアリにテントウムシなどの天敵から守ってもらう。この2種の関係を何というか。', a: '相利共生', exp: 'アリは食物を、アブラムシは身の安全を得ていて、どちらにも利益があります。マメ科植物と根粒菌の関係も相利共生の例です。' } }
    ],
    more: [
      { lv: 1, q: '一定の面積(または体積)あたりの個体数を何というか。', a: '個体群密度', exp: '個体群密度＝個体数÷生活空間の面積(体積)。動かない生物では区画法、動き回る動物では標識再捕法などで調べます。' },
      { lv: 1, q: 'ある環境で、個体群が維持できる最大の個体数を何というか。', a: '環境収容力', exp: '食物や生活空間などの資源の量で決まります。成長曲線では、増加が止まって一定になったときの個体数にあたります。' },
      { lv: 1, q: '草地に 1 m² の区画を5つつくり、ある植物の数を数えると、平均して 8 本あった。100 m² の草地全体では何本と推定できるか。', a: '800 本', exp: '1 m² あたり 8 本なので、100 m² では 8×100＝800 本と推定します(区画法)。区画を多く、まんべんなくとるほど正確になります。' },
      { lv: 1, q: 'マメ科植物と根粒菌の関係として正しいものはどれか。', choices: ['寄生', '相利共生', '捕食', '種間競争'], a: 'B(相利共生)', exp: '根粒菌は空気中の窒素を固定して植物に与え、植物は根粒菌に光合成でつくった有機物を与えます。両方に利益があります。' },
      { lv: 1, q: '生態系で、光合成などによって無機物から有機物をつくる生物を何というか。', a: '生産者', exp: '植物や藻類、シアノバクテリアなどが生産者です。生産者がつくった有機物を食べる動物は消費者、死体や排出物を分解する菌類・細菌は分解者とよびます。' },
      { lv: 1, q: '栄養段階ごとの個体数・生物量・エネルギー量を、下から積み上げた図を何というか。', a: '生態ピラミッド', exp: '個体数ピラミッド・生物量ピラミッド・生産力(エネルギー)ピラミッドがあります。エネルギーのピラミッドは、必ず上ほど小さくなります。' },
      { lv: 1, q: '日本に持ちこまれ、在来の魚などを食べて問題になっている外来生物はどれか。', choices: ['メダカ', 'オオクチバス', 'ニホンウナギ', 'アユ'], a: 'B(オオクチバス)', exp: 'オオクチバス(ブラックバス)は北アメリカ原産の肉食魚で、在来の小魚やエビを食べて生態系に影響を与えるため、特定外来生物に指定されています。' },
      { lv: 2, q: 'ある島でネズミを 40 匹捕まえて標識して放した。1週間後に 50 匹捕まえると、そのうち 8 匹に標識があった。島のネズミの数を推定せよ。', a: '250 匹', exp: 'N＝M×n/m＝40×50/8＝250 匹。2回目の中の標識の割合 8/50 が、全体の中の標識の割合 40/N と等しいと考えます。' },
      { lv: 2, q: '標識再捕法で正しく推定するために必要な条件として、まちがっているものはどれか。', choices: ['標識が調査の間に外れない', '標識した個体がほかの個体とよく混ざる', '標識によって捕まりやすさが変わらない', '調査の間にたくさんの個体が移入してくる'], a: 'D(調査の間にたくさんの個体が移入してくる)', exp: '調査の間は、出生・死亡・移出入が少なく、個体数がほぼ変わらないことが必要です。大量の移入があると、標識個体の割合が下がり、正しく推定できません。' },
      { lv: 2, q: 'ある一次消費者の摂食量が 500、不消化排出量が 150、呼吸量が 200(単位は同じ)であった。同化量と生産量を求めよ。', a: '同化量 350、生産量 150', exp: '同化量＝摂食量−不消化排出量＝500−150＝350。生産量＝同化量−呼吸量＝350−200＝150。ふんとして出た分は、体に取りこまれていないので同化量に入りません。' },
      { lv: 2, q: 'ゾウリムシとヒメゾウリムシを同じ容器で育てると、やがてゾウリムシだけがいなくなった。このような現象を何というか。', a: '競争的排除', exp: '同じ資源(食物の細菌など)を必要とする2種が同じ場所にいると、種間競争で一方が排除されることがあります。ガウゼの実験で示されました。' },
      { lv: 2, q: '川の上流にイワナ、下流にヤマメが分かれてすみ、片方がいない川では、もう一方がより広い範囲にすむ。この現象を何というか。', a: 'すみわけ', exp: '似た生活をする2種が、生活の場所を分けることで競争をさけている例です。生態的地位(ニッチ)を分けることで、共存できます。' },
      { lv: 2, q: 'トノサマバッタは、密度が高い状態で育つと、はねが長く集団で移動する性質をもつ型になる。この現象を何というか。', a: '相変異', exp: '低密度で育つ孤独相に対し、高密度で育つと群生相になります。群生相は移動能力が高く、食物を求めて大移動することがあります。' },
      { lv: 2, q: 'アユのなわばりは、大きすぎても小さすぎても不利になる。なわばりの最適な大きさが決まる理由を説明せよ。', a: 'なわばりを大きくすると得られる食物は増えるが、侵入者を追い払う労力(コスト)も大きくなる。利益からコストを引いた値が最大になる大きさが最適になるから。', exp: '利益とコストのバランスで行動を考える見方です。個体群密度が高くなると侵入者が増えてコストが上がり、なわばりをもたずに群れで暮らすアユがふえます。' },
      { lv: 2, q: 'ある海域でラッコがいなくなると、ウニが増えてケルプ(大型の海藻)の林が消え、多くの生物がすめなくなった。ラッコのように、少ない量でも生態系のバランスに大きな影響を与える種を何というか。', a: 'キーストーン種', exp: 'キーストーン種は、生物群集の構造を保つ「要」の役割をしています。この種がいなくなると、食物網を通じて多くの種に影響が広がります。' },
      { lv: 3, q: 'ある生態系で、生産者の総生産量が 5000、一次消費者の同化量が 500、二次消費者の同化量が 60(単位は同じ)であった。一次消費者と二次消費者のエネルギー効率をそれぞれ求めよ。', a: '一次消費者 10 %、二次消費者 12 %', exp: '一次消費者:500÷5000×100＝10 %。二次消費者:60÷500×100＝12 %。それぞれ、1つ前の栄養段階の同化量(生産者は総生産量)で割ります。' },
      { lv: 3, q: '標識再捕法で、標識された個体がわなをさけるようになり、2回目に捕まりにくくなった場合、推定される個体数は実際よりどうなるか。理由とともに答えよ。', a: '実際より大きく推定される。2回目の中の標識個体数 m が実際の割合より少なくなり、N＝M×n/m の分母が小さくなるから。', exp: '標識によって捕まりやすさが変わると、仮定がくずれます。逆に、標識個体がわなに慣れて捕まりやすくなると、実際より小さく推定されます。' },
      { lv: 3, q: '環境収容力が 1000 の個体群が S 字型の成長曲線にしたがって増えるとき、単位時間あたりの個体数の増加が最も大きくなるのは、個体数がおよそいくらのときか。', a: '約 500(環境収容力の半分)', exp: '個体数が少ないと増える元になる個体が少なく、多いと密度効果で増え方がにぶります。その中間の環境収容力の半分のとき、曲線の傾きが最大になります。漁業で資源を効率よく利用する考え方にも使われます。' },
      { lv: 3, q: 'ある昆虫の生命表で、卵 1000 個のうち、幼虫になったのが 500、さなぎになったのが 100、成虫になったのが 50 であった。卵→幼虫、幼虫→さなぎ、さなぎ→成虫 の各時期の死亡率を求めよ。また、死亡率が最も高い時期を答えよ。', a: '50 %、80 %、50 %。幼虫の時期が最も高い。', exp: '各時期の死亡率は「その時期に死んだ数÷その時期の初めの数」です。(1000−500)/1000＝50 %、(500−100)/500＝80 %、(100−50)/100＝50 %。死んだ数(500、400、50)と死亡率の大きさは一致しない点に注意します。' },
      { lv: 3, q: '台風や山火事などのかく乱が、ほどほどの規模・頻度で起こる場所で、生物の種の多様性が最も高くなるという考えを何というか。その理由も答えよ。', a: '中規模かく乱説。かく乱が強すぎると多くの種が生きられず、弱すぎると競争に強い種だけが残るが、ほどほどだと両方のタイプの種が共存できるから。', exp: 'かく乱のあとに入りこむ種と、競争に強い種が同じ場所に混ざって存在できるため、多様性が高まると考えられています。' }
    ]
  });

  add('b4_evo', {
    pat: [
      { name: 'ハーディ・ワインベルグの法則:劣性ホモの割合から遺伝子頻度を出す', freq: 'とてもよく出る', when: '集団の中の劣性の表現型の割合が与えられ、遺伝子頻度やヘテロ接合体の割合を問われたときです。', how: ['A の頻度を p、a の頻度を q(p＋q＝1)とします。', '任意交配する大きな集団では、AA:Aa:aa＝p²:2pq:q² です。', '劣性の表現型(aa)の割合 q² から q＝√(割合) を出し、p＝1−q、2pq を計算します。'], ex: { q: 'ある集団で劣性の表現型を示す個体(aa)が 16 % いた。ハーディ・ワインベルグの法則が成り立つとして、a と A の遺伝子頻度、およびヘテロ接合体(Aa)の割合を求めよ。', a: 'a 0.4、A 0.6、Aa 48 %', exp: 'q²＝0.16 より q＝0.4、p＝1−0.4＝0.6。Aa は 2pq＝2×0.6×0.4＝0.48 で 48 %。優性の表現型 84 % のうち、半分以上がヘテロ接合体であることがわかります。' } },
      { name: '分子系統樹:アミノ酸の置換数から分岐の年代を求める', freq: 'よく出る', when: '複数の生物のタンパク質のアミノ酸のちがいの数と、ある2種が分かれた年代が与えられている問題です。', how: ['分子時計:置換数は分岐してからの時間に比例すると考えます。', '年代がわかっている2種の置換数から、「1つの置換にかかる時間」を求めます。', 'ほかの2種の置換数にその時間をかけて、分岐の年代を求めます。'], ex: { q: 'あるタンパク質のアミノ酸のちがいは、生物 A と B で 20 か所、A と C で 40 か所であった。A と B が分かれたのが 1 億年前だとすると、A と C が分かれたのは何年前と推定できるか。', a: '約 2 億年前', exp: '置換数は分岐後の時間に比例するので、20 か所で 1 億年なら 40 か所では 2 億年です。ただし、置換は2つの系統の両方で起こるので、置換数は分岐後の時間の2倍の長さの変化を表している点も理解しておきます。' } },
      { name: '種分化のしくみ:地理的隔離から生殖的隔離へ', freq: 'よく出る', when: '山脈や海で分けられた集団が、別の種になる過程を説明する問題です。', how: ['地理的隔離で集団が分かれると、遺伝子の交流がなくなります。', 'それぞれの集団で、突然変異・自然選択・遺伝的浮動により遺伝子の構成がちがっていきます。', '再び出会っても交配できない(または子孫を残せない)生殖的隔離が生じると、別の種になったといえます。'], ex: { q: '地理的隔離だけでは、まだ別の種になったとはいえない。どのような状態になれば別の種といえるか。', a: '2つの集団が出会っても、交配して生殖能力のある子孫を残せない(生殖的隔離が成立した)状態。', exp: '地理的隔離はあくまで「出会えない」だけです。隔離の間に変化が積み重なり、出会っても交配しない・雑種が育たないなどの生殖的隔離が生じたとき、種分化が完成します(異所的種分化)。' } },
      { name: '遺伝的浮動と自然選択を見分ける', freq: 'よく出る', when: '遺伝子頻度が変化した例について、その原因を問われたときです。', how: ['生存や繁殖に有利・不利の差があって起こる変化は自然選択です。', '有利・不利と関係なく、偶然によって起こる変化は遺伝的浮動で、小さな集団ほど大きく効きます。', '大災害で生き残ったわずかな個体(びん首効果)や、少数の個体が新しい場所に移り住んだ場合(創始者効果)も遺伝的浮動の一種です。'], ex: { q: '島に流れ着いた数匹のトカゲから増えた集団では、もとの大陸の集団にくらべて、ある遺伝病の遺伝子の頻度が非常に高かった。この遺伝子頻度の変化は主に何によるか。', a: '遺伝的浮動(創始者効果)', exp: '病気の遺伝子は有利ではないので、自然選択では増えません。最初に島に来た少数の個体に、たまたまその遺伝子をもつ個体が多かったため、頻度が高くなったと考えられます。' } },
      { name: '3ドメイン説と系統樹の読み方', freq: 'よく出る', when: '系統樹から「どの生物とどの生物がより近縁か」を問われたときです。', how: ['系統樹では、枝の分かれ目(共通祖先)が新しい(先端に近い)ほど近縁です。', '3ドメイン説では、生物は細菌(バクテリア)、古細菌(アーキア)、真核生物の3つに分けられます。', '古細菌は原核生物ですが、rRNA の配列などから、細菌より真核生物に近いことがわかっています。'], ex: { q: '3ドメイン説で、古細菌はどのドメインと最も近縁とされているか。', a: '真核生物', exp: 'rRNA の塩基配列の比較から、まず細菌の系統が分かれ、そのあと古細菌と真核生物が分かれたと考えられています。細胞のつくりは細菌に似ていても、系統的には真核生物に近いのです。' } }
    ],
    more: [
      { lv: 1, q: '地球の最初の生物は、どのような生物だったと考えられているか。', choices: ['多細胞の真核生物', '単細胞の原核生物', '陸上植物', '脊椎動物'], a: 'B(単細胞の原核生物)', exp: '約 40 億年前ごろに、海の中で単細胞の原核生物が生まれたと考えられています。真核生物や多細胞生物は、それよりずっと後に現れました。' },
      { lv: 1, q: '光合成で酸素を放出し、地球の大気に酸素を増やした原核生物は何か。', a: 'シアノバクテリア', exp: 'シアノバクテリアの酸素で、海の鉄が酸化されて縞状鉄鉱層ができ、やがて大気にも酸素がたまりました。オゾン層ができ、生物の陸上進出が可能になりました。' },
      { lv: 1, q: 'ミトコンドリアのもとになったと考えられている生物はどれか。', choices: ['シアノバクテリア', '好気性細菌', 'ウイルス', '古細菌'], a: 'B(好気性細菌)', exp: '細胞内共生説では、好気性細菌が別の細胞に取りこまれてミトコンドリアに、シアノバクテリアが取りこまれて葉緑体になったと考えます。どちらも独自の DNA と二重の膜をもちます。' },
      { lv: 1, q: 'ヒトの腕とコウモリの翼のように、形やはたらきはちがっても、起源が同じ器官を何というか。', a: '相同器官', exp: '骨の並び方などの基本的なつくりが同じで、共通の祖先から受けついだ器官です。共通祖先をもつ証拠になります。' },
      { lv: 1, q: '鳥の翼と昆虫のはねのように、はたらきは似ているが起源がちがう器官を何というか。', a: '相似器官', exp: '似た環境やはたらきに適応して、別々に似た形になった器官です(収れん)。系統の近さを示すものではありません。' },
      { lv: 1, q: '生物の学名を「属名＋種小名」で表す方法を何というか。また、これを確立した人物はだれか。', a: '二名法、リンネ', exp: 'たとえばヒトは Homo sapiens と表します。世界共通の名前なので、国や言語がちがっても同じ生物を指せます。' },
      { lv: 1, q: '3ドメイン説で、生物を分ける3つのドメインを答えよ。', a: '細菌(バクテリア)、古細菌(アーキア)、真核生物(ユーカリア)', exp: 'ウーズが rRNA の塩基配列の比較をもとに提唱しました。それまでの「原核生物と真核生物」という分け方に対して、原核生物を2つに分けたのが特徴です。' },
      { lv: 2, q: 'ある集団で、遺伝子 A の頻度が 0.7 である。ハーディ・ワインベルグの法則が成り立つとき、AA、Aa、aa の割合を求めよ。', a: 'AA 49 %、Aa 42 %、aa 9 %', exp: 'p＝0.7、q＝0.3。AA＝p²＝0.49、Aa＝2pq＝0.42、aa＝q²＝0.09。合計が 1 になることを確かめます。' },
      { lv: 2, q: 'ハーディ・ワインベルグの法則が成り立つ条件として、まちがっているものはどれか。', choices: ['集団が十分に大きい', '突然変異が起こらない', '特定の遺伝子型が生存に有利である', 'ほかの集団との移出入がない'], a: 'C(特定の遺伝子型が生存に有利である)', exp: '法則が成り立つには、自然選択がはたらかない(遺伝子型によって生存や繁殖に差がない)ことが必要です。ほかに任意交配も条件です。条件が崩れると遺伝子頻度が変わり、進化が起こります。' },
      { lv: 2, q: 'イギリスで工業化が進み、すすで木の幹が黒くなると、オオシモフリエダシャクというガの暗色型が増えた。この現象の主な原因は何か。', a: '自然選択(暗色型が鳥に見つかりにくく、生き残りやすかった)', exp: '黒い幹の上では明色型が目立って鳥に食べられやすく、暗色型が生き残って子孫を多く残しました。空気がきれいになると、再び明色型が増えています(工業暗化)。' },
      { lv: 2, q: '分子レベルの変化の多くは、生存に有利でも不利でもなく、偶然によって集団に広がるという説を何というか。また、提唱者はだれか。', a: '中立説、木村資生', exp: 'DNA の塩基配列の変化の多くは、タンパク質のはたらきに影響しない中立なものです。これが遺伝的浮動で広がるので、分子の変化はほぼ一定の速さで積み重なります(分子時計の考えにつながる)。' },
      { lv: 2, q: 'あるタンパク質のアミノ酸の置換数が、生物 X と Y で 12、X と Z で 30 であった。X と Y が分かれたのが 6000 万年前とすると、X と Z が分かれたのは何年前と推定できるか。', a: '1 億 5000 万年前', exp: '置換数 12 で 6000 万年なので、置換数1あたり 500 万年です。30×500 万年＝1 億 5000 万年。置換の速さが一定という分子時計の仮定にもとづく推定です。' },
      { lv: 2, q: 'ガラパゴス諸島のフィンチ類のように、1つの祖先から、さまざまな環境に適応した多くの種に分かれることを何というか。', a: '適応放散', exp: 'フィンチ類は、食物(種子・昆虫・サボテンなど)に合わせて、くちばしの形が異なる多くの種に分かれました。哺乳類が中生代末以降に多様化したのも適応放散の例です。' },
      { lv: 2, q: 'ヒト(人類)が直立二足歩行をすることと関係の深い特徴はどれか。', choices: ['大後頭孔(頭骨の脊髄が通る穴)が頭骨の真下にある', '犬歯が大きく発達している', '前肢が後肢より長い', '親指が他の指と向かい合わない'], a: 'A(大後頭孔(頭骨の脊髄が通る穴)が頭骨の真下にある)', exp: '直立すると頭が脊柱の真上にのるので、大後頭孔が頭骨の下側にあります。ほかに、骨盤が横に広い、S 字状の脊柱なども二足歩行に関係する特徴です。' },
      { lv: 2, q: '花の距(きょ)の長さと、そのみつを吸うガの口器の長さが、ともに長くなる方向へ進化することがある。このように、互いに影響しあって進化することを何というか。', a: '共進化', exp: '花はみつを吸いにくくすることで花粉をつけさせやすくなり、ガは長い口器でみつを独占できます。互いが互いの自然選択の原因になって、一緒に変化していきます。' },
      { lv: 3, q: 'ある劣性の遺伝病は、1 万人に 1 人の割合で現れる。ハーディ・ワインベルグの法則が成り立つとき、この遺伝子を保因する(ヘテロ接合体の)人は、およそ何人に1人いるか。', a: '約 50 人に 1 人', exp: 'q²＝1/10000 より q＝0.01、p＝0.99。2pq＝2×0.99×0.01≒0.0198 で、約 2 %、つまり約 50 人に 1 人です。病気の人の約 200 倍の保因者がいることになります。' },
      { lv: 3, q: '劣性ホモ接合体 aa が子を残さずに必ず死ぬ集団で、ある世代の a の頻度が 0.5 であった。任意交配するとき、次の世代と、その次の世代の a の頻度を求めよ。', a: '次の世代 1/3、その次の世代 1/4', exp: 'aa が除かれると、a の頻度は q′＝q/(1＋q) になります。0.5/1.5＝1/3、(1/3)/(4/3)＝1/4。a は少なくなるほどヘテロ接合体の中にかくれ、減り方がゆっくりになります。' },
      { lv: 3, q: 'X 染色体上の劣性遺伝子による形質が、ある集団の男性の 8 % に現れている。ハーディ・ワインベルグの法則が成り立つとき、女性で現れる割合を求めよ。', a: '0.64 %', exp: '男性は X を1本しかもたないので、男性の発現率がそのまま遺伝子頻度 q＝0.08 になります。女性は2本とも劣性のときだけ現れるので q²＝0.0064＝0.64 %。男性に多く現れる理由がわかります。' },
      { lv: 3, q: '3種の生物 A、B、C の DNA の塩基のちがいの数は、A−B で 4、A−C で 10、B−C で 10 であった。最も近縁な2種と、系統樹の形を説明せよ。', a: 'A と B が最も近縁。まず C の系統が分かれ、その後に A と B が分かれた。', exp: 'ちがいの数が最も小さい A−B が最も近い関係です。C は A とも B とも同じだけちがうので、A と B の共通祖先から C が先に分かれたと考えられます。' },
      { lv: 3, q: 'はたらきバチが自分では子を産まずに妹たちを育てる行動が進化しうる理由を、ハミルトンの考え(rB＞C)を使って説明せよ。ある行動で、自分の子が 1 匹減る(C＝1)かわりに、血縁度 r＝0.5 のきょうだいが 3 匹多く育つ(B＝3)とする。', a: 'rB＝0.5×3＝1.5 が C＝1 より大きいので、自分と同じ遺伝子を次の世代に残す効果が大きく、このような行動の遺伝子が広まりうる。', exp: '自分の子を残すことだけでなく、同じ遺伝子をもつ血縁者を助けることも、遺伝子を残す方法になります(包括適応度)。ミツバチでは姉妹の血縁度がさらに高い 0.75 になります。' }
    ]
  });

  add('g4_earth', {
    pat: [
      { name: '地球の大きさ:緯度差と距離から全周を求める', freq: 'よく出る', when: '同じ経線上の2地点の緯度差(または太陽の南中高度の差)と距離が与えられている問題です。', how: ['2地点の緯度差は、地球の中心から見た角度(中心角)に等しいことを使います。', '全周:距離＝360°:緯度差 の比をつくります。', '全周＝距離×360/緯度差。半径が必要なら 全周÷2π で求めます。'], ex: { q: '同じ経線上にある2地点の緯度差が 8.0°、2地点間の距離が 890 km であった。地球の全周を求めよ。', a: '約 4.0×10⁴ km', exp: '全周＝890×360/8.0＝4.0×10⁴ km(40050 km)。エラトステネスは、夏至の日の太陽の高度の差から同じ方法で地球の大きさを求めました。' } },
      { name: '大森公式:震源距離＝k×初期微動継続時間', freq: 'とてもよく出る', when: 'P 波と S 波の到着時刻の差(PS 時間)が与えられ、震源までの距離を問われたときです。', how: ['震源距離 D を、P 波と S 波がそれぞれ進む時間で表します:D/Vs−D/Vp＝PS 時間。', '整理すると D＝{VpVs/(Vp−Vs)}×PS 時間＝k×PS 時間。', 'k が与えられていなければ、Vp と Vs から計算します(日本付近で約 6〜8 km/s)。'], ex: { q: 'P 波の速さ 6.0 km/s、S 波の速さ 3.5 km/s とする。初期微動継続時間が 6.0 秒の地点の震源距離を求めよ。', a: '約 50 km', exp: 'k＝6.0×3.5/(6.0−3.5)＝8.4 km/s。D＝8.4×6.0≒50 km(50.4 km)。D/3.5−D/6.0＝6.0 を直接解いても同じ値になります。' } },
      { name: '震源の深さ:震源距離と震央距離の三平方の定理', freq: 'よく出る', when: '観測点の震源距離と震央距離(震央までの地表の距離)がわかっていて、震源の深さを問われたときです。', how: ['震源・震央・観測点は直角三角形をつくります(震央の真下に震源)。', '深さ²＝震源距離²−震央距離²。', '3辺が 3:4:5 などの整数比になることが多いので、見つけると速く解けます。'], ex: { q: 'ある観測点の震源距離は 50 km、震央距離は 30 km であった。震源の深さを求めよ。', a: '40 km', exp: '深さ＝√(50²−30²)＝√1600＝40 km。3:4:5 の直角三角形です。震源距離と震央距離を取りちがえないように、図をかいてから計算します。' } },
      { name: 'アイソスタシー:同じ深さで圧力がつり合う', freq: 'よく出る', when: '氷床がとけたあとの隆起量や、山の「根」の深さを問われたときです。', how: ['ある深さ(補償面)より上の柱の重さ(密度×厚さの和)が、どこでも等しいと考えます。', '減った(増えた)物の重さを、マントルの密度で割ると、その分の高さの変化が出ます。', '「隆起量＝とけた氷の厚さ×氷の密度÷マントルの密度」のように式を立てます。'], ex: { q: '厚さ 1000 m の氷床(密度 0.90 g/cm³)がとけて完全になくなった。アイソスタシーが成り立つとすると、地面は最終的に何 m 隆起するか。(マントルの密度 3.3 g/cm³)', a: '約 270 m', exp: '氷の重さの分だけマントルが流れこんで地殻が持ち上がります。1000×0.90/3.3≒273 m。スカンジナビア半島が今も隆起しているのは、氷期の氷床がとけたためです。' } },
      { name: '地殻熱流量:熱流量＝熱伝導率×地温勾配', freq: '難関大で出る', when: '地下の温度の上がり方(地温勾配)や、地表から出ていく熱の量を問われたときです。', how: ['地温勾配は、深さ 1 km(または 100 m)あたりの温度上昇です。', '熱流量 q＝熱伝導率 k×地温勾配(K/m に直す)。単位は W/m² です。', '火山地帯や海嶺では熱流量が大きく、古い大陸の内部(楯状地)や海溝付近では小さくなります。'], ex: { q: '地温勾配が 30 K/km、岩石の熱伝導率が 2.5 W/(m·K) の地域の地殻熱流量を求めよ。', a: '7.5×10⁻² W/m²(75 mW/m²)', exp: '地温勾配を K/m に直すと 0.030 K/m。q＝2.5×0.030＝0.075 W/m²。地表に届く太陽放射(数百 W/m²)にくらべるとごくわずかです。' } }
    ],
    more: [
      { lv: 1, q: '地球の形について正しいものはどれか。', choices: ['完全な球', '赤道方向にややふくらんだ回転楕円体', '極方向にのびた楕円体', '平らな円盤'], a: 'B(赤道方向にややふくらんだ回転楕円体)', exp: '地球は自転による遠心力のため、赤道方向にわずかにふくらんでいます。赤道半径は約 6378 km、極半径は約 6357 km です。' },
      { lv: 1, q: '地球上で重力の大きさが最も小さいのはどこか。', choices: ['北極', '南極', '赤道', '北緯 45°'], a: 'C(赤道)', exp: '赤道では自転による遠心力が最も大きく、しかも地球の中心から最も遠いので、重力が最も小さくなります。' },
      { lv: 1, q: '地磁気の三要素を答えよ。', a: '偏角、伏角、水平分力(または全磁力)', exp: '偏角は磁針が真北からずれる角、伏角は磁針が水平面となす角、水平分力は磁場の水平方向の強さです。この3つで、その場所の地磁気の向きと強さが決まります。' },
      { lv: 1, q: 'P 波について正しいものはどれか。', choices: ['横波で、液体中を伝わらない', '縦波で、固体・液体・気体のどれも伝わる', 'S 波より遅い', '表面だけを伝わる'], a: 'B(縦波で、固体・液体・気体のどれも伝わる)', exp: 'P 波は進む向きに振動する縦波(疎密波)で、どんな状態の物質も伝わり、S 波より速く届きます。' },
      { lv: 1, q: 'S 波が液体の中を伝わらない理由を答えよ。', a: 'S 波は横波で、液体にはずれ(ねじれ)に抵抗する力がないから。', exp: '横波は媒質の「ずれ」が次々に伝わるものです。液体はずれをもとにもどす力をもたないので、S 波は伝わりません。この性質から外核が液体とわかります。' },
      { lv: 1, q: '地殻とマントルの境界の不連続面を何というか。', a: 'モホロビチッチ不連続面(モホ面)', exp: 'モホ面を境に地震波の速さが急に大きくなります。深さは大陸で 30〜60 km、海洋で約 5〜10 km です。' },
      { lv: 1, q: '地球の外核は、主に何でできていて、どのような状態か。', a: '主に鉄(とニッケル)で、液体の状態', exp: '外核は S 波が伝わらないので液体と考えられます。この液体の鉄の流れが、地磁気をつくると考えられています。内核は固体です。' },
      { lv: 2, q: 'P 波の速さ 6.0 km/s、S 波の速さ 3.5 km/s のとき、初期微動継続時間が 6.0 秒の地点の震源距離を求めよ。', a: '約 50 km', exp: 'D/3.5−D/6.0＝6.0 より D×(6.0−3.5)/(3.5×6.0)＝6.0、D＝6.0×21/2.5＝50.4≒50 km。' },
      { lv: 2, q: 'ある観測点で震源距離が 50 km、震源の深さが 40 km であった。震央距離を求めよ。', a: '30 km', exp: '震央距離＝√(50²−40²)＝√900＝30 km。震源・震央・観測点は直角三角形をつくります。' },
      { lv: 2, q: '震央からの角距離がおよそ 103° から 143° の範囲で、P 波が直接届かない地域を何というか。', a: 'P 波のシャドーゾーン(影の部分)', exp: 'P 波は液体の外核に入ると速さが落ちて大きく屈折するため、この範囲に届きにくくなります。グーテンベルクはこれから核の存在と大きさを推定しました。' },
      { lv: 2, q: '北半球のある地点で、伏角が大きいほどどのようなことがいえるか。', choices: ['磁北極に近い', '磁気赤道に近い', '偏角が小さい', '地磁気が弱い'], a: 'A(磁北極に近い)', exp: '伏角は磁気赤道で 0°、磁北極で 90° です。北半球では N 極が下を向き、北へ行くほど伏角が大きくなります。' },
      { lv: 2, q: '重力の測定値から、高さの補正だけをして標準の重力を引いた値を何というか。', choices: ['ブーゲー異常', 'フリーエア異常', 'ジオイド高', '地磁気異常'], a: 'B(フリーエア異常)', exp: '高さだけを補正したものがフリーエア異常、さらに測定点と基準面の間にある岩石の引力を補正したものがブーゲー異常です。ブーゲー異常は地下の密度のかたよりを表します。' },
      { lv: 2, q: '地球の全周を 4.0×10⁴ km とすると、同じ経線上で緯度 1° の差は何 km にあたるか。', a: '約 111 km', exp: '4.0×10⁴÷360≒111 km。この値を覚えておくと、地図上の距離の計算に便利です。' },
      { lv: 2, q: 'マントルと外核の境界の不連続面の名前と、深さを答えよ。', a: 'グーテンベルク不連続面、約 2900 km', exp: 'この面で S 波が伝わらなくなり、P 波の速さが急に小さくなります。マントルの岩石から液体の鉄へと、物質も状態も変わります。' },
      { lv: 2, q: '外核と内核の境界の深さはおよそいくらか。また、内核の状態を答えよ。', a: '約 5100 km、固体', exp: '内核は外核と同じく主に鉄ですが、圧力がとても高いので固体になっています。内核の境界(レーマン不連続面)で P 波の速さが少し大きくなります。' },
      { lv: 3, q: '大森公式の比例定数を 7.0 km/s とする。観測点 A では初期微動継続時間が 5.0 秒、観測点 B では 10 秒であった。A、B の震源距離を求めよ。', a: 'A 35 km、B 70 km', exp: 'D＝k×PS 時間 より、A は 7.0×5.0＝35 km、B は 7.0×10＝70 km。初期微動継続時間は震源距離に比例するので、2倍の時間なら2倍の距離です。' },
      { lv: 3, q: '標高 3.0 km の山脈がアイソスタシーでつり合っている。地殻の密度 2.7 g/cm³、マントルの密度 3.3 g/cm³ とすると、山脈の下の地殻は、まわりの地殻より何 km 深くまで張り出しているか(山の根の深さ)。', a: '約 13.5 km', exp: '山の分の重さ 3.0×2.7 を、根の部分の密度の差(3.3−2.7＝0.6)でつり合わせます。根の深さ＝3.0×2.7/0.6＝13.5 km。高い山ほど深い根をもちます。' },
      { lv: 3, q: '地殻熱流量が 60 mW/m²、岩石の熱伝導率が 3.0 W/(m·K) の地域の地温勾配(1 km あたりの温度上昇)を求めよ。', a: '20 K/km', exp: '地温勾配＝熱流量÷熱伝導率＝0.060/3.0＝0.020 K/m＝20 K/km。熱伝導率の大きい岩石では、同じ熱流量でも温度の上がり方がゆるやかになります。' },
      { lv: 3, q: '地表の重力加速度 g＝9.8 m/s²、地球の半径 R＝6.4×10⁶ m、万有引力定数 G＝6.67×10⁻¹¹ N·m²/kg² から、地球の平均密度を求めよ。(π＝3.14)', a: '約 5.5×10³ kg/m³(5.5 g/cm³)', exp: 'g＝GM/R²、M＝(4/3)πR³ρ より ρ＝3g/(4πGR)＝3×9.8/(4×3.14×6.67×10⁻¹¹×6.4×10⁶)≒5.5×10³ kg/m³。地表の岩石(約 2.7 g/cm³)より大きいので、内部に重い物質(鉄の核)があるとわかります。' },
      { lv: 3, q: 'P 波のシャドーゾーンができる理由として正しいものはどれか。', choices: ['P 波が液体の外核に入ると速さが小さくなり、境界で大きく屈折するから', 'P 波は液体を伝わらないから', 'マントルで P 波がすべて吸収されるから', '内核で P 波が反射されるから'], a: 'A(P 波が液体の外核に入ると速さが小さくなり、境界で大きく屈折するから)', exp: 'P 波は液体も伝わりますが、外核で速さが急に下がるため、核に入る波は中心側へ大きく曲げられます。その結果、地表のある範囲に P 波が直接届かなくなります。S 波は外核を通れないので、103° より遠くには直接届きません。' }
    ]
  });

  add('g4_plate', {
    pat: [
      { name: '海洋底の地磁気の縞模様から拡大速度を求める', freq: 'とてもよく出る', when: '海嶺をはさんで対称な縞模様の図があり、ある縞の距離と年代から海洋底の拡大速度を問われたときです。', how: ['海嶺で生まれた岩石は、そのときの地磁気の向きを記録したまま両側へ移動します。', '片側の速さ＝海嶺からの距離÷年代。', '海嶺の両側に同時に広がるので、2枚のプレートが離れる速さ(拡大速度)は片側の2倍です。cm/年に単位をそろえます。'], ex: { q: '海嶺から 50 km の位置の海底の岩石は 100 万年前にできたものであった。片側の移動速度を cm/年 で求めよ。', a: '5.0 cm/年', exp: '50 km＝5.0×10⁶ cm を 1.0×10⁶ 年で動いたので、5.0 cm/年です。両側のプレートが離れる速さは 10 cm/年 になります。' } },
      { name: 'プレート境界の3つのタイプを見分ける', freq: 'とてもよく出る', when: '地形や地震・火山の特徴から、どの種類のプレート境界かを答える問題です。', how: ['離れる境界(発散境界):海嶺・地溝帯。浅い地震と玄武岩質の火山活動。', '近づく境界(収束境界):海溝(沈みこみ帯)や大山脈(衝突帯)。深発地震まで起こり、沈みこみ帯では火山が多い。', 'すれちがう境界:トランスフォーム断層。浅い地震が多く、火山は少ない。'], ex: { q: '大西洋中央海嶺、日本海溝、ヒマラヤ山脈、サンアンドレアス断層は、それぞれどの種類の境界か。', a: '大西洋中央海嶺:離れる境界、日本海溝:近づく境界(沈みこみ)、ヒマラヤ山脈:近づく境界(衝突)、サンアンドレアス断層:すれちがう境界', exp: '海嶺はプレートが生まれる場所、海溝は沈みこむ場所、ヒマラヤはインド亜大陸がユーラシア大陸に衝突した場所です。サンアンドレアス断層はトランスフォーム断層の代表例です。' } },
      { name: 'ホットスポットの火山列からプレートの動きを読む', freq: 'よく出る', when: 'ハワイ諸島のように、火山島の年代が並んでいる図から、プレートの移動の向きや速さを問われたときです。', how: ['ホットスポットはマントルの深いところにあり、ほぼ動かないと考えます。', '今活動している火山が真上にあり、古い火山ほど、プレートの移動方向へ遠くにあります。', '速さ＝2つの火山の距離÷年代の差。火山列が折れ曲がっていれば、そのときにプレートの向きが変わったとわかります。'], ex: { q: 'ホットスポットの上にある活火山から 3000 km 離れた火山島の年代が 4000 万年前であった。プレートの移動速度を cm/年 で求めよ。', a: '7.5 cm/年', exp: '3000 km＝3.0×10⁸ cm を 4.0×10⁷ 年で動いたので、3.0×10⁸÷4.0×10⁷＝7.5 cm/年。古い島がある方向とは逆向きに、プレートは動いています。' } },
      { name: '火成岩の判定:組織と色(SiO₂ の量)の2つで決める', freq: 'とてもよく出る', when: '岩石の組織や鉱物の割合の説明から、岩石名を答える問題です。', how: ['組織:斑晶と石基があれば火山岩(急に冷えた)、大きな結晶ばかりの等粒状なら深成岩(ゆっくり冷えた)。', '色・成分:有色鉱物が多く黒っぽいほど SiO₂ が少ない(苦鉄質)、白っぽいほど SiO₂ が多い(ケイ長質)。', '表で、火山岩は玄武岩・安山岩・流紋岩、深成岩は斑れい岩・閃緑岩・花こう岩の順に SiO₂ が多くなります。'], ex: { q: '大きな結晶がすき間なく組み合わさった等粒状組織で、石英や長石が多く、全体に白っぽい岩石の名前を答えよ。', a: '花こう岩', exp: '等粒状組織なので深成岩、白っぽく石英が多いのでケイ長質です。この組み合わせは花こう岩です。同じ成分で斑状組織なら流紋岩になります。' } },
      { name: '震源の分布から沈みこむプレートの向きを読む', freq: 'よく出る', when: '海溝付近の断面図に震源がプロットされ、深発地震の並び方を問われたときです。', how: ['海溝から大陸側へ向かって、震源が次第に深くなる面(和達−ベニオフ帯)を探します。', 'この面にそって、海洋プレートが大陸プレートの下へ沈みこんでいます。', '面の傾きは、震源の深さと海溝からの水平距離から求められます。'], ex: { q: '日本列島付近では、深発地震の震源が太平洋側から日本海側へ向かって深くなっている。このことから何がわかるか。', a: '太平洋プレートが、日本海溝から日本列島の下へ斜めに沈みこんでいること。', exp: '沈みこむプレートとその上のプレートの境界や、沈みこむプレートの内部で地震が起こるので、震源がプレートにそって並びます。この面を和達−ベニオフ帯といいます。' } }
    ],
    more: [
      { lv: 1, q: '大西洋の両岸の海岸線の形が似ていることなどから、大陸移動説をとなえた人物はだれか。', a: 'ウェゲナー', exp: 'ウェゲナーは海岸線の形のほか、化石の分布や氷河の跡などを証拠に、大陸がかつて1つ(パンゲア)だったと考えました。動かす力を説明できず、当時は受け入れられませんでした。' },
      { lv: 1, q: '海嶺はどの種類のプレート境界か。', choices: ['離れる境界', '近づく境界', 'すれちがう境界', '境界ではない'], a: 'A(離れる境界)', exp: '海嶺ではマントルの物質が上昇してマグマができ、新しい海洋プレートがつくられて両側へ広がります。' },
      { lv: 1, q: '海嶺と海嶺の間をつなぎ、プレートがすれちがう断層を何というか。', a: 'トランスフォーム断層', exp: '海嶺はところどころでずれていて、そのずれの部分でプレートが逆向きに動きます。この部分の断層がトランスフォーム断層です。' },
      { lv: 1, q: '両側に引っぱる力(張力)がはたらいてできる断層を何というか。', choices: ['正断層', '逆断層', '横ずれ断層', 'トランスフォーム断層'], a: 'A(正断層)', exp: '張力がはたらくと、上盤が断層面にそって下へずれ落ちる正断層ができます。圧縮されると、上盤がのし上がる逆断層ができます。' },
      { lv: 1, q: '両側から圧縮されてできる断層で、上盤がずり上がるものを何というか。', a: '逆断層', exp: '日本列島はプレートの沈みこみで東西に圧縮されているので、逆断層が多く見られます。' },
      { lv: 1, q: '玄武岩の特徴として正しいものはどれか。', choices: ['SiO₂ が多く白っぽい', 'SiO₂ が少なく黒っぽい火山岩', '等粒状組織の深成岩', '石英を多く含む'], a: 'B(SiO₂ が少なく黒っぽい火山岩)', exp: '玄武岩は SiO₂ が約 45〜52 % と少なく、輝石やかんらん石などの有色鉱物を多く含む黒っぽい火山岩です。海洋地殻の上部をつくっています。' },
      { lv: 1, q: 'ハワイ島の火山のように、プレートの境界ではない場所で、マントル深部から高温の物質が上昇してできる火山の場所を何というか。', a: 'ホットスポット', exp: 'ホットスポットはほぼ動かないので、その上をプレートが動くと、火山島が列になって並びます。' },
      { lv: 2, q: '海嶺の片側で、海嶺から 40 km の位置の海底は 200 万年前にできたものであった。2枚のプレートが互いに離れる速さを cm/年 で求めよ。', a: '4.0 cm/年', exp: '片側の速さは 4.0×10⁶ cm÷2.0×10⁶ 年＝2.0 cm/年。両側に同じ速さで広がるので、離れる速さは2倍の 4.0 cm/年 です。' },
      { lv: 2, q: '海嶺から片側 5.0 cm/年 で海底が広がっているとき、海嶺から 1000 km の位置の海底の年代を求めよ。', a: '2000 万年前', exp: '1000 km＝1.0×10⁸ cm。1.0×10⁸÷5.0＝2.0×10⁷ 年。海洋底でいちばん古いものでも約 2 億年前で、大陸の岩石にくらべてとても若いです。' },
      { lv: 2, q: 'SiO₂ が多くねばりけの強いマグマからできる火山の形はどれか。', choices: ['たて状火山', '成層火山', '溶岩ドーム(溶岩円頂丘)', '溶岩台地'], a: 'C(溶岩ドーム(溶岩円頂丘))', exp: 'ねばりけが強いと溶岩が流れにくく、火口の上にもり上がってドーム状になります。爆発的な噴火を起こしやすい性質もあります。ねばりけが弱いとたて状火山や溶岩台地になります。' },
      { lv: 2, q: '斑晶と石基からなる組織を何というか。また、この組織をもつ岩石はどのようにしてできたか。', a: '斑状組織。マグマが地表付近で急に冷え固まってできた(火山岩)。', exp: '地下でゆっくり成長した結晶が斑晶、急に冷えて細かい結晶やガラスになった部分が石基です。2段階の冷え方を記録しています。' },
      { lv: 2, q: 'ヒマラヤ山脈ができた原因として正しいものはどれか。', choices: ['海洋プレートの沈みこみ', '大陸どうしの衝突', 'ホットスポットの火山活動', '海嶺での拡大'], a: 'B(大陸どうしの衝突)', exp: 'インド亜大陸をのせたプレートが北へ移動し、ユーラシア大陸に衝突しました。大陸の地殻は軽くて沈みこみにくいので、押し上げられて高い山脈ができました。' },
      { lv: 2, q: '海洋プレートが沈みこむとき、海底の堆積物などがはぎとられて陸側に押しつけられてできた地質体を何というか。', a: '付加体', exp: '付加体には、海洋プレートにのって運ばれてきたチャートや玄武岩、海溝でたまった砂や泥が混ざっています。日本列島の土台の多くは付加体でできています。' },
      { lv: 2, q: '泥岩がマグマの熱で変成してできる、かたく緻密な岩石を何というか。', a: 'ホルンフェルス', exp: 'マグマに接して熱によって変成する接触変成作用でできます。石灰岩が接触変成すると結晶質石灰岩(大理石)になります。' },
      { lv: 2, q: '地震のマグニチュードが 2 大きくなると、放出されるエネルギーはおよそ何倍になるか。', a: '約 1000 倍', exp: 'マグニチュードが 1 大きくなるとエネルギーは約 32 倍、2 大きくなると 32×32≒1000 倍です。M7 の地震は M5 の約 1000 個分のエネルギーです。' },
      { lv: 3, q: 'ホットスポットによる火山列で、活火山から 80 km の島が 100 万年前、400 km の島が 500 万年前にできた。この間のプレートの平均の移動速度を cm/年 で求めよ。', a: '8.0 cm/年', exp: '2つの島の距離の差は 320 km＝3.2×10⁷ cm、年代の差は 400 万年。3.2×10⁷÷4.0×10⁶＝8.0 cm/年。活火山からの距離ではなく、2つの島どうしの差で計算します。' },
      { lv: 3, q: '海洋底の水深は、海嶺からの年代の平方根にほぼ比例して深くなる(海嶺の深さを基準とした深さの増加量)。年代が 4 倍になると、深さの増加量は何倍になるか。また、その理由を答えよ。', a: '2 倍。古いプレートほど冷えて収縮し密度が大きくなり、アイソスタシーで沈むから。', exp: '√4＝2 倍です。海嶺の下は高温で軽いので高く、移動するにつれて冷えて重くなり沈んでいきます。冷えて厚くなるプレートの厚さが年代の平方根に比例するためです。' },
      { lv: 3, q: '海溝から陸側へ 300 km の地点の真下では、深さ 300 km で地震が起こっている。沈みこむプレートの平均の傾きは何度か。', a: '約 45°', exp: '水平距離 300 km で深さ 300 km なので、tanθ＝300/300＝1 より θ＝45°。実際の傾きは場所によってちがい、古く重いプレートほど急に沈みこむ傾向があります。' },
      { lv: 3, q: '輝石やかんらん石などの有色鉱物を多く含み、大きな結晶がすき間なく組み合わさった黒っぽい岩石の名前を答えよ。', a: '斑れい岩', exp: '等粒状組織なので深成岩、有色鉱物が多く黒っぽいので苦鉄質(SiO₂ が少ない)です。斑れい岩と同じ成分のマグマが急に冷えると玄武岩になります。' },
      { lv: 3, q: '地磁気を地球の中心に置いた棒磁石(双極子)と考えると、伏角 I と緯度 φ の間に tan I＝2 tan φ の関係がある。ある岩石が記録している伏角が 49° のとき、岩石ができたときの緯度はおよそ何度か。(tan 49°＝1.15、tan 30°＝0.58 とする)', a: '約 30°', exp: 'tan φ＝tan 49°/2＝1.15/2≒0.58 なので φ≒30°。岩石が記録した古い地磁気の伏角から、その大陸が昔どの緯度にあったかがわかり、大陸移動の証拠になりました。' }
    ]
  });

  add('g4_history', {
    pat: [
      { name: '地層の新旧:累重・不整合・貫入・断層で順番を決める', freq: 'とてもよく出る', when: '地質断面図があり、地層・断層・火成岩の貫入などの起こった順番を問われたときです。', how: ['地層の逆転がなければ、下の地層ほど古い(地層累重の法則)。', '切った方が新しい:断層や貫入岩は、それが切っている地層より新しいです。', '不整合面の上の地層は、下の地層が隆起・侵食されたあとに沈降して堆積したものです。不整合の上には基底れき岩があることが多いです。'], ex: { q: '地層 A(下)・B(上)が断層 F で切られ、その上を地層 C が不整合でおおっている。断層 F は地層 C を切っていない。A、B、C、F の起こった順を答えよ。', a: 'A→B→F→(隆起・侵食)→C', exp: 'A と B は累重の法則で A が古い。F は A と B を切るので B より新しく、C を切らないので C より古い。C は不整合の上なので、隆起と侵食をはさんで最後に堆積しました。' } },
      { name: '示準化石と示相化石を見分ける', freq: 'よく出る', when: '化石の名前から「地層ができた時代」か「当時の環境」を問われたときです。', how: ['示準化石:生存期間が短く、分布が広く、個体数が多い生物。時代を決めるのに使います(三葉虫・アンモナイト・ビカリアなど)。', '示相化石:生活できる環境が限られる生物。環境を知るのに使います(サンゴ・シジミ・ブナなど)。', 'サンゴは暖かく浅いきれいな海、シジミは河口や湖(汽水〜淡水)、ブナは温帯のやや寒冷な気候を示します。'], ex: { q: 'ある地層からサンゴの化石が見つかった。この地層ができた当時の環境を答えよ。', a: '暖かく浅い、きれいな海', exp: '造礁サンゴは、体内に共生する藻類が光合成をするので、光の届く浅い海でしか生きられず、暖かい水温を好みます。このように環境を示す化石を示相化石といいます。' } },
      { name: '放射年代:親核種と娘核種の比から半減期の回数を出す', freq: 'よく出る', when: '岩石中の放射性元素(親)と、それが壊れてできた元素(娘)の量の比から、年代を問われたときです。', how: ['はじめ親だけがあり、壊れた分がすべて娘になったと考えます。', '親:娘＝1:1 なら半減期1回、1:3 なら2回、1:7 なら3回(親の残りが 1/2、1/4、1/8)。', '年代＝半減期×回数。'], ex: { q: 'ある火成岩に含まれる放射性元素とその娘元素の量の比が 1:3 であった。半減期が 13 億年のとき、岩石ができてから何年たったか。', a: '26 億年', exp: '親が全体の 1/4 に減ったので、半減期2回分です。13 億年×2＝26 億年。比が 1:3 だから3回、とまちがえないよう「親が全体の何分の1か」で考えます。' } },
      { name: '鍵層で離れた地域の地層を対比する', freq: 'よく出る', when: '複数地点の柱状図があり、同じ時代の地層を結ぶ問題です。', how: ['火山灰層(凝灰岩層)は、広い範囲に短い時間で降り積もるので、よい鍵層になります。', '同じ鍵層を線で結び、その上下の地層の厚さや種類を比べます。', '同じ鍵層の標高を比べると、地層の傾きもわかります。'], ex: { q: '離れた2地点の地層を対比するのに、火山灰層がよい鍵層になる理由を答えよ。', a: '火山灰は噴火のときに短期間で広い範囲に降り積もるので、どこでもほぼ同じ時期の層とみなせ、しかも特徴的で見分けやすいから。', exp: '火山灰は噴火ごとに鉱物の組み合わせなどがちがうので、同じ噴火の火山灰かを判断できます。同時にできたことがはっきりしている層ほど、鍵層として役立ちます。' } },
      { name: '酸素同位体比で氷期・間氷期を読む', freq: '難関大で出る', when: '海底の有孔虫の殻や氷床コアの δ¹⁸O(酸素同位体比)のグラフから、当時の気候を問われたときです。', how: ['水が蒸発するとき、軽い ¹⁶O を含む水の方が蒸発しやすく、雪となって氷床にたくわえられます。', '氷期には氷床が大きくなるので、海水には重い ¹⁸O が多く残り、海の生物の殻の δ¹⁸O は大きくなります。', '逆に、氷床の氷そのものの δ¹⁸O は、寒いほど小さくなります。どちらの記録かを確かめます。'], ex: { q: '海底の堆積物中の有孔虫の殻の δ¹⁸O が大きい時期は、氷期と間氷期のどちらにあたるか。', a: '氷期', exp: '氷期には ¹⁶O を多く含む水が氷床に閉じこめられ、海水は ¹⁸O の割合が高くなります。その海水から殻をつくるので、殻の δ¹⁸O も大きくなります。' } }
    ],
    more: [
      { lv: 1, q: '粒の大きさが 2 mm 以上の粒子でできた堆積岩はどれか。', choices: ['れき岩', '砂岩', '泥岩', 'チャート'], a: 'A(れき岩)', exp: '粒の大きさで、2 mm 以上がれき岩、1/16〜2 mm が砂岩、1/16 mm 以下が泥岩です。粒が大きいほど、流れの速い場所や河口に近い場所で堆積します。' },
      { lv: 1, q: '放散虫などの殻が積もってできた、SiO₂ を主成分とするかたい堆積岩は何か。', a: 'チャート', exp: 'チャートはとてもかたく、鉄のハンマーでたたくと火花が出るほどです。塩酸をかけても泡は出ません。深海で堆積したものが多いです。' },
      { lv: 1, q: '石灰岩にうすい塩酸をかけるとどうなるか。', a: '二酸化炭素の泡が出る', exp: '石灰岩の主成分は炭酸カルシウム CaCO₃ で、塩酸と反応して CO₂ を出します。チャートとの見分け方として使われます。' },
      { lv: 1, q: 'アンモナイトが栄えた地質時代はどれか。', choices: ['古生代', '中生代', '新生代古第三紀', '新生代第四紀'], a: 'B(中生代)', exp: 'アンモナイトは中生代の示準化石で、恐竜と同じく白亜紀末に絶滅しました。古生代の代表的な示準化石は三葉虫です。' },
      { lv: 1, q: 'ビカリア(巻貝)の化石が見つかった地層は、どの時代のものと考えられるか。', a: '新生代(新第三紀)', exp: 'ビカリアは新生代新第三紀の示準化石で、暖かい地域の干潟(マングローブ林)にすんでいたので、示相化石としても使われます。' },
      { lv: 1, q: 'シアノバクテリアがつくった、層状の構造をもつ岩石を何というか。', a: 'ストロマトライト', exp: 'シアノバクテリアの粘液に泥がつき、その上でまたシアノバクテリアが増えることをくり返してできます。約 27 億年前ごろから多く見られ、酸素が増えた証拠になります。' },
      { lv: 1, q: '火山灰が固まってできた堆積岩を何というか。', a: '凝灰岩', exp: '凝灰岩は火山の噴火の時期を示すので、地層の対比の鍵層として使われます。粒が角ばっているのも特徴です。' },
      { lv: 2, q: 'ある岩石の放射性元素の量が、できたときの 25 % に減っていた。半減期を 7.0 億年とすると、岩石の年代を求めよ。', a: '14 億年前', exp: '25 %＝1/4＝(1/2)² なので、半減期2回分です。7.0 億年×2＝14 億年。' },
      { lv: 2, q: '1枚の地層の中で、下から上へ粒が細かくなっている構造を何というか。また、この構造から何がわかるか。', a: '級化層理(級化成層)。地層の上下(どちらが上か)がわかる。', exp: '水中で土砂がしずむとき、大きい粒ほど先にしずむので、下が粗く上が細かくなります。地層が逆転していても、この構造で本来の上下を判断できます。' },
      { lv: 2, q: '不整合面のすぐ上に、下の地層の岩石のれきを含む層がよく見られる。この層を何というか。', a: '基底れき岩', exp: '下の地層が陸上で侵食されたときのれきが、そのあと沈降したときに最初に堆積します。不整合を見分ける大切な手がかりです。' },
      { lv: 2, q: '約 25 億〜20 億年前に多くつくられた縞状鉄鉱層は、何を示していると考えられるか。', a: 'シアノバクテリアが放出した酸素によって、海水中の鉄イオンが酸化され、沈殿したこと。', exp: '酸素が海水中の鉄を酸化して酸化鉄が沈み、縞状にたまりました。世界の鉄鉱石の多くはこのときにできたものです。' },
      { lv: 2, q: '生物の歴史の中で最大規模とされる大量絶滅が起こったのは、いつの終わりか。', choices: ['カンブリア紀', 'ペルム紀(二畳紀)', '白亜紀', '新第三紀'], a: 'B(ペルム紀(二畳紀))', exp: '古生代の終わり(ペルム紀末)に、海の生物の種の 90 % 以上が絶滅したといわれます。三葉虫もこのとき絶滅しました。この絶滅で古生代と中生代が区切られます。' },
      { lv: 2, q: '白亜紀末の大量絶滅が巨大な隕石の衝突によるという説の証拠になった、境界の地層に多く含まれる元素は何か。', a: 'イリジウム', exp: 'イリジウムは地表の岩石にはごく少なく、隕石に多く含まれます。白亜紀と古第三紀の境界の粘土層に世界中でイリジウムが多いことから、衝突説が有力になりました。' },
      { lv: 2, q: '古生代カンブリア紀に、さまざまな形の動物が一気に現れた出来事を何というか。', a: 'カンブリア爆発', exp: 'カナダのバージェス頁岩や中国の澄江動物群などから、多様な動物の化石が見つかっています。かたい殻や骨格をもつ動物が増えたことも、化石が多く残った理由です。' },
      { lv: 2, q: '示相化石として使える生物の条件を答えよ。', a: '生きられる環境(水温・水深・塩分など)の範囲がせまいこと。また、現在も似た生物が生きていて、その環境がわかること。', exp: '環境の範囲が広い生物では、当時の環境をしぼりこめません。現生の近い仲間の生活のしかたから、昔の環境を推定します。' },
      { lv: 3, q: 'ある岩石中の放射性元素とその娘元素の比が 1:7 であった。半減期を 13 億年とすると、岩石の年代を求めよ。', a: '39 億年前', exp: '親は全体の 1/8＝(1/2)³ に減っているので半減期3回分。13 億年×3＝39 億年です。比が 1:7 でも、回数は 7 ではなく 3 であることに注意します。' },
      { lv: 3, q: '地層 P・Q・R がこの順に下から重なり、花こう岩 G が P と Q を貫いているが R は貫いていない。また、R と Q の間は不整合である。G のまわりの Q にはホルンフェルスが見られる。起こった順を答えよ。', a: 'P の堆積→Q の堆積→G の貫入(Q の接触変成)→隆起・侵食→沈降→R の堆積', exp: 'G は Q を貫くので Q より新しく、R を貫かないので R より古いです。ホルンフェルスは G の熱による接触変成で、G が Q より新しい証拠になります。不整合の間には隆起・侵食・沈降が入ります。' },
      { lv: 3, q: '南極の氷床から取り出した氷そのものの δ¹⁸O は、気温が低い時期ほどどうなるか。理由とともに答えよ。', a: '小さくなる。寒いほど、水蒸気が運ばれる途中で重い ¹⁸O を含む水が先に雨や雪として落ち、極地に届く雪は ¹⁶O の割合がより高くなるから。', exp: '有孔虫の殻(海水側の記録)とは、寒いときの変化の向きが逆になります。どちらの記録を見ているのかを確かめることが大切です。' },
      { lv: 3, q: '遺跡から出た木炭の ¹⁴C の割合が、生きている木の 1/8 であった。¹⁴C の半減期を 5730 年とすると、およそ何年前の木炭か。', a: '約 1.7 万年前(17190 年前)', exp: '1/8＝(1/2)³ なので半減期3回分、5730×3＝17190 年です。¹⁴C は半減期が短いので、数万年前までの若い年代の測定に向いています。' },
      { lv: 3, q: 'ある海底で、厚さ 100 m の地層が 50 万年かけてたまったとすると、平均の堆積速度は 1 年あたり何 mm か。', a: '0.2 mm/年', exp: '100 m＝1.0×10⁵ mm を 5.0×10⁵ 年でわると 0.2 mm/年。1000 年で 20 cm ほどで、地層ができるのにとても長い時間がかかることがわかります。' }
    ]
  });

  add('g4_atmos', {
    pat: [
      { name: 'フェーン現象の気温計算:雲の有無で減率を使い分ける', freq: 'とてもよく出る', when: '空気が山を越えるときの、風上と風下の気温を問われたときです。', how: ['雲ができるまでは乾燥断熱減率(100 m で 1.0 ℃)で下がります。', '雲ができてから山頂までは湿潤断熱減率(100 m で約 0.5 ℃)で下がります。', '風下で雲がなく下りるときは、乾燥断熱減率(100 m で 1.0 ℃)で上がります。'], ex: { q: '高度 0 m で 20 ℃の空気が山の斜面を上り、高度 1000 m で雲ができ、2000 m の山頂をこえて、風下の高度 0 m まで雲のないまま下りた。風下の気温を求めよ。(乾燥断熱減率 1.0 ℃/100 m、湿潤断熱減率 0.5 ℃/100 m)', a: '25 ℃', exp: '1000 m まで乾燥で 10 ℃下がって 10 ℃。山頂まで湿潤で 5 ℃下がって 5 ℃。風下は 2000 m を乾燥で下りるので 20 ℃上がって 25 ℃。上りの途中で雨を降らせた分、風下が暖かく乾きます。' } },
      { name: '雲底の高さ:(気温−露点)×125 m', freq: 'よく出る', when: '地上の気温と露点が与えられ、上昇する空気に雲ができる高さを問われたときです。', how: ['上昇する空気の気温は 100 m で 1.0 ℃、露点は約 0.2 ℃下がります。', '気温と露点の差は 100 m で 0.8 ℃ずつちぢまります。', '差が 0 になる高さが雲底で、(気温−露点)÷0.8×100＝(気温−露点)×125 m です。'], ex: { q: '地上の気温が 25 ℃、露点が 17 ℃の空気が上昇すると、およそ何 m の高さで雲ができるか。', a: '約 1000 m', exp: '差は 25−17＝8 ℃。100 m で 0.8 ℃ずつ縮まるので、8÷0.8×100＝1000 m。このとき気温は 15 ℃、露点も 15 ℃(17−2)になり一致します。' } },
      { name: '放射平衡温度:入る太陽放射＝出ていく地球放射', freq: 'よく出る', when: '太陽定数とアルベド(反射率)から、地球の放射平衡温度を問われたときです。', how: ['地球が受ける太陽放射は、断面積 πR² に太陽定数 S をかけ、反射の分を引いて S(1−A)πR²。', '地球が出す放射は、表面積 4πR² にステファン・ボルツマンの法則 σT⁴ をかけたもの。', '等しいとおくと σT⁴＝S(1−A)/4。4 で割るのは、断面積と表面積の比のためです。'], ex: { q: '太陽定数を 1370 W/m²、地球のアルベドを 0.30、σ＝5.67×10⁻⁸ W/(m²·K⁴) として、地球の放射平衡温度を求めよ。', a: '約 255 K(約 −18 ℃)', exp: 'σT⁴＝1370×0.70/4≒240 W/m²。T⁴＝240/5.67×10⁻⁸≒4.2×10⁹、T≒255 K。実際の平均気温は約 288 K(15 ℃)で、その差が温室効果によるものです。' } },
      { name: '大気の安定・不安定:気温減率を断熱減率と比べる', freq: 'よく出る', when: 'まわりの大気の気温減率が与えられ、空気が上昇しつづけるか(不安定)を問われたときです。', how: ['持ち上げられた空気の温度は、乾燥なら 1.0 ℃/100 m、飽和なら約 0.5 ℃/100 m で下がります。', 'まわりの気温減率がこれより大きいと、持ち上げた空気はまわりより暖かく(軽く)なり、さらに上昇します(不安定)。', 'まわりの減率が 0.5 と 1.0 の間なら、乾燥空気には安定、飽和空気には不安定(条件つき不安定)です。'], ex: { q: 'まわりの大気の気温減率が 0.7 ℃/100 m のとき、乾燥した空気と、水蒸気で飽和した空気の場合で、大気は安定か不安定か。', a: '乾燥した空気には安定、飽和した空気には不安定(条件つき不安定)', exp: '乾燥した空気は持ち上げると 1.0 ℃/100 m で冷え、まわりより冷たく重くなるので下へもどります(安定)。飽和した空気は 0.5 ℃/100 m しか冷えず、まわりより暖かいままなのでさらに上昇します。' } },
      { name: '相対湿度:水蒸気量÷飽和水蒸気量', freq: 'よく出る', when: '空気中の水蒸気量と、その気温の飽和水蒸気量が与えられ、湿度や露点を問われたときです。', how: ['相対湿度(%)＝空気 1 m³ 中の水蒸気量÷その気温での飽和水蒸気量×100。', '露点は、その空気の水蒸気量がちょうど飽和水蒸気量になる温度です。', '露点より冷やすと、その差の分の水蒸気が水滴になります。'], ex: { q: '気温 25 ℃(飽和水蒸気量 23.0 g/m³)の空気 1 m³ に、水蒸気が 11.5 g 含まれている。相対湿度を求めよ。', a: '50 %', exp: '11.5÷23.0×100＝50 %。同じ水蒸気量でも、気温が下がれば飽和水蒸気量が小さくなるので、相対湿度は上がります。' } }
    ],
    more: [
      { lv: 1, q: '地表付近の乾燥した大気で、体積の割合が最も大きい気体は何か。', a: '窒素(約 78 %)', exp: '乾燥した大気は、窒素約 78 %、酸素約 21 %、アルゴン約 0.9 %、二酸化炭素約 0.04 % です。この割合は高度約 80 km まではほぼ同じです。' },
      { lv: 1, q: '対流圏では、高さが 1 km 上がるごとに平均して気温が約何 ℃下がるか。', choices: ['約 0.65 ℃', '約 6.5 ℃', '約 65 ℃', '変わらない'], a: 'B(約 6.5 ℃)', exp: '対流圏の平均の気温減率は約 6.5 ℃/km です。地表が太陽放射で暖められ、その熱が上へ運ばれるため、上空ほど低温になります。' },
      { lv: 1, q: 'オゾン層があるのは大気のどの層か。', choices: ['対流圏', '成層圏', '中間圏', '熱圏'], a: 'B(成層圏)', exp: 'オゾンは高さ 20〜30 km 付近に多く、太陽の紫外線を吸収します。このため成層圏では上空ほど気温が上がります。' },
      { lv: 1, q: '地表から出る赤外線を吸収し、温室効果をもたらす気体の例を2つ答えよ。', a: '二酸化炭素、水蒸気(ほかにメタンなど)', exp: 'これらの気体は太陽からの可視光はよく通しますが、地表が出す赤外線を吸収して地表へ放射し返すので、地表を暖かく保ちます。' },
      { lv: 1, q: '赤道付近で上昇した空気が、緯度 30° 付近で下降する大気の循環を何というか。', a: 'ハドレー循環', exp: 'ハドレー循環の地表付近では、亜熱帯高圧帯から赤道へ向かう風が、地球の自転の影響で東寄りの風(貿易風)になります。' },
      { lv: 1, q: '中緯度の上空で、西から東へ吹く強い風を何というか。', a: '偏西風', exp: '偏西風は中緯度の上空を西から東へ吹き、特に強い部分をジェット気流といいます。日本の天気が西から東へ移り変わるのは、この風のためです。' },
      { lv: 1, q: '寒冷前線が通過するときの天気の特徴として正しいものはどれか。', choices: ['広い範囲で長い時間おだやかな雨が降る', 'せまい範囲で短い時間に強い雨が降り、通過後は気温が下がる', '気温が上がり、南寄りの風になる', '雲ができない'], a: 'B(せまい範囲で短い時間に強い雨が降り、通過後は気温が下がる)', exp: '寒冷前線では、寒気が暖気の下にもぐりこんで暖気を急に持ち上げるので、積乱雲が発達します。通過後は北寄りの風になり、気温が下がります。' },
      { lv: 2, q: '高度 0 m で 15 ℃の空気が山を上り、高度 500 m で雲ができ、1500 m の山頂をこえて、風下の 0 m まで雲のないまま下りた。風下の気温を求めよ。(乾燥断熱減率 1.0 ℃/100 m、湿潤断熱減率 0.5 ℃/100 m)', a: '20 ℃', exp: '500 m まで乾燥で 5 ℃下がり 10 ℃。山頂まで 1000 m を湿潤で 5 ℃下がり 5 ℃。風下は 1500 m を乾燥で下りるので 15 ℃上がり 20 ℃です。' },
      { lv: 2, q: '地上の気温が 20 ℃、露点が 12 ℃の空気が上昇するとき、雲ができる高さを求めよ。', a: '約 1000 m', exp: '気温と露点の差は 8 ℃で、100 m 上がるごとに 0.8 ℃縮まります。8×125＝1000 m です。' },
      { lv: 2, q: '日本の南岸にそって北東へ流れる暖流を何というか。', a: '黒潮(日本海流)', exp: '黒潮は北太平洋の亜熱帯環流の一部で、流れが速く、暖かい水を北へ運びます。日本の気候や漁業に大きな影響を与えています。' },
      { lv: 2, q: 'エルニーニョ現象が起こっているとき、太平洋赤道域の東部(ペルー沖)の海面水温はどうなっているか。', choices: ['平年より高い', '平年より低い', '平年と同じ', '東部だけ凍る'], a: 'A(平年より高い)', exp: '貿易風が弱まると、西へ吹き寄せられていた暖かい海水が東へもどり、東部の冷たい湧昇が弱まります。そのため東部の海面水温が平年より高くなります。' },
      { lv: 2, q: '中緯度で発生し、温暖前線と寒冷前線をともなう低気圧を何というか。', a: '温帯低気圧', exp: '温帯低気圧は、南北の寒気と暖気の境目でできます。暖気と寒気の温度差がエネルギー源で、台風(熱帯低気圧)とはでき方がちがいます。' },
      { lv: 2, q: '北半球の上空で、等圧線に平行に吹く地衡風は、低圧側を進行方向のどちらに見て吹くか。', a: '左側', exp: '気圧傾度力(低圧へ向かう力)と転向力(北半球では進行方向の右向き)がつり合うと、風は等圧線に平行になり、低圧側が左になります。' },
      { lv: 2, q: '中緯度の対流圏の上部で、偏西風が特に強く吹いている部分を何というか。', a: 'ジェット気流', exp: 'ジェット気流は高さ約 10 km 付近にあり、冬には秒速 100 m 近くになることもあります。航空機は東向きの便でこの風を利用します。' },
      { lv: 2, q: '地球に入射する太陽放射のうち、雲や地表などで反射されて宇宙へもどる割合(アルベド)はおよそいくらか。', choices: ['約 3 %', '約 30 %', '約 70 %', '約 97 %'], a: 'B(約 30 %)', exp: '地球のアルベドは約 0.3 です。残りの約 70 % が大気と地表に吸収され、最終的には赤外線として宇宙へ放射されます。' },
      { lv: 3, q: 'アルベドを 0(すべて吸収する)とすると、地球の放射平衡温度はおよそ何 K になるか。(太陽定数 1370 W/m²、σ＝5.67×10⁻⁸ W/(m²·K⁴))', a: '約 279 K', exp: 'σT⁴＝1370/4≒343 W/m²。T⁴≒6.04×10⁹ で T≒279 K。アルベド 0.3 のときの 255 K より高くなります。雪や氷が減って反射が減ると温暖化が進むしくみにつながります。' },
      { lv: 3, q: '大気を、可視光は通し、地表からの赤外線はすべて吸収する1枚の層とみなす。放射平衡温度が 255 K のとき、地表の温度は何 K になるか。(大気の層は上下に同じ量を放射する、2^(1/4)＝1.19)', a: '約 303 K', exp: '大気の層は宇宙へ σTₐ⁴ を出すので Tₐ＝255 K。地表へも同じ量を出すので、地表は太陽からの分と合わせて 2 倍のエネルギーを受け、σTₛ⁴＝2σTₐ⁴、Tₛ＝2^(1/4)×255≒303 K。実際(288 K)より高いのは、モデルが単純なためです。' },
      { lv: 3, q: 'まわりの大気の気温減率が 0.8 ℃/100 m の日、地上の空気を持ち上げた。(1) 雲ができる前 (2) 雲ができて水蒸気で飽和したあと、それぞれで空気はさらに上昇しつづけようとするか。', a: '(1) しない(安定) (2) する(不安定)', exp: '(1) 乾燥した空気は 1.0 ℃/100 m で冷え、まわり(0.8)より冷たく重くなるので、持ち上げをやめるともどります。(2) 飽和した空気は 0.5 ℃/100 m しか冷えないので、まわりより暖かく軽くなり、自分で上昇します。こうして積乱雲が発達します。' },
      { lv: 3, q: '北大西洋のグリーンランド付近などで海水が冷えて沈みこみ、深海をゆっくり流れて世界の海をめぐる循環が起こる。この循環を起こす主な原因はどれか。', choices: ['風が海面を押す力', '水温が低く塩分が高い海水の密度が大きいこと', '月の引力', '海底火山の熱'], a: 'B(水温が低く塩分が高い海水の密度が大きいこと)', exp: '冷えて、さらに海氷ができるときに塩分が残って濃くなった海水は重く、深くまで沈みます。この熱塩循環(深層循環)は 1000 年以上の時間をかけて世界の海をめぐります。' },
      { lv: 3, q: '地上の気温 25 ℃、露点 15 ℃の空気が上昇して雲ができ、さらに高度 3000 m まで上昇した。雲ができる高さと、高度 3000 m での空気の温度を求めよ。(乾燥断熱減率 1.0 ℃/100 m、湿潤断熱減率 0.5 ℃/100 m)', a: '雲底 1250 m、3000 m で約 3.8 ℃', exp: '雲底は (25−15)×125＝1250 m で、そのときの温度は 25−12.5＝12.5 ℃。そこから 1750 m を湿潤で上がるので 0.5×17.5＝8.75 ℃下がり、約 3.8 ℃です。' }
    ]
  });

  add('g4_space', {
    pat: [
      { name: '等級と明るさ:5 等級差で 100 倍', freq: 'とてもよく出る', when: '2つの星の等級の差から明るさの比を問われたり、逆に明るさの比から等級差を問われたときです。', how: ['1 等級の差は 100^(1/5)≒2.5 倍の明るさの差です。', '5 等級差で 100 倍、2.5 等級差で 10 倍、10 等級差で 10000 倍。', '等級は小さい(マイナスに近い)ほど明るいことに注意します。'], ex: { q: '1 等星と 3.5 等星の明るさの比を求めよ。', a: '1 等星が 10 倍明るい', exp: '等級差は 3.5−1＝2.5。2.5 等級差は 100^(2.5/5)＝100^(1/2)＝10 倍です。数の小さい 1 等星の方が明るい星です。' } },
      { name: '年周視差から距離:d(パーセク)＝1/p(秒)', freq: 'とてもよく出る', when: '年周視差が与えられ、恒星までの距離を問われたときです。', how: ['年周視差 p は、地球が太陽のまわりを回ることで星の見える方向がずれる角度の半分です。', '距離 d(パーセク)＝1/p(″)。', '1 パーセク≒3.26 光年 で光年に直します。'], ex: { q: '年周視差が 0.25″ の恒星までの距離をパーセクと光年で求めよ。', a: '4.0 パーセク、約 13 光年', exp: 'd＝1/0.25＝4.0 パーセク。4.0×3.26≒13 光年です。年周視差が小さいほど遠く、遠い星では測れなくなります。' } },
      { name: '絶対等級:M＝m＋5−5 log₁₀d', freq: 'よく出る', when: '見かけの等級と距離から絶対等級(10 パーセクに置いたときの等級)を問われたときです。', how: ['明るさは距離の2乗に反比例します。', '10 パーセクより遠い星は、10 パーセクに近づけると明るくなる(等級が小さくなる)ことを使います。', '式 M＝m＋5−5 log₁₀d(d はパーセク)に代入します。'], ex: { q: '見かけの等級が 5 等で、距離が 100 パーセクの恒星の絶対等級を求めよ。', a: '0 等', exp: 'M＝5＋5−5 log₁₀100＝10−10＝0。100 パーセクから 10 パーセクへ距離が 1/10 になると、明るさは 100 倍、つまり 5 等級明るくなる、と考えても同じです。' } },
      { name: '恒星の半径:L∝R²T⁴ から比で求める', freq: 'よく出る', when: '2つの恒星の光度(または絶対等級)と表面温度から、半径の比を問われたときです。', how: ['恒星の光度は L＝4πR²σT⁴ で、半径の2乗と温度の4乗に比例します。', '比をとると R∝√L/T²。', 'HR 図で同じ光度なら、温度の低い(右の)星ほど大きく、同じ温度なら明るい(上の)星ほど大きいことがわかります。'], ex: { q: '光度が同じで、表面温度が 2 倍の恒星は、半径が何倍か。', a: '1/4 倍', exp: 'L∝R²T⁴ で L が同じなら R²∝1/T⁴、R∝1/T²。T が 2 倍なら R は 1/4 倍です。高温で暗い白色矮星が小さいのも同じ考え方で説明できます。' } },
      { name: 'ハッブルの法則:v＝H₀d', freq: 'よく出る', when: '銀河の後退速度から距離を求めたり、宇宙の年齢を見積もったりする問題です。', how: ['遠い銀河ほど速く遠ざかり、後退速度 v は距離 d に比例します:v＝H₀d。', 'H₀ はハッブル定数で、約 70 km/s/Mpc(メガパーセク)です。', '1/H₀ はおよそ宇宙の年齢の目安になります(単位をそろえて計算)。'], ex: { q: 'ハッブル定数を 70 km/s/Mpc とする。後退速度 7000 km/s の銀河までの距離を求めよ。', a: '100 Mpc(1 億パーセク)', exp: 'd＝v/H₀＝7000/70＝100 Mpc。約 3.3 億光年です。後退速度は、スペクトルの赤方偏移から求めます。' } },
      { name: 'ウィーンの変位則:λmax×T＝2.9×10⁻³ m·K', freq: 'よく出る', when: '恒星の色(最も強く出る光の波長)から表面温度を求める問題です。', how: ['最も強い光の波長 λmax と表面温度 T は反比例します。', 'λmax T≒2.9×10⁻³ m·K を使います。', '温度が高いほど波長が短く青白く、低いほど赤く見えます。'], ex: { q: '表面温度 5800 K の太陽で、最も強く放射される光の波長を求めよ。', a: '約 5.0×10⁻⁷ m(500 nm)', exp: 'λmax＝2.9×10⁻³/5800＝5.0×10⁻⁷ m で、緑〜青緑の光です。実際には全体の色が混ざって、太陽は白っぽく見えます。' } }
    ],
    more: [
      { lv: 1, q: '太陽の光球の温度と、黒点の温度の組み合わせとして正しいものはどれか。', choices: ['光球 約 6000 K、黒点 約 4000 K', '光球 約 4000 K、黒点 約 6000 K', '光球 約 1600 万 K、黒点 約 6000 K', 'どちらも約 100 万 K'], a: 'A(光球 約 6000 K、黒点 約 4000 K)', exp: '黒点はまわりの光球より約 2000 K 温度が低いので黒く見えます。強い磁場が熱の流れをおさえているためです。' },
      { lv: 1, q: '太陽のエネルギー源は何か。', a: '中心部での水素の核融合(4 個の水素原子核からヘリウム原子核ができる反応)', exp: '太陽の中心は約 1600 万 K、高密度で、水素が核融合してヘリウムになります。このとき減った質量がエネルギー(E＝mc²)になります。' },
      { lv: 1, q: '1 パーセクは約何光年か。', choices: ['約 0.31 光年', '約 1 光年', '約 3.26 光年', '約 10 光年'], a: 'C(約 3.26 光年)', exp: '1 パーセクは年周視差が 1″ になる距離で、約 3.26 光年(約 3.1×10¹³ km)です。' },
      { lv: 1, q: 'HR 図で、左上から右下へのびる帯にある星を何というか。', a: '主系列星', exp: '主系列星は中心で水素の核融合をしている星で、恒星はその一生の大部分をこの段階で過ごします。太陽も主系列星です。' },
      { lv: 1, q: '太陽程度の質量の恒星が、一生の最後に残す小さく高温の天体を何というか。', a: '白色矮星', exp: '太陽ほどの恒星は、赤色巨星になって外層を放出したあと(惑星状星雲)、中心核が白色矮星として残ります。地球ほどの大きさで、ゆっくり冷えていきます。' },
      { lv: 1, q: '銀河系(天の川銀河)の円盤の直径はおよそいくらか。', choices: ['約 1 万光年', '約 10 万光年', '約 100 万光年', '約 1 億光年'], a: 'B(約 10 万光年)', exp: '銀河系は直径約 10 万光年の円盤状で、約 2000 億個の恒星を含みます。太陽系は中心から約 2.6〜2.8 万光年の位置にあります。' },
      { lv: 1, q: '恒星のスペクトル型を、表面温度の高い順に並べよ。', a: 'O、B、A、F、G、K、M', exp: 'O 型は青白く 3 万 K 以上、M 型は赤く 3000 K 程度です。太陽は G 型です。' },
      { lv: 2, q: '3 等級差の2つの星の明るさの比はおよそいくらか。(100^(1/5)＝2.51)', a: '約 16 倍', exp: '2.51³≒15.8≒16 倍です。2.5 等級で 10 倍、5 等級で 100 倍なので、その間の値になることを確かめられます。' },
      { lv: 2, q: '年周視差が 0.10″ の恒星について、見かけの等級と絶対等級の関係はどうなるか。', a: '距離が 10 パーセクなので、見かけの等級と絶対等級は等しい。', exp: 'd＝1/0.10＝10 パーセクです。絶対等級は「10 パーセクの距離に置いたときの等級」なので、この星では見かけの等級と同じになります。' },
      { lv: 2, q: 'ハッブル定数を 70 km/s/Mpc とすると、宇宙の年齢の目安 1/H₀ はおよそ何年か。(1 Mpc＝3.1×10¹⁹ km、1 年＝3.2×10⁷ s)', a: '約 140 億年', exp: '1/H₀＝3.1×10¹⁹/70≒4.4×10¹⁷ s。年に直すと 4.4×10¹⁷/3.2×10⁷≒1.4×10¹⁰ 年。観測から求められている宇宙の年齢 138 億年に近い値です。' },
      { lv: 2, q: '最も強く光を出す波長が 1.0×10⁻⁶ m の恒星の表面温度を求めよ。(λmax T＝2.9×10⁻³ m·K)', a: '約 2900 K', exp: 'T＝2.9×10⁻³/1.0×10⁻⁶＝2900 K。赤外線寄りに強く光る、赤く見える M 型の星です。' },
      { lv: 2, q: '表面温度が同じで、光度が 100 倍の恒星は、半径が何倍か。', a: '10 倍', exp: 'L∝R²T⁴ で T が同じなら L∝R²。R∝√L なので √100＝10 倍です。' },
      { lv: 2, q: '赤色巨星は HR 図のどのあたりにあるか。', choices: ['左上', '右上', '左下', '右下'], a: 'B(右上)', exp: '赤色巨星は表面温度が低い(右)のに光度が大きい(上)ので、HR 図の右上にあります。半径がとても大きいことが光度の大きさの理由です。' },
      { lv: 2, q: '太陽の約 8 倍以上の質量をもつ恒星は、一生の最後にどうなるか。', a: '超新星爆発を起こし、中性子星やブラックホールを残す。', exp: '重い星は中心で鉄までつくったあと、重力で一気につぶれて爆発します。このとき鉄より重い元素もつくられ、宇宙にまき散らされます。' },
      { lv: 2, q: '太陽の中心で水素 4 個からヘリウム 1 個ができるとき、質量のおよそ何 % がエネルギーに変わるか。', choices: ['約 0.007 %', '約 0.7 %', '約 7 %', '約 70 %'], a: 'B(約 0.7 %)', exp: '水素原子核 4 個の質量より、ヘリウム原子核 1 個の質量が約 0.7 % 小さく、その分が E＝mc² でエネルギーになります。わずかな割合でも c² が大きいので莫大なエネルギーです。' },
      { lv: 3, q: '見かけの等級が 10 等で、距離が 1000 パーセクの恒星の絶対等級を求めよ。', a: '0 等', exp: 'M＝m＋5−5 log₁₀d＝10＋5−5×3＝0。1000 パーセクから 10 パーセクに近づけると距離は 1/100、明るさは 10000 倍で 10 等級明るくなる、と考えても同じです。' },
      { lv: 3, q: '太陽の絶対等級を 4.8 等とする。絶対等級 −5.0 等の恒星の光度は太陽の約何倍か。(10^0.4＝2.51、10^3.92＝8.3×10³)', a: '約 8×10³ 倍', exp: '等級差は 4.8−(−5.0)＝9.8 等。光度の比は 10^(0.4×9.8)＝10^3.92≒8.3×10³ 倍です。' },
      { lv: 3, q: '連星の2つの星が、平均距離 4.0 天文単位、公転周期 2.0 年で互いのまわりを回っている。2つの星の質量の和は太陽の何倍か。(ケプラーの第3法則:質量の和(太陽単位)＝a³/P²、a は天文単位、P は年)', a: '16 倍', exp: '4.0³/2.0²＝64/4.0＝16 倍。恒星の質量を直接はかれるのは、このような連星の観測によります。' },
      { lv: 3, q: '主系列星の光度は質量のほぼ4乗に比例する(L∝M⁴)。寿命は「燃料の量(質量)÷燃える速さ(光度)」に比例するとして、太陽の 2 倍の質量の主系列星の寿命を求めよ。(太陽の主系列の寿命を 100 億年とする)', a: '約 12.5 億年', exp: '寿命∝M/L∝M/M⁴＝M⁻³。質量が 2 倍なら 2⁻³＝1/8 倍で、100 億年/8＝12.5 億年。重い星ほど燃料は多くても、ずっと速く燃やすので短命です。' },
      { lv: 3, q: '太陽定数を 1370 W/m²、太陽と地球の距離を 1.5×10¹¹ m として、太陽が1秒間に放出する全エネルギー(光度)を求めよ。(π＝3.14)', a: '約 3.9×10²⁶ W', exp: '太陽を中心とする半径 1.5×10¹¹ m の球面全体を、1 m² あたり 1370 W のエネルギーが通ります。L＝4π×(1.5×10¹¹)²×1370≒3.9×10²⁶ W です。' }
    ]
  });

  add('gb_solid', {
    pat: [
      { name: '震源距離:大森公式 D＝k×(初期微動継続時間)', freq: 'とてもよく出る', when: '初期微動継続時間(P 波が来てから S 波が来るまでの時間)が与えられ、震源までの距離を問われたときです。', how: ['初期微動継続時間は、震源からの距離に比例します。', '比例定数 k(km/s)が与えられたら、D＝k×時間 で求めます。', 'k がなければ、P 波・S 波の速さから D/Vs−D/Vp＝時間 の式を立てます。'], ex: { q: '大森公式の比例定数を 8.0 km/s とする。初期微動継続時間が 5.0 秒の観測点の震源距離を求めよ。', a: '40 km', exp: 'D＝8.0×5.0＝40 km。初期微動継続時間が長いほど、震源から遠い場所です。' } },
      { name: '地震の発生時刻:P 波の到着時刻から逆算する', freq: 'よく出る', when: '観測点の震源距離と P 波の到着時刻が与えられ、地震が起こった時刻を問われたときです。', how: ['P 波が震源から観測点まで届くのにかかった時間＝震源距離÷P 波の速さ。', '発生時刻＝P 波の到着時刻−その時間。', 'S 波で考えても同じ時刻になるので、検算に使えます。'], ex: { q: '震源距離 60 km の観測点に、P 波が 10 時 15 分 20 秒に届いた。P 波の速さを 6.0 km/s とすると、地震の発生時刻は何時何分何秒か。', a: '10 時 15 分 10 秒', exp: 'P 波は 60÷6.0＝10 秒かかって届いたので、発生時刻は 20 秒の 10 秒前の 10 時 15 分 10 秒です。' } },
      { name: 'マグニチュードとエネルギー:1 大きいと約 32 倍', freq: 'とてもよく出る', when: '2つの地震のマグニチュードの差から、エネルギーの比を問われたときです。', how: ['マグニチュードが 1 大きいと、エネルギーは約 32 倍です。', '2 大きいと約 32×32≒1000 倍になります。', '震度(ゆれの強さ)とマグニチュード(地震の規模)を区別します。'], ex: { q: 'マグニチュード 8 の地震のエネルギーは、マグニチュード 6 の地震のおよそ何倍か。', a: '約 1000 倍', exp: '差は 2 なので 32×32≒1000 倍です。M8 の地震 1 回は、M6 の地震約 1000 回分のエネルギーにあたります。' } },
      { name: 'マグマのねばりけと火山の形・噴火のようす', freq: 'とてもよく出る', when: '火山の形や噴火のしかたから、マグマの性質(SiO₂ の量)を問われたときです。', how: ['SiO₂ が少ないマグマはねばりけが弱く、溶岩が流れやすい。おだやかな噴火で、たて状火山や溶岩台地になります(ハワイのキラウエアなど)。', 'SiO₂ が多いマグマはねばりけが強く、爆発的な噴火をしやすい。溶岩ドームができます(昭和新山など)。', '中間のものは、噴火と溶岩流をくり返して成層火山になります(富士山など)。'], ex: { q: '溶岩がもり上がってドーム状の火山ができた。このマグマの SiO₂ の量とねばりけを答えよ。', a: 'SiO₂ が多く、ねばりけが強い', exp: 'ねばりけが強い溶岩は流れにくく、火口の上に積み重なってドーム状になります。こうしたマグマはガスがぬけにくく、爆発的な噴火や火砕流を起こしやすいです。' } },
      { name: '日本の地震の型:海溝型と内陸型を見分ける', freq: 'よく出る', when: '地震が起きた場所や深さ、被害の特徴から、地震の種類を答える問題です。', how: ['海溝型地震:沈みこむ海洋プレートと陸のプレートの境界で起こる。規模が大きく、津波をともなうことが多い。', '内陸型地震(直下型):陸のプレートの内部の活断層で起こる。震源が浅く、規模は比較的小さくても真上で強くゆれる。', '震源の位置(海の下か陸の下か)、深さ、津波の有無を手がかりにします。'], ex: { q: '2011 年の東北地方太平洋沖地震は、どの型の地震か。また、大きな津波が起きた理由を答えよ。', a: '海溝型地震。プレート境界が大きくずれて、海底が広い範囲で急に持ち上がったから。', exp: '陸のプレートが、沈みこむ太平洋プレートに引きずられてたまったひずみが一気に解放されました。海底の変形が海水を持ち上げ、大津波になりました。' } }
    ],
    more: [
      { lv: 1, q: '地球の内部を、表面から順に3つに分けるとどうなるか。', a: '地殻、マントル、核', exp: '地殻はうすい岩石の層、マントルはかんらん岩などの岩石、核は主に鉄でできています。核はさらに液体の外核と固体の内核に分かれます。' },
      { lv: 1, q: '海洋プレートが大陸プレートの下に沈みこむ場所にできる、深い溝状の地形を何というか。', a: '海溝', exp: '日本列島の太平洋側には、日本海溝・南海トラフなどがあります。海溝付近では大きな地震が起こり、陸側には火山が並びます。' },
      { lv: 1, q: 'P 波と S 波で、先に観測点に届くのはどちらか。', a: 'P 波', exp: 'P 波は S 波より速いので先に届き、小さなゆれ(初期微動)を起こします。あとから届く S 波が大きなゆれ(主要動)を起こします。' },
      { lv: 1, q: '日本の気象庁の震度は、何階級に分けられているか。', choices: ['7 階級', '8 階級', '10 階級', '12 階級'], a: 'C(10 階級)', exp: '震度は 0、1、2、3、4、5 弱、5 強、6 弱、6 強、7 の 10 階級です。震度はその場所のゆれの強さを表します。' },
      { lv: 1, q: '地震そのものの規模(放出されたエネルギーの大きさ)を表す尺度を何というか。', a: 'マグニチュード', exp: '1つの地震でマグニチュードは1つですが、震度は場所によってちがいます。震源に近いほど、また地盤がやわらかいほど震度は大きくなりがちです。' },
      { lv: 1, q: '地震のゆれで、水を多く含む砂の地盤が液体のようになる現象を何というか。', a: '液状化(現象)', exp: '埋め立て地や川ぞいの低い土地で起こりやすく、建物がかたむいたり、マンホールがうき上がったりします。' },
      { lv: 1, q: 'ねばりけの弱い玄武岩質のマグマがつくりやすい火山の形はどれか。', choices: ['たて状火山', '溶岩ドーム', '成層火山', 'カルデラだけ'], a: 'A(たて状火山)', exp: '流れやすい溶岩がうすく広がって積み重なるので、なだらかな傾きの大きな火山になります。ハワイのマウナロアが代表例です。' },
      { lv: 2, q: '大森公式の比例定数を 7.0 km/s とする。初期微動継続時間が 8.0 秒の観測点の震源距離を求めよ。', a: '56 km', exp: 'D＝7.0×8.0＝56 km です。' },
      { lv: 2, q: '震源距離 48 km の観測点に、P 波が 9 時 00 分 12 秒に届いた。P 波の速さを 6.0 km/s とすると、地震の発生時刻を求めよ。', a: '9 時 00 分 04 秒', exp: 'P 波が届くのにかかった時間は 48÷6.0＝8.0 秒。12 秒から 8 秒をもどして 9 時 00 分 04 秒です。' },
      { lv: 2, q: 'マグニチュード 7 の地震は、マグニチュード 5 の地震のおよそ何倍のエネルギーをもつか。', a: '約 1000 倍', exp: '2 の差なので 32×32≒1000 倍です。マグニチュードは数が少しちがうだけで、エネルギーは大きくちがいます。' },
      { lv: 2, q: '地球の全周を約 4 万 km とすると、地球の半径はおよそ何 km か。(π＝3.14)', a: '約 6400 km', exp: '全周＝2πR より R＝40000÷6.28≒6370 km。約 6400 km として覚えておくと便利です。' },
      { lv: 2, q: '緊急地震速報で、大きなゆれが来る前に知らせることができるしくみを説明せよ。', a: '震源の近くで速い P 波をとらえて震源や規模を推定し、大きなゆれを起こす S 波が届く前に情報を伝えるから。', exp: 'P 波と S 波の速さのちがいと、電気信号が地震波よりずっと速く伝わることを利用しています。震源に近い場所では、間に合わないこともあります。' },
      { lv: 2, q: '海溝型地震で大きな津波が起こりやすい理由として正しいものはどれか。', choices: ['震源が陸の下にあるから', '海底が広い範囲で急に上下に動き、海水全体を持ち上げるから', '海の水温が高いから', '風が強くなるから'], a: 'B(海底が広い範囲で急に上下に動き、海水全体を持ち上げるから)', exp: '津波は海底から海面までの水全体が動く波なので、エネルギーが大きく、陸に近づくと高くなります。高い場所へすぐに避難することが大切です。' },
      { lv: 2, q: '火山の噴火で、高温の火山ガスと火山灰・岩石が混ざって、高速で斜面を流れ下る現象を何というか。', a: '火砕流', exp: '火砕流は温度が数百 ℃にもなり、時速 100 km をこえることもあります。1991 年の雲仙普賢岳の噴火で大きな被害が出ました。' },
      { lv: 2, q: '活断層とはどのような断層か。', a: '最近の地質時代(数十万年前以降)にくり返し活動し、今後も活動する可能性がある断層。', exp: '内陸型の地震は活断層が動いて起こります。活断層の位置を調べることは、地震の被害を減らす防災に役立ちます。' },
      { lv: 3, q: 'P 波の速さ 6.0 km/s、S 波の速さ 3.0 km/s とする。観測点 A では初期微動継続時間が 5.0 秒で、P 波が 10 時 15 分 20 秒に届いた。地震の発生時刻と、A の震源距離を求めよ。', a: '発生時刻 10 時 15 分 15 秒、震源距離 30 km', exp: 'D/3.0−D/6.0＝5.0 より D/6.0＝5.0、D＝30 km。P 波が届くのに 30÷6.0＝5.0 秒かかったので、発生時刻は 10 時 15 分 15 秒です。S 波は 10 秒かかり 25 秒に届き、PS 時間 5 秒と合います。' },
      { lv: 3, q: 'マグニチュードが 0.2 大きくなると、地震のエネルギーはおよそ何倍になるか。(マグニチュードが 1 大きいとエネルギーは約 32 倍、2 大きいと 1000 倍とする)', a: '約 2 倍', exp: 'エネルギーは 10^(1.5×M) に比例するので、0.2 の差では 10^(0.3)≒2 倍です。M が 1 で約 32 倍(10^1.5)、2 で 1000 倍(10³)と同じ関係です。' },
      { lv: 3, q: '大きな氷河におおわれていたスカンジナビア半島は、氷河がとけたあと、現在も少しずつ隆起している。その理由として正しいものはどれか。', choices: ['火山活動が続いているから', '氷の重さがなくなり、アイソスタシーによって地殻が浮き上がろうとしているから', '海水面が下がっているから', 'プレートが衝突しているから'], a: 'B(氷の重さがなくなり、アイソスタシーによって地殻が浮き上がろうとしているから)', exp: '地殻はマントルの上に浮かんだようにつり合っています。重い氷がのっている間は沈み、氷がなくなると、ゆっくり流れるマントルが入りこんで地殻が持ち上がります。' },
      { lv: 3, q: 'ハワイ諸島では、北西にある島ほど年代が古い。このことからわかる、太平洋プレートの動く向きを答えよ。', a: '北西の向き(西北西)', exp: 'ホットスポットの位置はほぼ動かず、その上で火山ができてはプレートに運ばれていきます。古い島ほど遠くへ運ばれているので、プレートは古い島のある北西の方向へ動いています。' },
      { lv: 3, q: '地球(直径約 12800 km)を直径 1.28 m の球に縮めた模型をつくる。厚さ約 30 km の大陸地殻は、模型では何 mm になるか。', a: '約 3 mm', exp: '縮尺は 1.28 m/12800 km＝1/10⁷。30 km＝3.0×10⁷ mm なので、模型では 3.0 mm です。地殻は地球全体から見るととてもうすい「皮」であることがわかります。' }
    ]
  });

  add('gb_rock', {
    pat: [
      { name: '火成岩の分類表を使う:組織で「火山岩か深成岩か」、色で「SiO₂ の量」', freq: 'とてもよく出る', when: '岩石の観察結果(組織・色・鉱物)から岩石名を答える問題です。', how: ['斑状組織(斑晶＋石基)なら火山岩、等粒状組織なら深成岩です。', '有色鉱物(黒雲母・角閃石・輝石・かんらん石)が多いほど黒っぽく、SiO₂ が少なくなります。', '火山岩は 玄武岩−安山岩−流紋岩、深成岩は 斑れい岩−閃緑岩−花こう岩 の順で白っぽくなります。'], ex: { q: '斑状組織をもち、全体に灰色で、斜長石と角閃石・輝石を含む岩石の名前を答えよ。', a: '安山岩', exp: '斑状組織なので火山岩。白黒の中間の灰色で、角閃石や輝石を含むので中間質です。日本の火山に最も多い岩石です。' } },
      { name: '地層の新旧と出来事の順番', freq: 'とてもよく出る', when: '露頭や断面図から、地層のでき方や断層・不整合の順番を問われたときです。', how: ['地層は下から上へ順に積もるので、下ほど古いです(逆転していなければ)。', '断層や岩脈は、それが切っている地層よりあとにできました。', '不整合があれば、その間に「隆起→侵食→沈降」が起こっています。'], ex: { q: '地層 A の上に地層 B が整合に重なり、両方を断層が切っている。その上を地層 C がおおい、断層は C を切っていない。断層ができたのはいつか。', a: '地層 B が堆積したあと、地層 C が堆積する前', exp: '断層は A と B を切っているので B より新しく、C を切っていないので C より古いです。「切っている方が新しい」がポイントです。' } },
      { name: '柱状図と鍵層で離れた地層をつなぐ', freq: 'よく出る', when: '2〜3地点の柱状図が並べられ、同じ時代の地層を見つける問題です。', how: ['火山灰層(凝灰岩)や特徴的な化石を含む層など、見分けやすい層(鍵層)を探します。', '同じ鍵層どうしを線で結びます。', '鍵層の標高を比べて、地層がどちらへかたむいているか、上下の層がどう変わるかを読みとります。'], ex: { q: '地点 X と Y の柱状図に、同じ火山灰層がある。X ではこの層が標高 120 m に、Y では 100 m にある。地層はどちらに向かって低くなっているか。', a: 'Y の方向へ低くなっている', exp: '同じ時期に積もった火山灰層が、Y の方が 20 m 低いところにあります。地層が水平でなく、Y の方へかたむいているとわかります(断層などがない場合)。' } },
      { name: '示準化石で地質時代を決める', freq: 'とてもよく出る', when: '地層から見つかった化石の名前から、その地層の時代を答える問題です。', how: ['古生代:三葉虫、フズリナ(紡錘虫)、クサリサンゴ など。', '中生代:アンモナイト、恐竜、イノセラムス など。', '新生代:ビカリア、デスモスチルス、ナウマンゾウ、カヘイ石(ヌンムリテス) など。'], ex: { q: 'ある地層からフズリナの化石が見つかった。この地層ができた時代を答えよ。', a: '古生代(石炭紀〜ペルム紀)', exp: 'フズリナは古生代の後半に栄えた単細胞生物(有孔虫の仲間)で、古生代末に絶滅しました。日本の石灰岩からよく見つかります。' } },
      { name: '風化・侵食から堆積岩へ:粒の大きさで分類する', freq: 'よく出る', when: '堆積岩の種類や、川によって運ばれる粒の大きさとたまる場所を問われたときです。', how: ['砕屑岩は粒の大きさで分けます:れき岩(2 mm 以上)、砂岩(1/16〜2 mm)、泥岩(1/16 mm 以下)。', '流れが遅くなる河口から沖へ向かって、れき→砂→泥の順にたまります。', '生物の殻などからできた石灰岩・チャート、火山灰からできた凝灰岩も区別します。'], ex: { q: '河口から沖へ向かって、たまる粒の大きさはどう変わるか。理由も答えよ。', a: 'れき→砂→泥と、だんだん細かくなる。粒が大きいほど重く、流れが弱まるとすぐにしずむから。', exp: '細かい泥は軽いので、流れがゆるやかになっても遠くまで運ばれます。地層の粒の大きさから、当時の海岸からの距離や水深を推定できます。' } }
    ],
    more: [
      { lv: 1, q: '岩石をつくっている鉱物のうち、無色・白色の鉱物はどれか。', choices: ['黒雲母', '角閃石', '石英', 'かんらん石'], a: 'C(石英)', exp: '石英と長石は無色鉱物(白っぽい)、黒雲母・角閃石・輝石・かんらん石は有色鉱物(黒・緑っぽい)です。' },
      { lv: 1, q: 'マグマが地下深くでゆっくり冷え固まってできた岩石を何というか。', a: '深成岩', exp: 'ゆっくり冷えるので、どの鉱物も大きな結晶に成長し、等粒状組織になります。花こう岩・閃緑岩・斑れい岩がその例です。' },
      { lv: 1, q: '岩石が、気温の変化や水のこおる力などで細かくくだかれることを何というか。', a: '物理的風化(機械的風化)', exp: '岩石のすき間にしみこんだ水がこおると体積が増え、すき間を広げます。これをくり返して岩石がくずれていきます。' },
      { lv: 1, q: '石灰岩が二酸化炭素をふくむ雨水などにとけて、鍾乳洞などの地形ができる。このような風化を何というか。', a: '化学的風化', exp: '石灰岩の CaCO₃ は、CO₂ をとかした水に少しずつとけます。秋吉台のようなカルスト地形ができます。' },
      { lv: 1, q: 'サンゴやフズリナなどの殻が積もってできる堆積岩はどれか。', choices: ['砂岩', '石灰岩', '凝灰岩', 'チャート'], a: 'B(石灰岩)', exp: '石灰岩は CaCO₃ を主成分とし、うすい塩酸をかけると CO₂ の泡を出します。チャートは放散虫などの SiO₂ の殻からできます。' },
      { lv: 1, q: '恐竜が栄えていた地質時代はどれか。', choices: ['古生代', '中生代', '新生代', '先カンブリア時代'], a: 'B(中生代)', exp: '恐竜は中生代の三畳紀に現れ、ジュラ紀・白亜紀に栄えて、白亜紀の終わりに絶滅しました。' },
      { lv: 1, q: '地層が積み重なったあと、陸上で侵食され、再び沈んでその上に新しい地層が重なった、地層の重なり方を何というか。', a: '不整合', exp: '不整合面の上下では、地層ができた時代が大きく離れています。不整合面の上には、下の地層のれきを含む基底れき岩がよく見られます。' },
      { lv: 2, q: '等粒状組織で白っぽく、石英・長石・黒雲母を含む岩石の名前を答えよ。', a: '花こう岩', exp: '等粒状組織なので深成岩、白っぽく石英が多いので SiO₂ が多いケイ長質の岩石です。墓石や建物の石材(御影石)に使われます。' },
      { lv: 2, q: '化石の中で、地層ができた時代を知るのに役立つものを何というか。また、その条件を答えよ。', a: '示準化石。生存期間が短く、広い地域に多く分布していた生物であること。', exp: '短い期間しか生きていなかった生物なら、時代をせまい範囲にしぼりこめます。分布が広ければ、離れた地域の地層の対比にも使えます。' },
      { lv: 2, q: 'ナウマンゾウの化石が見つかる地層の時代はどれか。', choices: ['古生代', '中生代', '新生代第四紀', '先カンブリア時代'], a: 'C(新生代第四紀)', exp: 'ナウマンゾウは新生代第四紀の氷期に、陸続きだった大陸から日本にわたってきた大型のゾウです。' },
      { lv: 2, q: '火山灰層が鍵層としてすぐれている理由を2つ答えよ。', a: '短い期間に広い範囲に降り積もること。含まれる鉱物などの特徴から、どの噴火のものかを見分けやすいこと。', exp: 'ほぼ同じ時期にできた層を、離れた場所どうしで確実に結びつけられます。降った年代がわかっている火山灰なら、地層の年代も決められます。' },
      { lv: 2, q: '泥岩とれき岩のうち、海岸から遠い深い海でたまりやすいのはどちらか。', a: '泥岩', exp: '細かい泥は流れの弱いところまで運ばれるので、沖合いの深い海にたまります。れきは河口や海岸の近くにたまります。' },
      { lv: 2, q: '地層の上下が逆転しているかどうかを判断するのに使える手がかりを1つ答えよ。', a: '級化層理(1枚の層の中で下ほど粒が大きい)、斜交葉理(クロスラミナ)の形、漣痕(リプルマーク)の形など', exp: '地層ができたときの上下を示す構造を使います。たとえば級化層理なら、粒の大きい側が本来の下です。' },
      { lv: 2, q: '古生代の終わりに起こった大量絶滅で絶滅した生物はどれか。', choices: ['三葉虫', 'アンモナイト', '恐竜', 'ナウマンゾウ'], a: 'A(三葉虫)', exp: '三葉虫はカンブリア紀から栄えた古生代の代表的な生物で、ペルム紀末の大量絶滅でいなくなりました。アンモナイトと恐竜は中生代末に絶滅しました。' },
      { lv: 2, q: '生物の大量絶滅のあと、新しいグループが栄える。中生代末の大量絶滅のあと新生代に栄えたグループはどれか。', choices: ['は虫類', '哺乳類', '三葉虫', 'シダ植物'], a: 'B(哺乳類)', exp: '恐竜がいなくなって空いた生活の場に、哺乳類が進出して多様化しました。新生代は「哺乳類の時代」とよばれます。' },
      { lv: 3, q: 'マグマが冷えていくとき、有色鉱物がでてくる順番として正しいものはどれか。', choices: ['黒雲母→角閃石→輝石→かんらん石', 'かんらん石→輝石→角閃石→黒雲母', '輝石→かんらん石→黒雲母→角閃石', '角閃石→黒雲母→かんらん石→輝石'], a: 'B(かんらん石→輝石→角閃石→黒雲母)', exp: '高温で先に固まるのはかんらん石で、温度が下がるにつれて輝石・角閃石・黒雲母の順に出てきます。石英は最後に出ます。そのため SiO₂ の少ない(高温の)マグマの岩石には、かんらん石が多く含まれます。' },
      { lv: 3, q: 'ある露頭で、下から 泥岩 → 砂岩 → れき岩 の順に重なっていた(地層の逆転はない)。この間に、この場所の水深はどう変わったと考えられるか。', a: 'だんだん浅くなった(海岸に近づいた)', exp: '下ほど古く、古い方から泥→砂→れきと粒が大きくなっているので、たまる場所が沖合いから海岸近くに変わったと考えられます。土地の隆起や、海水面の低下などが原因です。' },
      { lv: 3, q: 'ある海で地層が 1000 年あたり 1 cm の速さでたまるとする。厚さ 30 m の地層がたまるのにかかる時間を求めよ。', a: '300 万年', exp: '30 m＝3000 cm。3000÷1×1000＝3.0×10⁶ 年＝300 万年です。地層の厚さから、とても長い時間が記録されていることがわかります。' },
      { lv: 3, q: '露頭で、地層 A・B・C(下から順)を岩脈 D が貫き、D と地層はすべて断層 E で切られていた。その上を地層 F が不整合でおおっている。A〜F の出来事を古い順に並べよ。', a: 'A→B→C→D→E→(隆起・侵食・沈降)→F', exp: 'D は C まで貫くので C より新しく、E は D も切るので D より新しいです。F は不整合の上なので、E のあとに隆起・侵食・沈降をはさんでたまりました。' },
      { lv: 3, q: '地層の中から、デスモスチルスの化石とビカリアの化石が一緒に見つかった。この地層の時代と、当時の環境について考えられることを答えよ。', a: '新生代(新第三紀)。ビカリアから、暖かい地域の干潟(マングローブの生える浅い海)の環境だったと考えられる。', exp: 'どちらも新生代新第三紀の示準化石です。ビカリアは現在の熱帯〜亜熱帯のマングローブ林にすむ巻貝の仲間なので、示相化石として当時の環境もわかります。' }
    ]
  });

  add('gb_atmos', {
    pat: [
      { name: '湿度と露点:飽和水蒸気量の表を使う', freq: 'とてもよく出る', when: '気温と空気中の水蒸気量が与えられ、湿度・露点・凝結する水の量を問われたときです。', how: ['湿度(%)＝空気 1 m³ 中の水蒸気量÷その気温の飽和水蒸気量×100。', '露点は、表で「その水蒸気量＝飽和水蒸気量」となる温度を探します。', '露点より冷やすと、(水蒸気量−冷やした温度の飽和水蒸気量)の分が水滴になります。'], ex: { q: '気温 25 ℃の空気 1 m³ に 12.8 g の水蒸気が含まれている。湿度と露点を求めよ。また、10 ℃まで冷やすと何 g の水滴ができるか。(飽和水蒸気量:10 ℃ 9.4 g/m³、15 ℃ 12.8 g/m³、25 ℃ 23.1 g/m³)', a: '湿度 約 55 %、露点 15 ℃、水滴 3.4 g', exp: '湿度は 12.8÷23.1×100≒55 %。12.8 g/m³ が飽和水蒸気量になる 15 ℃が露点です。10 ℃では 9.4 g しか含めないので 12.8−9.4＝3.4 g が水滴になります。' } },
      { name: 'フェーン現象:山をこえると暖かく乾いた風になる', freq: 'よく出る', when: '湿った空気が山をこえるときの、風上・風下の気温を問われたときです。', how: ['雲ができるまでは 100 m 上がるごとに 1.0 ℃下がります。', '雲ができてからは、水蒸気が水滴になるときに熱を出すので 100 m で約 0.5 ℃しか下がりません。', '山をこえて下りるとき(雲がなければ)は 100 m で 1.0 ℃上がるので、風下では風上より暖かくなります。'], ex: { q: '高度 0 m で 25 ℃の空気が山を上り、1000 m で雲ができた。2000 m の山頂をこえたあと、風下の高度 0 m まで雲のないまま下りた。風下の気温を求めよ。', a: '30 ℃', exp: '1000 m まで 10 ℃下がって 15 ℃。山頂まで 0.5 ℃/100 m で 5 ℃下がって 10 ℃。風下は 2000 m を 1.0 ℃/100 m で下りるので 20 ℃上がって 30 ℃です。' } },
      { name: '日本の季節の天気図:気圧配置で季節を判断する', freq: 'とてもよく出る', when: '天気図が与えられ、季節や天気の特徴を問われたときです。', how: ['冬:西高東低(大陸にシベリア高気圧、東の海上に低気圧)。等圧線が南北にせまく並び、北西の季節風。日本海側は雪、太平洋側は晴れ。', '梅雨:オホーツク海高気圧と太平洋高気圧の間に停滞前線(梅雨前線)。', '夏:南高北低(太平洋高気圧が日本をおおう)。蒸し暑い晴れ。春・秋は移動性高気圧と低気圧が交互に通ります。'], ex: { q: '天気図で、大陸に高気圧、日本の東の海上に発達した低気圧があり、等圧線が南北方向にせまい間隔で並んでいた。季節と、日本海側の天気を答えよ。', a: '冬。日本海側は雪(くもりや雪の日が多い)。', exp: '西高東低の冬型の気圧配置です。シベリアからの冷たく乾いた北西の季節風が、日本海で水蒸気を受けとって雲をつくり、山脈にぶつかって日本海側に雪を降らせます。' } },
      { name: '台風の進行方向の右側が危険な理由', freq: 'よく出る', when: '台風の進路と風の強さの関係を問われたときです。', how: ['北半球の台風では、地表付近の風は中心に向かって反時計回りにふきこみます。', '進行方向の右側では、台風自身の風の向きと、台風が進む向きが同じになり、風が強まります。', '左側では向きが逆になるので、風は弱まります。'], ex: { q: '中心付近の風速が 40 m/s の台風が、北へ 15 m/s で進んでいる。進行方向の右側(東側)と左側(西側)の風速はおよそいくらになるか。', a: '右側 約 55 m/s、左側 約 25 m/s', exp: '右側では台風の風(北向き)と進む速さが足し合わさって 40＋15＝55 m/s、左側では台風の風(南向き)から差し引かれて 40−15＝25 m/s になります。' } },
      { name: '地球の熱収支:入るエネルギーと出るエネルギーの数字を追う', freq: 'よく出る', when: '太陽放射を 100 としたときの、反射・吸収・放射の割合の図を読む問題です。', how: ['太陽放射 100 のうち、約 30 が雲・大気・地表で反射されて宇宙へもどります。', '残り約 70 のうち、約 20 を大気が、約 50 を地表が吸収します。', '地表と大気は赤外線を出し合い、最終的に宇宙へ出ていく赤外線は 70 で、入る量とつり合います。'], ex: { q: '地球に入る太陽放射を 100 とすると、地球から宇宙へ出ていく赤外線(地球放射)はおよそいくらか。', a: '約 70', exp: '地球が吸収した太陽放射は 100−30(反射)＝70 です。地球の平均気温がほぼ一定なので、出ていく赤外線も 70 になってつり合っています(放射平衡)。' } }
    ],
    more: [
      { lv: 1, q: '気温が上がると、飽和水蒸気量はどうなるか。', choices: ['大きくなる', '小さくなる', '変わらない', '0 になる'], a: 'A(大きくなる)', exp: '暖かい空気ほど多くの水蒸気を含むことができます。そのため、同じ水蒸気量でも気温が下がると湿度が上がり、やがて露点に達します。' },
      { lv: 1, q: '空気が上昇すると温度が下がる理由として正しいものはどれか。', choices: ['上空ほど太陽から遠いから', '上空ほど気圧が低く、空気が膨張するから', '上空の空気は水を含まないから', '上空ほど風が強いから'], a: 'B(上空ほど気圧が低く、空気が膨張するから)', exp: '上昇した空気は、まわりの気圧が低いので膨張し、そのとき自分のエネルギーを使うので温度が下がります(断熱膨張)。これが雲のでき方のもとです。' },
      { lv: 1, q: '大気の層のうち、雲ができたり雨が降ったりする天気の変化が起こるのはどこか。', choices: ['対流圏', '成層圏', '中間圏', '熱圏'], a: 'A(対流圏)', exp: '対流圏は地表から高さ約 10 km(極で低く、赤道で高い)までで、水蒸気のほとんどがここにあり、対流がさかんです。' },
      { lv: 1, q: '冬の日本付近によく見られる気圧配置を何というか。', a: '西高東低(冬型の気圧配置)', exp: '大陸のシベリア高気圧と、日本の東の海上の低気圧の間で、北西の冷たい季節風がふきます。' },
      { lv: 1, q: '梅雨の時期に日本付近にのびる前線を何というか。', a: '梅雨前線(停滞前線)', exp: '北のオホーツク海高気圧と南の太平洋高気圧の勢力がつり合って、前線がほぼ同じ場所にとどまり、長雨になります。' },
      { lv: 1, q: '台風は、もともとどこで発生した何という低気圧か。', a: '熱帯の海上で発生した熱帯低気圧', exp: '熱帯低気圧のうち、北西太平洋で最大風速が約 17 m/s 以上になったものを台風とよびます。暖かい海からの水蒸気がエネルギー源です。' },
      { lv: 1, q: '温室効果をもつ気体として正しいものはどれか。', choices: ['窒素', '酸素', '二酸化炭素', 'アルゴン'], a: 'C(二酸化炭素)', exp: '二酸化炭素や水蒸気、メタンは、地表から出る赤外線を吸収して地表へ放射し返します。窒素・酸素・アルゴンには、その性質がほとんどありません。' },
      { lv: 2, q: '高度 0 m で 20 ℃の空気が山を上り、500 m で雲ができ、2500 m の山頂をこえて、風下の高度 0 m まで雲のないまま下りた。風下の気温を求めよ。(雲がないとき 1.0 ℃/100 m、雲があるとき 0.5 ℃/100 m)', a: '30 ℃', exp: '500 m まで 5 ℃下がって 15 ℃。山頂まで 2000 m を 0.5 ℃/100 m で 10 ℃下がって 5 ℃。風下は 2500 m を 1.0 ℃/100 m で下りて 25 ℃上がり 30 ℃です。' },
      { lv: 2, q: '気温 30 ℃(飽和水蒸気量 30.4 g/m³)の空気 1 m³ に、水蒸気が 15.2 g 含まれている。湿度を求めよ。', a: '50 %', exp: '15.2÷30.4×100＝50 %。同じ 15.2 g でも、気温 20 ℃(飽和 17.3 g/m³)なら湿度は約 88 % になります。' },
      { lv: 2, q: '冬に日本海側で雪が多く降る理由を説明せよ。', a: '大陸からの冷たく乾いた北西の季節風が、比較的暖かい日本海の上で水蒸気を受けとって雲をつくり、それが日本列島の山脈にぶつかって上昇し、日本海側に雪を降らせるから。', exp: '山脈をこえた太平洋側には、水蒸気を失って乾いた風がふき下りるので、晴れて乾燥した日が多くなります。' },
      { lv: 2, q: '夏の日本付近の天気を支配する高気圧はどれか。', choices: ['シベリア高気圧', 'オホーツク海高気圧', '太平洋高気圧', '移動性高気圧'], a: 'C(太平洋高気圧)', exp: '太平洋高気圧は暖かく湿った空気をもつ高気圧で、夏に日本をおおうと、蒸し暑い晴れの日が続きます(南高北低)。' },
      { lv: 2, q: '温帯低気圧の寒冷前線が通過したあと、天気や気温・風向はどう変わるか。', a: '雨がやんで晴れることが多く、気温が下がり、風向は北寄りに変わる。', exp: '寒冷前線のうしろには寒気があるので、通過すると気温が急に下がります。通過するときは積乱雲によって短時間に強い雨や突風が起こりやすいです。' },
      { lv: 2, q: '台風が近づくと、海水面が異常に高くなる高潮が起こる。その原因を2つ答えよ。', a: '気圧が低いため海水面が吸い上げられること。強い風が海水を海岸へふき寄せること。', exp: '気圧が 1 hPa 下がると海面は約 1 cm 上がります。これに強風のふき寄せが加わり、湾の奥や満潮の時刻と重なると、特に大きな被害になります。' },
      { lv: 2, q: '大気の大循環で、日本付近の上空をふいている風はどれか。', choices: ['貿易風', '偏西風', '極偏東風', '季節風だけ'], a: 'B(偏西風)', exp: '中緯度の上空には偏西風がふいているので、日本の天気は西から東へ移り変わります。低緯度の地表には貿易風、極地方には極偏東風がふきます。' },
      { lv: 2, q: '地球に入る太陽放射を 100 とすると、雲・大気・地表で反射されて宇宙へもどる割合はおよそいくらか。', choices: ['約 10', '約 30', '約 50', '約 70'], a: 'B(約 30)', exp: '約 30 が反射され、残りの約 70 が大気と地表に吸収されます。反射される割合をアルベドといい、雲や雪・氷が多いと大きくなります。' },
      { lv: 3, q: '気温 30 ℃、湿度 60 % の空気 1 m³ を 15 ℃まで冷やした。何 g の水滴ができるか。(飽和水蒸気量:15 ℃ 12.8 g/m³、30 ℃ 30.4 g/m³)', a: '約 5.4 g', exp: '水蒸気量は 30.4×0.60≒18.2 g。15 ℃では 12.8 g までしか含めないので、18.2−12.8≒5.4 g が水滴になります。' },
      { lv: 3, q: '中心気圧が 960 hPa の台風が近づいている。まわりの気圧を 1010 hPa とすると、気圧の低下による海面の上昇はおよそ何 cm か。(気圧が 1 hPa 下がると海面は約 1 cm 上がるとする)', a: '約 50 cm', exp: '気圧差は 1010−960＝50 hPa なので、約 50 cm 上がります。実際には、強風のふき寄せの効果がこれに加わり、さらに高くなることがあります。' },
      { lv: 3, q: '中心付近の風速が 50 m/s の台風が、北東へ 20 m/s で進んでいる。進行方向の右側と左側の風速を求めよ。また、より警戒が必要なのはどちら側か。', a: '右側 約 70 m/s、左側 約 30 m/s。右側', exp: '反時計回りにふく台風の風は、進行方向の右側では進む向きと同じ向きになるので 50＋20＝70 m/s、左側では逆向きになるので 50−20＝30 m/s です。' },
      { lv: 3, q: 'エルニーニョ現象が起こると、日本の夏はどうなりやすいか。理由とともに答えよ。', a: '冷夏になりやすい。太平洋の西部(日本の南)の海面水温が下がって積乱雲の活動が弱まり、太平洋高気圧の張り出しが弱くなるから。', exp: 'エルニーニョのときは、暖かい海水が太平洋の東へ移ります。西部での上昇気流が弱まると、日本付近をおおう太平洋高気圧も弱くなり、梅雨明けがおそくなったり気温が低くなったりします。' },
      { lv: 3, q: '温室効果がまったくないとすると、地球の平均気温は約 −18 ℃になると計算される。実際の平均気温(約 15 ℃)との差が生じる理由を説明せよ。', a: '大気中の水蒸気や二酸化炭素が、地表から出る赤外線を吸収し、その一部を地表へ放射し返すので、地表は太陽放射に加えて大気からのエネルギーも受けとり、暖かく保たれるから。', exp: '温室効果は、地球を生物がすめる温度に保つ大切なはたらきです。問題になっているのは、人間活動で温室効果ガスが増え、温室効果が強まりすぎていることです。' }
    ]
  });

  add('gb_space', {
    pat: [
      { name: '縮尺モデルで宇宙のスケールを実感する', freq: 'よく出る', when: '太陽や地球を身近な大きさに縮めたとき、ほかの天体の大きさや距離がどうなるかを問われたときです。', how: ['縮尺(比)＝模型の大きさ÷実際の大きさ を最初に求めます。', 'ほかの天体の大きさや距離に、同じ縮尺をかけます。', '単位(km、m、cm)をそろえ、けたをまちがえないようにします。'], ex: { q: '太陽(直径約 1.4×10⁶ km)を直径 1.4 m の球にした模型をつくる。地球(直径約 1.3×10⁴ km)の大きさと、太陽から地球までの距離(約 1.5×10⁸ km)は、それぞれどうなるか。', a: '地球 約 1.3 cm、距離 約 150 m', exp: '縮尺は 1.4 m/1.4×10⁶ km＝1/10⁹。地球は 1.3×10⁴ km＝1.3×10⁷ m の 1/10⁹ で 1.3 cm、距離は 1.5×10¹¹ m の 1/10⁹ で 150 m です。宇宙がすかすかであることがわかります。' } },
      { name: '光の速さで距離と時間を結びつける', freq: 'よく出る', when: '天体から光が届くまでの時間や、光年で表した距離を問われたときです。', how: ['光の速さは約 3.0×10⁵ km/s(3.0×10⁸ m/s)です。', '時間＝距離÷光の速さ。', '1 光年は光が1年に進む距離で、約 9.5×10¹² km です。遠くの天体ほど、昔の姿を見ていることになります。'], ex: { q: '太陽から地球までの距離を 1.5×10⁸ km とすると、太陽の光が地球に届くまでに何秒かかるか。', a: '約 500 秒(約 8 分 20 秒)', exp: '1.5×10⁸÷3.0×10⁵＝500 秒です。今見ている太陽は、約 8 分前の姿ということになります。' } },
      { name: '惑星の分類:地球型惑星と木星型惑星', freq: 'とてもよく出る', when: '惑星のデータ(半径・質量・密度など)の表から、どちらのグループかを判断する問題です。', how: ['地球型惑星(水星・金星・地球・火星):小さく、密度が大きい(岩石と金属)。衛星は少ない。', '木星型惑星(木星・土星・天王星・海王星):大きく、密度が小さい(ガスや氷が多い)。衛星が多く、環をもつ。', '密度 3 g/cm³ 以上なら地球型、それより小さければ木星型と考えるとよいです。'], ex: { q: '半径が地球の約 9.4 倍、平均密度が約 0.7 g/cm³ で、大きな環をもつ惑星は何か。', a: '土星(木星型惑星)', exp: '大きく密度が小さいので木星型惑星です。その中で密度が水より小さく、目立つ環をもつのは土星です。主に水素とヘリウムでできています。' } },
      { name: '宇宙の歴史の順番を並べる', freq: 'よく出る', when: 'ビッグバンから現在までの出来事を、起こった順に並べる問題です。', how: ['ビッグバン(約 138 億年前)→数分で水素・ヘリウムの原子核ができる。', '約 38 万年後:電子が原子核に捕まって原子ができ、光がまっすぐ進めるようになる(宇宙の晴れ上がり)。', 'その後、最初の恒星や銀河ができ、約 46 億年前に太陽系ができました。'], ex: { q: '次の出来事を古い順に並べよ。(ア) 太陽系の誕生 (イ) 宇宙の晴れ上がり (ウ) ヘリウムの原子核ができる (エ) 最初の恒星の誕生', a: 'ウ→イ→エ→ア', exp: 'ヘリウムの原子核はビッグバンから数分で、晴れ上がりは約 38 万年後、最初の恒星は数億年後、太陽系は約 46 億年前(ビッグバンから約 92 億年後)です。' } },
      { name: 'ハビタブルゾーン:光の量は距離の2乗に反比例', freq: 'よく出る', when: '恒星の明るさが変わったとき、水が液体で存在できる範囲(ハビタブルゾーン)がどこへ移るかを問われたときです。', how: ['惑星が受ける光の量は、恒星の光度に比例し、距離の2乗に反比例します。', '地球と同じだけの光を受ける距離は、√(光度の比)天文単位です。', '光度が4倍なら 2 天文単位、1/4 なら 0.5 天文単位になります。'], ex: { q: '太陽の 4 倍の光度をもつ恒星のまわりで、地球と同じ量の光を受ける惑星の距離は何天文単位か。', a: '2 天文単位', exp: '受ける光∝光度/距離²。光度が 4 倍のとき、地球と同じにするには距離² も 4 倍にすればよいので、距離は √4＝2 天文単位です。' } }
    ],
    more: [
      { lv: 1, q: '宇宙はおよそ何年前に誕生したと考えられているか。', choices: ['約 46 億年前', '約 100 億年前', '約 138 億年前', '約 1000 億年前'], a: 'C(約 138 億年前)', exp: '宇宙は約 138 億年前にビッグバンで始まったと考えられています。46 億年前は太陽系ができた時期です。' },
      { lv: 1, q: '太陽のように自ら光を出してかがやく天体を何というか。', a: '恒星', exp: '恒星は中心での核融合でエネルギーを生み出しています。惑星や月は自ら光を出さず、太陽の光を反射して光って見えます。' },
      { lv: 1, q: '地球型惑星を4つ答えよ。', a: '水星、金星、地球、火星', exp: '太陽に近い4つの惑星で、岩石と金属でできていて、小さく密度が大きいのが特徴です。' },
      { lv: 1, q: '木星型惑星の特徴として正しいものはどれか。', choices: ['小さく密度が大きい', '大きく密度が小さい', '衛星をもたない', '表面が岩石でおおわれている'], a: 'B(大きく密度が小さい)', exp: '木星型惑星は水素・ヘリウムなどのガスや氷を多く含むので、大きいのに密度が小さく、多くの衛星と環をもちます。' },
      { lv: 1, q: '太陽の表面に見える黒い点(黒点)が黒く見える理由を答えよ。', a: 'まわりの光球より温度が低い(約 4000 K)から。', exp: '光球は約 6000 K、黒点は約 4000 K です。黒点も実際には光っていますが、まわりより暗いので黒く見えます。' },
      { lv: 1, q: '夜空に見える天の川は、何を内側から見たものか。', a: '私たちのいる銀河系(天の川銀河)の円盤部分', exp: '太陽系は銀河系の円盤の中にあるので、円盤の方向を見ると多くの星が重なって、帯のように見えます。' },
      { lv: 1, q: '1 光年とは何の長さか。', a: '光が1年間に進む距離', exp: '1 光年は約 9.5×10¹² km(約 9.5 兆 km)です。時間の単位ではなく距離の単位であることに注意します。' },
      { lv: 2, q: 'ビッグバンから約 38 万年後に、光がまっすぐ進めるようになった出来事を何というか。', a: '宇宙の晴れ上がり', exp: 'それまでは自由に飛び回る電子に光がぶつかって進めませんでしたが、温度が下がって電子が原子核に捕まり原子ができると、光が直進できるようになりました。' },
      { lv: 2, q: '宇宙のはじめにつくられた元素は主に何か。', choices: ['水素とヘリウム', '炭素と酸素', '鉄とニッケル', 'ケイ素とアルミニウム'], a: 'A(水素とヘリウム)', exp: 'ビッグバン直後の数分間で、水素とヘリウム(とわずかなリチウム)の原子核ができました。炭素や酸素、鉄などは、のちに恒星の中でつくられました。' },
      { lv: 2, q: '太陽の表面で起こる爆発現象(フレア)が地球にあたえる影響として正しいものはどれか。', choices: ['地震が起こる', '通信障害(デリンジャー現象)や磁気嵐が起こる', '海の潮の満ち干がなくなる', '地球の公転が速くなる'], a: 'B(通信障害(デリンジャー現象)や磁気嵐が起こる)', exp: 'フレアで出た X 線や紫外線は電離層を乱して短波の通信障害を起こし、遅れて届く電気を帯びた粒子は磁気嵐やオーロラを引き起こします。' },
      { lv: 2, q: '地球から月までの距離を 3.8×10⁵ km とすると、月で反射した光が地球に届くまでに何秒かかるか。(光の速さ 3.0×10⁵ km/s)', a: '約 1.3 秒', exp: '3.8×10⁵÷3.0×10⁵≒1.3 秒です。太陽の光(約 8 分)や、遠くの星の光(何年〜何億年)とくらべると、月はとても近い天体です。' },
      { lv: 2, q: '木星の半径は地球のおよそ何倍か。', choices: ['約 2 倍', '約 11 倍', '約 50 倍', '約 109 倍'], a: 'B(約 11 倍)', exp: '木星は太陽系最大の惑星で、半径は地球の約 11 倍、質量は約 320 倍です。太陽の半径は地球の約 109 倍です。' },
      { lv: 2, q: '太陽の中心部の温度はおよそいくらか。', choices: ['約 6000 K', '約 100 万 K', '約 1600 万 K', '約 10 億 K'], a: 'C(約 1600 万 K)', exp: '中心部は約 1600 万 K、高い圧力で、水素の核融合が起こっています。表面(光球)は約 6000 K、コロナは約 100 万 K 以上です。' },
      { lv: 2, q: '原始太陽のまわりのガスやちりから、惑星ができるまでの順として正しいものはどれか。', choices: ['ちり→微惑星→原始惑星→惑星', '惑星→原始惑星→微惑星→ちり', '微惑星→ちり→惑星→原始惑星', 'ちり→惑星→微惑星→原始惑星'], a: 'A(ちり→微惑星→原始惑星→惑星)', exp: 'ちりが集まって数 km の微惑星になり、微惑星どうしが衝突・合体して原始惑星に成長し、さらに惑星になったと考えられています。' },
      { lv: 2, q: '地球の表面に液体の水が大量に存在できる理由として、適切なものを1つ答えよ。', a: '太陽からの距離がちょうどよく、表面の温度が水の凍る温度と沸騰する温度の間に保たれているから(ほかに、重力で大気をとどめていることなど)。', exp: '太陽に近すぎると水は蒸発し、遠すぎると凍ります。地球は液体の水が存在できる範囲(ハビタブルゾーン)にあり、大気の温室効果も温度を保つのに役立っています。' },
      { lv: 3, q: '銀河系の直径を 10 万光年とすると、何 km か。(1 光年＝9.5×10¹² km)', a: '約 9.5×10¹⁷ km', exp: '1.0×10⁵×9.5×10¹²＝9.5×10¹⁷ km です。光の速さでも横断するのに 10 万年かかります。' },
      { lv: 3, q: '太陽の 9 倍の光度をもつ恒星のまわりで、地球と同じ量の光を受ける惑星の距離は何天文単位か。', a: '3 天文単位', exp: '受ける光∝光度/距離²。光度が 9 倍なら、距離を √9＝3 倍にすれば同じ量になります。明るい星ほど、ハビタブルゾーンは遠くにあります。' },
      { lv: 3, q: '太陽と地球の距離(1 天文単位)を 1 m に縮めた模型で、最も近い恒星(約 4.2 光年＝約 2.7×10⁵ 天文単位)はどれくらいの距離になるか。', a: '約 270 km', exp: '1 天文単位が 1 m なので、2.7×10⁵ 天文単位は 2.7×10⁵ m＝270 km です。海王星は約 30 m のところにあり、恒星までの距離がけた違いに遠いことがわかります。' },
      { lv: 3, q: '太陽は 1 秒間に約 3.9×10²⁶ J のエネルギーを放出している。E＝mc² を使って、太陽が 1 秒間に失う質量を求めよ。(c＝3.0×10⁸ m/s)', a: '約 4.3×10⁹ kg', exp: 'm＝E/c²＝3.9×10²⁶/(3.0×10⁸)²＝3.9×10²⁶/9.0×10¹⁶≒4.3×10⁹ kg。毎秒約 430 万トンも軽くなっていますが、太陽の質量(約 2×10³⁰ kg)にくらべるとごくわずかです。' },
      { lv: 3, q: 'ある惑星の平均密度は 5.2 g/cm³、半径は地球の約 0.95 倍、衛星はなく、厚い CO₂ の大気をもつ。この惑星は何か。また、どちらのグループに分類されるか。', a: '金星、地球型惑星', exp: '密度が大きく小さいので地球型惑星です。地球とほぼ同じ大きさで衛星がなく、CO₂ の厚い大気の強い温室効果で表面が約 460 ℃にもなるのは金星です。' }
    ]
  });
})(WPS.LESSONS);
